const baseAgentToolNames = [
  'create_plan',
  'run_terminal_command',
  'str_replace',
  'write_file',
  'spawn_agents',
  'add_subgoal',
  'browser_logs',
  'code_search',
  'end_turn',
  'read_files',
  'think_deeply',
  'update_subgoal',
] as const

const baseAgentSubagents = [
  AgentTemplateTypes.file_picker,
  AgentTemplateTypes.researcher,
