import { endsAgentStepParam } from '@codebuff/common/tools/constants'
import { renderToolResults } from '@codebuff/common/tools/utils'
import { generateCompactId } from '@codebuff/common/util/string'
import z from 'zod/v4'
import { convertJsonSchemaToZod } from 'zod-from-json-schema'

import { checkLiveUserInput } from '../live-user-inputs'
import { logger } from '../util/logger'
import { asSystemMessage } from '../util/messages'
import { requestToolCall } from '../websockets/websocket-action'
import { codebuffToolDefs } from './definitions/list'
import { codebuffToolHandlers } from './handlers/list'

import type { CodebuffToolHandlerFunction } from './handlers/handler-function-type'
import type { AgentTemplate } from '../templates/types'
import type { ToolName } from '@codebuff/common/tools/constants'
import type {
  ClientToolCall,
  ClientToolName,
  CodebuffToolCall,
} from '@codebuff/common/tools/list'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type { ToolResult } from '@codebuff/common/types/session-state'
import type {
  customToolDefinitionsSchema,
  ProjectFileContext,
} from '@codebuff/common/util/file'
import type { ToolCallPart } from 'ai'
import type { WebSocket } from 'ws'

export type CustomToolCall = {
  toolName: string
  input: Record<string, unknown>
} & Omit<ToolCallPart, 'type'>

export type ToolCallError = {
  toolName?: string
  input: Record<string, unknown>
  error: string
} & Pick<CodebuffToolCall, 'toolCallId'>

export function parseRawToolCall<T extends ToolName = ToolName>(
  rawToolCall: {
    toolName: T
    toolCallId: string
    input: Record<string, unknown>
  },
  autoInsertEndStepParam: boolean = false,
): CodebuffToolCall<T> | ToolCallError {
  const toolName = rawToolCall.toolName

  if (!(toolName in codebuffToolDefs)) {
    return {
      toolName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Tool ${toolName} not found`,
    }
  }
  const validName = toolName as T

  const processedParameters: Record<string, any> = {}
  for (const [param, val] of Object.entries(rawToolCall.input ?? {})) {
    processedParameters[param] = val
  }

  // Add the required codebuff_end_step parameter with the correct value for this tool if requested
  if (autoInsertEndStepParam) {
    processedParameters[endsAgentStepParam] =
      codebuffToolDefs[validName].endsAgentStep
  }

  const paramsSchema = codebuffToolDefs[validName].endsAgentStep
    ? (
        codebuffToolDefs[validName]
          .parameters satisfies z.ZodObject as z.ZodObject
      ).extend({
        [endsAgentStepParam]: z.literal(
          codebuffToolDefs[validName].endsAgentStep,
        ),
      })
    : codebuffToolDefs[validName].parameters
  const result = paramsSchema.safeParse(processedParameters)

  if (!result.success) {
    return {
      toolName: validName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Invalid parameters for ${validName}: ${JSON.stringify(
        result.error.issues,
        null,
        2,
      )}`,
    }
  }

  if (endsAgentStepParam in result.data) {
    delete result.data[endsAgentStepParam]
  }

  return {
    toolName: validName,
    input: result.data,
    toolCallId: rawToolCall.toolCallId,
  } as CodebuffToolCall<T>
}

export interface ExecuteToolCallParams<T extends string = ToolName> {
  toolName: T
  input: Record<string, unknown>
  toolCalls: (CodebuffToolCall | CustomToolCall)[]
  toolResults: ToolResult[]
  previousToolCallFinished: Promise<void>
  ws: WebSocket
  agentTemplate: AgentTemplate
  fileContext: ProjectFileContext
  agentStepId: string
  clientSessionId: string
  userInputId: string
  fullResponse: string
  onResponseChunk: (chunk: string | PrintModeEvent) => void
  state: Record<string, any>
  userId: string | undefined
  autoInsertEndStepParam?: boolean
}

export function executeToolCall<T extends ToolName>({
  toolName,
  input,
  toolCalls,
  toolResults,
  previousToolCallFinished,
  ws,
  agentTemplate,
  fileContext,
  agentStepId,
  clientSessionId,
  userInputId,
  fullResponse,
  onResponseChunk,
  state,
  userId,
  autoInsertEndStepParam = false,
}: ExecuteToolCallParams<T>): Promise<void> {
  const toolCall: CodebuffToolCall<T> | ToolCallError = parseRawToolCall<T>(
    {
      toolName,
      toolCallId: generateCompactId(),
      input,
    },
    autoInsertEndStepParam,
  )
  if ('error' in toolCall) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: toolCall.error,
      },
    })
    logger.debug(
      { toolCall, error: toolCall.error },
      `${toolName} error: ${toolCall.error}`,
    )
    return previousToolCallFinished
  }

  onResponseChunk({
    type: 'tool_call',
    toolCallId: toolCall.toolCallId,
    toolName,
    input: toolCall.input,
  })

  logger.debug(
    { toolCall },
    `${toolName} (${toolCall.toolCallId}) tool call detected in stream`,
  )
  toolCalls.push(toolCall)

  // Filter out restricted tools in ask mode unless exporting summary
  if (!agentTemplate.toolNames.includes(toolCall.toolName)) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: `Tool \`${toolName}\` is not currently available. Make sure to only use tools listed in the system instructions.`,
      },
    })
    return previousToolCallFinished
  }

  const { result: toolResultPromise, state: stateUpdate } = (
    codebuffToolHandlers[toolName] as CodebuffToolHandlerFunction<T>
  )({
    previousToolCallFinished,
    fileContext,
    agentStepId,
    clientSessionId,
    userInputId,
    fullResponse,
    writeToClient: onResponseChunk,
    requestClientToolCall: async (
      clientToolCall: ClientToolCall<T extends ClientToolName ? T : never>,
    ) => {
      if (!checkLiveUserInput(userId, userInputId, clientSessionId)) {
        return ''
      }

      const clientToolResult = await requestToolCall(
        ws,
        userInputId,
        clientToolCall.toolName,
        clientToolCall.input,
      )
      return (
        clientToolResult.error ??
        (clientToolResult.output?.type === 'text'
          ? clientToolResult.output.value
          : 'undefined')
      )
    },
    toolCall,
    getLatestState: () => state,
    state,
  })

  for (const [key, value] of Object.entries(stateUpdate ?? {})) {
    if (key === 'agentState' && typeof value === 'object' && value !== null) {
      // Replace the agentState reference to ensure all updates are captured
      state.agentState = value
    } else {
      state[key] = value
    }
  }

  return toolResultPromise.then((result) => {
    const toolResult = {
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text' as const,
        value: result as string,
      },
    }
    logger.debug(
      { toolResult },
      `${toolName} (${toolResult.toolCallId}) tool result for tool`,
    )
    if (result === undefined) {
      return
    }

    onResponseChunk({
      type: 'tool_result',
      toolCallId: toolResult.toolCallId,
      output: toolResult.output,
    })

    toolResults.push(toolResult)

    state.messages.push({
      role: 'user' as const,
      content: asSystemMessage(renderToolResults([toolResult])),
    })
  })
}

export function parseRawCustomToolCall(
  customToolDefs: z.infer<typeof customToolDefinitionsSchema>,
  rawToolCall: {
    toolName: string
    toolCallId: string
    input: Record<string, unknown>
  },
  autoInsertEndStepParam: boolean = false,
): CustomToolCall | ToolCallError {
  const toolName = rawToolCall.toolName

  if (!(toolName in customToolDefs)) {
    return {
      toolName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Tool ${toolName} not found`,
    }
  }

  const processedParameters: Record<string, any> = {}
  for (const [param, val] of Object.entries(rawToolCall.input ?? {})) {
    processedParameters[param] = val
  }

  // Add the required codebuff_end_step parameter with the correct value for this tool if requested
  if (autoInsertEndStepParam) {
    processedParameters[endsAgentStepParam] =
      customToolDefs[toolName].endsAgentStep
  }

  const jsonSchema = JSON.parse(
    JSON.stringify(customToolDefs[toolName].inputJsonSchema),
  )
  if (customToolDefs[toolName].endsAgentStep) {
    if (!jsonSchema.properties) {
      jsonSchema.properties = {}
    }
    jsonSchema.properties[endsAgentStepParam] = {
      const: true,
      type: 'boolean',
      description: 'Easp flag must be set to true',
    }
    if (!jsonSchema.required) {
      jsonSchema.required = []
    }
    jsonSchema.required.push(endsAgentStepParam)
  }
  const paramsSchema = convertJsonSchemaToZod(jsonSchema)
  const result = paramsSchema.safeParse(
    processedParameters,
  ) as z.ZodSafeParseResult<any>

  if (!result.success) {
    return {
      toolName: toolName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Invalid parameters for ${toolName}: ${JSON.stringify(
        result.error.issues,
        null,
        2,
      )}`,
    }
  }

  if (endsAgentStepParam in result.data) {
    delete result.data[endsAgentStepParam]
  }

  return {
    toolName: toolName,
    input: result.data,
    toolCallId: rawToolCall.toolCallId,
  }
}

export function executeCustomToolCall({
  toolName,
  input,
  toolCalls,
  toolResults,
  previousToolCallFinished,
  ws,
  agentTemplate,
  fileContext,
  clientSessionId,
  userInputId,
  onResponseChunk,
  state,
  userId,
  autoInsertEndStepParam = false,
}: ExecuteToolCallParams<string>): Promise<void> {
  const toolCall: CustomToolCall | ToolCallError = parseRawCustomToolCall(
    fileContext.customToolDefinitions,
    {
      toolName,
      toolCallId: generateCompactId(),
      input,
    },
    autoInsertEndStepParam,
  )
  if ('error' in toolCall) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: toolCall.error,
      },
    })
    logger.debug(
      { toolCall, error: toolCall.error },
      `${toolName} error: ${toolCall.error}`,
    )
    return previousToolCallFinished
  }

  onResponseChunk({
    type: 'tool_call',
    toolCallId: toolCall.toolCallId,
    toolName,
    input: toolCall.input,
  })

  logger.debug(
    { toolCall },
    `${toolName} (${toolCall.toolCallId}) custom tool call detected in stream`,
  )
  toolCalls.push(toolCall)

  // Filter out restricted tools in ask mode unless exporting summary
  if (!(agentTemplate.toolNames as string[]).includes(toolCall.toolName)) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: `Tool \`${toolName}\` is not currently available. Make sure to only use tools listed in the system instructions.`,
      },
    })
    return previousToolCallFinished
  }

  return previousToolCallFinished
    .then(async () => {
      if (!checkLiveUserInput(userId, userInputId, clientSessionId)) {
        return ''
      }

      const clientToolResult = await requestToolCall(
        ws,
        userInputId,
        toolCall.toolName,
        toolCall.input,
      )
      return (
        clientToolResult.error ??
        (clientToolResult.output?.type === 'text'
          ? clientToolResult.output.value
          : 'undefined')
      )
    })
    .then((result) => {
      const toolResult = {
        toolName,
        toolCallId: toolCall.toolCallId,
        output: {
          type: 'text' as const,
          value: result as string,
        },
      }
      logger.debug(
        { toolResult },
        `${toolName} (${toolResult.toolCallId}) custom tool result for tool`,
      )
      if (result === undefined) {
        return
      }

      onResponseChunk({
        type: 'tool_result',
        toolCallId: toolResult.toolCallId,
        output: toolResult.output,
      })

      toolResults.push(toolResult)

      state.messages.push({
        role: 'user' as const,
        content: asSystemMessage(renderToolResults([toolResult])),
      })
    })
}

import { initialSessionState, type RunState } from './run-state'
import { changeFile } from './tools/change-file'
import { getFiles } from './tools/read-files'
import { runTerminalCommand } from './tools/run-terminal-command'
import { WebSocketHandler } from './websocket-client'
import {
  PromptResponseSchema,
  type ServerAction,
} from '../../common/src/actions'
import { API_KEY_ENV_VAR } from '../../common/src/constants'
import { DEFAULT_MAX_AGENT_STEPS } from '../../common/src/json-config/constants'
import { toolNames } from '../../common/src/tools/constants'

import type { CustomToolDefinition } from './custom-tool'
import type { AgentDefinition } from '../../common/src/templates/initial-agents-dir/types/agent-definition'
import type { ToolName } from '../../common/src/tools/constants'
import type { PrintModeEvent } from '../../common/src/types/print-mode'

type ClientToolName = 'write_file' | 'run_terminal_command'

export type CodebuffClientOptions = {
  // Provide an API key or set the CODEBUFF_API_KEY environment variable.
  apiKey?: string
  cwd: string
  onError: (error: { message: string }) => void
  overrideTools?: Partial<
    Record<
      ClientToolName,
      (
        input: ServerAction<'tool-call-request'>['input'],
      ) => Promise<{ toolResultMessage: string }>
    > & {
      // Include read_files separately, since it has a different signature.
      read_files: (
        filePath: string[],
      ) => Promise<{ files: Record<string, string | null> }>
    }
  >
}

export class CodebuffClient {
  public cwd: string

  private readonly websocketHandler: WebSocketHandler
  private readonly overrideTools: NonNullable<
    CodebuffClientOptions['overrideTools']
  >
  private readonly fingerprintId = `codebuff-sdk-${Math.random().toString(36).substring(2, 15)}`

  private readonly promptIdToHandleEvent: Record<
    string,
    (event: PrintModeEvent) => void
  > = {}
  private readonly promptIdToResolveResponse: Record<
    string,
    { resolve: (response: any) => void; reject: (error: any) => void }
  > = {}
  private readonly promptIdToCustomToolHandler: Record<
    string,
    WebSocketHandler['handleToolCall']
  > = {}

  constructor({ apiKey, cwd, onError, overrideTools }: CodebuffClientOptions) {
    const foundApiKey = apiKey ?? process.env[API_KEY_ENV_VAR]
    if (!foundApiKey) {
      throw new Error(
        `Codebuff API key not found. Please provide an apiKey in the constructor of CodebuffClient or set the ${API_KEY_ENV_VAR} environment variable.`,
      )
    }

    this.cwd = cwd
    this.overrideTools = overrideTools ?? {}
    this.websocketHandler = new WebSocketHandler({
      apiKey: foundApiKey,
      onWebsocketError: (error) => {
        onError({ message: error.message })
      },
      onWebsocketReconnect: () => {},
      onRequestReconnect: async () => {},
      onResponseError: async (error) => {
        onError({ message: error.message })
      },
      readFiles: this.readFiles.bind(this),
      handleToolCall: this.handleToolCall.bind(this),
      onCostResponse: async () => {},

      onResponseChunk: async (action) => {
        const { userInputId, chunk } = action
        const handleEvent = this.promptIdToHandleEvent[userInputId]
        if (handleEvent && typeof chunk === 'object') {
          handleEvent(chunk)
        }
      },
      onSubagentResponseChunk: async () => {},

      onPromptResponse: this.handlePromptResponse.bind(this),
    })
  }

  public closeConnection() {
    this.websocketHandler.close()
  }

  /**
   * Run a Codebuff agent with the specified options.
   *
   * @param agent - The agent to run. Use 'base' for the default agent, or specify a custom agent ID if you made your own agent config.
   * @param prompt - The user prompt describing what you want the agent to do.
   * @param params - (Optional) Additional parameters for the agent. Most agents don't use this, but some custom agents can take a JSON object as input in addition to the user prompt string.
   * @param handleEvent - (Optional) Callback function that receives every event during execution (assistant messages, tool calls, etc.). This allows you to stream the agent's progress in real-time. We will likely add a token-by-token streaming callback in the future.
   * @param previousRun - (Optional) JSON state returned from a previous run() call. Use this to continue a conversation or session with the agent, maintaining context from previous interactions.
   * @param projectFiles - (Optional) All the files in your project as a plain JavaScript object. Keys should be the full path from your current directory to each file, and values should be the string contents of the file. Example: { "src/index.ts": "console.log('hi')" }. This helps Codebuff pick good source files for context.
   * @param knowledgeFiles - (Optional) Knowledge files to inject into every run() call. Uses the same schema as projectFiles - keys are file paths and values are file contents. These files are added directly to the agent's context.
   * @param agentDefinitions - (Optional) Array of custom agent definitions. Each object should satisfy the AgentDefinition type. You can input the agent's id field into the agent parameter to run that agent.
   * @param maxAgentSteps - (Optional) Maximum number of steps the agent can take before stopping. Use this as a safety measure in case your agent starts going off the rails. A reasonable number is around 20.
   *
   * @returns A Promise that resolves to a RunState JSON object which you can pass to a subsequent run() call to continue the run.
   */
  public async run({
    agent,
    prompt,
    params,
    handleEvent,
    previousRun,
    projectFiles,
    knowledgeFiles,
    agentDefinitions,
    customToolDefinitions,
    maxAgentSteps = DEFAULT_MAX_AGENT_STEPS,
  }: {
    agent: string
    prompt: string
    params?: Record<string, any>
    handleEvent?: (event: PrintModeEvent) => void
    previousRun?: RunState
    projectFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentDefinitions?: AgentDefinition[]
    customToolDefinitions?: CustomToolDefinition[]
    maxAgentSteps?: number
  }): Promise<RunState> {
    await this.websocketHandler.connect()

    const promptId = Math.random().toString(36).substring(2, 15)
    const sessionState =
      previousRun?.sessionState ??
      initialSessionState(this.cwd, {
        knowledgeFiles,
        agentDefinitions,
        customToolDefinitions,
        projectFiles,
        maxAgentSteps,
      })
    sessionState.mainAgentState.stepsRemaining = maxAgentSteps
    const toolResults = previousRun?.toolResults ?? []
    if (handleEvent) {
      this.promptIdToHandleEvent[promptId] = handleEvent
    }
    if (customToolDefinitions) {
      this.promptIdToCustomToolHandler[promptId] = async ({
        toolName,
        input,
      }) => {
        const toolDefs = customToolDefinitions.filter(
          (def) => def.toolName === toolName,
        )
        if (toolDefs.length === 0) {
          throw new Error(
            `Implementation for custom tool ${toolName} not found.`,
          )
        }
        const handler = toolDefs[toolDefs.length - 1].handler
        try {
          return {
            success: true,
            output: {
              type: 'text',
              value: (await handler(input)).toolResultMessage,
            },
          }
        } catch (error) {
          return {
            success: false,
            output: {
              type: 'text',
              value:
                error &&
                typeof error === 'object' &&
                'message' in error &&
                typeof error.message === 'string'
                  ? error.message
                  : typeof error === 'string'
                    ? error
                    : 'Unknown error',
            },
          }
        }
      }
    }
    this.websocketHandler.sendInput({
      promptId,
      prompt,
      promptParams: params,
      fingerprintId: this.fingerprintId,
      costMode: 'normal',
      sessionState,
      toolResults,
      agentId: agent,
    })

    return new Promise<RunState>((resolve, reject) => {
      this.promptIdToResolveResponse[promptId] = { resolve, reject }
    })
  }

  private async handlePromptResponse(action: ServerAction<'prompt-response'>) {
    const promiseActions =
      this.promptIdToResolveResponse[action?.promptId ?? '']

    const parsedAction = PromptResponseSchema.safeParse(action)
    if (!parsedAction.success) {
      const message = [
        'Received invalid prompt response from server:',
        JSON.stringify(parsedAction.error.issues),
        'If this issues persists, please contact support@codebuff.com',
      ].join('\n')
      if (promiseActions) {
        promiseActions.reject(new Error(message))
      }
      return
    }

    if (promiseActions) {
      const { sessionState, toolResults } = parsedAction.data
      const state: RunState = {
        sessionState,
        toolResults,
      }
      promiseActions.resolve(state)

      delete this.promptIdToResolveResponse[action.promptId]
      delete this.promptIdToHandleEvent[action.promptId]
      delete this.promptIdToCustomToolHandler[action.promptId]
    }
  }

  private async readFiles(filePath: string[]) {
    const override = this.overrideTools.read_files
    if (override) {
      const overrideResult = await override(filePath)
      return overrideResult.files
    }
    return getFiles(filePath, this.cwd)
  }

  private async handleToolCall(
    action: ServerAction<'tool-call-request'>,
  ): ReturnType<WebSocketHandler['handleToolCall']> {
    const toolName = action.toolName
    const input = action.input

    let result: string
    if (!toolNames.includes(toolName as ToolName)) {
      return this.promptIdToCustomToolHandler[action.userInputId](action)
    }

    try {
      let override = this.overrideTools[toolName as ClientToolName]
      if (!override && toolName === 'str_replace') {
        // Note: write_file and str_replace have the same implementation, so reuse their write_file override.
        override = this.overrideTools['write_file']
      }
      if (override) {
        const overrideResult = await override(input)
        result = overrideResult.toolResultMessage
      } else if (toolName === 'end_turn') {
        result = ''
      } else if (toolName === 'write_file' || toolName === 'str_replace') {
        const r = changeFile(input, this.cwd)
        result = r.toolResultMessage
      } else if (toolName === 'run_terminal_command') {
        const r = await runTerminalCommand({
          ...input,
          cwd: input.cwd ?? this.cwd,
        } as Parameters<typeof runTerminalCommand>[0])
        result = r.output
      } else {
        throw new Error(
          `Tool not implemented in SDK. Please provide an override or modify your agent to not use this tool: ${toolName}`,
        )
      }
    } catch (error) {
      return {
        success: false,
        output: {
          type: 'text',
          value:
            error &&
            typeof error === 'object' &&
            'message' in error &&
            typeof error.message === 'string'
              ? error.message
              : typeof error === 'string'
                ? error
                : 'Unknown error',
        },
      }
    }
    return {
      success: true,
      output: {
        type: 'text',
        value: result,
      },
    }
  }
}

