describe('runAgentStep - set_output tool', () => {
  let testAgent: AgentTemplate

  beforeAll(() => {
    // Mock logger
    mockModule('@codebuff/backend/util/logger', () => ({
      logger: {
        debug: () => {},
        error: () => {},
