    await OriginalRequestFilesPromptModule.requestRelevantFiles(
      { messages: mockMessages, system: mockSystem },
      mockFileContext,
      mockAssistantPrompt,
      mockAgentStepId,
      mockClientSessionId,
      mockFingerprintId,
      mockUserInputId,
      mockUserId,
      mockRepoId,
