    expect(result).toBeNull()
    expect(
      geminiWithFallbacksModule.promptFlashWithFallbacks,
    ).not.toHaveBeenCalled()
    expect(getCustomFilePickerConfigForOrgSpy).toHaveBeenCalled()
  })
