import { AGENT_PERSONAS } from '../constants/agents'

export interface AgentInfo {
  id: string
  displayName: string
  purpose?: string
  isBuiltIn: boolean
}

/**
 * Get all built-in agents (excluding hidden ones)
 */
export function getBuiltInAgents(): AgentInfo[] {
  return Object.entries(AGENT_PERSONAS)
    .filter(([, persona]) => !('hidden' in persona) || !persona.hidden)
    .map(([agentId, persona]) => ({
      id: agentId,
      displayName: persona.displayName,
      purpose: persona.purpose,
      isBuiltIn: true,
    }))
}

/**
 * Convert local agent configs to AgentInfo array
 */
export function getLocalAgents(
  localAgents: Record<string, { displayName: string; purpose?: string }>,
): AgentInfo[] {
  return Object.entries(localAgents).map(([agentId, config]) => ({
    id: agentId,
    displayName: config.displayName,
    purpose: config.purpose,
    isBuiltIn: false,
  }))
}

/**
 * Get all agents (built-in + local)
 */
export function getAllAgents(
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): AgentInfo[] {
  return [...getBuiltInAgents(), ...getLocalAgents(localAgents)]
}

/**
 * Resolve display name to agent ID
 */
export function resolveNameToId(
  displayName: string,
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): string | null {
  const agents = getAllAgents(localAgents)
  const agent = agents.find(
    (a) => a.displayName.toLowerCase() === displayName.toLowerCase(),
  )
  return agent?.id || null
}

/**
 * Resolve agent ID to display name
 */
function resolveIdToName(
  agentId: string,
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): string | null {
  const agents = getAllAgents(localAgents)
  const agent = agents.find((a) => a.id === agentId)
  return agent?.displayName || null
}

/**
 * Get agent display name from ID or name, with fallback
 */
export function getAgentDisplayName(
  agentIdOrName: string,
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): string {
  return (
    resolveIdToName(agentIdOrName, localAgents) ||
    (resolveNameToId(agentIdOrName, localAgents)
      ? agentIdOrName
      : agentIdOrName)
  )
}

/**
 * Utility functions for working with agent template files
 */

import type { DynamicAgentTemplate } from '../types/dynamic-agent-template'

/**
 * Determines if a file is a valid custom agent template file.
 *
 * Custom agent files must:
 * - End with .ts extension
 * - NOT end with .d.ts (TypeScript declaration files)
 *
 * @param fileName - The name of the file to check
 * @returns true if the file is a valid custom agent template
 */
export function isCustomAgentFile(fileName: string): boolean {
  return fileName.endsWith('.ts') && !fileName.endsWith('.d.ts')
}

/**
 * Filters a list of file names to only include valid custom agent template files.
 *
 * @param fileNames - Array of file names to filter
 * @returns Array of file names that are valid custom agent templates
 */
export function filterCustomAgentFiles(fileNames: string[]): string[] {
  return fileNames.filter(isCustomAgentFile)
}

/**
 * Filters an object of file paths/templates to only include valid custom agent templates.
 *
 * @param agentTemplates - Object with file paths as keys
 * @returns Filtered object containing only valid custom agent templates
 */
export function filterCustomAgentTemplates<T>(
  agentTemplates: Record<string, T>,
): Record<string, T> {
  return Object.fromEntries(
    Object.entries(agentTemplates).filter(([filePath]) =>
      isCustomAgentFile(filePath),
    ),
  )
}

/**
 * Extracts the agent ID from a TypeScript file name.
 *
 * @param fileName - The TypeScript file name (e.g., 'my-agent.ts')
 * @returns The agent ID (e.g., 'my-agent')
 */
export function extractAgentIdFromFileName(fileName: string): string {
  return fileName.replace('.ts', '')
}

/**
 * Filters agent templates to include only valid ones, excluding generated files and invalid entries.
 *
 * This method handles various edge cases:
 * - TypeScript declaration files (.d.ts) generated by tools
 * - Frontend key normalization (strips .ts extensions)
 * - Files without extensions
 * - Invalid or empty template data
 *
 * @param agentTemplates - Object with file paths as keys and templates as values
 * @returns Filtered object containing only valid agent templates
 */
export function filterValidAgentTemplates(
  agentTemplates: Record<string, DynamicAgentTemplate>,
): Record<string, DynamicAgentTemplate> {
  return Object.fromEntries(
    Object.entries(agentTemplates).filter(([key, template]) => {
      // Skip if no template data
      if (!template) {
        return false
      }

      // Skip TypeScript declaration files (.d.ts) - these are generated artifacts
      if (key.endsWith('.d.ts')) {
        return false
      }

      // Skip files with invalid extensions (but allow files without extensions)
      // This handles cases where frontend strips .ts but we want to exclude other extensions
      if (key.includes('.') && !key.endsWith('.ts')) {
        // Allow common valid extensions for agent templates
        const validExtensions = ['.ts', '.js', '.mjs']
        const hasValidExtension = validExtensions.some((ext) =>
          key.endsWith(ext),
        )
        if (!hasValidExtension) {
          return false
        }
      }

      // Skip if template doesn't have required fields
      if (!template.id || typeof template.id !== 'string') {
        return false
      }

      // Skip if template has invalid structure
      if (typeof template !== 'object') {
        return false
      }

      return true
    }),
  )
}

import { z } from 'zod/v4'

import { ALLOWED_MODEL_PREFIXES, models } from '../constants'
import { toolNames } from '../tools/constants'

import type { JSONSchema } from 'zod/v4/core'

// Filter models to only include those that begin with allowed prefixes
const filteredModels = Object.values(models).filter((model) =>
  ALLOWED_MODEL_PREFIXES.some((prefix) => model.startsWith(prefix)),
)

if (filteredModels.length === 0) {
  throw new Error('No valid models found with allowed prefixes')
}

// Simplified JSON Schema definition - supports object schemas with nested properties
const JsonSchemaSchema: z.ZodType<
  JSONSchema.BaseSchema,
  JSONSchema.BaseSchema
> = z.lazy(() =>
  z.looseObject({
    type: z
      .enum([
        'object',
        'array',
        'string',
        'number',
        'boolean',
        'null',
        'integer',
      ])
      .optional(),
    description: z.string().optional(),
    properties: z
      .record(z.string(), JsonSchemaSchema.or(z.boolean()))
      .optional(),
    required: z.string().array().optional(),
    enum: z
      .union([z.string(), z.number(), z.boolean(), z.null()])
      .array()
      .optional(),
  }),
)
const JsonObjectSchemaSchema = z.intersection(
  JsonSchemaSchema,
  z.object({ type: z.literal('object') }),
)

// Schema for the combined inputSchema object
const InputSchemaObjectSchema = z
  .looseObject({
    prompt: z
      .looseObject({
        type: z.literal('string'),
        description: z.string().optional(),
      })
      .optional(), // Optional JSON schema for prompt validation
    params: JsonObjectSchemaSchema.optional(), // Optional JSON schema for params validation
  })
  .optional()

// Schema for prompt fields that can be either a string or a path reference
const PromptFieldSchema = z.union([
  z.string(), // Direct string content
  z.object({ path: z.string() }), // Path reference to external file
])
export type PromptField = z.infer<typeof PromptFieldSchema>

const functionSchema = <T extends z.core.$ZodFunction>(schema: T) =>
  z.custom<Parameters<T['implement']>[0]>((fn: any) => schema.implement(fn))
// Schema for validating handleSteps function signature
const HandleStepsSchema = functionSchema(
  z.function({
    input: [
      z.object({
        agentState: z.object({
          agentId: z.string(),
          parentId: z.string(),
          messageHistory: z.array(z.any()),
        }),
        prompt: z.string().optional(),
        params: z.any().optional(),
      }),
    ],
    output: z.any(),
  }),
).optional()

// Validates the Typescript template file.
export const DynamicAgentDefinitionSchema = z.object({
  id: z
    .string()
    .regex(
      /^[a-z0-9-]+$/,
      'Agent ID must contain only lowercase letters, numbers, and hyphens',
    ), // The unique identifier for this agent
  version: z.string().optional(),
  publisher: z.string().optional(),

  // Required fields for new agents
  displayName: z.string(),
  model: z.string(),
  reasoningOptions: z
    .object({
      enabled: z.boolean().optional(),
      exclude: z.boolean().optional(),
    })
    .and(
      z.union([
        z.object({ max_tokens: z.number() }),
        z.object({ effort: z.enum(['high', 'medium', 'low']) }),
      ]),
    )
    .optional(),

  // Tools and spawnable agents
  toolNames: z.array(z.enum(toolNames)).optional().default([]),
  spawnableAgents: z.array(z.string()).optional().default([]),

  // Input and output
  inputSchema: InputSchemaObjectSchema,
  includeMessageHistory: z.boolean().default(false),
  outputMode: z
    .enum(['last_message', 'all_messages', 'structured_output'])
    .default('last_message'),
  outputSchema: JsonObjectSchemaSchema.optional(), // Optional JSON schema for output validation

  // Prompts
  spawnerPrompt: z.string().optional(),
  systemPrompt: z.string().optional(),
  instructionsPrompt: z.string().optional(),
  stepPrompt: z.string().optional(),

  // Optional generator function for programmatic agents
  handleSteps: z.union([z.string(), HandleStepsSchema]).optional(),
})
export type DynamicAgentDefinition = z.input<
  typeof DynamicAgentDefinitionSchema
>
export type DynamicAgentDefinitionParsed = z.infer<
  typeof DynamicAgentDefinitionSchema
>

export const DynamicAgentTemplateSchema = DynamicAgentDefinitionSchema.extend({
  systemPrompt: z.string(),
  instructionsPrompt: z.string(),
  stepPrompt: z.string(),
  handleSteps: z.string().optional(), // Converted to string after processing
})
  .refine(
    (data) => {
      // If outputSchema is provided, outputMode must be explicitly set to 'structured_output'
      if (data.outputSchema && data.outputMode !== 'structured_output') {
        return false
      }
      return true
    },
    {
      message:
        "outputSchema requires outputMode to be explicitly set to 'structured_output'.",
      path: ['outputMode'],
    },
  )
  .refine(
    (data) => {
      // If outputMode is 'structured_output', 'set_output' tool must be included
      if (
        data.outputMode === 'structured_output' &&
        !data.toolNames.includes('set_output')
      ) {
        return false
      }
      return true
    },
    {
      message:
        "outputMode 'structured_output' requires the 'set_output' tool. Add 'set_output' to toolNames.",
      path: ['toolNames'],
    },
  )
  .refine(
    (data) => {
      // If 'set_output' tool is included, outputMode must be 'structured_output'
      if (
        data.toolNames.includes('set_output') &&
        data.outputMode !== 'structured_output'
      ) {
        return false
      }
      return true
    },
    {
      message:
        "'set_output' tool requires outputMode to be 'structured_output'. Change outputMode to 'structured_output' or remove 'set_output' from toolNames.",
      path: ['outputMode'],
    },
  )
  .refine(
    (data) => {
      // If spawnableAgents array is non-empty, 'spawn_agents' tool must be included
      if (
        data.spawnableAgents.length > 0 &&
        !data.toolNames.includes('spawn_agents')
      ) {
        return false
      }
      return true
    },
    {
      message:
        "Non-empty spawnableAgents array requires the 'spawn_agents' tool. Add 'spawn_agents' to toolNames or remove spawnableAgents.",
      path: ['toolNames'],
    },
  )
export type DynamicAgentTemplate = z.infer<typeof DynamicAgentTemplateSchema>

import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { and, desc, eq } from 'drizzle-orm'

import { ProjectFileContext } from '@codebuff/common/util/file'
import { logger } from '../util/logger'
import {
  DynamicAgentValidationError,
  validateAgents,
  validateSingleAgent,
} from '@codebuff/common/templates/agent-validation'
import { DynamicAgentTemplate } from '@codebuff/common/types/dynamic-agent-template'
import { DEFAULT_ORG_PREFIX } from '@codebuff/common/util/agent-name-normalization'
import { parsePublishedAgentId } from '@codebuff/common/util/agent-id-parsing'

export type AgentRegistry = Record<string, AgentTemplate>

// Global database cache - only state in the system
const databaseAgentCache = new Map<string, AgentTemplate | null>()

/**
 * Fetch an agent from the database by publisher/agent-id[@version] format
 */
async function fetchAgentFromDatabase(parsedAgentId: {
  publisherId: string
  agentId: string
  version?: string
}): Promise<AgentTemplate | null> {
  const { publisherId, agentId, version } = parsedAgentId

  try {
    let agentConfig

    if (version && version !== 'latest') {
      // Query for specific version
      agentConfig = await db
        .select()
        .from(schema.agentConfig)
        .where(
          and(
            eq(schema.agentConfig.id, agentId),
            eq(schema.agentConfig.publisher_id, publisherId),
            eq(schema.agentConfig.version, version),
          ),
        )
        .then((rows) => rows[0])
    } else {
      // Query for latest version
      agentConfig = await db
        .select()
        .from(schema.agentConfig)
        .where(
          and(
            eq(schema.agentConfig.id, agentId),
            eq(schema.agentConfig.publisher_id, publisherId),
          ),
        )
        .orderBy(
          desc(schema.agentConfig.major),
          desc(schema.agentConfig.minor),
          desc(schema.agentConfig.patch),
        )
        .limit(1)
        .then((rows) => rows[0])
    }

    if (!agentConfig) {
      logger.debug(
        { publisherId, agentId, version },
        'fetchAgentFromDatabase: Agent not found in database',
      )
      return null
    }

    const rawAgentData = agentConfig.data as DynamicAgentTemplate

    // Validate the raw agent data with the original agentId (not full identifier)
    const validationResult = validateSingleAgent(
      { ...rawAgentData, id: agentId },
      {
        filePath: `${publisherId}/${agentId}@${agentConfig.version}`,
        skipSubagentValidation: true,
      },
    )

    if (!validationResult.success) {
      logger.error(
        {
          publisherId,
          agentId,
          version: agentConfig.version,
          error: validationResult.error,
        },
        'fetchAgentFromDatabase: Agent validation failed',
      )
      return null
    }

    // Set the correct full agent ID for the final template
    const agentTemplate = {
      ...validationResult.agentTemplate!,
      id: `${publisherId}/${agentId}@${agentConfig.version}`,
    }

    logger.debug(
      {
        publisherId,
        agentId,
        version: agentConfig.version,
        fullAgentId: agentTemplate.id,
      },
      'fetchAgentFromDatabase: Successfully loaded and validated agent from database',
    )

    return agentTemplate
  } catch (error) {
    logger.error(
      { publisherId, agentId, version, error },
      'fetchAgentFromDatabase: Error fetching agent from database',
    )
    return null
  }
}

/**
 * Single function to look up an agent template with clear priority order:
 * 1. localAgentTemplates (dynamic agents + static templates)
 * 2. Database cache
 * 3. Database query
 */
export async function getAgentTemplate(
  agentId: string,
  localAgentTemplates: Record<string, AgentTemplate>,
): Promise<AgentTemplate | null> {
  // 1. Check localAgentTemplates first (dynamic agents + static templates)
  if (localAgentTemplates[agentId]) {
    return localAgentTemplates[agentId]
  }
  // 2. Check database cache
  const cacheKey = agentId
  if (databaseAgentCache.has(cacheKey)) {
    return databaseAgentCache.get(cacheKey) || null
  }

  const parsed = parsePublishedAgentId(agentId)
  if (!parsed) {
    // If agentId doesn't parse as publisher/agent format, try as codebuff/agentId
    const codebuffParsed = parsePublishedAgentId(
      `${DEFAULT_ORG_PREFIX}${agentId}`,
    )
    if (codebuffParsed) {
      const dbAgent = await fetchAgentFromDatabase(codebuffParsed)
      if (dbAgent) {
        databaseAgentCache.set(cacheKey, dbAgent)
        return dbAgent
      }
    }
    logger.debug({ agentId }, 'getAgentTemplate: Failed to parse agent ID')
    return null
  }

  // 3. Query database (only for publisher/agent-id format)
  const dbAgent = await fetchAgentFromDatabase(parsed)
  if (dbAgent && parsed.version && parsed.version !== 'latest') {
    // Cache only specific versions to avoid stale 'latest' results
    databaseAgentCache.set(cacheKey, dbAgent)
  }
  return dbAgent
}

/**
 * Assemble local agent templates from fileContext + static templates
 */
export function assembleLocalAgentTemplates(fileContext: ProjectFileContext): {
  agentTemplates: Record<string, AgentTemplate>
  validationErrors: DynamicAgentValidationError[]
} {
  // Load dynamic agents using the service
  const { templates: dynamicTemplates, validationErrors } = validateAgents(
    fileContext.agentTemplates || {},
  )

  // Use dynamic templates only

  const agentTemplates = { ...dynamicTemplates }
  return { agentTemplates, validationErrors }
}

/**
 * Clear the database agent cache (useful for testing)
 */
export function clearDatabaseCache(): void {
  databaseAgentCache.clear()
}

import { MAX_AGENT_STEPS_DEFAULT } from '@codebuff/common/constants/agents'
import { generateCompactId } from '@codebuff/common/util/string'
import { parseAgentId } from '@codebuff/common/util/agent-id-parsing'

import { getAgentTemplate } from '../../../templates/agent-registry'
import { logger } from '../../../util/logger'

import type { CodebuffToolHandlerFunction } from '../handler-function-type'
import type { CodebuffToolCall } from '@codebuff/common/tools/list'
import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import type { CodebuffMessage } from '@codebuff/common/types/message'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  AgentState,
  AgentTemplateType,
} from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'
import type { WebSocket } from 'ws'

export type SendSubagentChunk = (data: {
  userInputId: string
  agentId: string
  agentType: string
  chunk: string
  prompt?: string
}) => void

export const handleSpawnAgents = ((params: {
  previousToolCallFinished: Promise<void>
  toolCall: CodebuffToolCall<'spawn_agents'>

  fileContext: ProjectFileContext
  clientSessionId: string
  userInputId: string

  getLatestState: () => { messages: CodebuffMessage[] }
  state: {
    ws?: WebSocket
    fingerprintId?: string
    userId?: string
    agentTemplate?: AgentTemplate
    localAgentTemplates?: Record<string, AgentTemplate>
    sendSubagentChunk?: SendSubagentChunk
    messages?: CodebuffMessage[]
    agentState?: AgentState
  }
}): { result: Promise<string>; state: {} } => {
  const {
    previousToolCallFinished,
    toolCall,

    fileContext,
    clientSessionId,
    userInputId,
    getLatestState,
    state,
  } = params
  const { agents } = toolCall.input
  const {
    ws,
    fingerprintId,
    userId,
    agentTemplate: parentAgentTemplate,
    localAgentTemplates,
    sendSubagentChunk,
    messages,
  } = state
  let { agentState } = state

  if (!ws) {
    throw new Error(
      'Internal error for spawn_agents: Missing WebSocket in state',
    )
  }
  if (!fingerprintId) {
    throw new Error(
      'Internal error for spawn_agents: Missing fingerprintId in state',
    )
  }
  if (!parentAgentTemplate) {
    throw new Error(
      'Internal error for spawn_agents: Missing agentTemplate in state',
    )
  }
  if (!sendSubagentChunk) {
    throw new Error(
      'Internal error for spawn_agents: Missing sendSubagentChunk in state',
    )
  }
  if (!messages) {
    throw new Error(
      'Internal error for spawn_agents: Missing messages in state',
    )
  }
  if (!agentState) {
    throw new Error(
      'Internal error for spawn_agents: Missing agentState in state',
    )
  }
  if (!localAgentTemplates) {
    throw new Error(
      'Internal error for spawn_agents: Missing localAgentTemplates in state',
    )
  }

  const triggerSpawnAgents = async () => {
    const conversationHistoryMessage: CodebuffMessage = {
      role: 'user',
      content: `For context, the following is the conversation history between the user and an assistant:\n\n${JSON.stringify(
        getLatestState().messages,
        null,
        2,
      )}`,
    }
    const results = await Promise.allSettled(
      agents.map(async ({ agent_type: agentTypeStr, prompt, params }) => {
        const agentTemplate = await getAgentTemplate(
          agentTypeStr,
          localAgentTemplates,
        )

        if (!agentTemplate) {
          throw new Error(`Agent type ${agentTypeStr} not found.`)
        }

        const agentType = getMatchingSpawn(
          parentAgentTemplate.spawnableAgents,
          agentTypeStr,
        )
        if (!agentType) {
          throw new Error(
            `Agent type ${parentAgentTemplate.id} is not allowed to spawn child agent type ${agentTypeStr}.`,
          )
        }

        // Validate prompt and params against agent's schema
        const { inputSchema } = agentTemplate

        // Validate prompt requirement
        if (inputSchema.prompt) {
          const result = inputSchema.prompt.safeParse(prompt)
          if (!result.success) {
            throw new Error(
              `Invalid prompt for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
            )
          }
        }

        // Validate params if schema exists
        if (inputSchema.params) {
          const result = inputSchema.params.safeParse(params)
          if (!result.success) {
            throw new Error(
              `Invalid params for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
            )
          }
        }

        const agentId = generateCompactId()
        const subAgentMessages: CodebuffMessage[] = []
        if (agentTemplate.includeMessageHistory) {
          subAgentMessages.push(conversationHistoryMessage)
        }

        const subAgentState: AgentState = {
          agentId,
          agentType,
          agentContext: {},
          subagents: [],
          messageHistory: subAgentMessages,
          stepsRemaining: MAX_AGENT_STEPS_DEFAULT,
          output: undefined,
          parentId: agentState!.agentId,
        }

        logger.debug(
          {
            agentTemplate,
            prompt,
            params,
            agentId,
            parentId: subAgentState.parentId,
          },
          `Spawning agent — ${agentType} (${agentId})`,
        )

        // Import loopAgentSteps dynamically to avoid circular dependency
        const { loopAgentSteps } = await import('../../../run-agent-step')

        const result = await loopAgentSteps(ws, {
          userInputId: `${userInputId}-${agentType}${agentId}`,
          prompt: prompt || '',
          params,
          agentType: agentTemplate.id,
          agentState: subAgentState,
          fingerprintId,
          fileContext,
          localAgentTemplates,
          toolResults: [],
          userId,
          clientSessionId,
          onResponseChunk: (chunk: string | PrintModeEvent) => {
            if (typeof chunk !== 'string') {
              return
            }
            // Send subagent streaming chunks to client
            sendSubagentChunk({
              userInputId,
              agentId,
              agentType,
              chunk,
              prompt,
            })
          },
        })

        return {
          ...result,
          agentType,
          agentName: agentTemplate.displayName,
        }
      }),
    )

    const reports = await Promise.all(
      results.map(async (result, index) => {
        const agentInfo = agents[index]
        const agentTypeStr = agentInfo.agent_type

        if (result.status === 'fulfilled') {
          const { agentState, agentName } = result.value
          const agentTemplate = await getAgentTemplate(
            agentState.agentType!,
            localAgentTemplates,
          )
          if (!agentTemplate) {
            return `**Agent (${agentTypeStr}):**\nError: Could not find agent template for ${agentState.agentType!}`
          }
          let report = ''

          if (agentTemplate.outputMode === 'structured_output') {
            report = JSON.stringify(result.value.agentState.output, null, 2)
          } else if (agentTemplate.outputMode === 'last_message') {
            const { agentState } = result.value
            const assistantMessages = agentState.messageHistory.filter(
              (message) => message.role === 'assistant',
            )
            const lastAssistantMessage =
              assistantMessages[assistantMessages.length - 1]
            if (!lastAssistantMessage) {
              report = 'No response from agent'
            } else if (typeof lastAssistantMessage.content === 'string') {
              report = lastAssistantMessage.content
            } else {
              report = JSON.stringify(lastAssistantMessage.content, null, 2)
            }
          } else if (agentTemplate.outputMode === 'all_messages') {
            const { agentState } = result.value
            // Remove the first message, which includes the previous conversation history.
            const agentMessages = agentState.messageHistory.slice(1)
            report = `Agent messages:\n\n${JSON.stringify(agentMessages, null, 2)}`
          } else {
            throw new Error(
              `Unknown output mode: ${'outputMode' in agentTemplate ? agentTemplate.outputMode : 'undefined'}`,
            )
          }

          return `**${agentName}:**\n${report}`
        } else {
          return `**Agent (${agentTypeStr}):**\nError spawning agent: ${result.reason}`
        }
      }),
    )
    return reports
      .map((report: string) => `<agent_report>${report}</agent_report>`)
      .join('\n')
  }

  return {
    result: previousToolCallFinished.then(triggerSpawnAgents),
    state: {},
  }
}) satisfies CodebuffToolHandlerFunction<'spawn_agents'>

const getMatchingSpawn = (
  spawnableAgents: AgentTemplateType[],
  childFullAgentId: string,
) => {
  const {
    publisherId: childPublisherId,
    agentId: childAgentId,
    version: childVersion,
  } = parseAgentId(childFullAgentId)

  if (!childAgentId) {
    return null
  }

  for (const spawnableAgent of spawnableAgents) {
    const {
      publisherId: spawnablePublisherId,
      agentId: spawnableAgentId,
      version: spawnableVersion,
    } = parseAgentId(spawnableAgent)

    if (!spawnableAgentId) {
      continue
    }

    if (
      spawnableAgentId === childAgentId &&
      spawnablePublisherId === childPublisherId &&
      spawnableVersion === childVersion
    ) {
      return spawnableAgent
    }
    if (!childVersion && childPublisherId) {
      if (
        spawnablePublisherId === childPublisherId &&
        spawnableAgentId === childAgentId
      ) {
        return spawnableAgent
      }
    }
    if (!childPublisherId && childVersion) {
      if (
        spawnableAgentId === childAgentId &&
        spawnableVersion === childVersion
      ) {
        return spawnableAgent
      }
    }

    if (!childVersion && !childPublisherId) {
      if (spawnableAgentId === childAgentId) {
        return spawnableAgent
      }
    }
  }
  return null
}

/**
 * Parse agent ID to extract publisher, agent name, and version
 * Supports formats:
 * - publisher/agentId[@version]
 * - agentId[@version] (no publisher)
 */
export function parseAgentId(fullAgentId: string): {
  publisherId?: string
  agentId?: string
  version?: string
} {
  // Check if it's in the publisher/agent-id[@version] format
  const parts = fullAgentId.split('/')

  if (parts.length === 2) {
    // Full format: publisher/agentId[@version]
    const [publisherId, agentNameWithVersion] = parts

    if (!publisherId || !agentNameWithVersion) {
      return { publisherId: undefined, agentId: undefined, version: undefined }
    }

    // Check for version suffix
    const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
    if (versionMatch) {
      const [, agentId, version] = versionMatch
      return { publisherId, agentId, version }
    }

    return { publisherId, agentId: agentNameWithVersion }
  } else if (parts.length === 1) {
    // Just agent name (for backward compatibility)
    const agentNameWithVersion = parts[0]

    if (!agentNameWithVersion) {
      return { publisherId: undefined, agentId: undefined, version: undefined }
    }

    // Check for version suffix
    const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
    if (versionMatch) {
      const [, agentId, version] = versionMatch
      return { publisherId: undefined, agentId, version }
    }

    return {
      publisherId: undefined,
      agentId: agentNameWithVersion,
      version: undefined,
    }
  }

  return { publisherId: undefined, agentId: undefined, version: undefined }
}

/**
 * Parse publishded agent ID to extract publisher, agent name, and optionally version
 *
 * If the agent ID is not in the publisher/agent format, return null
 */
export function parsePublishedAgentId(fullAgentId: string): {
  publisherId: string
  agentId: string
  version?: string
} | null {
  const { publisherId, agentId, version } = parseAgentId(fullAgentId)
  if (!publisherId || !agentId) {
    return null
  }
  return {
    publisherId,
    agentId,
    version,
  }
}

export const DEFAULT_ORG_PREFIX = 'codebuff/'

/**
 * Resolves an agent ID by trying multiple strategies:
 * 1. Direct lookup in registry
 * 2. Try with DEFAULT_ORG_PREFIX for spawnable agents
 * 3. Return null if not found
 *
 * This provides a more robust alternative to string concatenation
 * and handles the common case where users reference spawnable agents
 * without the org prefix.
 */
export function resolveAgentId(
  agentId: string,
  agentRegistry: Record<string, any>,
): string | null {
  // Handle empty or invalid input
  if (!agentId || typeof agentId !== 'string') {
    return null
  }

  // Try direct lookup first
  if (agentId in agentRegistry) {
    return agentId
  }

  // Try with DEFAULT_ORG_PREFIX for spawnable agents
  // Only add prefix if the agent ID doesn't already contain a slash
  // (to avoid double-prefixing or interfering with other org prefixes)
  if (!agentId.includes('/')) {
    const prefixedAgentId = `${DEFAULT_ORG_PREFIX}${agentId}`
    if (prefixedAgentId in agentRegistry) {
      return prefixedAgentId
    }
  }

  return null
}

