import { describe, expect, test } from 'bun:test'
import { getMatchingSpawn } from './agent-matching'

describe('getMatchingSpawn', () => {
  test('exact match with full format publisher/agent@version', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0', 'codebuff/editor@2.0.0']
    const result = getMatchingSpawn(spawnableAgents, 'codebuff/thinker@1.0.0')
    expect(result).toBe('codebuff/thinker@1.0.0')
  })

  test('match publisher/agent when version omitted', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0', 'codebuff/editor@2.0.0']
    const result = getMatchingSpawn(spawnableAgents, 'codebuff/thinker')
    expect(result).toBe('codebuff/thinker@1.0.0')
  })

  test('match agent@version when publisher omitted', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0', 'other/thinker@1.0.0']
    const result = getMatchingSpawn(spawnableAgents, 'thinker@1.0.0')
    expect(result).toBe('codebuff/thinker@1.0.0')
  })

  test('match simple agent name', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0', 'codebuff/editor@2.0.0']
    const result = getMatchingSpawn(spawnableAgents, 'thinker')
    expect(result).toBe('codebuff/thinker@1.0.0')
  })

  test('return first match when multiple agents match', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0', 'other/thinker@2.0.0']
    const result = getMatchingSpawn(spawnableAgents, 'thinker')
    expect(result).toBe('codebuff/thinker@1.0.0')
  })

  test('return null when no match found', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0']
    const result = getMatchingSpawn(spawnableAgents, 'nonexistent')
    expect(result).toBe(null)
  })

  test('return null for empty spawnable agents array', () => {
    const result = getMatchingSpawn([], 'thinker')
    expect(result).toBe(null)
  })

  test('return null for malformed child agent ID', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0']
    const result = getMatchingSpawn(spawnableAgents, '')
    expect(result).toBe(null)
  })

  test('return null for null child agent ID', () => {
    const spawnableAgents = ['codebuff/thinker@1.0.0']
    const result = getMatchingSpawn(spawnableAgents, null as any)
    expect(result).toBe(null)
  })

  test('skip malformed spawnable agents', () => {
    const spawnableAgents = ['', 'codebuff/thinker@1.0.0']
    const result = getMatchingSpawn(spawnableAgents, 'thinker')
    expect(result).toBe('codebuff/thinker@1.0.0')
  })

  test('handle null spawnable agents array', () => {
    const result = getMatchingSpawn(null as any, 'thinker')
    expect(result).toBe(null)
  })
})

