'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useEffect, useMemo, useState } from 'react'

import type { NewsArticle } from '@/lib/docs'

import { getDocsByCategory, getNewsArticles } from '@/lib/docs'
import { cn } from '@/lib/utils'

export const sections = [
  {
    title: 'Intro',
    href: '/docs/help',
    subsections: getDocsByCategory('help').map((doc) => ({
      title: doc.title,
      href: `/docs/help/${doc.slug}`,
    })),
    external: false,
  },
  {
    title: 'Tips & Tricks',
    href: '/docs/tips',
    subsections: getDocsByCategory('tips').map((doc) => ({
      title: doc.title,
      href: `/docs/tips/${doc.slug}`,
    })),
    external: false,
  },
  {
    title: 'Agents',
    href: '/docs/agents',
    subsections: getDocsByCategory('agents').map((doc) => ({
      title: doc.title,
      href: `/docs/agents/${doc.slug}`,
    })),
    external: false,
  },
  {
    title: 'Advanced',
    href: '/docs/advanced',
    subsections: getDocsByCategory('advanced').map((doc) => ({
      title: doc.title,
      href: `/docs/advanced/${doc.slug}`,
    })),
    external: false,
  },
  {
    title: 'Case Studies',
    href: '/docs/case-studies',
    subsections: getDocsByCategory('case-studies').map((doc) => ({
      title: doc.title,
      href: `/docs/case-studies/${doc.slug}`,
    })),
    external: false,
  },
]

export function DocSidebar({
  className,
  onNavigate,
}: {
  className?: string
  onNavigate: () => void
}) {
  const pathname = usePathname()
  const [newsArticles, setNewsArticles] = useState<NewsArticle[]>([])

  const allSections = useMemo(
    () => [
      ...sections,
      {
        title: 'News',
        href: 'https://news.codebuff.com',
        external: true,
        subsections: newsArticles,
      },
    ],
    [newsArticles]
  )

  useEffect(() => {
    async function fetchNews() {
      const articles = await getNewsArticles()
      setNewsArticles(articles)
    }

    fetchNews()
  }, [])

  return (
    <nav className={cn('space-y-6', className)}>
      {allSections.map((section) => (
        <div key={section.href} className="space-y-2">
          <Link
            href={section.href}
            target={section.external ? '_blank' : undefined}
            onClick={() => {
              const sheet = document.querySelector('[data-state="open"]')
              if (sheet) sheet.setAttribute('data-state', 'closed')
              onNavigate?.()
            }}
            className={cn(
              'block px-3 py-2 hover:bg-accent rounded-md transition-all text-sm font-medium',
              pathname === section.href && 'bg-accent text-accent-foreground'
            )}
          >
            {section.title}
          </Link>
          {section.subsections && section.subsections.length > 0 && (
            <div className="ml-4 space-y-1">
              {section.subsections.map((subsection) => (
                <Link
                  key={subsection.href}
                  href={
                    section.external
                      ? subsection.href
                      : `${section.href}#${subsection.title.toLowerCase().replace(/\s+/g, '-')}`
                  }
                  target={section.external ? '_blank' : undefined}
                  onClick={(e) => {
                    onNavigate?.()
                    if (pathname.startsWith(section.href)) {
                      e.preventDefault()
                      const id = subsection.title
                        .toLowerCase()
                        .replace(/\s+/g, '-')
                      document
                        .getElementById(id)
                        ?.scrollIntoView({ behavior: 'smooth', block: 'start' })
                      history.replaceState(null, '', `#${id}`)
                    }
                    const sheet = document.querySelector('[data-state="open"]')
                    if (sheet) sheet.setAttribute('data-state', 'closed')
                    onNavigate?.()
                  }}
                  className={cn(
                    'block w-full text-left px-3 py-1.5 text-sm hover:bg-accent rounded-md transition-all text-muted-foreground hover:text-foreground',
                    pathname === subsection.href &&
                      'bg-accent text-accent-foreground'
                  )}
                >
                  {subsection.title}
                </Link>
              ))}
            </div>
          )}
        </div>
      ))}
    </nav>
  )
}

'use client'

import { Menu } from 'lucide-react'
import { usePathname } from 'next/navigation'
import { useState, useEffect } from 'react'

import { DocSidebar, sections } from '@/components/docs/doc-sidebar'
import { Button } from '@/components/ui/button'
import { Sheet, SheetContent, SheetTrigger } from '@/components/ui/sheet'

export default function DocsLayout({
  children,
}: {
  children: React.ReactNode
}) {
  const pathname = usePathname()
  const [open, setOpen] = useState(false)

  // New: Smoothly scroll to hash target on back/forward navigation
  useEffect(() => {
    const handleHashChange = () => {
      const id = window.location.hash.slice(1)
      if (id) {
        document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' })
      }
    }

    // If landing with a hash, ensure smooth scroll to target
    handleHashChange()

    window.addEventListener('hashchange', handleHashChange)
    return () => window.removeEventListener('hashchange', handleHashChange)
  }, [])

  return (
    <div className="pt-8">
      <div className="container flex md:space-x-8 overflow-x-hidden">
        <div className="hidden lg:block w-64 shrink-0">
          <DocSidebar
            className="fixed top-24 w-64 h-[calc(100vh-12rem)] overflow-y-auto pr-4 z-40"
            onNavigate={() => setOpen(false)}
          />
        </div>
        <main className="flex-1 mx-auto pb-36 md:px-8 min-w-0">{children}</main>
      </div>
      <div className="flex items-center lg:hidden sticky bottom-0 z-50 bg-background/80 backdrop-blur-sm container p-4 rounded-t-lg border-t">
        <Sheet
          open={open}
          onOpenChange={(isOpen) => {
            setOpen(isOpen)
            if (!open) {
              document.body.style.position = ''
              document.body.style.overflow = ''
              document.body.style.top = ''
            }
          }}
        >
          <SheetTrigger asChild>
            <Button variant="ghost" size="icon" className="mr-4">
              <Menu className="h-5 w-5" />
              <span className="sr-only">Toggle menu</span>
            </Button>
          </SheetTrigger>
          <SheetContent
            side="bottom"
            className="h-[80vh] p-6 pt-12 overflow-y-auto"
          >
            <DocSidebar onNavigate={() => setOpen(false)} />
          </SheetContent>
          <SheetTrigger asChild>
            <h1 className="text-xl font-semibold w-full">
              {sections.find((section) => pathname.startsWith(section.href))
                ?.title || 'Documentation'}
            </h1>
          </SheetTrigger>
        </Sheet>
      </div>
    </div>
  )
}

