I'll sketch out the key code changes needed for the enhanced DocSidebar component with scroll-based fade effects.

web/src/components/docs/doc-sidebar.tsx
```typescript
'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useEffect, useMemo, useRef, useState } from 'react'

export function DocSidebar({
  className,
  onNavigate,
}: {
  className?: string
  onNavigate: () => void
}) {
  const pathname = usePathname()
  const [newsArticles, setNewsArticles] = useState<NewsArticle[]>([])

  // New: Scroll-based fade state
  const [showTopFade, setShowTopFade] = useState(false)
  const [showBottomFade, setShowBottomFade] = useState(false)
  const scrollContainerRef = useRef<HTMLDivElement>(null)

  // New: Scroll handler with debouncing
  useEffect(() => {
    const container = scrollContainerRef.current
    if (!container) return

    // Check if on desktop (only show fades on desktop)
    const isDesktop = window.innerWidth >= 1024 // lg breakpoint

    const handleScroll = () => {
      if (!isDesktop) return

      const { scrollTop, scrollHeight, clientHeight } = container
      setShowTopFade(scrollTop > 0)
      setShowBottomFade(scrollTop + clientHeight < scrollHeight - 1)
    }

    // Initial check
    handleScroll()

    // Debounced scroll listener
    let timeoutId: NodeJS.Timeout
    const debouncedHandleScroll = () => {
      clearTimeout(timeoutId)
      timeoutId = setTimeout(handleScroll, 50)
    }

    container.addEventListener('scroll', debouncedHandleScroll)
    window.addEventListener('resize', handleScroll)

    return () => {
      container.removeEventListener('scroll', debouncedHandleScroll)
      window.removeEventListener('resize', handleScroll)
      clearTimeout(timeoutId)
    }
  }, [])

  // ... existing fetchNews effect ...

  return (
    <div className={cn('relative', className)}>
      {/* Enhanced container wrapper - only on desktop */}
      <div className="hidden lg:block lg:bg-white/5 lg:backdrop-blur-lg lg:border lg:border-white/20 lg:shadow-lg lg:rounded-lg lg:p-4">
        {/* Top fade gradient */}
        <div
          className={cn(
            'absolute top-0 left-0 right-0 h-12 pointer-events-none z-10 rounded-t-lg transition-opacity duration-500',
            showTopFade ? 'opacity-100' : 'opacity-0'
          )}
          style={{
            background: 'linear-gradient(to bottom, hsl(var(--background)), transparent)',
          }}
        />

        {/* Scrollable content with custom scrollbar */}
        <nav
          ref={scrollContainerRef}
          className="space-y-6 overflow-y-auto custom-scrollbar"
          style={{ maxHeight: 'calc(100vh - 14rem)' }}
        >
          {/* ... existing navigation content ... */}
        </nav>

        {/* Bottom fade gradient */}
        <div
          className={cn(
            'absolute bottom-0 left-0 right-0 h-12 pointer-events-none z-10 rounded-b-lg transition-opacity duration-500',
            showBottomFade ? 'opacity-100' : 'opacity-0'
          )}
          style={{
            background: 'linear-gradient(to top, hsl(var(--background)), transparent)',
          }}
        />
      </div>

      {/* Mobile version without enhancements */}
      <nav className="lg:hidden space-y-6">
        {/* ... existing navigation content ... */}
      </nav>
    </div>
  )
}
