    <div className="pt-8">
      <div className="container flex md:space-x-8 overflow-x-hidden">
        <DocSidebar
          className="hidden lg:block w-64 shrink-0 sticky top-[24px] h-[calc(100vh-24px)] overflow-y-auto pr-4"
