import { toContentString } from '@codebuff/common/util/messages'
import { generateCompactId } from '@codebuff/common/util/string'
import { closeXml } from '@codebuff/common/util/xml'

import type { StringToolResultPart } from '@codebuff/common/tools/constants'
import type { CodebuffMessage } from '@codebuff/common/types/message'

/**
 * Parses XML content for a tool call into a structured object with only string values.
 * Example input:
 * <type>click</type>
 * <selector>#button</selector>
 * <timeout>5000</timeout>
 */
export function parseToolCallXml(xmlString: string): Record<string, string> {
  if (!xmlString.trim()) return {}

  const result: Record<string, string> = {}
  const tagPattern = /<(\w+)>([\s\S]*?)<\/\1>/g
  let match

  while ((match = tagPattern.exec(xmlString)) !== null) {
    const [_, key, rawValue] = match

    // Remove leading/trailing whitespace but preserve internal whitespace
    const value = rawValue.replace(/^\s+|\s+$/g, '')

    // Assign all values as strings
    result[key] = value
  }

  return result
}

export const parseToolResults = (xmlString: string): StringToolResultPart[] => {
  if (!xmlString.trim()) return []

  const results: StringToolResultPart[] = []
  const toolResultPattern = /<tool_result>([\s\S]*?)<\/tool_result>/g
  let match

  while ((match = toolResultPattern.exec(xmlString)) !== null) {
    const [_, toolResultContent] = match
    const toolMatch = /<tool>(.*?)<\/tool>/g.exec(toolResultContent)
    const resultMatch = /<result>([\s\S]*?)<\/result>/g.exec(toolResultContent)

    if (toolMatch && resultMatch) {
      results.push({
        toolName: toolMatch[1],
        toolCallId: generateCompactId(),
        output: { type: 'text', value: resultMatch[1].trim() },
      })
    }
  }

  return results
}

export interface TokenCallerMap {
  [filePath: string]: {
    [token: string]: string[] // Array of files that call this token
  }
}

export function renderReadFilesResult(
  files: { path: string; content: string }[],
  tokenCallers: TokenCallerMap,
) {
  return files
    .map((file) => {
      const referencedBy =
        Object.entries(tokenCallers[file.path] ?? {})
          .filter(([_, callers]) => callers.length > 0)
          .map(([token, callers]) => `${token}: ${callers.join(', ')}`)
          .join('\n') || 'None'
      return `<read_file>\n<path>${file.path}${closeXml('path')}\n<content>${file.content}${closeXml('content')}\n<referenced_by>${referencedBy}${closeXml('referenced_by')}\n${closeXml('read_file')}`
    })
    .join('\n\n')
}

export function parseReadFilesResult(
  xmlString: string,
): { path: string; content: string; referencedBy: string }[] {
  const files: { path: string; content: string; referencedBy: string }[] = []
  const filePattern =
    /<read_file>\s*<path>([^<>]+)<\/path>\s*<content>([\s\S]*?)<\/content>\s*<referenced_by>([\s\S]*?)<\/referenced_by>\s*<\/read_file>/g
  let match

  while ((match = filePattern.exec(xmlString)) !== null) {
    const [, filePath, content, referencedBy] = match
    if (filePath.trim()) {
      files.push({ path: filePath.trim(), content, referencedBy })
    }
  }

  return files
}

export function isToolResult(message: CodebuffMessage): boolean {
  return toContentString(message).includes('<tool_result')
}

import { logger } from '@codebuff/common/util/logger'
import { createPatch } from 'diff'

import { tryToDoStringReplacementWithExtraIndentation } from './generate-diffs-prompt'

export async function processStrReplace(
  path: string,
  replacements: { old: string; new: string }[],
  initialContentPromise: Promise<string | null>,
): Promise<
  | {
      tool: 'str_replace'
      path: string
      content: string
      patch: string
      messages: string[]
    }
  | { tool: 'str_replace'; path: string; error: string }
> {
  const initialContent = await initialContentPromise

  // Process each old/new string pair
  let currentContent = initialContent
  let allPatches: string[] = []
  let messages: string[] = []

  for (const { old: oldStr, new: newStr } of replacements) {
    // Regular case: require oldStr for replacements
    if (!oldStr) {
      messages.push(
        'The old string was empty, which does not match any content, skipping.',
      )
      continue
    }
    if (currentContent === null) {
      messages.push(
        'The file does not exist, skipping. Please use the write_file tool to create the file.',
      )
      continue
    }

    const lineEnding = currentContent.includes('\r\n') ? '\r\n' : '\n'
    const normalizeLineEndings = (str: string) => str.replace(/\r\n/g, '\n')
    const normalizedCurrentContent = normalizeLineEndings(currentContent)
    const normalizedOldStr = normalizeLineEndings(oldStr)

    const updatedOldStr = tryMatchOldStr(
      normalizedCurrentContent,
      normalizedOldStr,
      newStr,
    )
    if (updatedOldStr === null) {
      messages.push(
        `The old string ${JSON.stringify(oldStr)} was not found in the file, skipping. Please try again with a different old string that matches the file content exactly.`,
      )
    }

    const updatedContent =
      updatedOldStr === null
        ? normalizedCurrentContent
        : normalizedCurrentContent.replaceAll(updatedOldStr, newStr)

    let patch = createPatch(path, normalizedCurrentContent, updatedContent)
    const lines = patch.split('\n')
    const hunkStartIndex = lines.findIndex((line) => line.startsWith('@@'))
    if (hunkStartIndex !== -1) {
      patch = lines.slice(hunkStartIndex).join('\n')
      patch = patch.replaceAll('\n', lineEnding)
      allPatches.push(patch)
    }

    // Update current content for next iteration
    currentContent = updatedContent.replaceAll('\n', lineEnding)
  }

  if (allPatches.length === 0) {
    logger.debug(
      {
        path,
        initialContent,
      },
      `processStrReplace: No change to ${path}`,
    )
    messages.push('No change to the file.')
    return {
      tool: 'str_replace' as const,
      path,
      error: messages.join('\n\n'),
    }
  }

  const finalPatch = allPatches.join('\n')

  logger.debug(
    {
      path,
      newContent: currentContent,
      patch: finalPatch,
      messages,
    },
    `processStrReplace: Updated file ${path}`,
  )

  return {
    tool: 'str_replace' as const,
    path,
    content: currentContent!,
    patch: finalPatch,
    messages,
  }
}

const tryMatchOldStr = (
  initialContent: string,
  oldStr: string,
  newStr: string,
) => {
  if (initialContent.includes(oldStr)) {
    return oldStr
  }

  const newChange = tryToDoStringReplacementWithExtraIndentation(
    initialContent,
    oldStr,
    newStr,
  )
  if (newChange) {
    logger.debug('Matched with indentation modification')
    return newChange.searchContent
  } else {
    // Try matching without any whitespace as a last resort
    const noWhitespaceSearch = oldStr.replace(/\s+/g, '')
    const noWhitespaceOld = initialContent.replace(/\s+/g, '')
    const noWhitespaceIndex = noWhitespaceOld.indexOf(noWhitespaceSearch)

    if (noWhitespaceIndex >= 0) {
      // Count non-whitespace characters to find the real position
      let realIndex = 0
      let nonWhitespaceCount = 0
      while (nonWhitespaceCount < noWhitespaceIndex) {
        if (initialContent[realIndex].match(/\S/)) {
          nonWhitespaceCount++
        }
        realIndex++
      }

      // Count non-whitespace characters in search content to find length
      let searchLength = 0
      let nonWhitespaceSearchCount = 0
      while (
        nonWhitespaceSearchCount < noWhitespaceSearch.length &&
        realIndex + searchLength < initialContent.length
      ) {
        if (initialContent[realIndex + searchLength].match(/\S/)) {
          nonWhitespaceSearchCount++
        }
        searchLength++
      }

      // Find the actual content with original whitespace
      const actualContent = initialContent.slice(
        realIndex,
        realIndex + searchLength,
      )
      if (initialContent.includes(actualContent)) {
        logger.debug('Matched with whitespace removed')
        return actualContent
      }
    }
  }
  return null
}

import { models, TEST_USER_ID } from '@codebuff/common/constants'
import { closeXml } from '@codebuff/common/util/xml'

import { promptAiSdk } from '../llm-apis/vercel-ai-sdk/ai-sdk'

import type { Relabel, GetRelevantFilesTrace } from '@codebuff/bigquery'

const PROMPT = `
You are an evaluator system, measuring how well various models perform at selecting the most relevant files for a given user request.
You will be provided the context given to the other models, in the <request_context>${closeXml('request_context')} tags.
You will then be provided with multiple outputs, in the <model_outputs>${closeXml('model_outputs')} tags.
It will be provided in the following format:

<request_context>
  ...
${closeXml('request_context')}

<model_outputs>
  <output>
    <model_id>1${closeXml('model_id')}
    ...
  ${closeXml('output')}
  <output>
    <model_id>2${closeXml('model_id')}
    ...
  ${closeXml('output')}
${closeXml('model_outputs')}

Your goal is to rank and grade the outputs from best to worst, and provide 1-5 scores based on how well they followed the instructions in the <request_context> tags.
Provide the best output first, and the worst output last. Multiple models may receive the same score, but you should break ties by quality.
Multiple models may receive the same score.

You will provide your response in the following format:

<scores>
  <score>
    <model_id>2${closeXml('model_id')}
    <score>4${closeXml('score')}
  ${closeXml('score')}
  <score>
    <model_id>1${closeXml('model_id')}
    <score>4${closeXml('score')}
  ${closeXml('score')}
  <score>
    <model_id>3${closeXml('model_id')}
    <score>2${closeXml('score')}
  ${closeXml('score')}
  ...
${closeXml('scores')}
`

function modelsToXML(models: { model: string; output: string }[]) {
  // 1-indexed ID, and then the output
  return models
    .map(
      (model, index) =>
        `<output>
<model_id>${index + 1}${closeXml('model_id')}
${model.output}
${closeXml('output')}`,
    )
    .join('\n')
}

function extractResponse(response: string): {
  scores: { id: string; score: number }[]
} {
  const scoresMatch = response.match(/<scores>([\s\S]*?)<\/scores>/)
  if (!scoresMatch) {
    throw new Error('No scores found in response')
  }

  const scoresXml = scoresMatch[1]
  const scoreMatches = scoresXml.match(
    /<score>[\s\S]*?<model_id>(\d+)<\/model_id>[\s\S]*?<score>(\d+)<\/score>[\s\S]*?<\/score>/g,
  )

  if (!scoreMatches) {
    throw new Error('No valid score entries found')
  }

  return {
    scores: scoreMatches.map((scoreXml) => {
      const modelMatch = scoreXml.match(/<model_id>[\s]*(\d+)[\s]*<\/model_id>/)
      const scoreMatch = scoreXml.match(/<score>[\s]*(\d+)[\s]*<\/score>/)

      if (!modelMatch || !scoreMatch) {
        throw new Error('Invalid score entry format')
      }

      return {
        id: modelMatch[1],
        score: parseInt(scoreMatch[1], 10),
      }
    }),
  }
}

export async function gradeRun(tracesAndRelabels: {
  trace: GetRelevantFilesTrace
  relabels: Relabel[]
}) {
  const { trace, relabels } = tracesAndRelabels
  const messages = trace.payload.messages

  const originalOutput = trace.payload.output
  const originalModel = trace.payload.model

  const modelsWithOutputs: {
    model: string
    output: string
  }[] = [
    {
      model: originalModel ?? 'original',
      output: originalOutput,
    },
  ]

  for (const relabel of relabels) {
    const model = relabel.model
    const output = relabel.payload.output
    modelsWithOutputs.push({ model, output })
  }

  // randomize the order of the models, but remember the original order
  modelsWithOutputs.sort(() => Math.random() - 0.5)

  const modelOutputs = modelsToXML(modelsWithOutputs)

  console.log(relabels)

  const stringified = JSON.stringify(messages)
  const response = await promptAiSdk({
    messages: [
      { role: 'system', content: PROMPT },
      {
        role: 'user',
        content: `<request_context>${stringified}${closeXml('request_context')}`,
      },
      {
        role: 'user',
        content: `<model_outputs>${modelOutputs}${closeXml('model_outputs')}`,
      },
      { role: 'user', content: PROMPT },
    ],
    model: models.openrouter_claude_sonnet_4,
    clientSessionId: 'relabel-trace-api',
    fingerprintId: 'relabel-trace-api',
    userInputId: 'relabel-trace-api',
    userId: TEST_USER_ID,
    //   thinking: {
    //     type: 'enabled',
    //     budget_tokens: 10000,
    //   },
  })

  const { scores } = extractResponse(response)

  // Combine the scores with the model name from modelsWithOutputs
  const scoresWithModelName = scores.map((score, index) => {
    const model = modelsWithOutputs[index]
    return { model: model.model, score: score.score, rank: index + 1 }
  })

  console.log(response)
  console.log(scoresWithModelName)
}

import fs from 'fs'
import path from 'path'

import { withCacheControl } from '@codebuff/common/util/messages'

import { logger } from '../util/logger'

import type { CodebuffMessage } from '@codebuff/common/types/message'

export async function saveAgentRequest(
  messages: CodebuffMessage[],
  userInputId: string,
) {
  try {
    const promptsDir = path.join(process.cwd(), 'system-prompts')
    await fs.promises.mkdir(promptsDir, { recursive: true })

    const messageCount = messages.length
    const filename = `system-prompt-${messageCount}-${userInputId}.json`
    const filePath = path.join(promptsDir, filename)

    const transformedMessages = messages.map(withCacheControl)

    await fs.promises.writeFile(
      filePath,
      JSON.stringify(transformedMessages, null, 2),
    )

    logger.debug(
      { messageCount, userInputId },
      `Saved system prompt to ${filePath}`,
    )
  } catch (error) {
    logger.error({ error }, 'Failed to save system prompt')
  }
}

import { providerModelNames } from '@codebuff/common/constants'

import { promptAiSdkStream } from './llm-apis/vercel-ai-sdk/ai-sdk'
import { globalStopSequence } from './tools/constants'

import type { AgentTemplate } from './templates/types'
import type { CodebuffMessage } from '@codebuff/common/types/message'

export const getAgentStreamFromTemplate = (params: {
  clientSessionId: string
  fingerprintId: string
  userInputId: string
  userId: string | undefined

  template: AgentTemplate
}) => {
  const { clientSessionId, fingerprintId, userInputId, userId, template } =
    params

  if (!template) {
    throw new Error('Agent template is null/undefined')
  }

  const { model } = template

  const getStream = (messages: CodebuffMessage[]) => {
    const options: Parameters<typeof promptAiSdkStream>[0] = {
      messages,
      model,
      stopSequences: [globalStopSequence],
      clientSessionId,
      fingerprintId,
      userInputId,
      userId,
      maxOutputTokens: 32_000,
    }

    // Add Gemini-specific options if needed
    const primaryModel = Array.isArray(model) ? model[0] : model
    const provider =
      providerModelNames[primaryModel as keyof typeof providerModelNames]

    if (provider === 'gemini') {
      if (!options.providerOptions) {
        options.providerOptions = {}
      }
      if (!options.providerOptions.gemini) {
        options.providerOptions.gemini = {}
      }
      if (!options.providerOptions.gemini.thinkingConfig) {
        options.providerOptions.gemini.thinkingConfig = { thinkingBudget: 128 }
      }
    }

    return promptAiSdkStream(options)
  }

  return getStream
}

