/**
 * Sends an action to the client via WebSocket
 * @param ws - The WebSocket connection to send the action to
 * @param action - The server action to send
 */
export const sendAction = (ws: WebSocket, action: ServerAction) => {
  sendMessage(ws, {
    type: 'action',
    data: action,
  })
}

/**
 * Retrieves a user ID from an authentication token
 * @param authToken - The authentication token to validate
 * @returns The user ID if found, undefined otherwise
 */
export const getUserIdFromAuthToken = async (
  authToken?: string,
): Promise<string | undefined> => {
  if (!authToken) return undefined

  const userId = await db
    .select({ userId: schema.user.id })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, authToken))
    .then((users) => {
      if (users.length === 1) {
        return users[0].userId
      }
      return undefined
    })

  return userId
}

/**
 * Generates a usage response object for the client
 * @param fingerprintId - The fingerprint ID for the user/device
 * @param userId - user ID for authenticated users
 * @param clientSessionId - Optional session ID
 * @returns A UsageResponse object containing usage metrics and referral information
 */
export async function genUsageResponse(
  fingerprintId: string,
  userId: string,
  clientSessionId: string | undefined,
): Promise<UsageResponse> {
  const logContext = { fingerprintId, userId, sessionId: clientSessionId }
  const defaultResp = {
    type: 'usage-response' as const,
    usage: 0,
    remainingBalance: 0,
    next_quota_reset: null,
  } satisfies UsageResponse

  return withLoggerContext<UsageResponse>(logContext, async () => {
    const user = await db.query.user.findFirst({
      where: eq(schema.user.id, userId),
      columns: {
        next_quota_reset: true,
      },
    })

    if (!user) {
      return defaultResp
    }

    try {
      // Get the usage data
      const { balance: balanceDetails, usageThisCycle } =
        await calculateUsageAndBalance(userId, new Date())

      return {
        type: 'usage-response' as const,
        usage: usageThisCycle,
        remainingBalance: balanceDetails.totalRemaining,
        balanceBreakdown: balanceDetails.breakdown,
        next_quota_reset: user.next_quota_reset,
      } satisfies UsageResponse
    } catch (error) {
      logger.error(
        { error, usage: defaultResp },
        'Error generating usage response, returning default',
      )
    }

    return defaultResp
  })
}

/**
 * Handles prompt actions from the client
 * @param action - The prompt action from the client
 * @param clientSessionId - The client's session ID
 * @param ws - The WebSocket connection
 */
const onPrompt = async (
  action: ClientAction<'prompt'>,
  clientSessionId: string,
  ws: WebSocket,
) => {
  const { fingerprintId, authToken, promptId, prompt, costMode } = action

  await withLoggerContext(
    { fingerprintId, clientRequestId: promptId, costMode },
    async () => {
      const userId = await getUserIdFromAuthToken(authToken)
      if (!userId) {
        throw new Error('User not found')
      }

      if (prompt) {
        logger.info(`USER INPUT: ${prompt}`)
        trackEvent(AnalyticsEvent.USER_INPUT, userId, {
          prompt,
          promptId,
        })
      }

      startUserInput(userId, promptId)

      try {
        await callMainPrompt(ws, action, {
          userId,
          promptId,
          clientSessionId,
        })
      } catch (e) {
        logger.error(e, 'Error in mainPrompt')
        let response =
          e && typeof e === 'object' && 'message' in e ? `${e.message}` : `${e}`

        sendAction(ws, {
          type: 'prompt-error',
          userInputId: promptId,
          message: response,
        })
      } finally {
        endUserInput(userId, promptId)
        const usageResponse = await genUsageResponse(
          fingerprintId,
          userId,
          undefined,
        )
        sendAction(ws, usageResponse)
      }
    },
  )
}

export const callMainPrompt = async (
  ws: WebSocket,
  action: ClientAction<'prompt'>,
  options: {
    userId: string
    promptId: string
    clientSessionId: string
  },
) => {
  const { userId, promptId, clientSessionId } = options
  const { fileContext } = action.sessionState

  // Assemble local agent templates from fileContext
  const { agentTemplates: localAgentTemplates, validationErrors } =
    assembleLocalAgentTemplates(fileContext)

  if (validationErrors.length > 0) {
    sendAction(ws, {
      type: 'prompt-error',
      message: `Invalid agent config: ${validationErrors.map((err) => err.message).join('\n')}`,
      userInputId: promptId,
    })
  }

  const result = await mainPrompt(ws, action, {
    userId,
    clientSessionId,
    localAgentTemplates,
    onResponseChunk: (chunk) => {
      if (checkLiveUserInput(userId, promptId, clientSessionId)) {
        sendAction(ws, {
          type: 'response-chunk',
          userInputId: promptId,
          chunk,
        })
      }
    },
  })

  const { sessionState, toolCalls, toolResults } = result
  // Send prompt data back
  sendAction(ws, {
    type: 'prompt-response',
    promptId,
    sessionState,
    toolCalls: toolCalls as any[],
    toolResults,
  })

  return result
}

/**
 * Handles initialization actions from the client
 * @param fileContext - The file context information
 * @param fingerprintId - The fingerprint ID for the user/device
 * @param authToken - The authentication token
 * @param clientSessionId - The client's session ID
 * @param ws - The WebSocket connection
 */
const onInit = async (
  { fileContext, fingerprintId, authToken }: ClientAction<'init'>,
  clientSessionId: string,
  ws: WebSocket,
) => {
  await withLoggerContext({ fingerprintId }, async () => {
    const userId = await getUserIdFromAuthToken(authToken)

    if (!userId) {
      sendAction(ws, {
        usage: 0,
        remainingBalance: 0,
        next_quota_reset: null,
        type: 'init-response',
      })
      return
    }

    // Send combined init and usage response
    const usageResponse = await genUsageResponse(
      fingerprintId,
      userId,
      clientSessionId,
    )
    sendAction(ws, {
      ...usageResponse,
      type: 'init-response',
    })
  })
}

const onCancelUserInput = async ({
  authToken,
  promptId,
}: ClientAction<'cancel-user-input'>) => {
  const userId = await getUserIdFromAuthToken(authToken)
  if (!userId) {
    logger.error({ authToken }, 'User id not found for authToken')
    return
  }
  cancelUserInput(userId, promptId)
  if (ASYNC_AGENTS_ENABLED) {
    asyncAgentManager.cleanupUserInputAgents(promptId)
  }
}

/**
 * Storage for action callbacks organized by action type
 */
const callbacksByAction = {} as Record<
  ClientAction['type'],
  ((action: ClientAction, clientSessionId: string, ws: WebSocket) => void)[]
>

/**
 * Subscribes a callback function to a specific action type
 * @param type - The action type to subscribe to
 * @param callback - The callback function to execute when the action is received
 * @returns A function to unsubscribe the callback
 */
export const subscribeToAction = <T extends ClientAction['type']>(
  type: T,
  callback: (
    action: ClientAction<T>,
    clientSessionId: string,
    ws: WebSocket,
  ) => void,
) => {
  callbacksByAction[type] = (callbacksByAction[type] ?? []).concat(
    callback as (
      action: ClientAction,
      clientSessionId: string,
      ws: WebSocket,
    ) => void,
  )
  return () => {
    callbacksByAction[type] = (callbacksByAction[type] ?? []).filter(
      (cb) => cb !== callback,
    )
  }
}

/**
 * Handles WebSocket action messages from clients
 * @param ws - The WebSocket connection
 * @param clientSessionId - The client's session ID
 * @param msg - The action message from the client
 */
export const onWebsocketAction = async (
  ws: WebSocket,
  clientSessionId: string,
  msg: ClientMessage & { type: 'action' },
) => {
  await withLoggerContext({ clientSessionId }, async () => {
    const callbacks = callbacksByAction[msg.data.type] ?? []
    try {
      await Promise.all(
        callbacks.map((cb) => cb(msg.data, clientSessionId, ws)),
      )
    } catch (e) {
      logger.error(
        {
          message: msg,
          error: e && typeof e === 'object' && 'message' in e ? e.message : e,
        },
        'Got error running subscribeToAction callback',
      )
    }
  })
}

// Register action handlers
subscribeToAction('prompt', protec.run(onPrompt))
subscribeToAction('init', protec.run(onInit, { silent: true }))
subscribeToAction('cancel-user-input', protec.run(onCancelUserInput))

/**
 * Requests multiple files from the client
 * @param ws - The WebSocket connection
 * @param filePaths - Array of file paths to request
 * @returns Promise resolving to an object mapping file paths to their contents
 */
export async function requestFiles(ws: WebSocket, filePaths: string[]) {
  return new Promise<Record<string, string | null>>((resolve) => {
    const requestId = generateCompactId()
    const unsubscribe = subscribeToAction('read-files-response', (action) => {
      for (const [filename, contents] of Object.entries(action.files)) {
        action.files[filename] = ensureEndsWithNewline(contents)
      }
      if (action.requestId === requestId) {
        unsubscribe()
        resolve(action.files)
      }
    })
    sendAction(ws, {
      type: 'read-files',
      filePaths,
      requestId,
    })
  })
}

/**
 * Requests a single file from the client
 * @param ws - The WebSocket connection
 * @param filePath - The path of the file to request
 * @returns Promise resolving to the file contents or null if not found
 */
export async function requestFile(ws: WebSocket, filePath: string) {
  const files = await requestFiles(ws, [filePath])
  return files[filePath] ?? null
}

export async function requestOptionalFile(ws: WebSocket, filePath: string) {
  const file = await requestFile(ws, filePath)
  return toOptionalFile(file)
}

/**
 * Requests a tool call execution from the client with timeout support
 * @param ws - The WebSocket connection
 * @param toolName - Name of the tool to execute
 * @param input - Arguments for the tool (can include timeout)
 * @returns Promise resolving to the tool execution result
 */
export async function requestToolCall(
  ws: WebSocket,
  userInputId: string,
  toolName: string,
  input: Record<string, any> & { timeout_seconds?: number },
): Promise<{
  success: boolean
  output?: {
    type: 'text'
    value: string
  }
  error?: string
}> {
  return new Promise((resolve, reject) => {
    const requestId = generateCompactId()
    const timeoutInSeconds =
      (input.timeout_seconds || 30) < 0
        ? undefined
        : input.timeout_seconds || 30

    // Set up timeout
    const timeoutHandle =
      timeoutInSeconds === undefined
        ? undefined
        : setTimeout(
            () => {
              unsubscribe()
              reject(
                new Error(
                  `Tool call '${toolName}' timed out after ${timeoutInSeconds}s`,
                ),
              )
            },
            timeoutInSeconds * 1000 + 5000, // Convert to ms and add a small buffer
          )

    // Subscribe to response
    const unsubscribe = subscribeToAction('tool-call-response', (action) => {
      if (action.requestId === requestId) {
        clearTimeout(timeoutHandle)
        unsubscribe()
        resolve({
          success: action.success,
          output: action.output,
          error: action.error,
        })
      }
    })

    // Send the request
    sendAction(ws, {
      type: 'tool-call-request',
      requestId,
      userInputId,
      toolName,
      input,
      timeout:
        timeoutInSeconds === undefined ? undefined : timeoutInSeconds * 1000, // Send timeout in milliseconds
    })
  })
}

import { ASYNC_AGENTS_ENABLED } from '@codebuff/common/constants'
import { CLIENT_MESSAGE_SCHEMA } from '@codebuff/common/websockets/websocket-schema'
import { isError } from 'lodash'
import { WebSocketServer } from 'ws'

import { asyncAgentManager } from '../async-agent-manager'
import { setSessionConnected } from '../live-user-inputs'
import { Switchboard } from './switchboard'
import { onWebsocketAction } from './websocket-action'
import { logger } from '../util/logger'

import type { ServerMessage } from '@codebuff/common/websockets/websocket-schema'
import type { Server as HttpServer } from 'node:http'
import type { RawData, WebSocket } from 'ws'

export const SWITCHBOARD = new Switchboard()

// if a connection doesn't ping for this long, we assume the other side is toast
const CONNECTION_TIMEOUT_MS = 60 * 1000

export class MessageParseError extends Error {
  details?: unknown
  constructor(message: string, details?: unknown) {
    super(message)
    this.name = 'MessageParseError'
    this.details = details
  }
}

function serializeError(err: unknown) {
  return isError(err) ? err.message : 'Unexpected error.'
}

async function processMessage(
  ws: WebSocket,
  clientSessionId: string,
  data: RawData,
): Promise<ServerMessage<'ack'>> {
  let messageObj: any
  try {
    messageObj = JSON.parse(data.toString())
  } catch (err) {
    logger.error(
      { err, data },
      'Error parsing message: not valid UTF-8 encoded JSON.',
    )
    return { type: 'ack', success: false, error: serializeError(err) }
  }

  try {
    const msg = CLIENT_MESSAGE_SCHEMA.parse(messageObj)
    const { type, txid } = msg
    switch (type) {
      case 'subscribe': {
        SWITCHBOARD.subscribe(ws, ...msg.topics)
        break
      }
      case 'unsubscribe': {
        SWITCHBOARD.unsubscribe(ws, ...msg.topics)
        break
      }
      case 'ping': {
        SWITCHBOARD.markSeen(ws)
        break
      }
      case 'action': {
        onWebsocketAction(ws, clientSessionId, msg)
        break
      }
      default:
        throw new Error("Unknown message type; shouldn't be possible here.")
    }
    return { type: 'ack', txid, success: true }
  } catch (err) {
    logger.error({ err }, 'Error processing message')
    return {
      type: 'ack',
      txid: messageObj.txid,
      success: false,
      error: serializeError(err),
    }
  }
}

export function listen(server: HttpServer, path: string) {
  const wss = new WebSocketServer({ server, path })
  let deadConnectionCleaner: NodeJS.Timeout | undefined
  wss.on('listening', () => {
    logger.info(`Web socket server listening on ${path}.`)
    deadConnectionCleaner = setInterval(function ping() {
      const now = Date.now()
      try {
        for (const ws of wss.clients) {
          try {
            const client = SWITCHBOARD.getClient(ws)
            if (!client) {
              logger.warn(
                'Client not found in switchboard, terminating connection',
              )
              ws.terminate()
              continue
            }

            const lastSeen = client.lastSeen
            if (lastSeen < now - CONNECTION_TIMEOUT_MS) {
              ws.terminate()
            }
          } catch (err) {
            // logger.error(
            //   { error: err },
            //   'Error checking individual connection in deadConnectionCleaner'
            // )
          }
        }
      } catch (error) {
        logger.error({ error }, 'Error in deadConnectionCleaner outer loop')
      }
    }, CONNECTION_TIMEOUT_MS)
  })
  wss.on('error', (err: Error) => {
    logger.error({ error: err }, 'Error on websocket server.')
  })
  wss.on('connection', (ws: WebSocket) => {
    // todo: should likely kill connections that haven't sent any ping for a long time
    // logger.info('WS client connected.')
    SWITCHBOARD.connect(ws)
    const clientSessionId =
      SWITCHBOARD.clients.get(ws)?.sessionId ?? 'mc-client-unknown'

    // Mark session as connected
    setSessionConnected(clientSessionId, true)
    ws.on('message', async (data: RawData) => {
      const result = await processMessage(ws, clientSessionId, data)
      // mqp: check ws.readyState before sending?
      ws.send(JSON.stringify(result))
    })
    ws.on('close', (code: number, reason: Buffer) => {
      // logger.debug(
      //   { code, reason: reason.toString() },
      //   'WS client disconnected.'
      // )

      // Mark session as disconnected to stop all agents
      setSessionConnected(clientSessionId, false)

      if (ASYNC_AGENTS_ENABLED) {
        // Cleanup async agents for this session
        asyncAgentManager.cleanupSession(clientSessionId)
      }

      SWITCHBOARD.disconnect(ws)
    })
    ws.on('error', (err: Error) => {
      logger.error({ error: err }, 'Error on websocket connection.')
    })
  })
  wss.on('close', function close() {
    if (deadConnectionCleaner) {
      clearInterval(deadConnectionCleaner)
    }
  })
  return wss
}

export const sendMessage = (ws: WebSocket, server: ServerMessage) => {
  ws.send(JSON.stringify(server))
}

export function sendRequestReconnect() {
  for (const ws of SWITCHBOARD.clients.keys()) {
    sendMessage(ws, { type: 'action', data: { type: 'request-reconnect' } })
  }
}

export function waitForAllClientsDisconnected() {
  return SWITCHBOARD.waitForAllClientsDisconnected()
}

import { renderToolResults } from '@codebuff/common/tools/utils'
import { AgentTemplateTypes } from '@codebuff/common/types/session-state'
import { generateCompactId } from '@codebuff/common/util/string'
import { uniq } from 'lodash'

import { checkTerminalCommand } from './check-terminal-command'
import { loopAgentSteps } from './run-agent-step'
import { getAgentTemplate } from './templates/agent-registry'
import { logger } from './util/logger'
import { expireMessages } from './util/messages'
import { requestToolCall } from './websockets/websocket-action'

import type { AgentTemplate } from './templates/types'
import type { ClientToolCall } from './tools/constants'
import type { ClientAction } from '@codebuff/common/actions'
import type { CostMode } from '@codebuff/common/constants'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  SessionState,
  ToolResult,
  AgentTemplateType,
} from '@codebuff/common/types/session-state'
import type { WebSocket } from 'ws'

export interface MainPromptOptions {
  userId: string | undefined
  clientSessionId: string
  onResponseChunk: (chunk: string | PrintModeEvent) => void
  localAgentTemplates: Record<string, AgentTemplate>
}

export const mainPrompt = async (
  ws: WebSocket,
  action: ClientAction<'prompt'>,
  options: MainPromptOptions,
): Promise<{
  sessionState: SessionState
  toolCalls: Array<ClientToolCall>
  toolResults: Array<ToolResult>
}> => {
  const { userId, clientSessionId, onResponseChunk, localAgentTemplates } =
    options

  const {
    prompt,
    sessionState: sessionState,
    fingerprintId,
    costMode,
    promptId,
    agentId,
    promptParams,
  } = action
  const { fileContext, mainAgentState } = sessionState

  if (prompt) {
    // Check if this is a direct terminal command
    const startTime = Date.now()
    const terminalCommand = await checkTerminalCommand(prompt, {
      clientSessionId,
      fingerprintId,
      userInputId: promptId,
      userId,
    })
    const duration = Date.now() - startTime

    if (terminalCommand) {
      logger.debug(
        {
          duration,
          prompt,
        },
        `Detected terminal command in ${duration}ms, executing directly: ${prompt}`,
      )

      const response = await requestToolCall(
        ws,
        promptId,
        'run_terminal_command',
        {
          command: terminalCommand,
          mode: 'user',
          process_type: 'SYNC',
          timeout_seconds: -1,
        },
      )

      const toolResult: ToolResult['output'] = {
        type: 'text',
        value:
          (response.success ? response.output?.value : response.error) || '',
      }
      if (response.success) {
        mainAgentState.messageHistory.push({
          role: 'user',
          content: renderToolResults([
            {
              toolName: 'run_terminal_command',
              toolCallId: generateCompactId(),
              output: toolResult,
            },
          ]),
        })
      }

      const newSessionState = {
        ...sessionState,
        messageHistory: expireMessages(
          mainAgentState.messageHistory,
          'userPrompt',
        ),
      }

      return {
        sessionState: newSessionState,
        toolCalls: [],
        toolResults: [],
      }
    }
  }

  const availableAgents = Object.keys(localAgentTemplates)

  // Determine agent type - prioritize CLI agent selection, then config base agent, then cost mode
  let agentType: AgentTemplateType

  if (agentId) {
    if (!(await getAgentTemplate(agentId, localAgentTemplates))) {
      throw new Error(
        `Invalid agent ID: "${agentId}". Available agents: ${availableAgents.join(', ')}`,
      )
    }

    agentType = agentId
    logger.info(
      {
        agentId,
        promptParams,
        prompt: prompt?.slice(0, 50),
      },
      `Using CLI-specified agent: ${agentId}`,
    )
  } else {
    // Check for base agent in config
    const configBaseAgent = fileContext.codebuffConfig?.baseAgent
    if (configBaseAgent) {
      if (!(await getAgentTemplate(configBaseAgent, localAgentTemplates))) {
        throw new Error(
          `Invalid base agent in config: "${configBaseAgent}". Available agents: ${availableAgents.join(', ')}`,
        )
      }
      agentType = configBaseAgent
      logger.info(
        {
          configBaseAgent,
          promptParams,
          prompt: prompt?.slice(0, 50),
        },
        `Using config-specified base agent: ${configBaseAgent}`,
      )
    } else {
      // Fall back to cost mode mapping
      agentType = (
        {
          ask: AgentTemplateTypes.ask,
          lite: AgentTemplateTypes.base_lite,
          normal: AgentTemplateTypes.base,
          max: AgentTemplateTypes.base_max,
          experimental: AgentTemplateTypes.base_experimental,
        } satisfies Record<CostMode, AgentTemplateType>
      )[costMode]
    }
  }

  mainAgentState.agentType = agentType

  let mainAgentTemplate = await getAgentTemplate(agentType, localAgentTemplates)
  if (!mainAgentTemplate) {
    throw new Error(`Agent template not found for type: ${agentType}`)
  }

  let updatedSubagents = mainAgentTemplate.spawnableAgents
  if (!agentId) {
    // If --agent is not specified, use the spawnableAgents from the codebuff config or add all local agents
    updatedSubagents =
      fileContext.codebuffConfig?.spawnableAgents ??
      uniq([...mainAgentTemplate.spawnableAgents, ...availableAgents])
  }
  mainAgentTemplate.spawnableAgents = updatedSubagents
  localAgentTemplates[agentType] = mainAgentTemplate

  const { agentState } = await loopAgentSteps(ws, {
    userInputId: promptId,
    prompt,
    params: promptParams,
    agentType,
    agentState: mainAgentState,
    fingerprintId,
    fileContext,
    toolResults: [],
    userId,
    clientSessionId,
    onResponseChunk,
    localAgentTemplates,
  })

  return {
    sessionState: {
      fileContext,
      mainAgentState: agentState,
    },
    toolCalls: [],
    toolResults: [],
  }
}

import { endsAgentStepParam } from '@codebuff/common/tools/constants'
import { renderToolResults } from '@codebuff/common/tools/utils'
import { generateCompactId } from '@codebuff/common/util/string'
import z from 'zod/v4'

import { checkLiveUserInput } from '../live-user-inputs'
import { logger } from '../util/logger'
import { asSystemMessage } from '../util/messages'
import { requestToolCall } from '../websockets/websocket-action'
import { codebuffToolDefs } from './definitions/list'
import { codebuffToolHandlers } from './handlers/list'

import type { ClientToolCall, CodebuffToolCall } from './constants'
import type { CodebuffToolHandlerFunction } from './handlers/handler-function-type'
import type { AgentTemplate } from '../templates/types'
import type { ToolName } from '@codebuff/common/tools/constants'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type { ToolResult } from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'
import type { WebSocket } from 'ws'

export type ToolCallError = {
  toolName?: string
  input: Record<string, unknown>
  error: string
} & Pick<CodebuffToolCall, 'toolCallId'>

export function parseRawToolCall<T extends ToolName = ToolName>(
  rawToolCall: {
    toolName: T
    toolCallId: string
    input: Record<string, unknown>
  },
  autoInsertEndStepParam: boolean = false,
): CodebuffToolCall<T> | ToolCallError {
  const toolName = rawToolCall.toolName

  if (!(toolName in codebuffToolDefs)) {
    return {
      toolName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Tool ${toolName} not found`,
    }
  }
  const validName = toolName as T

  const processedParameters: Record<string, any> = {}
  for (const [param, val] of Object.entries(rawToolCall.input ?? {})) {
    processedParameters[param] = val
  }

  // Add the required codebuff_end_step parameter with the correct value for this tool if requested
  if (autoInsertEndStepParam) {
    processedParameters[endsAgentStepParam] =
      codebuffToolDefs[validName].endsAgentStep
  }

  const paramsSchema = codebuffToolDefs[validName].endsAgentStep
    ? (
        codebuffToolDefs[validName]
          .parameters satisfies z.ZodObject as z.ZodObject
      ).extend({
        [endsAgentStepParam]: z.literal(
          codebuffToolDefs[validName].endsAgentStep,
        ),
      })
    : codebuffToolDefs[validName].parameters
  const result = paramsSchema.safeParse(processedParameters)

  if (!result.success) {
    return {
      toolName: validName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Invalid parameters for ${validName}: ${JSON.stringify(
        result.error.issues,
        null,
        2,
      )}`,
    }
  }

  if (endsAgentStepParam in result.data) {
    delete result.data[endsAgentStepParam]
  }

  return {
    toolName: validName,
    input: result.data,
    toolCallId: rawToolCall.toolCallId,
  } as CodebuffToolCall<T>
}

export interface ExecuteToolCallParams<T extends ToolName = ToolName> {
  toolName: T
  input: Record<string, unknown>
  toolCalls: CodebuffToolCall[]
  toolResults: ToolResult[]
  previousToolCallFinished: Promise<void>
  ws: WebSocket
  agentTemplate: AgentTemplate
  fileContext: ProjectFileContext
  agentStepId: string
  clientSessionId: string
  userInputId: string
  fullResponse: string
  onResponseChunk: (chunk: string | PrintModeEvent) => void
  state: Record<string, any>
  userId: string | undefined
  autoInsertEndStepParam?: boolean
}

export function executeToolCall<T extends ToolName>({
  toolName,
  input,
  toolCalls,
  toolResults,
  previousToolCallFinished,
  ws,
  agentTemplate,
  fileContext,
  agentStepId,
  clientSessionId,
  userInputId,
  fullResponse,
  onResponseChunk,
  state,
  userId,
  autoInsertEndStepParam = false,
}: ExecuteToolCallParams<T>): Promise<void> {
  const toolCall: CodebuffToolCall<T> | ToolCallError = parseRawToolCall<T>(
    {
      toolName,
      toolCallId: generateCompactId(),
      input,
    },
    autoInsertEndStepParam,
  )
  if ('error' in toolCall) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: toolCall.error,
      },
    })
    logger.debug(
      { toolCall, error: toolCall.error },
      `${toolName} error: ${toolCall.error}`,
    )
    return previousToolCallFinished
  }

  onResponseChunk({
    type: 'tool_call',
    toolCallId: toolCall.toolCallId,
    toolName,
    input: toolCall.input,
  })

  logger.debug(
    { toolCall },
    `${toolName} (${toolCall.toolCallId}) tool call detected in stream`,
  )
  toolCalls.push(toolCall)

  // Filter out restricted tools in ask mode unless exporting summary
  if (!agentTemplate.toolNames.includes(toolCall.toolName)) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: `Tool \`${toolName}\` is not currently available. Make sure to only use tools listed in the system instructions.`,
      },
    })
    return previousToolCallFinished
  }

  const { result: toolResultPromise, state: stateUpdate } = (
    codebuffToolHandlers[toolName] as CodebuffToolHandlerFunction<T>
  )({
    previousToolCallFinished,
    fileContext,
    agentStepId,
    clientSessionId,
    userInputId,
    fullResponse,
    writeToClient: onResponseChunk,
    requestClientToolCall: async (clientToolCall: ClientToolCall<T>) => {
      if (!checkLiveUserInput(userId, userInputId, clientSessionId)) {
        return ''
      }

      const clientToolResult = await requestToolCall(
        ws,
        userInputId,
        clientToolCall.toolName,
        clientToolCall.input,
      )
      return (
        clientToolResult.error ??
        (clientToolResult.output?.type === 'text'
          ? clientToolResult.output.value
          : 'undefined')
      )
    },
    toolCall,
    getLatestState: () => state,
    state,
  })

  for (const [key, value] of Object.entries(stateUpdate ?? {})) {
    if (key === 'agentState' && typeof value === 'object' && value !== null) {
      // Replace the agentState reference to ensure all updates are captured
      state.agentState = value
    } else {
      state[key] = value
    }
  }

  return toolResultPromise.then((result) => {
    const toolResult = {
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text' as const,
        value: result as string,
      },
    }
    logger.debug(
      { toolResult },
      `${toolName} (${toolResult.toolCallId}) tool result for tool`,
    )
    if (result === undefined) {
      return
    }

    onResponseChunk({
      type: 'tool_result',
      toolCallId: toolResult.toolCallId,
      output: toolResult.output,
    })

    toolResults.push(toolResult)

    state.messages.push({
      role: 'user' as const,
      content: asSystemMessage(renderToolResults([toolResult])),
    })
  })
}

