  resetRepoToCommit,
}

#!/usr/bin/env bun

import { execFileSync } from 'child_process'
import fs from 'fs'
import path from 'path'

import { TEST_REPOS_DIR } from '../test-setup'

/**
 * Extracts the repository name from a git URL
 * Supports both HTTPS and SSH formats
 * Examples:
 * - https://github.com/user/repo.git -> repo
 * - git@github.com:user/repo.git -> repo
 * - https://github.com/user/repo -> repo
 */
export function extractRepoNameFromUrl(repoUrl: string): string {
  // Remove .git suffix if present
  let cleanUrl = repoUrl.endsWith('.git') ? repoUrl.slice(0, -4) : repoUrl

  // Handle SSH format: git@github.com:user/repo
  if (cleanUrl.includes('@') && cleanUrl.includes(':')) {
    cleanUrl = cleanUrl.split(':')[1]
  }

  // Handle HTTPS format: https://github.com/user/repo
  if (cleanUrl.includes('://')) {
    cleanUrl = cleanUrl.split('://')[1]
  }

  // Remove domain and get the last part (repo name)
  const parts = cleanUrl.split('/')
  return parts[parts.length - 1]
}

export async function setupTestRepo(
  repoUrl: string,
  customRepoName: string,
  commitSha: string = 'HEAD',
): Promise<string> {
  const repoName = customRepoName || extractRepoNameFromUrl(repoUrl)
  console.log(`Setting up test repository: ${repoName}...`)

  const repoDir = path.join(TEST_REPOS_DIR, `${repoName}-${commitSha}`)

  // Create test-repos directory if it doesn't exist
  if (!fs.existsSync(TEST_REPOS_DIR)) {
    fs.mkdirSync(TEST_REPOS_DIR, { recursive: true })
  }

  // Remove existing repo if it exists
  if (fs.existsSync(repoDir)) {
    console.log(`Removing existing ${repoName} repo...`)
    fs.rmSync(repoDir, { recursive: true, force: true })
  }

  try {
    // Check if we're in a CI environment (GitHub Actions or Render.com)
    const isGitHubActions = process.env.GITHUB_ACTIONS === 'true'
    const isRenderCron =
      process.env.RENDER === 'true' || process.env.IS_PULL_REQUEST === 'false'

    // Always try authenticated approach first if we have a token, regardless of environment
    const githubToken = process.env.CODEBUFF_GITHUB_TOKEN
    const shouldUseAuth = githubToken && repoUrl.includes('github.com')

    if (shouldUseAuth) {
      // In CI environments or when we have a token, handle authentication for private repos
      const envName = isGitHubActions
        ? 'GitHub Actions'
        : isRenderCron
          ? 'Render.com'
          : 'Local with token'
      console.log(`${envName} detected - setting up authentication...`)

      let cloneUrl = repoUrl

      // Convert SSH URL to HTTPS with token if needed
      if (repoUrl.startsWith('git@github.com:')) {
        cloneUrl = repoUrl.replace('git@github.com:', 'https://github.com/')
      }
      if (cloneUrl.endsWith('.git')) {
        cloneUrl = cloneUrl.slice(0, -4)
      }

      // Validate token format
      if (
        !githubToken.startsWith('ghp_') &&
        !githubToken.startsWith('github_pat_')
      ) {
        console.warn('GitHub token does not appear to be in expected format')
      }

      // Add token authentication to the URL
      cloneUrl = cloneUrl.replace(
        'https://github.com/',
        `https://${githubToken}@github.com/`,
      )
      console.log('Using GitHub token authentication for private repository')
      console.log(`Token prefix: ${githubToken.substring(0, 10)}...`)

      console.log(
        `Cloning from remote: ${cloneUrl.replace(githubToken || '', '***')}`,
      )

      // Set git configuration for the clone operation
      const gitEnv = {
        ...process.env,
        GIT_TERMINAL_PROMPT: '0', // Disable interactive prompts
        GIT_ASKPASS: 'echo', // Provide empty password if prompted
      }

      execFileSync('git', ['clone', '--no-checkout', cloneUrl, repoDir], {
        timeout: 120_000, // 2 minute timeout for cloning
        stdio: 'inherit',
        env: gitEnv,
      })
      execFileSync('git', ['fetch', 'origin', commitSha], {
        cwd: repoDir,
        stdio: 'inherit',
        env: gitEnv,
      })
      execFileSync('git', ['checkout', commitSha], {
        cwd: repoDir,
        stdio: 'inherit',
      })
    } else {
      // Local development or public repos
      console.log(`Local environment detected - cloning from: ${repoUrl}`)

      execFileSync('git', ['clone', '--no-checkout', repoUrl, repoDir], {
        timeout: 120_000, // 2 minute timeout for cloning
        stdio: 'inherit',
      })
      execFileSync('git', ['fetch', 'origin', commitSha], {
        cwd: repoDir,
        stdio: 'inherit',
      })
      execFileSync('git', ['checkout', commitSha], {
        cwd: repoDir,
        stdio: 'inherit',
      })
    }

    console.log('Repository cloned successfully!')

    // Verify the setup worked
    if (!fs.existsSync(path.join(repoDir, '.git'))) {
      throw new Error('Git directory was not cloned properly')
    }

    // Verify git operations work in the cloned repo
    console.log('Verifying git operations...')
    const gitStatus = execFileSync('git', ['status', '--porcelain'], {
      cwd: repoDir,
      encoding: 'utf-8',
      timeout: 10_000,
    })

    console.log(
      `Git status check passed. Working directory status: ${gitStatus.trim() || 'clean'}`,
    )

    // Test that we can access commit history
    const commitCount = execFileSync('git', ['rev-list', '--count', 'HEAD'], {
      cwd: repoDir,
      encoding: 'utf-8',
      timeout: 10_000,
    })
      .toString()
      .trim()

    console.log(`Repository has ${commitCount} commits in history`)

    console.log('Repository verification passed')

    return repoDir
  } catch (error) {
    console.error(`Error setting up ${repoName} repository:`, error)

    // If authentication failed, provide more specific guidance
    if (
      error instanceof Error &&
      (error.message.includes('403') ||
        error.message.includes('authentication'))
    ) {
      console.error('\nAuthentication troubleshooting:')
      console.error(
        '1. Verify CODEBUFF_GITHUB_TOKEN environment variable is set',
      )
      console.error(
        '2. Ensure token has appropriate repository access permissions',
      )
      console.error(
        '3. Check if token is a Personal Access Token (PAT) with repo scope',
      )
      console.error(
        '4. For private repos, ensure token owner has access to the repository',
      )

      const token = process.env.CODEBUFF_GITHUB_TOKEN
      if (token) {
        console.error(
          `Token format: ${token.substring(0, 10)}... (length: ${token.length})`,
        )
      } else {
        console.error('CODEBUFF_GITHUB_TOKEN environment variable is not set')
      }
    }

    throw error
  }
}

// CLI handling
if (require.main === module) {
  const args = process.argv.slice(2)
  if (args.length < 3) {
    console.error(
      'Usage: bun run setup-test-repo <repo-url> <repo-name> <commit-sha>',
    )
    process.exit(1)
  }

  const [repoUrl, repoName, commitSha] = args

  setupTestRepo(repoUrl, repoName, commitSha)
    .then((repoDir) => {
      console.log(`Repository cloned successfully at ${repoDir}`)
      process.exit(0)
    })
    .catch((err) => {
      console.error(`Error setting up repository:`, err)
      process.exit(1)
    })
}

import { promptAiSdkStructured } from '@codebuff/backend/llm-apis/vercel-ai-sdk/ai-sdk'
import { countTokens } from '@codebuff/backend/util/token-counter'
import { geminiModels } from '@codebuff/common/constants'
import { generateCompactId } from '@codebuff/common/util/string'
import { createPatch } from 'diff'

import { JudgingAnalysisSchema } from './types'

import type { EvalRunLog } from './types'

const MAX_TOKENS = 1_000_000 // 1 million token limit

function buildAnalysisPrompt(
  evalRun: EvalRunLog,
  includeBeforeContent: boolean,
  includeAfterContent: boolean,
  truncatedTrace?: string,
): string {
  // Format timing information
  const durationSeconds = (evalRun.durationMs / 1000).toFixed(1)

  // Build ground truth changes section
  const groundTruthChanges = evalRun.eval_commit.fileStates
    .map((state) => {
      const diff = createPatch(state.path, state.preContent, state.postContent)
      let content = `File: ${state.path}\n\nUnified Diff (Ground Truth):\n${diff}`

      if (includeBeforeContent) {
        content += `\n\nPre-commit content:\n${state.preContent}`
      }

      if (includeAfterContent) {
        content += `\n\nPost-commit content (Ground Truth):\n${state.postContent}`
      }

      return content
    })
    .join('\n\n---\n\n')

  // Build Codebuff changes section
  const codebuffChanges = evalRun.fileStates
    .map((state) => {
      const diff = createPatch(state.path, state.preContent, state.postContent)
      let content = `File: ${state.path}\n\nUnified Diff (Codebuff's Changes):\n${diff}`

      if (includeBeforeContent) {
        content += `\n\nPre-commit content:\n${state.preContent}`
      }

      if (includeAfterContent) {
        content += `\n\nPost-commit content (Codebuff's Attempt):\n${state.postContent}`
      }

      return content
    })
    .join('\n\n---\n\n')

  // Build trace section
  const traceContent =
    truncatedTrace ||
    evalRun.trace
      .map(({ prompt, steps }) =>
        `Prompt: ${prompt}\n\nCodebuff Steps: ${JSON.stringify(steps)}`.trim(),
      )
      .join('\n\n')

  return `You are an expert software engineer tasked with analyzing and scoring the code quality of changes made by an AI coding assistant (Codebuff). Please analyze the following interaction trace and compare both the attempted changes and the ground truth changes.

[SPEC]
${evalRun.eval_commit.spec}
[/SPEC]

[TIMING_INFORMATION]
Task Duration: ${durationSeconds} seconds (${evalRun.durationMs}ms)
[/TIMING_INFORMATION]

[GROUND_TRUTH_CHANGES]
${groundTruthChanges}
[/GROUND_TRUTH_CHANGES]

[CHANGES_BY_CODEBUFF]
${codebuffChanges}
[/CHANGES_BY_CODEBUFF]

[TRACE]
${traceContent}
[/TRACE]

[ERROR]
${evalRun.error ? evalRun.error : 'None'}
[/ERROR]

Please analyze the trace of the implementation attempt and provide:
1. A detailed analysis of the implementation trace and the final changes. Include how the changes compare to the ground truth change. Does it have similar behavior at least?
2. Key strengths and weaknesses of the implementation
3. Numerical scores (0-10):
   - Completion: How completely and correctly was the spec implemented compared to the ground truth changes?
   - Efficiency: How efficiently did Codebuff respond to the Agent's prompts without taking unnecessary steps? Speed is important! Consider the task duration of ${durationSeconds} seconds.
   - Code Quality: How well-structured, maintainable and idiomatic is the code?
   - Overall: Combined assessment of the implementation quality

Focus on:
- Correctness and completeness compared to the ground truth changes
- Quality of the code produced
- Minimal changes: it's better to change as little code as possible to accomplish what the agent prompted
- Speed and efficiency: did Codebuff make unnecessary changes or take unnecessary steps? The task took ${durationSeconds} seconds - was this reasonable for the complexity?
- Error: If there was an error encountered, you should give a very low score.

Provide your response in a structured format with analysis, lists of strengths and weaknesses, and metrics.`
}

function truncateTraceFromEnd(trace: any[], maxTokens: number): string {
  // Start with full trace and progressively remove from the end
  let currentTrace = [...trace]

  while (currentTrace.length > 0) {
    const traceContent = currentTrace
      .map(({ prompt, steps }) =>
        `Prompt: ${prompt}\n\nCodebuff Steps: ${JSON.stringify(steps)}`.trim(),
      )
      .join('\n\n')

    if (countTokens(traceContent) <= maxTokens) {
      const truncationNotice =
        currentTrace.length < trace.length
          ? `\n\n[TRACE TRUNCATED: Showing ${currentTrace.length} of ${trace.length} trace entries to fit within token limit]`
          : ''
      return traceContent + truncationNotice
    }

    // Remove the last entry and try again
    currentTrace.pop()
  }

  return '[TRACE TRUNCATED: All trace entries removed to fit within token limit]'
}

export async function judgeEvalRun(evalRun: EvalRunLog) {
  let finalPrompt: string | undefined

  // Try different levels of content inclusion until we fit within token limit
  const attempts = [
    {
      includeBeforeContent: true,
      includeAfterContent: true,
      truncatedTrace: undefined,
    },
    {
      includeBeforeContent: false,
      includeAfterContent: true,
      truncatedTrace: undefined,
    },
    {
      includeBeforeContent: false,
      includeAfterContent: false,
      truncatedTrace: undefined,
    },
  ]

  for (const attempt of attempts) {
    const prompt = buildAnalysisPrompt(
      evalRun,
      attempt.includeBeforeContent,
      attempt.includeAfterContent,
      attempt.truncatedTrace,
    )

    const tokenCount = countTokens(prompt)

    if (tokenCount <= MAX_TOKENS) {
      console.log(
        `Using prompt with ${tokenCount} tokens (before: ${attempt.includeBeforeContent}, after: ${attempt.includeAfterContent})`,
      )
      finalPrompt = prompt
      break
    }
  }

  if (!finalPrompt) {
    // If even without file contents we're still too big, truncate the trace
    // First, calculate base prompt size with empty trace to determine available tokens for trace
    const basePrompt = buildAnalysisPrompt(
      { ...evalRun, trace: [] }, // Empty trace
      false, // includeBeforeContent
      false, // includeAfterContent
      '', // empty trace content
    )
    const baseTokens = countTokens(basePrompt)
    const maxTraceTokens = MAX_TOKENS - baseTokens - 100 // Reserve 100 tokens for truncation notice

    const truncatedTrace = truncateTraceFromEnd(evalRun.trace, maxTraceTokens)

    finalPrompt = buildAnalysisPrompt(
      evalRun,
      false, // includeBeforeContent
      false, // includeAfterContent
      truncatedTrace,
    )

    const finalTokenCount = countTokens(finalPrompt)
    console.log(
      `Using truncated prompt with ${finalTokenCount} tokens (trace truncated, base: ${baseTokens}, max trace: ${maxTraceTokens})`,
    )
  }

  // Run 3 judges in parallel
  console.log('Running 3 judges in parallel for more robust scoring...')

  const judgePromises = Array.from({ length: 3 }, (_, index) =>
    promptAiSdkStructured({
      messages: [{ role: 'user', content: finalPrompt }],
      schema: JudgingAnalysisSchema,
      model: geminiModels.gemini2_5_pro_preview,
      clientSessionId: generateCompactId(),
      fingerprintId: generateCompactId(),
      userInputId: generateCompactId(),
      userId: undefined,
      timeout: 10 * 60 * 1000, // 10 minute timeout
    }).catch((error) => {
      console.warn(`Judge ${index + 1} failed:`, error)
      return null
    }),
  )

  const judgeResults = await Promise.all(judgePromises)
  const validResults = judgeResults.filter((result) => result !== null)

  if (validResults.length === 0) {
    throw new Error('All judges failed to provide results')
  }

  console.log(`Successfully got results from ${validResults.length}/3 judges`)

  // Sort judges by overall score and select the median
  const sortedResults = validResults.sort(
    (a, b) => a.metrics.overallScore - b.metrics.overallScore,
  )
  const medianIndex = Math.floor(sortedResults.length / 2)
  const medianResult = sortedResults[medianIndex]

  console.log(
    `Using median judge (${medianIndex + 1} of ${sortedResults.length}) with overall score: ${medianResult.metrics.overallScore}`,
  )

  return medianResult
}

