    .array(ProblemSchema)
    .describe(
      'Priority-ordered list of problems to solve, most important first',
    ),
  recommendations: z
    .array(z.string())
    .describe('Specific development recommendations based on the analysis'),
})

export type PostEvalAnalysis = z.infer<typeof PostEvalAnalysisSchema>

function buildAnalysisPrompt(evalResult: FullEvalLog): string {
  // Build summary of overall metrics
  const metrics = evalResult.overall_metrics
  const metricsSection = `
Overall Performance Metrics:
- Average Completion Score: ${metrics.average_completion.toFixed(2)}/10
- Average Efficiency Score: ${metrics.average_efficiency.toFixed(2)}/10
- Average Code Quality Score: ${metrics.average_code_quality.toFixed(2)}/10
- Average Overall Score: ${metrics.average_overall.toFixed(2)}/10
- Average Duration: ${(metrics.average_duration_ms / 1000).toFixed(1)} seconds
- Success Rate: ${metrics.successful_runs}/${metrics.total_runs} (${((metrics.successful_runs / metrics.total_runs) * 100).toFixed(1)}%)
`

  // Build detailed analysis of each eval run
  const evalRunsSection = evalResult.eval_runs
    .map((run, index) => {
      const judging = run.judging_results
      const durationSeconds = (run.durationMs / 1000).toFixed(1)

      return `
=== Eval Run ${index + 1}: ${run.eval_commit.message} ===
Spec: ${run.eval_commit.spec}
Duration: ${durationSeconds}s
Error: ${run.error || 'None'}

Scores:
- Completion: ${judging.metrics.completionScore}/10
- Efficiency: ${judging.metrics.efficiencyScore}/10
- Code Quality: ${judging.metrics.codeQualityScore}/10
- Overall: ${judging.metrics.overallScore}/10

Judge Analysis: ${judging.analysis}

Strengths: ${judging.strengths.join('; ')}
Weaknesses: ${judging.weaknesses.join('; ')}

Files Changed by Codebuff: ${run.fileStates.map((f) => f.path).join(', ') || 'None'}
Ground Truth Files: ${run.eval_commit.fileStates.map((f) => f.path).join(', ')}

Trace Summary: ${run.trace.length} conversation turns
${run.trace.map((t, i) => `Turn ${i + 1}: "${t.prompt}" -> ${t.steps.length} steps`).join('\n')}
`
    })
    .join('\n')

  return `You are an expert software engineering manager analyzing the performance of Codebuff, an AI coding assistant. You have been given the results of a comprehensive evaluation where Codebuff attempted to implement various coding tasks.

Your goal is to identify the most important problems that need to be solved to improve Codebuff's performance, prioritized by impact and frequency. Focus on actionable development priorities that the engineering team can work on.

${metricsSection}

${evalRunsSection}

Please analyze these results and provide:

1. A summary of the overall performance and key patterns
2. A priority-ordered list of specific problems to solve (most important first)
3. Specific development recommendations

For each problem, consider:
- How frequently it occurs across tasks
- How severely it impacts performance
- How actionable it is for the development team
- Specific examples from the eval runs

Focus on systemic issues before one-off, smaller problems. Look for patterns in the judge analyses, weaknesses, and failure modes.`
}

// Warning: this function completely vibe-coded, probably wrong.
function truncatePromptIfNeeded(prompt: string, maxTokens: number): string {
  const tokenCount = countTokens(prompt)

  if (tokenCount <= maxTokens) {
    return prompt
  }

  // If too long, truncate the detailed eval runs section while keeping the summary
  const lines = prompt.split('\n')
  const metricsEndIndex = lines.findIndex((line) =>
    line.includes('=== Eval Run 1:'),
  )

  if (metricsEndIndex === -1) {
    // Fallback: just truncate from the end
    const words = prompt.split(' ')
    const targetWords = Math.floor((words.length * maxTokens) / tokenCount)
    return (
      words.slice(0, targetWords).join(' ') +
      '\n\n[TRUNCATED: Content reduced to fit token limit]'
    )
  }

  // Keep the intro and metrics, but limit the detailed runs
  const intro = lines.slice(0, metricsEndIndex).join('\n')
  const evalRunsLines = lines.slice(metricsEndIndex)

  // Calculate how many tokens we have left for eval runs
  const introTokens = countTokens(intro)
  const remainingTokens = maxTokens - introTokens - 100 // Reserve 100 for truncation notice

  if (remainingTokens <= 0) {
    return intro + '\n\n[TRUNCATED: Eval runs removed to fit token limit]'
  }

  // Truncate eval runs to fit
  const evalRunsText = evalRunsLines.join('\n')
  const evalRunsWords = evalRunsText.split(' ')
  const targetEvalWords = Math.floor(
    (evalRunsWords.length * remainingTokens) / countTokens(evalRunsText),
  )

  const truncatedEvalRuns = evalRunsWords.slice(0, targetEvalWords).join(' ')

  return (
    intro +
    '\n' +
    truncatedEvalRuns +
    '\n\n[TRUNCATED: Some eval run details removed to fit token limit]'
  )
}

/**
 * Analyzes eval results to identify priority problems for Codebuff development
 * @param evalResult The complete eval results from running git evals
 * @returns Analysis with prioritized list of problems to solve
 */
export async function analyzeEvalResults(
  evalResult: FullEvalLog,
): Promise<PostEvalAnalysis> {
  const prompt = buildAnalysisPrompt(evalResult)
  const finalPrompt = truncatePromptIfNeeded(prompt, MAX_TOKENS)

  const tokenCount = countTokens(finalPrompt)
  console.log(`Post-eval analysis prompt: ${tokenCount} tokens`)

  return promptAiSdkStructured({
    messages: [{ role: 'user', content: finalPrompt }],
    schema: PostEvalAnalysisSchema,
    model: geminiModels.gemini2_5_pro_preview,
    clientSessionId: generateCompactId(),
    fingerprintId: generateCompactId(),
    userInputId: generateCompactId(),
    userId: undefined,
    timeout: 10 * 60 * 1000, // 10 minute timeout
  })
}

import { renderToolResults } from '@codebuff/common/tools/utils'
import { AgentTemplateTypes } from '@codebuff/common/types/session-state'
import { generateCompactId } from '@codebuff/common/util/string'
import { uniq } from 'lodash'

import { checkTerminalCommand } from './check-terminal-command'
import { loopAgentSteps } from './run-agent-step'
import { getAgentTemplate } from './templates/agent-registry'
import { logger } from './util/logger'
import { expireMessages } from './util/messages'
import { requestToolCall } from './websockets/websocket-action'

import type { AgentTemplate } from './templates/types'
import type { ClientToolCall } from './tools/constants'
import type { ClientAction } from '@codebuff/common/actions'
import type { CostMode } from '@codebuff/common/constants'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  SessionState,
  ToolResult,
  AgentTemplateType,
} from '@codebuff/common/types/session-state'
import type { WebSocket } from 'ws'

export interface MainPromptOptions {
  userId: string | undefined
  clientSessionId: string
  onResponseChunk: (chunk: string | PrintModeEvent) => void
  localAgentTemplates: Record<string, AgentTemplate>
}

export const mainPrompt = async (
  ws: WebSocket,
  action: ClientAction<'prompt'>,
  options: MainPromptOptions,
): Promise<{
  sessionState: SessionState
  toolCalls: Array<ClientToolCall>
  toolResults: Array<ToolResult>
}> => {
  const { userId, clientSessionId, onResponseChunk, localAgentTemplates } =
    options

  const {
    prompt,
    sessionState: sessionState,
    fingerprintId,
    costMode,
    promptId,
    agentId,
    promptParams,
  } = action
  const { fileContext, mainAgentState } = sessionState

  if (prompt) {
    // Check if this is a direct terminal command
    const startTime = Date.now()
    const terminalCommand = await checkTerminalCommand(prompt, {
      clientSessionId,
      fingerprintId,
      userInputId: promptId,
      userId,
    })
    const duration = Date.now() - startTime

    if (terminalCommand) {
      logger.debug(
        {
          duration,
          prompt,
        },
        `Detected terminal command in ${duration}ms, executing directly: ${prompt}`,
      )

      const response = await requestToolCall(
        ws,
        promptId,
        'run_terminal_command',
        {
          command: terminalCommand,
          mode: 'user',
          process_type: 'SYNC',
          timeout_seconds: -1,
        },
      )

      const toolResult: ToolResult['output'] = {
        type: 'text',
        value:
          (response.success ? response.output?.value : response.error) || '',
      }
      if (response.success) {
        mainAgentState.messageHistory.push({
          role: 'user',
          content: renderToolResults([
            {
              toolName: 'run_terminal_command',
              toolCallId: generateCompactId(),
              output: toolResult,
            },
          ]),
        })
      }

      const newSessionState = {
        ...sessionState,
        messageHistory: expireMessages(
          mainAgentState.messageHistory,
          'userPrompt',
        ),
      }

      return {
        sessionState: newSessionState,
        toolCalls: [],
        toolResults: [],
      }
    }
  }

  const availableAgents = Object.keys(localAgentTemplates)

  // Determine agent type - prioritize CLI agent selection, then config base agent, then cost mode
  let agentType: AgentTemplateType

  if (agentId) {
    if (!(await getAgentTemplate(agentId, localAgentTemplates))) {
      throw new Error(
        `Invalid agent ID: "${agentId}". Available agents: ${availableAgents.join(', ')}`,
      )
    }

    agentType = agentId
    logger.info(
      {
        agentId,
        promptParams,
        prompt: prompt?.slice(0, 50),
      },
      `Using CLI-specified agent: ${agentId}`,
    )
  } else {
    // Check for base agent in config
    const configBaseAgent = fileContext.codebuffConfig?.baseAgent
    if (configBaseAgent) {
      if (!(await getAgentTemplate(configBaseAgent, localAgentTemplates))) {
        throw new Error(
          `Invalid base agent in config: "${configBaseAgent}". Available agents: ${availableAgents.join(', ')}`,
        )
      }
      agentType = configBaseAgent
      logger.info(
        {
          configBaseAgent,
          promptParams,
          prompt: prompt?.slice(0, 50),
        },
        `Using config-specified base agent: ${configBaseAgent}`,
      )
    } else {
      // Fall back to cost mode mapping
      agentType = (
        {
          ask: AgentTemplateTypes.ask,
          lite: AgentTemplateTypes.base_lite,
          normal: AgentTemplateTypes.base,
          max: AgentTemplateTypes.base_max,
          experimental: AgentTemplateTypes.base_experimental,
        } satisfies Record<CostMode, AgentTemplateType>
      )[costMode]
    }
  }

  mainAgentState.agentType = agentType

  let mainAgentTemplate = await getAgentTemplate(agentType, localAgentTemplates)
  if (!mainAgentTemplate) {
    throw new Error(`Agent template not found for type: ${agentType}`)
  }

  let updatedSubagents = mainAgentTemplate.spawnableAgents
  if (!agentId) {
    // If --agent is not specified, use the spawnableAgents from the codebuff config or add all local agents
    updatedSubagents =
      fileContext.codebuffConfig?.spawnableAgents ??
      uniq([...mainAgentTemplate.spawnableAgents, ...availableAgents])
  }
  mainAgentTemplate.spawnableAgents = updatedSubagents
  localAgentTemplates[agentType] = mainAgentTemplate

  const { agentState } = await loopAgentSteps(ws, {
    userInputId: promptId,
    prompt,
    params: promptParams,
    agentType,
    agentState: mainAgentState,
    fingerprintId,
    fileContext,
    toolResults: [],
    userId,
    clientSessionId,
    onResponseChunk,
    localAgentTemplates,
  })

  return {
    sessionState: {
      fileContext,
      mainAgentState: agentState,
    },
    toolCalls: [],
    toolResults: [],
  }
}

import { MAX_AGENT_STEPS_DEFAULT } from '@codebuff/common/constants/agents'
import { mainPrompt } from './main-prompt'

import type { MainPromptOptions } from './main-prompt'
import type { ClientToolCall } from './tools/constants'
import type { ClientAction } from '@codebuff/common/actions'
import type {
  SessionState,
  ToolResult,
} from '@codebuff/common/types/session-state'
import type { WebSocket } from 'ws'

export async function loopMainPrompt(
  ws: WebSocket,
  action: ClientAction<'prompt'>,
  options: MainPromptOptions & { maxIterations?: number },
): Promise<{
  sessionState: SessionState
  toolCalls: Array<ClientToolCall>
  toolResults: Array<ToolResult>
}> {
  const maxIterations = options.maxIterations ?? MAX_AGENT_STEPS_DEFAULT
  let { sessionState, toolResults, toolCalls } = await mainPrompt(
    ws,
    action,
    options,
  )
  let iterations = 0
  // Continue running as long as the agent is using tools and hasn't decided to end the turn.
  while (
    toolCalls.length > 0 &&
    !toolCalls.some((tc) => tc.toolName === 'end_turn')
  ) {
    const nextAction: ClientAction<'prompt'> = {
      ...action,
      sessionState,
      toolResults,
      prompt: undefined,
    }
    const result = await mainPrompt(ws, nextAction, options)
    sessionState = result.sessionState
    toolResults = result.toolResults
    toolCalls = result.toolCalls
    iterations++
    if (iterations >= maxIterations) {
      break
    }
  }

  return { sessionState, toolCalls, toolResults }
}

import { endsAgentStepParam } from '@codebuff/common/tools/constants'
import { renderToolResults } from '@codebuff/common/tools/utils'
import { generateCompactId } from '@codebuff/common/util/string'
import z from 'zod/v4'

import { checkLiveUserInput } from '../live-user-inputs'
import { logger } from '../util/logger'
import { asSystemMessage } from '../util/messages'
import { requestToolCall } from '../websockets/websocket-action'
import { codebuffToolDefs } from './definitions/list'
import { codebuffToolHandlers } from './handlers/list'

import type { ClientToolCall, CodebuffToolCall } from './constants'
import type { CodebuffToolHandlerFunction } from './handlers/handler-function-type'
import type { AgentTemplate } from '../templates/types'
import type { ToolName } from '@codebuff/common/tools/constants'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type { ToolResult } from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'
import type { WebSocket } from 'ws'

export type ToolCallError = {
  toolName?: string
  input: Record<string, unknown>
  error: string
} & Pick<CodebuffToolCall, 'toolCallId'>

export function parseRawToolCall<T extends ToolName = ToolName>(
  rawToolCall: {
    toolName: T
    toolCallId: string
    input: Record<string, unknown>
  },
  autoInsertEndStepParam: boolean = false,
): CodebuffToolCall<T> | ToolCallError {
  const toolName = rawToolCall.toolName

  if (!(toolName in codebuffToolDefs)) {
    return {
      toolName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Tool ${toolName} not found`,
    }
  }
  const validName = toolName as T

  const processedParameters: Record<string, any> = {}
  for (const [param, val] of Object.entries(rawToolCall.input ?? {})) {
    processedParameters[param] = val
  }

  // Add the required codebuff_end_step parameter with the correct value for this tool if requested
  if (autoInsertEndStepParam) {
    processedParameters[endsAgentStepParam] =
      codebuffToolDefs[validName].endsAgentStep
  }

  const paramsSchema = codebuffToolDefs[validName].endsAgentStep
    ? (
        codebuffToolDefs[validName]
          .parameters satisfies z.ZodObject as z.ZodObject
      ).extend({
        [endsAgentStepParam]: z.literal(
          codebuffToolDefs[validName].endsAgentStep,
        ),
      })
    : codebuffToolDefs[validName].parameters
  const result = paramsSchema.safeParse(processedParameters)

  if (!result.success) {
    return {
      toolName: validName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Invalid parameters for ${validName}: ${JSON.stringify(
        result.error.issues,
        null,
        2,
      )}`,
    }
  }

  if (endsAgentStepParam in result.data) {
    delete result.data[endsAgentStepParam]
  }

  return {
    toolName: validName,
    input: result.data,
    toolCallId: rawToolCall.toolCallId,
  } as CodebuffToolCall<T>
}

export interface ExecuteToolCallParams<T extends ToolName = ToolName> {
  toolName: T
  input: Record<string, unknown>
  toolCalls: CodebuffToolCall[]
  toolResults: ToolResult[]
  previousToolCallFinished: Promise<void>
  ws: WebSocket
  agentTemplate: AgentTemplate
  fileContext: ProjectFileContext
  agentStepId: string
  clientSessionId: string
  userInputId: string
  fullResponse: string
  onResponseChunk: (chunk: string | PrintModeEvent) => void
  state: Record<string, any>
  userId: string | undefined
  autoInsertEndStepParam?: boolean
}

export function executeToolCall<T extends ToolName>({
  toolName,
  input,
  toolCalls,
  toolResults,
  previousToolCallFinished,
  ws,
  agentTemplate,
  fileContext,
  agentStepId,
  clientSessionId,
  userInputId,
  fullResponse,
  onResponseChunk,
  state,
  userId,
  autoInsertEndStepParam = false,
}: ExecuteToolCallParams<T>): Promise<void> {
  const toolCall: CodebuffToolCall<T> | ToolCallError = parseRawToolCall<T>(
    {
      toolName,
      toolCallId: generateCompactId(),
      input,
    },
    autoInsertEndStepParam,
  )
  if ('error' in toolCall) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: toolCall.error,
      },
    })
    logger.debug(
      { toolCall, error: toolCall.error },
      `${toolName} error: ${toolCall.error}`,
    )
    return previousToolCallFinished
  }

  onResponseChunk({
    type: 'tool_call',
    toolCallId: toolCall.toolCallId,
    toolName,
    input: toolCall.input,
  })

  logger.debug(
    { toolCall },
    `${toolName} (${toolCall.toolCallId}) tool call detected in stream`,
  )
  toolCalls.push(toolCall)

  // Filter out restricted tools in ask mode unless exporting summary
  if (!agentTemplate.toolNames.includes(toolCall.toolName)) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: `Tool \`${toolName}\` is not currently available. Make sure to only use tools listed in the system instructions.`,
      },
    })
    return previousToolCallFinished
  }

  const { result: toolResultPromise, state: stateUpdate } = (
    codebuffToolHandlers[toolName] as CodebuffToolHandlerFunction<T>
  )({
    previousToolCallFinished,
    fileContext,
    agentStepId,
    clientSessionId,
    userInputId,
    fullResponse,
    writeToClient: onResponseChunk,
    requestClientToolCall: async (clientToolCall: ClientToolCall<T>) => {
      if (!checkLiveUserInput(userId, userInputId, clientSessionId)) {
        return ''
      }

      const clientToolResult = await requestToolCall(
        ws,
        userInputId,
        clientToolCall.toolName,
        clientToolCall.input,
      )
      return (
        clientToolResult.error ??
        (clientToolResult.output?.type === 'text'
          ? clientToolResult.output.value
          : 'undefined')
      )
    },
    toolCall,
    getLatestState: () => state,
    state,
  })

  for (const [key, value] of Object.entries(stateUpdate ?? {})) {
    if (key === 'agentState' && typeof value === 'object' && value !== null) {
      // Replace the agentState reference to ensure all updates are captured
      state.agentState = value
    } else {
      state[key] = value
    }
  }

  return toolResultPromise.then((result) => {
    const toolResult = {
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text' as const,
        value: result as string,
      },
    }
    logger.debug(
      { toolResult },
      `${toolName} (${toolResult.toolCallId}) tool result for tool`,
    )
    if (result === undefined) {
      return
    }

    onResponseChunk({
      type: 'tool_result',
      toolCallId: toolResult.toolCallId,
      output: toolResult.output,
    })

    toolResults.push(toolResult)

    state.messages.push({
      role: 'user' as const,
      content: asSystemMessage(renderToolResults([toolResult])),
    })
  })
}

import { execSync } from 'child_process'
import { EventEmitter } from 'events'
import fs from 'fs'
import path from 'path'

import { runAgentStep } from '@codebuff/backend/run-agent-step'
import { assembleLocalAgentTemplates } from '@codebuff/backend/templates/agent-registry'
import { getFileTokenScores } from '@codebuff/code-map/parse'
import { TEST_USER_ID } from '@codebuff/common/constants'
import { mockModule } from '@codebuff/common/testing/mock-modules'
import { applyAndRevertChanges } from '@codebuff/common/util/changes'
import { generateCompactId } from '@codebuff/common/util/string'
import { handleToolCall } from '@codebuff/npm-app/tool-handlers'
import { getSystemInfo } from '@codebuff/npm-app/utils/system-info'
import { mock } from 'bun:test'
import { blue } from 'picocolors'

import {
  getAllFilePaths,
  getProjectFileTree,
} from '../common/src/project-file-tree'

import type { ClientToolCall } from '@codebuff/backend/tools/constants'
import type {
  requestFiles as originalRequestFiles,
  requestToolCall as originalRequestToolCall,
} from '@codebuff/backend/websockets/websocket-action'
import type { FileChanges } from '@codebuff/common/actions'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  AgentState,
  AgentTemplateType,
  SessionState,
  ToolResult,
} from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'
import type { WebSocket } from 'ws'

const DEBUG_MODE = true

export type AgentStep = {
  response: string
  toolCalls: ClientToolCall[]
  toolResults: ToolResult[]
}

function readMockFile(projectRoot: string, filePath: string): string | null {
  const fullPath = path.join(projectRoot, filePath)
  try {
    return fs.readFileSync(fullPath, 'utf-8')
  } catch (error) {
    return null
  }
}

let toolCalls: ClientToolCall[] = []
let toolResults: ToolResult[] = []
export function createFileReadingMock(projectRoot: string) {
  mockModule('@codebuff/backend/websockets/websocket-action', () => ({
    requestFiles: ((ws: WebSocket, filePaths: string[]) => {
      const files: Record<string, string | null> = {}
      for (const filePath of filePaths) {
        files[filePath] = readMockFile(projectRoot, filePath)
      }
      return Promise.resolve(files)
    }) satisfies typeof originalRequestFiles,
    requestToolCall: (async (
      ws: WebSocket,
      userInputId: string,
      toolName: string,
      input: Record<string, any>,
      timeout: number = 30_000,
    ): ReturnType<typeof originalRequestToolCall> => {
      // Execute the tool call using existing tool handlers
      const toolCall = {
        toolCallId: generateCompactId(),
        toolName,
        input,
      }
      toolCalls.push(toolCall as ClientToolCall)
      try {
        const toolResult = await handleToolCall(toolCall as any)
        toolResults.push({
          toolName: toolCall.toolName,
          toolCallId: toolCall.toolCallId,
          output: toolResult.output,
        })

        // Send successful response back to backend
        return {
          success: true,
          output: toolResult.output,
        }
      } catch (error) {
        // Send error response back to backend
        const resultString =
          error instanceof Error ? error.message : String(error)
        toolResults.push({
          toolName: toolCall.toolName,
          toolCallId: toolCall.toolCallId,
          output: { type: 'text', value: resultString },
        })
        return {
          success: false,
          error: resultString,
        }
      }
    }) satisfies typeof originalRequestToolCall,
  }))
}

export async function getProjectFileContext(
  projectPath: string,
): Promise<ProjectFileContext> {
  const fileTree = getProjectFileTree(projectPath)
  const allFilePaths = getAllFilePaths(fileTree)
  const knowledgeFilePaths = allFilePaths.filter((filePath) =>
    filePath.endsWith('knowledge.md'),
  )
  const knowledgeFiles: Record<string, string> = {}
  for (const filePath of knowledgeFilePaths) {
    const content = readMockFile(projectPath, filePath)
    if (content !== null) {
      knowledgeFiles[filePath] = content
    }
  }
  const fileTokenScores = (await getFileTokenScores(projectPath, allFilePaths))
    .tokenScores
  return {
    projectRoot: projectPath,
    cwd: projectPath,
    gitChanges: {
      status: '',
      diff: '',
      diffCached: '',
      lastCommitMessages: '',
    },
    changesSinceLastChat: {},
    fileVersions: [],
    systemInfo: getSystemInfo(),
    shellConfigFiles: {},
    knowledgeFiles,
    fileTokenScores,
    fileTree,
    agentTemplates: {},
  }
}

export async function runAgentStepScaffolding(
  agentState: AgentState,
  fileContext: ProjectFileContext,
  prompt: string | undefined,
  sessionId: string,
  agentType: AgentTemplateType,
) {
  const mockWs = new EventEmitter() as WebSocket
  mockWs.send = mock()
  mockWs.close = mock()

  let fullResponse = ''
  const { agentTemplates: localAgentTemplates } =
    assembleLocalAgentTemplates(fileContext)

  const result = await runAgentStep(mockWs, {
    userId: TEST_USER_ID,
    userInputId: generateCompactId(),
    clientSessionId: sessionId,
    fingerprintId: 'test-fingerprint-id',
    onResponseChunk: (chunk: string | PrintModeEvent) => {
      if (typeof chunk !== 'string') {
        return
      }
      if (DEBUG_MODE) {
        process.stdout.write(chunk)
      }
      fullResponse += chunk
    },
    agentType,
    fileContext,
    localAgentTemplates,
    agentState,
    prompt,
    params: undefined,
  })

  return {
    ...result,
    fullResponse,
  }
}

export async function runToolCalls(toolCalls: ClientToolCall[]) {
  const toolResults: ToolResult[] = []
  for (const toolCall of toolCalls) {
    if (
      toolCall.toolName === 'spawn_agents' ||
      toolCall.toolName === 'set_output'
    ) {
      // should never happen
      continue
    }
    const toolResult = await handleToolCall(toolCall)
    toolResults.push(toolResult)
  }
  return toolResults
}

export async function loopMainPrompt({
  sessionState,
  prompt,
  projectPath,
  maxIterations,
  stopCondition,
  agentType,
}: {
  sessionState: SessionState
  prompt: string
  projectPath: string
  maxIterations: number
  stopCondition?: (sessionState: AgentState) => boolean
  agentType: AgentTemplateType
}) {
  console.log(blue(prompt))

  const startTime = Date.now()
  const sessionId = 'test-session-id-' + generateCompactId()
  let currentAgentState = sessionState.mainAgentState
  let iterations = 1
  const steps: AgentStep[] = []

  for (; iterations < maxIterations; iterations++) {
    console.log('\nIteration', iterations)
    let {
      agentState: newAgentState,
      fullResponse,
      shouldEndTurn,
    } = await runAgentStepScaffolding(
      currentAgentState,
      sessionState.fileContext,
      iterations === 1 ? prompt : undefined,
      sessionId,
      agentType,
    )
    currentAgentState = newAgentState

    const stop = stopCondition && stopCondition(currentAgentState)
    if (stop) break

    steps.push({
      response: fullResponse,
      toolCalls,
      toolResults,
    })

    toolCalls = []
    toolResults = []

    if (shouldEndTurn) {
      break
    }
  }

  console.log('Main loop finished!')
  console.log('  - iterations', iterations)
  console.log(
    '  - took',
    ((Date.now() - startTime) / 1000).toFixed(2),
    'seconds',
  )

  return {
    agentState: currentAgentState,
    iterations: iterations - 1,
    steps,
    duration: Date.now() - startTime,
  }
}

export function extractErrorFiles(output: string): string[] {
  const lines = output.split('\n')
  return lines
    .filter((line) => line.includes(': error TS'))
    .map((line) => line.split('(')[0].trim())
}

export const applyAndRevertChangesSequentially = (() => {
  const queue: Array<() => Promise<void>> = []
  let isProcessing = false

  const processQueue = async () => {
    if (isProcessing || queue.length === 0) return
    isProcessing = true
    const nextOperation = queue.shift()
    if (nextOperation) {
      await nextOperation()
    }
    isProcessing = false
    processQueue()
  }

  return async (
    projectRoot: string,
    changes: FileChanges,
    onApply: () => Promise<void>,
  ) => {
    return new Promise<void>((resolve, reject) => {
      queue.push(async () => {
        try {
          await applyAndRevertChanges(projectRoot, changes, onApply)
          resolve()
        } catch (error) {
          reject(error)
        }
      })
      processQueue()
    })
  }
})()

export function resetRepoToCommit(projectPath: string, commit: string) {
  console.log(`Resetting repository at ${projectPath} to commit ${commit}...`)
  try {
    execSync(
      `cd ${projectPath} && git reset --hard ${commit} && git clean -fd`,
      {
        timeout: 30_000,
      },
    )
    console.log('Repository reset successful')
  } catch (error) {
    console.error('Error resetting repository:', error)
    throw error
  }
}

export default {
  createFileReadingMock,
  getProjectFileContext,
  runAgentStepScaffolding,
  runToolCalls,
  loopMainPrompt,
  extractErrorFiles,
  applyAndRevertChangesSequentially,
  resetRepoToCommit,
}

