import { AGENT_PERSONAS } from '@codebuff/common/constants/agents'
import { z } from 'zod/v4'

import { getAgentTemplate } from '../templates/agent-registry'
import { extractAuthTokenFromHeader } from '../util/auth-helpers'
import { logger } from '../util/logger'

import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'

// Add short-lived cache for positive validations
const AGENT_VALIDATION_CACHE_TTL_MS = 5 * 60 * 1000 // 5 minutes

type CacheEntry = {
  result: { valid: true; source?: string; normalizedId?: string; displayName?: string }
  expiresAt: number
}

const agentValidationCache = new Map<string, CacheEntry>()

// Simple request schema
const validateAgentRequestSchema = z.object({
  agentId: z.string().min(1),
})

// GET /api/agents/validate-name
export async function validateAgentNameHandler(
  req: ExpressRequest,
  res: ExpressResponse,
  next: NextFunction,
): Promise<void | ExpressResponse> {
  try {
    // Parse from query instead (GET)
    const { agentId } = validateAgentRequestSchema.parse({
      agentId: String((req.query as any)?.agentId ?? ''),
    })

    // Check for x-codebuff-api-key header for authentication
    const apiKey = extractAuthTokenFromHeader(req)

    if (!apiKey) {
      return res.status(403).json({ error: 'API key required' })
    }

    logger.debug(
      {
        hasApiKey: true,
        agentId,
      },
      'Agent validation request with API key authentication',
    )

    // Check cache (positive results only)
    const cached = agentValidationCache.get(agentId)
    if (cached && cached.expiresAt > Date.now()) {
      return res.status(200).json({ ...cached.result, cached: true })
    } else if (cached) {
      agentValidationCache.delete(agentId)
    }

    // Check built-in agents first
    if (AGENT_PERSONAS[agentId as keyof typeof AGENT_PERSONAS]) {
      const displayName = AGENT_PERSONAS[agentId as keyof typeof AGENT_PERSONAS].displayName
      const result = {
        valid: true as const,
        source: 'builtin',
        normalizedId: agentId,
        displayName,
      }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    // Check published agents (database)
    const found = await getAgentTemplate(agentId, {})
    if (found) {
      const result = {
        valid: true as const,
        source: 'published',
        normalizedId: found.id,
        displayName: found.displayName,
      }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    return res.status(200).json({ valid: false })
  } catch (error) {
    logger.error(
      { error: error instanceof Error ? error.message : String(error) },
      'Error validating agent name',
    )
    if (error instanceof z.ZodError) {
      return res.status(400).json({
        valid: false,
        message: 'Invalid request',
        issues: error.issues,
      })
    }
    next(error)
    return
  }
}

#!/usr/bin/env node

import { type CostMode } from '@codebuff/common/constants'
import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import { Command, Option } from 'commander'
import { red, yellow, bold } from 'picocolors'

import { displayLoadedAgents, loadLocalAgents } from './agents/load-agents'
import { CLI } from './cli'
import { cliArguments, cliOptions } from './cli-definitions'
import { handlePublish } from './cli-handlers/publish'
import { npmAppVersion, backendUrl } from './config'
import { createTemplateProject } from './create-template-project'
import { printModeLog, setPrintMode } from './display/print-mode'
import { enableSquashNewlines } from './display/squash-newlines'
import { loadCodebuffConfig } from './json-config/parser'
import {
  getProjectRoot,
  getWorkingDirectory,
  initializeProjectRootAndWorkingDir,
  initProjectFileContextWithWorker,
} from './project-files'
import { rageDetectors } from './rage-detectors'
import { logAndHandleStartup } from './startup-process-handler'
import { recreateShell } from './terminal/run-command'
import { validateAgentDefinitionsIfAuthenticated } from './utils/agent-validation'
import { initAnalytics, trackEvent } from './utils/analytics'
import { createAuthHeaders } from './utils/auth-headers'
import { logger } from './utils/logger'
import { Spinner } from './utils/spinner'

import type { CliOptions } from './types'

export async function validateAgent(
  agent: string,
  localAgents?: Record<string, any>,
): Promise<void> {
  const agents = localAgents ?? {}

  // if local agents are loaded, they're already validated
  if (
    !!agents?.[agent] ||
    !!Object.values(agents ?? {}).find((a: any) => a?.displayName === agent)
  )
    return

  Spinner.get().start('Checking agent...')
  try {
    const url = `${backendUrl}/api/agents/validate-name?agentId=${encodeURIComponent(agent)}`

    // Use helper to create headers with x-codebuff-api-key
    const headers = createAuthHeaders()

    const resp = await fetch(url, {
      method: 'GET',
      headers,
    })
    const data: { valid?: boolean } = await resp.json().catch(() => ({}) as any)

    if (resp.ok && data.valid) return

    if (resp.ok && !data.valid) {
      console.error(red(`\nUnknown agent: ${bold(agent)}. Exiting.`))
      process.exit(1)
    }
  } catch {
    console.error(
      yellow(
        `\nCould not validate agent due to a network error. Proceeding...`,
      ),
    )
  } finally {
    Spinner.get().stop()
  }
}

async function codebuff({
  initialInput,
  git,
  costMode,
  runInitFlow,
  model,
  agent,
  params,
  print,
  cwd,
  trace,
}: CliOptions) {
  enableSquashNewlines()
  const workingDir = getWorkingDirectory()
  const projectRoot = getProjectRoot()
  await recreateShell(workingDir)

  // Kill all processes we failed to kill before
  const processCleanupPromise = logAndHandleStartup()

  initAnalytics()
  rageDetectors.startupTimeDetector.start()

  const initFileContextPromise = initProjectFileContextWithWorker(projectRoot)

  // Ensure validation runs strictly after local agent load/display
  const loadAndValidatePromise: Promise<void> = loadLocalAgents({
    verbose: true,
  }).then((agents) => {
    validateAgentDefinitionsIfAuthenticated(Object.values(agents))

    const codebuffConfig = loadCodebuffConfig()
    if (!agent) {
      displayLoadedAgents(codebuffConfig)
      return
    }

    return validateAgent(agent, agents)
  })

  const readyPromise = Promise.all([
    initFileContextPromise,
    processCleanupPromise,
    loadAndValidatePromise,
  ])

  // Initialize the CLI singleton
  CLI.initialize(readyPromise, {
    git,
    costMode,
    model,
    agent,
    params,
    print,
    trace,
  })

  const cli = CLI.getInstance()
  await cli.printInitialPrompt({ initialInput, runInitFlow })

  rageDetectors.startupTimeDetector.end()
}

if (require.main === module) {
  const program = new Command()

  program.name('codebuff').version(npmAppVersion || '0.0.0')

  // Add arguments from shared definitions
  cliArguments.forEach((arg) => {
    // For hidden arguments, just skip adding them to the help text
    if (!arg.hidden) {
      program.argument(arg.flags, arg.description)
    }
  })

  // Add options from shared definitions
  cliOptions.forEach((opt) => {
    const optionInstance = new Option(opt.flags, opt.description)
    if (opt.hidden) {
      optionInstance.hideHelp(true)
    }
    program.addOption(optionInstance)
  })

  program.addHelpText(
    'after',
    `
Examples:
  $ codebuff                                  # Start in current directory
  $ codebuff -p "tell me about the codebase"  # Print mode (non-interactive)
  $ codebuff --cwd my-project                 # Start in specific directory
  $ codebuff --trace                          # Enable subagent trace logging to .agents/traces/*.log
  $ codebuff --create nextjs my-app           # Create and scaffold a new Next.js project
  $ codebuff publish my-agent                 # Publish agent template to store
  $ codebuff --agent file-picker "find relevant files for authentication"
  $ codebuff --agent reviewer --params '{"focus": "security"}' "review this code"

For all commands and options, run 'codebuff' and then type 'help'.
`,
  )

  program.parse()

  const options = program.opts()
  const args = program.args // Handle template creation

  // Initialize project root and working directory
  initializeProjectRootAndWorkingDir(options.cwd)

  if (options.create) {
    const template = options.create
    const projectDir = args[0] || '.'
    const projectName = args[1] || template
    createTemplateProject(template, projectDir, projectName)
    process.exit(0)
  }

  // Handle publish command
  if (args[0] === 'publish') {
    const agentNames = args.slice(1)
    await handlePublish(agentNames)
    process.exit(0)
  }

  // Handle deprecated --pro flag
  if (options.pro) {
    console.error(
      red(
        'Warning: The --pro flag is deprecated. Please restart codebuff and use the --max option instead.',
      ),
    )
    logger.error(
      {
        errorMessage:
          'The --pro flag is deprecated. Please restart codebuff and use the --max option instead.',
      },
      'Deprecated --pro flag used',
    )
    process.exit(1)
  }

  // Determine cost mode
  let costMode: CostMode = 'normal'
  if (options.lite) {
    costMode = 'lite'
  } else if (options.max) {
    costMode = 'max'
  } else if (options.experimental) {
    costMode = 'experimental'
  } else if (options.ask) {
    costMode = 'ask'
  }

  // Handle git integration
  const git = options.git === 'stage' ? ('stage' as const) : undefined

  // Validate print mode requirements
  if (options.print) {
    const hasPrompt = args.length > 0
    const hasParams = options.params

    setPrintMode(true)
    trackEvent(AnalyticsEvent.PRINT_MODE, {
      args,
      options,
    })

    if (!hasPrompt && !hasParams) {
      printModeLog({
        type: 'error',
        message: 'Error: Print mode requires a prompt to be set',
      })
      process.exit(1)
    }
  }

  // Parse agent params if provided
  let parsedAgentParams: Record<string, any> | undefined
  if (options.params) {
    try {
      parsedAgentParams = JSON.parse(options.params)
    } catch (error) {
      console.error(red(`Error parsing --params JSON: ${error}`))
      process.exit(1)
    }
  }

  // Remove the first argument if it's the compiled binary path which bun weirdly injects (starts with /$bunfs)
  const filteredArgs = args[0]?.startsWith('/$bunfs') ? args.slice(1) : args

  // If first arg is a command like 'publish', don't treat it as initial input
  const isCommand = filteredArgs[0] === 'publish'
  const initialInput = isCommand ? '' : filteredArgs.join(' ')

  codebuff({
    initialInput,
    git,
    costMode,
    runInitFlow: options.init,
    model: options.model,
    agent: options.agent,
    params: parsedAgentParams,
    print: options.print,
    cwd: options.cwd,
    trace: options.trace,
  })
}

import {
  describe,
  it,
  expect,
  beforeEach,
  afterEach,
  spyOn,
  mock,
} from 'bun:test'

import { validateAgent } from '../index'
import * as SpinnerMod from '../utils/spinner'

describe('validateAgent agent pass-through', () => {
  let fetchSpy: ReturnType<typeof spyOn>
  let spinnerSpy: ReturnType<typeof spyOn>

  beforeEach(() => {
    fetchSpy = spyOn(globalThis as any, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => ({ valid: true }),
    } as any)

    spinnerSpy = spyOn(SpinnerMod.Spinner, 'get').mockReturnValue({
      start: () => {},
      stop: () => {},
    } as any)
  })

  afterEach(() => {
    mock.restore()
  })

  it('passes published agent id unchanged to backend (publisher/name@version)', async () => {
    const agent = 'codebuff/file-explorer@0.0.1'
    await validateAgent(agent, {})

    expect(fetchSpy).toHaveBeenCalled()
    const url = (fetchSpy.mock.calls[0] as any[])[0] as string
    const u = new URL(url)
    expect(u.searchParams.get('agentId')).toBe(agent)
  })

  it('short-circuits when agent is found locally (by id)', async () => {
    const agent = 'codebuff/file-explorer@0.0.1'
    fetchSpy.mockClear()

    await validateAgent(agent, {
      [agent]: { displayName: 'File Explorer' },
    })

    expect(fetchSpy).not.toHaveBeenCalled()
  })
})

import { isFileIgnored } from '@codebuff/common/project-file-tree'
import { capitalize, snakeToTitleCase } from '@codebuff/common/util/string'
import { bold, gray, strikethrough } from 'picocolors'

import { Client } from '../client'
import { getProjectRoot } from '../project-files'
import { Spinner } from './spinner'

import type { ToolName } from '@codebuff/common/tools/constants'

interface SpawnAgentConfig {
  agent_type: string
  prompt?: string
  params?: Record<string, any>
}

/**
 * Interface for handling tool call rendering
 */
export interface ToolCallRenderer {
  // Called when a tool tag starts
  onToolStart?: (
    toolName: string,
    attributes: Record<string, string>,
  ) => string | null | (() => void)

  // Called when a parameter tag is found within a tool
  onParamStart?: (
    paramName: string,
    toolName: string,
  ) => string | null | (() => void)

  // Called when parameter content is received
  onParamChunk?: (
    content: string,
    paramName: string,
    toolName: string,
  ) => string | null | (() => void)

  // Called when a parameter tag ends
  onParamEnd?: (
    paramName: string,
    toolName: string,
    content: string,
  ) => string | null | (() => void)

  // Called when a tool tag ends
  onToolEnd?: (
    toolName: string,
    params: Record<string, string>,
  ) => string | null | (() => void)
}

let toolStart = true

/**
 * Shared function for rendering spawn agents parameters
 */
const renderSpawnAgentsParam = (
  paramName: string,
  toolName: string,
  content: string,
) => {
  if (paramName === 'agents') {
    let agents: SpawnAgentConfig[] = []
    try {
      agents = JSON.parse(content)
    } catch (e) {
      return null
    }
    if (agents.length > 0) {
      const client = Client.getInstance(false)
      return gray(
        agents
          .map((props: SpawnAgentConfig) => {
            const agentType = props.agent_type
            const prompt = props.prompt
            const agentName =
              (client?.agentNames && client.agentNames[agentType]) || agentType

            return `@${bold(agentName)}:\n${prompt || 'No prompt provided'}`
          })
          .join('\n\n') + '\n',
      )
    }
  }
  return null
}

/**
 * Default renderer for tool calls that formats them nicely for the console
 */
export const defaultToolCallRenderer: ToolCallRenderer = {
  onToolStart: (toolName) => {
    toolStart = true
    return '\n\n' + gray(`[${bold(snakeToTitleCase(toolName))}]`) + '\n'
  },

  onParamChunk: (content, paramName, toolName) => {
    if (toolStart && content.startsWith('\n')) content = content.slice(1)
    toolStart = false
    return gray(content)
  },

  onParamEnd: () => null,

  onToolEnd: () => '\n\n',
}

export const toolRenderers: Record<ToolName, ToolCallRenderer> = {
  end_turn: {
    // Don't render anything
  },
  run_terminal_command: {
    // Don't render anything
  },
  code_search: {
    // Don't render anything
  },
  browser_logs: {
    // Don't render anything
  },
  run_file_change_hooks: {
    // Don't render anything
  },
  read_files: {
    ...defaultToolCallRenderer,
    onParamChunk: (content, paramName, toolName) => {
      // Don't render chunks for paths, wait for the full list
      return null
    },

    onParamEnd: (paramName, toolName, content) => {
      let files: string[] = []
      try {
        files = JSON.parse(content)
      } catch (e) {
        return null
      }
      files = files.map((fname) =>
        isFileIgnored(fname, getProjectRoot())
          ? strikethrough(fname) + ' (blocked)'
          : fname,
      )
      const numFiles = files.length
      const maxInitialFiles = 3

      if (numFiles <= maxInitialFiles) {
        // If 3 or fewer files, list them all on new lines
        return gray(files.join('\n'))
      } else {
        // If more than 3 files
        const initialFiles = files.slice(0, maxInitialFiles)
        const remainingFiles = files.slice(maxInitialFiles)
        const numRemaining = remainingFiles.length
        const remainingFilesString = remainingFiles.join(' ')

        return gray(
          `${initialFiles.map((file) => '- ' + file).join('\n')}\nand ${numRemaining} more: ${remainingFilesString}`,
        )
      }
    },
    onToolEnd: (toolName, params) => {
      // Add a final newline after the file list
      return '\n\n'
    },
  },
  read_docs: {
    ...defaultToolCallRenderer,
  },
  web_search: {
    ...defaultToolCallRenderer,
    onParamChunk: (content, paramName, toolName) => {
      return null
    },
    onParamEnd: (paramName, toolName, content) => {
      if (paramName !== 'query') {
        return null
      }
      return gray(content)
    },
  },
  find_files: {
    ...defaultToolCallRenderer,
  },
  think_deeply: {
    ...defaultToolCallRenderer,
  },
  create_plan: {
    ...defaultToolCallRenderer,
    onParamStart: (paramName) => {
      if (paramName === 'path') {
        return gray('Editing plan at ')
      }
      return null
    },
    onParamChunk: (content, paramName) => {
      if (paramName === 'path') {
        return gray(content)
      }
      return null
    },
    onParamEnd: (paramName) => {
      if (paramName === 'path') {
        return gray('...') + '\n'
      }
      return null
    },
  },
  write_file: {
    ...defaultToolCallRenderer,
    onParamStart: (paramName) => {
      if (paramName === 'path') {
        return gray('Editing file at ')
      }
      return null
    },
    onParamChunk: (content, paramName, toolName) => {
      return null
    },
    onParamEnd: (paramName, toolName, content) => {
      if (paramName === 'path') {
        return isFileIgnored(content, getProjectRoot())
          ? gray(strikethrough(content) + ' (blocked)')
          : gray(content + '...')
      }
      if (paramName === 'instructions') {
        return gray('\n' + content)
      }
      return null
    },
  },
  str_replace: {
