    onParamEnd: (paramName, toolName, content) => {
      if (paramName === 'agent_type') {
        const client = Client.getInstance(false)
        const agentName =
          (client?.agentNames && client.agentNames[content]) || content
        return gray(`@${bold(agentName)}\n`)
      }
      if (paramName === 'prompt') {
