import { logger } from '../utils/logger'

import type { ChildProcessWithoutNullStreams } from 'child_process'

/* ------------------------------------------------------------------ */
/* constants                                                          */
/* ------------------------------------------------------------------ */

const COMMAND_OUTPUT_LIMIT = 10_000
const IS_WINDOWS = os.platform() === 'win32'

/* ------------------------------------------------------------------ */
/* colour‑helper : adds "--color" style flags when missing            */
/* ------------------------------------------------------------------ */

function applyColorHints(cmd: string): string {
  /* don't touch complex pipelines – best effort */
  if (cmd.includes('|') || cmd.includes('>')) return cmd

  /* ---------- git -------------------------------------------------- */
  if (/^\s*git\b/.test(cmd) && !/--color\b/.test(cmd)) {
    if (/\bdiff\b/.test(cmd)) {
      // Insert --color=always after 'git diff' but before any file paths or other args
      return cmd.replace(/^(\s*git\s+diff)/, '$1 --color=always')
    }
    if (/\blog\b/.test(cmd)) {
      return cmd.replace(/^(\s*git\s+log)/, '$1 --color=always')
    }
    if (/\bshow\b/.test(cmd)) {
      return cmd.replace(/^(\s*git\s+show)/, '$1 --color=always')
    }
  }

  /* ---------- grep / ripgrep --------------------------------------- */
  if (/\b(rg|grep|egrep|fgrep)\b/.test(cmd) && !/--color\b/.test(cmd)) {
    return `${cmd} --color=always`
  }

  /* ---------- ls ---------------------------------------------------- */
  if (
    /^\s*ls\b/.test(cmd) && // plain "ls"
    !/[\s\-][1lCx]/.test(cmd) && // none of -1 -l -C -x present
    !/--color\b/.test(cmd) // and no colour flag yet
  ) {
    const colourFlag = IS_WINDOWS
      ? '--color=always' // Git‑coreutils on Win
      : process.platform === 'darwin'
        ? '-G' // BSD flag
        : '--color=always'

    /* -C forces multi‑column even when stdout isn't a TTY */
    return `${cmd} -C ${colourFlag}`
  }

  /* ---------- tree -------------------------------------------------- */
  if (/^\s*tree\b/.test(cmd) && !/\s\-C\b/.test(cmd)) {
    return `${cmd} -C`
  }

  return cmd
}

/* ------------------------------------------------------------------ */
/* helpers                                                            */
/* ------------------------------------------------------------------ */

/** Which family of shell are we launching? */
type UnixShell = 'bash' | 'zsh'
type WinShell = 'cmd.exe'

type ShellKind = UnixShell | WinShell

function basename(cmd: string) {
  return path.basename(cmd).toLowerCase()
}

/** Decide which concrete binary to start based on platform + env */
function selectShell(): ShellKind {
  if (IS_WINDOWS) {
    return 'cmd.exe'
  }

  const detectedShell = detectShell()
  // Prefer zsh if available, otherwise fallback to bash
  return detectedShell === 'zsh' ? 'zsh' : 'bash'
}

/** Build shell‑specific "initialisation" snippets. */
function buildInit(shell: ShellKind): string[] {
  if (IS_WINDOWS) {
    /* cmd.exe has nothing useful we can "source"                          */
    return []
  }

  switch (shell) {
    case 'zsh':
      return [
        'setopt aliases', // Enable alias expansion
        'source ~/.zshenv 2>/dev/null || true',
        'source ~/.zprofile 2>/dev/null || true',
        'source ~/.zshrc 2>/dev/null || true',
        'source ~/.zlogin 2>/dev/null || true',
      ]
    case 'bash':
    default:
      return [
        'shopt -s expand_aliases', // Enable alias expansion for non-interactive bash
        // Source standard rc files – some may short-circuit
        'source ~/.bash_profile 2>/dev/null || true',
        'source ~/.profile 2>/dev/null || true',
        'source ~/.bashrc 2>/dev/null || true',
        'source ~/.bash_aliases 2>/dev/null || true', // Handle Debian/Ubuntu systems
        // Reap any alias definitions that were skipped by the "return if not interactive" guard
        'if [ -f ~/.bashrc ]; then',
        '  eval "$(grep -E \\"^[[:space:]]*alias[[:space:]]+\\" ~/.bashrc)"',
        'fi',
      ]
  }
}

/** Build environment */
function buildEnv(shell: ShellKind): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {
    ...process.env,
    PAGER: 'cat',
    GIT_PAGER: 'cat',
    GIT_TERMINAL_PROMPT: '0',
    LESS: '-FRX',
    /* ---- colour‑forcing vars -------------------------------------- */
    FORCE_COLOR: '3', // chalk / picocolors / many Node CLIs
    CLICOLOR: '1', // coreutils (BSD) honour this
    CLICOLOR_FORCE: '1',
    GIT_CONFIG_PARAMETERS: `'color.ui=always'`,
    /* ---- width / height ------------------------------------------- */
    COLUMNS: String(process.stdout.columns || 80),
    LINES: String(process.stdout.rows || 24),
    LANG: 'en_US.UTF-8',
    LC_ALL: 'en_US.UTF-8',
  }

  if (IS_WINDOWS) {
    env.TERM = 'cygwin'
  } else {
    env.TERM = 'xterm-256color'
    env.SHELL = `/bin/${shell}` // Currently: bash or zsh
  }

  return env
}

/** Create a one‑shot wrapper script for Unix‑like shells. */
function createWrapperScript(
  shell: UnixShell,
  initLines: string[],
  userCmd: string,
) {
  const tmp = mkdtempSync(join(tmpdir(), 'codebuff-')) // safe unique dir
  const scriptPath = join(tmp, `cmd.${shell}`)

  const shebang = shell === 'zsh' ? '#!/usr/bin/env zsh' : '#!/usr/bin/env bash'

  const aliasEnable =
    shell === 'zsh' ? 'setopt aliases' : 'shopt -s expand_aliases'

  writeFileSync(
    scriptPath,
    [
      shebang,
      aliasEnable,
      ...initLines,
      '',
      userCmd,
      '', // final newline
    ].join('\n'),
    { mode: 0o755 },
  )

  return scriptPath
}

/** Windows : translate shell+init+cmd -> executable + argv */
function buildWinInvocation(
  shell: WinShell,
  initLines: string[],
  userCmd: string,
): { exe: string; args: string[] } {
  const init = initLines.join('; ')
  const cmdAll = init ? `${init}; ${userCmd}` : userCmd

  if (shell === 'cmd.exe') {
    return { exe: 'cmd.exe', args: ['/d', '/s', '/c', cmdAll] } // ﻿˅ doc  :contentReference[oaicite:0]{index=0}
  }

  /* PowerShell / pwsh -------------------------------------------------- */
  return {
    exe: shell,
    args: [
      '-NoLogo',
      '-NonInteractive',
      '-ExecutionPolicy',
      'Bypass',
      '-Command',
      cmdAll,
    ],
  }
}

/* ------------------------------------------------------------------ */
/* persistent‑process bookkeeping                                     */
/* ------------------------------------------------------------------ */

export type PersistentProcess = {
  type: 'process'
  shell: ShellKind
  childProcess: ChildProcessWithoutNullStreams | null
  timerId: NodeJS.Timeout | null
  globalOutputBuffer: string
  globalOutputLastReadLength: number
  env: NodeJS.ProcessEnv
  shellInitCommands: string[]
}

async function createPersistentProcess(
  dir: string,
): Promise<PersistentProcess> {
  const shell = selectShell()
  const env = buildEnv(shell)
  const shellInitCommands = buildInit(shell)

  logger.debug({ shell, shellInitCommands }, 'Initialised persistent shell')

  return {
    type: 'process',
    shell,
    childProcess: null,
    timerId: null,
    globalOutputBuffer: '',
    globalOutputLastReadLength: 0,
    env,
    shellInitCommands,
  }
}

/* ------------------------------------------------------------------ */
/* exported state + helpers                                           */
/* ------------------------------------------------------------------ */

export let persistentProcess: Awaited<
  ReturnType<typeof createPersistentProcess>
> | null = null

let commandIsRunning = false

export const isCommandRunning = () => commandIsRunning

export const recreateShell = async (cwd: string) => {
  persistentProcess = await createPersistentProcess(cwd)
  trackEvent(AnalyticsEvent.SHELL_RECREATED, { persistentProcess })
}

export const resetShell = async (cwd: string) => {
  commandIsRunning = false
  if (persistentProcess) {
    persistentProcess.timerId && clearTimeout(persistentProcess.timerId)
    persistentProcess.childProcess?.kill()
    persistentProcess.childProcess = null
  }
}

/* ------------------------------------------------------------------ */
/* formatting helper
/* ------------------------------------------------------------------ */

function formatResult(command: string, stdout: string, status: string): string {
  return buildArray(
    `<command>${command}${closeXml('command')}`,
    '<terminal_command_result>',
    `<output>${truncateStringWithMessage({
      str: stripColors(stdout),
      maxLength: COMMAND_OUTPUT_LIMIT,
      remove: 'MIDDLE',
    })}${closeXml('output')}`,
    `<status>${status}${closeXml('status')}`,
    `${closeXml('terminal_command_result')}`,
  ).join('\n')
}

/* ------------------------------------------------------------------ */
/* PUBLIC API – runTerminalCommand                                    */
/* ------------------------------------------------------------------ */

export const runTerminalCommand = async (
  toolCallId: string,
  command: string,
  mode: 'user' | 'assistant',
  processType: 'SYNC' | 'BACKGROUND',
  timeoutSeconds: number,
  cwd?: string,
  stdoutFile?: string,
  stderrFile?: string,
): Promise<{ result: string; stdout: string; exitCode: number | null }> => {
  const maybeTimeoutSeconds = timeoutSeconds < 0 ? null : timeoutSeconds
  const projectRoot = getProjectRoot()
  cwd = cwd
    ? // Make sure cwd is an absolute path.
      path.resolve(projectRoot, cwd)
    : mode === 'assistant'
      ? projectRoot
      : getWorkingDirectory()

  /* guard: shell must exist ------------------------------------------ */
  if (!persistentProcess)
    throw new Error('Shell not initialised – call recreateShell first')

  /* reset if concurrent ---------------------------------------------- */
  if (commandIsRunning) resetShell(cwd)
  commandIsRunning = true

  /* limit huge git logs, then add colour/width hints ----------------- */
  let modifiedCmd = command.trim() === 'git log' ? 'git log -n 5' : command
  modifiedCmd = applyColorHints(modifiedCmd)

  /* analytics wrapper ------------------------------------------------- */
  const resolveCommand = (value: {
    result: string
    stdout: string
    exitCode: number | null
  }) => {
    commandIsRunning = false
    trackEvent(AnalyticsEvent.TERMINAL_COMMAND_COMPLETED, {
      command,
      result: value.result,
      stdout: value.stdout,
      exitCode: value.exitCode,
      mode,
      processType,
    })
    return value
  }

  if (processType === 'BACKGROUND') {
    return new Promise((res) =>
      runBackgroundCommand(
        { toolCallId, command: modifiedCmd, mode, cwd, stdoutFile, stderrFile },
        (v) => res(resolveCommand(v)),
      ),
    )
  }

  /* sync mode --------------------------------------------------------- */
  return new Promise((resolve) =>
    runCommandChildProcess(
      persistentProcess!,
      modifiedCmd,
      mode,
      cwd!,
      maybeTimeoutSeconds,
      (v) => resolve(resolveCommand(v)),
    ),
  )
}

/* ------------------------------------------------------------------ */
/* core command runner                                                */
/* ------------------------------------------------------------------ */

const runCommandChildProcess = async (
  pp: PersistentProcess,
  command: string,
  mode: 'user' | 'assistant' | 'manager',
  cwd: string,
  maybeTimeoutSeconds: number | null,
  resolve: (value: {
    result: string
    stdout: string
    exitCode: number | null
  }) => void,
) => {
  const projectRoot = getProjectRoot()

  /* clear screen ----------------------------------------------------- */
  if (command.trim() === 'clear') {
    process.stdout.write('\u001b[2J\u001b[0;0H')
    resolve({
      result: formatResult(command, '', 'Complete'),
      stdout: '',
      exitCode: 0,
    })
    return
  }

  /* assistant prompt banner ----------------------------------------- */
  if (mode === 'assistant') {
    const displayDir = path.join(
      path.parse(projectRoot).base,
      path.relative(projectRoot, path.resolve(projectRoot, cwd)),
    )
    // Some models omit new lines.
    console.log()
    console.log()
    console.log(green(`${displayDir} > ${command}`))
  }

  /* build process invocation ---------------------------------------- */
  const shell = pp.shell
  const initLines = pp.shellInitCommands
  let child: ChildProcessWithoutNullStreams

  if (IS_WINDOWS) {
    const { exe, args } = buildWinInvocation(
      shell as WinShell,
      initLines,
      command,
    )
    child = spawn(exe, args, { cwd, env: pp.env })
  } else {
    const script = createWrapperScript(shell as UnixShell, initLines, command)
    child = spawn(shell, [script], { cwd, env: pp.env })

    /* cleanup tmp file */
    child.on('exit', () => {
      try {
        unlinkSync(script)
      } catch {
        /* ignore */
      }
    })
  }

  /* hook into persistent state -------------------------------------- */
  pp.childProcess = child

  /* timeout guard ---------------------------------------------------- */
  let timer: NodeJS.Timeout | null = null
  if (maybeTimeoutSeconds !== null) {
    timer = setTimeout(() => {
      resetShell(cwd)
      if (mode === 'assistant') {
        resolve({
          result: formatResult(
            command,
            '',
            `Command timed out after ${maybeTimeoutSeconds}s and was terminated.`,
          ),
          stdout: '',
          exitCode: 124,
        })
      }
    }, maybeTimeoutSeconds * 1_000)
    pp.timerId = timer
  }

  /* capture output --------------------------------------------------- */
  let cmdOut = ''
  const outHandler = (data: Buffer) => {
    const s = data.toString()
    cmdOut += s
    process.stdout.write(s)
    pp.globalOutputBuffer += s
  }
  child.stdout.on('data', outHandler)
  child.stderr.on('data', outHandler)

  /* close handler ---------------------------------------------------- */
  child.on('close', (code) => {
    timer && clearTimeout(timer)

    /* cd tracking for user‑mode -------------------------------------- */
    if (command.startsWith('cd ') && mode === 'user') {
      const target = command.split(' ').slice(1).join(' ')
      const resolved = path.resolve(cwd, target)
      if (!path.relative(projectRoot, resolved).startsWith('..')) {
        setWorkingDirectory(resolved)
        trackEvent(AnalyticsEvent.CHANGE_DIRECTORY, {
          from: cwd,
          to: resolved,
          isSubdir: isSubdir(cwd, resolved),
        })
      } else {
        console.log(`
Unable to cd outside of the project root (${projectRoot})

If you want to change the project root:
1. Exit Codebuff (type "exit")
2. Navigate into the target directory (type "cd ${target}")
3. Restart Codebuff`)
      }
    }

    /* build response ------------------------------------------------- */
    const status = code === 0 ? 'Complete' : `Failed with exit code: ${code}`
    const payload =
      mode === 'assistant'
        ? formatResult(
            command,
            cmdOut,
            buildArray([`cwd: ${path.resolve(projectRoot, cwd)}`, status]).join(
              '\n\n',
            ),
          )
        : formatResult(
            command,
            cmdOut,
            buildArray([
              `Starting cwd: ${cwd}`,
              `${status}\n`,
              `Final **user** cwd: ${getWorkingDirectory()} (Assistant's cwd is still project root)`,
            ]).join('\n'),
          )

    resolve({ result: payload, stdout: cmdOut, exitCode: code })
  })
}

/* ------------------------------------------------------------------ */
/* misc exports                                                       */
/* ------------------------------------------------------------------ */

export function killAndResetPersistentProcess() {
  persistentProcess?.childProcess?.kill()
  persistentProcess = null
}

export function clearScreen() {
  process.stdout.write('\u001b[2J\u001b[0;0H')
}

import assert from 'assert'
import { createWriteStream, mkdirSync } from 'fs'
import * as os from 'os'
import path, { dirname } from 'path'

import { stripColors } from '@codebuff/common/util/string'
import { closeXml } from '@codebuff/common/util/xml'
import { green } from 'picocolors'

import {
  backgroundProcesses,
  spawnAndTrack,
} from '../background-process-manager'

import type { BackgroundProcessInfo } from '../background-process-manager'
import type { WriteStream } from 'fs'

export function runBackgroundCommand(
  options: {
    toolCallId: string
    command: string
    mode: 'user' | 'assistant' | 'manager'
    cwd: string
    stdoutFile?: string
    stderrFile?: string
  },
  resolveCommand: (value: {
    result: string
    stdout: string
    exitCode: number | null
  }) => void,
): void {
  const { toolCallId, command, mode, cwd, stdoutFile, stderrFile } = options
  const isWindows = os.platform() === 'win32'
  const shell = isWindows ? 'cmd.exe' : 'bash'
  const shellArgs = isWindows ? ['/c'] : ['-c']

  if (mode === 'assistant') {
    console.log(green(`Running background process...\n> ${command}`))
  }

  const initialStdout = ''
  const initialStderr = ''

  try {
    const childProcess = spawnAndTrack(shell, [...shellArgs, command], {
      cwd,
      env: { ...process.env, FORCE_COLOR: '1' },
      // Ensure detached is always false to link child lifetime to parent
      detached: false,
      stdio: 'pipe',
    })

    // An error should have been thrown when we called `spawn`
    assert(
      childProcess.pid !== undefined,
      'Failed to spawn process: no PID assigned.',
    )

    const processId = childProcess.pid
    const processInfo: BackgroundProcessInfo = {
      pid: processId,
      toolCallId,
      command,
      process: childProcess,
      stdoutBuffer: [],
      stderrBuffer: [],
      status: 'running',
      startTime: Date.now(),
      endTime: null,
      lastReportedStdoutLength: 0,
      lastReportedStderrLength: 0,
      lastReportedStatus: null,
      stdoutFile,
      stderrFile,
    }
    backgroundProcesses.set(processId, processInfo)

    // Set up file streams if paths are provided
    let stdoutStream: WriteStream | undefined
    let stderrStream: WriteStream | undefined

    if (stdoutFile) {
      const stdoutAbs = path.isAbsolute(stdoutFile)
        ? stdoutFile
        : path.join(cwd, stdoutFile)
      mkdirSync(dirname(stdoutAbs), { recursive: true })
      stdoutStream = createWriteStream(stdoutAbs)
    }

    const realStderrFile = stderrFile || stdoutFile
    if (realStderrFile) {
      const stderrAbs = path.isAbsolute(realStderrFile)
        ? realStderrFile
        : path.join(cwd, realStderrFile)
      mkdirSync(dirname(stderrAbs), { recursive: true })
      stderrStream = createWriteStream(stderrAbs)
    }

    childProcess.stdout.on('data', (data: Buffer) => {
      const output = stripColors(data.toString())
      processInfo.stdoutBuffer.push(output)

      // Write to file if stream exists
      if (stdoutStream) {
        stdoutStream.write(output)
      }
    })

    childProcess.stderr.on('data', (data: Buffer) => {
      const output = stripColors(data.toString())
      processInfo.stderrBuffer.push(output)

      // Write to file if stream exists
      if (stderrStream) {
        stderrStream.write(output)
      }
    })

    childProcess.on('error', (error) => {
      processInfo.status = 'error'
      processInfo.stderrBuffer.push(
        `\nError spawning command: ${error.message}`,
      )
      processInfo.endTime = Date.now()

      // Close file streams
      stdoutStream?.end()
      stderrStream?.end()
    })

    let exitCode = null

    childProcess.on('close', (code) => {
      exitCode = code
      processInfo.status = code === 0 ? 'completed' : 'error'
      processInfo.endTime = Date.now()

      // Close file streams
      stdoutStream?.end()
      stderrStream?.end()
    })

    // Unreference the process so the parent can exit independently IF the child is the only thing keeping it alive.
    childProcess.unref()

    const resultMessage = `<background_process>
<process_id>${processId}${closeXml('process_id')}
<command>${command}${closeXml('command')}
<status>${processInfo.status}${closeXml('status')}
${closeXml('background_process')}`
    resolveCommand({
      result: resultMessage,
      stdout: initialStdout + initialStderr,
      exitCode,
    })
  } catch (error: any) {
    const errorMessage = `<background_process>\n<command>${command}${closeXml('command')}\n<error>${error.message}${closeXml('error')}\n${closeXml('background_process')}`
    resolveCommand({
      result: errorMessage,
      stdout: error.message,
      exitCode: null,
    })
  }
}

/**
 * Overwrites writing multiple (more than 2) newlines for all functions.
 *
 * Only replaces raw '\n\n\n' strings. i.e. '\n\n' + green('\n\n'), still
 * renders as four newline characters. Because there is an ANSI escape
 * character between the first two and the last two newline characters.
 */
import stringWidth from 'string-width'

import {
  originalConsoleDebug,
  originalConsoleError,
  originalConsoleInfo,
  originalConsoleLog,
  originalConsoleWarn,
  originalStderrWrite,
  originalStdoutWrite,
} from './overrides'
import { printModeIsEnabled } from './print-mode'

const PREFIX = '.\r\n'
let squashingEnabled = false
let previous = PREFIX

export function getPrevious(): string {
  return previous
}

export function setPrevious(str: string): void {
  previous = str
}

export function enableSquashNewlines(): void {
  squashingEnabled = true
}

export function disableSquashNewlines(): void {
  squashingEnabled = false
}

/** OSC  …  BEL | ST   (titles, hyperlinks, cwd hints, etc.) */
const OSC = /\u001B\][^\u0007\u001B]*(?:\u0007|\u001B\\)/g

/** CSI  …  final-byte   (cursor moves, ?2004h, colours if stripAnsi missed them) */
const CSI = /\u001B\[[0-?]*[ -/]*[@-~]/g

/** Zero-width Unicode code-points (format, combining, enclosing) */
const ZW = /[\p{Cf}\p{Mn}\p{Me}]/gu

/**
 * `true` → after stripping VT controls and whitespace the string has zero width
 */
export function onlyWhitespace(raw: string): boolean {
  const visible = raw
    .replace(OSC, '') // remove OSC 0/7/8/133/697/…
    .replace(CSI, '') // remove CSI H, A, ?2004h, …
    .replace(/\s+/g, '') // remove spaces, tabs, CR, LF
    .replace(ZW, '') // remove ZWJ, ZWNJ, VS16, etc.

  return stringWidth(visible) === 0
}

function addCarriageReturn(str: string): string {
  // Do not copy over \n from previous
  const base = (previous[previous.length - 1] === '\r' ? '\r' : '.') + str
  // Replace twice, because of no overlap '\n\n'
  const withCarriageReturns = base.replace(/(?<!\r)\n/g, '\r\n')
  return withCarriageReturns.slice(1)
}

function getLastTwoLines(str: string): string {
  return PREFIX + str.split('\r\n').slice(-2).join('\r\n')
}

export function squashNewlines(str: string): string {
  if (!str.startsWith(PREFIX)) {
    throw new Error(`Expected string to start with ${JSON.stringify(PREFIX)}`)
  }

  const lines = str
    .split('\r\n')
    .map((line) => ({ line, empty: onlyWhitespace(line) }))

  const agg: string[] = []
  let consecutiveEmptyLines = 0
  for (const { line, empty } of lines) {
    if (consecutiveEmptyLines > 1) {
      agg[agg.length - 1] += line
    } else {
      agg.push(line)
    }

    if (empty) {
      consecutiveEmptyLines++
    } else {
      consecutiveEmptyLines = 0
    }
  }

  return agg.join('\r\n')
}

/**
 * Common utility function to handle squashing logic for any write function
 */
function createSquashingWriteFunction<T extends Function>(
  originalWrite: T,
  isSquashingEnabled: () => boolean,
): T {
  return function (
    chunk: string | Uint8Array,
    encodingOrCallback?:
      | BufferEncoding
      | ((err?: Error | null | undefined) => void),
    callbackMaybe?: (err?: Error | null | undefined) => void,
  ): boolean {
    if (printModeIsEnabled()) {
      return false
    }
    let chunkString = typeof chunk === 'string' ? chunk : chunk.toString()
    chunkString = addCarriageReturn(chunkString)

    if (!isSquashingEnabled()) {
      previous += chunkString
      previous = getLastTwoLines(previous)

      if (typeof encodingOrCallback === 'function') {
        return originalWrite(chunkString, encodingOrCallback)
      }
      return originalWrite(chunkString, encodingOrCallback, callbackMaybe)
    }

    const combinedContent = previous + chunkString
    const processedContent = squashNewlines(combinedContent)
    const processedChunk = processedContent.slice(previous.length)
    previous = getLastTwoLines(processedContent)

    if (typeof encodingOrCallback === 'function') {
      return originalWrite(processedChunk, encodingOrCallback)
    }
    return originalWrite(processedChunk, encodingOrCallback, callbackMaybe)
  } as any as T
}

// Override stdout and stderr write functions
process.stdout.write = createSquashingWriteFunction(
  originalStdoutWrite,
  () => squashingEnabled,
)

process.stderr.write = createSquashingWriteFunction(
  originalStderrWrite,
  () => squashingEnabled,
)

console.log = function (...args: any[]) {
  if (!squashingEnabled) {
    if (printModeIsEnabled()) {
      return
    }
    return originalConsoleLog(...args)
  }

  // Convert arguments to string and process through squashing logic
  const output =
    args
      .map((arg) =>
        typeof arg === 'string'
          ? arg
          : typeof arg === 'object'
            ? JSON.stringify(arg, null, 2)
            : String(arg),
      )
      .join(' ') + '\n'

  process.stdout.write(output)
}

