import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { utils } from '@codebuff/internal'
import { eq } from 'drizzle-orm'

import { logger } from './logger'

import type { ServerAction } from '@codebuff/common/actions'
import type { Request, Response, NextFunction } from 'express'

export const checkAuth = async ({
  fingerprintId,
  authToken,
  clientSessionId,
}: {
  fingerprintId?: string
  authToken?: string
  clientSessionId: string
}): Promise<void | ServerAction> => {
  // Use shared auth check functionality
  const authResult = await utils.checkAuthToken({
    fingerprintId,
    authToken,
  })

  if (!authResult.success) {
    const errorMessage = authResult.error?.message || 'Authentication failed'
    logger.error({ clientSessionId, error: errorMessage }, errorMessage)
    return {
      type: 'action-error',
      message: errorMessage,
    }
  }

  // if (authResult.user) {
  //   // Log successful authentication if we have a user
  //   logger.debug(
  //     { clientSessionId, userId: authResult.user.id },
  //     'Authentication successful'
  //   )
  // }

  return
}

// Express middleware for checking admin access
export const checkAdmin = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  // Extract auth token from Authorization header
  const authHeader = req.headers.authorization
  if (!authHeader?.startsWith('Bearer ')) {
    return res
      .status(401)
      .json({ error: 'Missing or invalid Authorization header' })
  }
  const authToken = authHeader.substring(7) // Remove 'Bearer ' prefix

  // Generate a client session ID for this request
  const clientSessionId = `admin-relabel-${Date.now()}`

  // Check authentication
  const authResult = await checkAuth({
    authToken,
    clientSessionId,
  })

  if (authResult) {
    // checkAuth returns an error action if auth fails
    const errorMessage =
      authResult.type === 'action-error'
        ? authResult.message
        : 'Authentication failed'
    return res.status(401).json({ error: errorMessage })
  }

  // Get the user ID associated with this session token
  const user = await db
    .select({
      id: schema.user.id,
      email: schema.user.email,
    })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, authToken))
    .then((users) => users[0])

  if (!user) {
    return res.status(401).json({ error: 'Invalid session' })
  }

  // Check if user has admin access using shared utility
  const adminUser = await utils.checkUserIsCodebuffAdmin(user.id)
  if (!adminUser) {
    logger.warn(
      { userId: user.id, email: user.email, clientSessionId },
      'Unauthorized access attempt to admin endpoint',
    )
    return res.status(403).json({ error: 'Forbidden' })
  }

  // Store user info in request for handlers to use if needed
  // req.user = adminUser // TODO: ensure type check passes

  // Auth passed and user is admin, proceed to next middleware
  next()
  return
}

import { z } from 'zod/v4'
import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'
import { logger } from '../util/logger'
import { AGENT_PERSONAS } from '@codebuff/common/constants/agents'
import { getAgentTemplate } from '../templates/agent-registry'

// Add short-lived cache for positive validations
const AGENT_VALIDATION_CACHE_TTL_MS = 5 * 60 * 1000 // 5 minutes

type CacheEntry = {
  result: { valid: true; source?: string; normalizedId?: string }
  expiresAt: number
}

const agentValidationCache = new Map<string, CacheEntry>()

// Simple request schema
const validateAgentRequestSchema = z.object({
  agentId: z.string().min(1),
})

// GET /api/agents/validate-name
export async function validateAgentNameHandler(
  req: ExpressRequest,
  res: ExpressResponse,
  next: NextFunction,
): Promise<void | ExpressResponse> {
  try {
    // Log authentication headers if present (for debugging)
    const hasAuthHeader = !!req.headers.authorization
    const hasApiKey = !!req.headers['x-api-key']

    if (hasAuthHeader || hasApiKey) {
      logger.info(
        { 
          hasAuthHeader,
          hasApiKey,
          agentId: req.query.agentId,
        },
        'Agent validation request with authentication',
      )
    }

    // Parse from query instead (GET)
    const { agentId } = validateAgentRequestSchema.parse({
      agentId: String((req.query as any)?.agentId ?? ''),
    })

    // Check cache (positive results only)
    const cached = agentValidationCache.get(agentId)
    if (cached && cached.expiresAt > Date.now()) {
      return res.status(200).json({ ...cached.result, cached: true })
    } else if (cached) {
      agentValidationCache.delete(agentId)
    }

    // Check built-in agents first
    if (AGENT_PERSONAS[agentId as keyof typeof AGENT_PERSONAS]) {
      const result = { valid: true as const, source: 'builtin', normalizedId: agentId }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    // Check published agents (database)
    const found = await getAgentTemplate(agentId, {})
    if (found) {
      const result = {
        valid: true as const,
        source: 'published',
        normalizedId: found.id,
      }
      agentValidationCache.set(agentId, {
        result,
        expiresAt: Date.now() + AGENT_VALIDATION_CACHE_TTL_MS,
      })
      return res.status(200).json(result)
    }

    return res.status(200).json({ valid: false })
  } catch (error) {
    logger.error(
      { error: error instanceof Error ? error.message : String(error) },
      'Error validating agent name',
    )
    if (error instanceof z.ZodError) {
      return res.status(400).json({ valid: false, message: 'Invalid request', issues: error.issues })
    }
    next(error)
    return
  }
}

import { findOrganizationForRepository } from '@codebuff/billing'
import { z } from 'zod/v4'

import { logger } from '../util/logger'
import { getUserIdFromAuthToken } from '../websockets/websocket-action'

import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'

const isRepoCoveredRequestSchema = z.object({
  owner: z.string(),
  repo: z.string(),
  remoteUrl: z.string(),
})

async function isRepoCoveredHandler(
  req: ExpressRequest,
  res: ExpressResponse,
  next: NextFunction,
): Promise<void | ExpressResponse> {
  try {
    const { owner, repo, remoteUrl } = isRepoCoveredRequestSchema.parse(
      req.body,
    )

    // Get user ID from Authorization header
    const authHeader = req.headers.authorization
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res
        .status(401)
        .json({ error: 'Missing or invalid authorization header' })
    }

    const authToken = authHeader.substring(7) // Remove 'Bearer ' prefix
    const userId = await getUserIdFromAuthToken(authToken)

    if (!userId) {
      return res.status(401).json({ error: 'Invalid authentication token' })
    }

    // Check if repository is covered by an organization
    const orgLookup = await findOrganizationForRepository(userId, remoteUrl)

    return res.status(200).json({
      isCovered: orgLookup.found,
      organizationName: orgLookup.organizationName,
      organizationId: orgLookup.organizationId, // Keep organizationId for now, might be used elsewhere
      organizationSlug: orgLookup.organizationSlug, // Add organizationSlug
    })
  } catch (error) {
    logger.error({ error }, 'Error handling /api/orgs/is-repo-covered request')
    if (error instanceof z.ZodError) {
      return res
        .status(400)
        .json({ error: 'Invalid request body', issues: error.issues })
    }
    next(error)
    return
  }
}

export { isRepoCoveredHandler }

