  public cancelCurrentInput() {
    if (!this.user) {
      return
    }
    if (!this.userInputId) {
      return
    }

    // Remove the cancelled input ID from the non-cancelled list
    this.nonCancelledUserInputIds = this.nonCancelledUserInputIds.filter(
      (id) => id !== this.userInputId,
    )

    sendActionAndHandleError(this.webSocket, {
      type: 'cancel-user-input',
      authToken: this.user?.authToken,
      promptId: this.userInputId,
    })
    this.userInputId = undefined
  }

  private subscribeToResponse(
    onChunk: (chunk: string | PrintModeEvent) => void,
    userInputId: string,
    onStreamStart: () => void,
    prompt: string,
    startTime: number,
  ) {
    const rawChunkBuffer: string[] = []
    let streamStarted = false
    let responseStopped = false
    let resolveResponse: (
      value: ServerAction & { type: 'prompt-response' } & {
        wasStoppedByUser: boolean
      },
    ) => void
    let rejectResponse: (reason?: any) => void
    let unsubscribeChunks: () => void
    let unsubscribeComplete: () => void

    const responsePromise = new Promise<
      ServerAction & { type: 'prompt-response' } & {
        wasStoppedByUser: boolean
      }
    >((resolve, reject) => {
      resolveResponse = resolve
      rejectResponse = reject
    })

    this.userInputId = userInputId

    const stopResponse = () => {
      responseStopped = true
      unsubscribeChunks()
      unsubscribeComplete()
      this.cancelCurrentInput()

      const additionalMessages = prompt
        ? [
            { role: 'user' as const, content: prompt },
            {
              role: 'user' as const,
              content: `<system><assistant_message>${rawChunkBuffer.join('')}${closeXml('assistant_message')}[RESPONSE_CANCELED_BY_USER]${closeXml('system')}`,
            },
          ]
        : []

      // Update the agent state with just the assistant's response
      const {
        mainAgentState: { messageHistory },
      } = this.sessionState!
      const newMessages = [...messageHistory, ...additionalMessages]
      this.sessionState = {
        ...this.sessionState!,
        mainAgentState: {
          ...this.sessionState!.mainAgentState,
          messageHistory: newMessages,
        },
      }
      setMessages(newMessages)

      resolveResponse({
        type: 'prompt-response',
        promptId: userInputId,
        sessionState: this.sessionState!,
        toolCalls: [],
        toolResults: [],
        wasStoppedByUser: true,
      })
    }

    const xmlStreamParser = createXMLStreamParser(toolRenderers, (chunk) => {
      onChunk(chunk)
    })

    unsubscribeChunks = this.webSocket.subscribe('response-chunk', (a) => {
      if (a.userInputId !== userInputId) return
      if (typeof a.chunk === 'string') {
        const { chunk } = a

        rawChunkBuffer.push(chunk)

        const trimmed = chunk.trim()
        for (const tag of ONE_TIME_TAGS) {
          if (
            trimmed.startsWith(`<${tag}>`) &&
            trimmed.endsWith(closeXml(tag))
          ) {
            if (this.oneTimeFlags[tag]) {
              return
            }
            Spinner.get().stop()
            const warningMessage = trimmed
              .replace(`<${tag}>`, '')
              .replace(closeXml(tag), '')
            process.stdout.write(yellow(`\n\n${warningMessage}\n\n`))
            this.oneTimeFlags[tag as (typeof ONE_TIME_LABELS)[number]] = true
            return
          }
        }

        if (chunk && chunk.trim()) {
          if (!streamStarted && chunk.trim()) {
            streamStarted = true
            onStreamStart()
          }
        }

        try {
          xmlStreamParser.write(chunk, 'utf8')
        } catch (e) {
          logger.error(
            {
              errorMessage: e instanceof Error ? e.message : String(e),
              errorStack: e instanceof Error ? e.stack : undefined,
              chunk,
            },
            'Error writing chunk to XML stream parser',
          )
        }
      } else {
        onChunk(a.chunk)
      }
    })

    let stepsCount = 0
    let toolCallsCount = 0
    unsubscribeComplete = this.webSocket.subscribe(
      'prompt-response',
      async (action) => {
        const parsedAction = PromptResponseSchema.safeParse(action)
        if (!parsedAction.success) {
          const message = [
            'Received invalid prompt response from server:',
            JSON.stringify(parsedAction.error.issues),
            'If this issues persists, please contact support@codebuff.com',
          ].join('\n')
          console.error(message)
          logger.error(
            {
              errorMessage: message,
              action,
              eventId: AnalyticsEvent.MALFORMED_PROMPT_RESPONSE,
            },
            'Malformed prompt response',
          )
          return
        }
        if (action.promptId !== userInputId) return
        const a = parsedAction.data
        this.responseComplete = true

        Spinner.get().stop()

        this.sessionState = a.sessionState
        const toolResults: ToolResult[] = []

        stepsCount++
        console.log('\n')

        // If we had any file changes, update the project context
        if (DiffManager.getChanges().length > 0) {
          this.fileContext = await getProjectFileContext(getProjectRoot(), {})
        }

        const endTime = Date.now()
        const latencyMs = endTime - startTime
        trackEvent(AnalyticsEvent.USER_INPUT_COMPLETE, {
          userInputId,
          latencyMs,
          stepsCount,
          toolCallsCount,
        })

        this.lastToolResults = toolResults

        askConfig: if (
          this.oneTimeFlags[SHOULD_ASK_CONFIG] &&
          !this.oneTimeFlags[ASKED_CONFIG]
        ) {
          this.oneTimeFlags[ASKED_CONFIG] = true
          if (existsSync(path.join(getProjectRoot(), CONFIG_FILE_NAME))) {
            break askConfig
          }

          console.log(
            '\n\n' +
              yellow(`✨ Recommended: run the 'init' command in order to create a configuration file!

If you would like background processes (like this one) to run automatically whenever Codebuff starts, creating a ${CONFIG_FILE_NAME} config file can improve your workflow.
Go to https://www.codebuff.com/config for more information.`) +
              '\n',
          )
        }

        if (this.sessionState) {
          setMessages(this.sessionState.mainAgentState.messageHistory)
        }

        // Mark any spawnable agents as inactive when the main response completes
        // This is a simple heuristic - in practice you might want more sophisticated tracking
        const allSubagentIds = getAllSubagentIds()
        allSubagentIds.forEach((agentId: string) => {
          markSubagentInactive(agentId)
        })

        // Show total credits used for this prompt if significant
        const credits =
          this.creditsByPromptId[userInputId]?.reduce((a, b) => a + b, 0) ?? 0
        if (credits >= REQUEST_CREDIT_SHOW_THRESHOLD) {
          console.log(
            `\n\n${pluralize(credits, 'credit')} used for this request.`,
          )
        }

        if (DiffManager.getChanges().length > 0) {
          let checkpointAddendum = ''
          try {
            checkpointAddendum = ` or "checkpoint ${checkpointManager.getLatestCheckpoint().id}" to revert`
          } catch (error) {
            // No latest checkpoint, don't show addendum
            logger.info(
              {
                errorMessage:
                  error instanceof Error ? error.message : String(error),
                errorStack: error instanceof Error ? error.stack : undefined,
              },
              'No latest checkpoint for addendum',
            )
          }
          console.log(
            `\n\nComplete! Type "diff" to review changes${checkpointAddendum}.\n`,
          )

          if (this.isInitializing) {
            this.isInitializing = false
            // Show tips and start background processes
            this.handleInitializationComplete()
          }

          this.freshPrompt()
        }

        if (!ASYNC_AGENTS_ENABLED) {
          xmlStreamParser.end()
          unsubscribeChunks()
          unsubscribeComplete()
        }
        resolveResponse({ ...a, wasStoppedByUser: false })
      },
    )

    // Reset flags at the start of each response
    this.responseComplete = false

    return {
      responsePromise,
      stopResponse,
    }
  }

  public async getUsage() {
    try {
      // Check for organization coverage first
      const coverage = await this.checkRepositoryCoverage()

      const response = await fetch(`${backendUrl}/api/usage`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          fingerprintId: await this.fingerprintId,
          authToken: this.user?.authToken,
          ...(coverage.isCovered &&
            coverage.organizationId && { orgId: coverage.organizationId }),
        }),
      })

      const data = await response.json()

      // Use zod schema to validate response
      const parsedResponse = UsageReponseSchema.parse(data)

      if ((data as any).type === 'action-error') {
        console.error(red((data as any).message))
        logger.error(
          {
            errorMessage: (data as any).message,
          },
          'Action error',
        )
        return
      }

      this.setUsage(parsedResponse)

      // Calculate session usage and total for display
      const totalCreditsUsedThisSession = Object.values(this.creditsByPromptId)
        .flat()
        .reduce((sum, credits) => sum + credits, 0)

      let sessionUsageMessage = `Session usage: ${totalCreditsUsedThisSession.toLocaleString()}`
      if (this.usageData.remainingBalance !== null) {
        const remainingColor =
          this.usageData.remainingBalance === null
            ? yellow
            : this.usageData.remainingBalance <= 0
              ? red
              : this.usageData.remainingBalance <= LOW_BALANCE_THRESHOLD
                ? red
                : green
        sessionUsageMessage += `. Credits Remaining: ${remainingColor(this.usageData.remainingBalance.toLocaleString())}`
      } else {
        sessionUsageMessage += '.'
      }
      console.log(sessionUsageMessage)

      if (coverage.isCovered && coverage.organizationName) {
        // When covered by an organization, show organization information
        console.log(
          green(
            `🏢 Your usage in this repository is covered by ${bold(coverage.organizationName)}.`,
          ),
        )
        // Try to use organizationSlug from the coverage response
        if (coverage.organizationSlug) {
          const orgUsageLink = `${websiteUrl}/orgs/${coverage.organizationSlug}`
          console.log(
            `View your organization's usage details: ${underline(blue(orgUsageLink))}`,
          )
        }
      } else {
        // Only show personal usage details when not covered by an organization
        const usageLink = `${websiteUrl}/usage` // Personal usage link

        // Only show personal credit renewal if not covered by an organization
        if (this.usageData.next_quota_reset) {
          const resetDate = new Date(this.usageData.next_quota_reset)
          const today = new Date()
          const isToday = resetDate.toDateString() === today.toDateString()

          const dateDisplay = isToday
            ? resetDate.toLocaleString() // Show full date and time for today
            : resetDate.toLocaleDateString() // Just show date otherwise

          console.log(
            `Free credits will renew on ${dateDisplay}. Details: ${underline(blue(usageLink))}`,
          )
        }

        this.showUsageWarning()
      }
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
        },
        'Error checking usage',
      )
      console.error(
        red(
          `Error checking usage: Please reach out to ${process.env.NEXT_PUBLIC_SUPPORT_EMAIL} for help.`,
        ),
      )
      // Check if it's a ZodError for more specific feedback
      if (error instanceof z.ZodError) {
        console.error(red('Data validation failed:'), error.issues)
        logger.error(
          {
            errorMessage: 'Data validation failed',
            errors: error.issues,
          },
          'Data validation failed',
        )
      } else {
        console.error(error)
        logger.error(
          {
            errorMessage:
              error instanceof Error ? error.message : String(error),
            errorStack: error instanceof Error ? error.stack : undefined,
          },
          'Error checking usage',
        )
      }
    } finally {
      this.freshPrompt()
    }
  }

  public async warmContextCache() {
    const fileContext = await getProjectFileContext(getProjectRoot(), {})
    if (!fileContext) {
      throw new Error('Failed to initialize project file context')
    }

    this.webSocket.subscribe('init-response', (a) => {
      const parsedAction = InitResponseSchema.safeParse(a)
      if (!parsedAction.success) {
        return
      }

      // Store agent names for tool renderer (merge backend and local agents)
      if (parsedAction.data.agentNames) {
        const localAgentNames = getLoadedAgentNames()
        this.agentNames = {
          ...parsedAction.data.agentNames,
          ...localAgentNames,
        }
      }

      // Log the message if it's defined
      if (parsedAction.data.message) {
        console.log(`\n${parsedAction.data.message}`)
        this.freshPrompt()
      }

      // Set initial usage data from the init response
      this.setUsage(parsedAction.data)
    })

    const initAction: ClientAction<'init'> = {
      type: 'init',
      fingerprintId: await this.fingerprintId,
      authToken: this.user?.authToken,
      fileContext,
      // Add repoUrl here as per the diff for client.ts
      repoUrl: loggerContext.repoUrl,
    }
    sendActionAndHandleError(this.webSocket, initAction)

    await this.fetchStoredApiKeyTypes()
  }

  /**
   * Checks if the current repository is covered by an organization.
   * @param remoteUrl Optional remote URL. If not provided, will try to get from git config.
   * @returns Promise<{ isCovered: boolean; organizationName?: string; organizationId?: string; organizationSlug?: string; error?: string }>
   */
  public async checkRepositoryCoverage(remoteUrl?: string): Promise<{
    isCovered: boolean
    organizationName?: string
    organizationId?: string
    organizationSlug?: string
    error?: string
  }> {
    try {
      // Always use getRepoMetrics to get repo info, passing remoteUrl if provided
      let repoMetrics: Awaited<ReturnType<typeof getRepoMetrics>>
      try {
        repoMetrics = await getRepoMetrics(remoteUrl)
      } catch (error) {
        return {
          isCovered: false,
          error: 'Could not get repository information',
        }
      }

      const { repoUrl, owner, repo } = repoMetrics

      if (!repoUrl) {
        return { isCovered: false, error: 'No remote URL found' }
      }

      if (!owner || !repo) {
        return { isCovered: false, error: 'Could not parse repository URL' }
      }

      // Check if user is authenticated
      if (!this.user || !this.user.authToken) {
        return { isCovered: false, error: 'User not authenticated' }
      }

      // Call backend API to check if repo is covered by organization
      const response = await fetch(`${backendUrl}/api/orgs/is-repo-covered`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.user.authToken}`,
        },
        body: JSON.stringify({
          owner: owner.toLowerCase(),
          repo: repo.toLowerCase(),
          remoteUrl: repoUrl,
        }),
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        return {
          isCovered: false,
          error:
            (errorData as any).error ||
            `HTTP ${response.status}: ${response.statusText}`,
        }
      }

      const data: any = await response.json()
      return {
        isCovered: data.isCovered || false,
        organizationName: data.organizationName,
        organizationId: data.organizationId,
        organizationSlug: data.organizationSlug,
      }
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          remoteUrl,
        },
        'Error checking repository coverage',
      )
      return {
        isCovered: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      }
    }
  }
}

import { PostHog } from 'posthog-node'

import { suppressConsoleOutput } from './suppress-console'

import type { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'

// Prints the events to console
// It's very noisy, so recommended you set this to true
// only when you're actively adding new analytics
let DEBUG_DEV_EVENTS = false

// Store the identified user ID
let currentUserId: string | undefined
let client: PostHog | undefined

export let identified: boolean = false

// Apply console wrapping when PostHog is initialized
function suppressPostHogConsoleErrors() {
  suppressConsoleOutput('error', (args, errorName) =>
    errorName.toLowerCase().includes('posthog'),
  )
  suppressConsoleOutput('warn', (args, errorName) =>
    errorName.toLowerCase().includes('posthog'),
  )
}

export function initAnalytics() {
  if (
    !process.env.NEXT_PUBLIC_POSTHOG_API_KEY ||
    !process.env.NEXT_PUBLIC_POSTHOG_HOST_URL
  ) {
    throw new Error(
      'NEXT_PUBLIC_POSTHOG_API_KEY or NEXT_PUBLIC_POSTHOG_HOST_URL is not set',
    )
  }

  client = new PostHog(process.env.NEXT_PUBLIC_POSTHOG_API_KEY, {
    host: process.env.NEXT_PUBLIC_POSTHOG_HOST_URL,
    enableExceptionAutocapture:
      process.env.NEXT_PUBLIC_CB_ENVIRONMENT === 'prod',
  })

  // Suppress PostHog console errors after initialization
  suppressPostHogConsoleErrors()
}

export async function flushAnalytics() {
  if (!client) {
    return
  }
  try {
    await client.flush()
  } catch (error) {
    // Silently handle PostHog network errors - don't log to console or logger
    // This prevents PostHog errors from cluttering the user's console
  }
}

export function trackEvent(
  event: AnalyticsEvent,
  properties?: Record<string, any>,
) {
  const distinctId = currentUserId
  if (!distinctId) {
    return
  }
  if (!client) {
    if (process.env.NEXT_PUBLIC_CB_ENVIRONMENT === 'prod') {
      throw new Error('Analytics client not initialized')
    }
    return
  }

  if (process.env.NEXT_PUBLIC_CB_ENVIRONMENT !== 'prod') {
    if (DEBUG_DEV_EVENTS) {
      console.log('Analytics event sent', {
        event,
        properties,
      })
    }
    return
  }

  client.capture({
    distinctId,
    event,
    properties,
  })
}

export function identifyUser(userId: string, properties?: Record<string, any>) {
  // Store the user ID for future events
  currentUserId = userId

  if (!client) {
    throw new Error('Analytics client not initialized')
  }

  if (process.env.NEXT_PUBLIC_CB_ENVIRONMENT !== 'prod') {
    if (DEBUG_DEV_EVENTS) {
      console.log('Identify event sent', {
        userId,
        properties,
      })
    }
    return
  }

  client.identify({
    distinctId: userId,
    properties,
  })
}

export function logError(
  error: any,
  userId?: string,
  properties?: Record<string, any>,
) {
  if (!client) {
    return
  }

  try {
    client.captureException(
      error,
      userId ?? currentUserId ?? 'unknown',
      properties,
    )
  } catch (postHogError) {
    // Silently handle PostHog errors - don't log them to console
    // This prevents PostHog connection issues from cluttering the user's console
  }
}

import { mkdirSync } from 'fs'
import path, { dirname } from 'path'
import { format as stringFormat } from 'util'

import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import { pino } from 'pino'

import { getCurrentChatDir, getProjectRoot } from '../project-files'
import { flushAnalytics, logError, trackEvent } from './analytics'

export interface LoggerContext {
  userId?: string
  userEmail?: string
  clientSessionId?: string
  fingerprintId?: string
  clientRequestId?: string
  [key: string]: any // Allow for future extensions
}

export const loggerContext: LoggerContext = {}

const analyticsBuffer: { analyticsEventId: AnalyticsEvent; toTrack: any }[] = []

let logPath: string | undefined = undefined
let pinoLogger: any = undefined

const loggingLevels = ['info', 'debug', 'warn', 'error', 'fatal'] as const
type LogLevel = (typeof loggingLevels)[number]

function setLogPath(p: string): void {
  if (p === logPath) return // nothing to do

  logPath = p
  mkdirSync(dirname(p), { recursive: true })

  // ──────────────────────────────────────────────────────────────
  //  pino.destination(..) → SonicBoom stream, no worker thread
  // ──────────────────────────────────────────────────────────────
  const fileStream = pino.destination({
    dest: p, // absolute or relative file path
    mkdir: true, // create parent dirs if they don’t exist
    sync: false, // set true if you *must* block on every write
  })

  pinoLogger = pino(
    {
      level: 'debug',
      formatters: {
        level: (label) => ({ level: label.toUpperCase() }),
      },
      timestamp: () => `,"timestamp":"${new Date().toISOString()}"`,
    },
    fileStream, // <-- no worker thread involved
  )
}

function sendAnalyticsAndLog(
  level: LogLevel,
  data: any,
  msg?: string,
  ...args: any[]
): void {
  if (
    process.env.CODEBUFF_GITHUB_ACTIONS !== 'true' &&
    process.env.NEXT_PUBLIC_CB_ENVIRONMENT !== 'test'
  ) {
    const projectRoot = getProjectRoot() || process.cwd()

    const logTarget =
      process.env.NEXT_PUBLIC_CB_ENVIRONMENT === 'dev'
        ? path.join(projectRoot, 'debug', 'npm-app.log')
        : (() => {
            try {
              return path.join(getCurrentChatDir(), 'log.jsonl')
            } catch {
              return path.join(projectRoot, 'debug', 'npm-app.log')
            }
          })()

    setLogPath(logTarget)
  }

  const toTrack = {
    data,
    level,
    loggerContext,
    msg: stringFormat(msg, ...args),
  }

  logAsErrorIfNeeded(toTrack)

  logOrStore: if (
    process.env.NEXT_PUBLIC_CB_ENVIRONMENT !== 'dev' &&
    Object.values(AnalyticsEvent).includes(data.eventId)
  ) {
    const analyticsEventId = data.eventId as AnalyticsEvent
    // Not accurate for anonymous users
    if (!loggerContext.userId) {
      analyticsBuffer.push({ analyticsEventId, toTrack })
      break logOrStore
    }

    for (const item of analyticsBuffer) {
      trackEvent(item.analyticsEventId, item.toTrack)
    }
    analyticsBuffer.length = 0
    trackEvent(analyticsEventId, toTrack)
  }

  if (pinoLogger !== undefined) {
    pinoLogger[level]({ ...loggerContext, data }, msg, ...args)
  }
}

function logAsErrorIfNeeded(toTrack: {
  data: any
  level: LogLevel
  loggerContext: LoggerContext
  msg: string
}) {
  if (toTrack.level === 'error' || toTrack.level === 'fatal') {
    logError(
      new Error(toTrack.msg),
      toTrack.loggerContext.userId ?? 'unknown',
      { ...toTrack.data, context: toTrack.loggerContext },
    )
    flushAnalytics()
  }
}

/**
 * Wrapper around Pino logger.
 *
 * To also send to Posthog, set data.eventId to type AnalyticsEvent
 *
 * e.g. logger.info({eventId: AnalyticsEvent.SOME_EVENT, field: value}, 'some message')
 */
export const logger: Record<LogLevel, pino.LogFn> = Object.fromEntries(
  loggingLevels.map((level) => {
    return [
      level,
      (data: any, msg?: string, ...args: any[]) =>
        sendAnalyticsAndLog(level, data, msg, ...args),
    ]
  }),
) as Record<LogLevel, pino.LogFn>

import assert from 'assert'
import { spawn } from 'child_process'
import {
  mkdirSync,
  readdirSync,
  readFileSync,
  unlinkSync,
  writeFileSync,
} from 'fs'
import path from 'path'
import process from 'process'

import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import { buildArray } from '@codebuff/common/util/array'
import { truncateStringWithMessage } from '@codebuff/common/util/string'
import { closeXml } from '@codebuff/common/util/xml'
import { gray, red } from 'picocolors'
import { z } from 'zod/v4'

import { CONFIG_DIR } from './credentials'
import { logger } from './utils/logger'

import type { ToolResult } from '@codebuff/common/types/session-state'
import type {
  ChildProcessByStdio,
  ChildProcessWithoutNullStreams,
  SpawnOptionsWithoutStdio,
} from 'child_process'

const COMMAND_OUTPUT_LIMIT = 5000 // Limit output to 10KB per stream
const COMMAND_KILL_TIMEOUT_MS = 5000
const POLLING_INTERVAL_MS = 200

const LOCK_DIR = path.join(CONFIG_DIR, 'background_processes')

/**
 * Interface describing the information stored for each background process.
 */
export interface BackgroundProcessInfo {
  // OS-assigned Process ID
  pid: number
  toolCallId: string
  command: string
  // The actual child process object
  process: ChildProcessByStdio<any, any, any>
  // Buffer to store stdout chunks
  stdoutBuffer: string[]
  // Buffer to store stderr chunks
  stderrBuffer: string[]
  // Current status of the process
  status: 'running' | 'completed' | 'error'
  // Timestamp when the process was started
  startTime: number
  // Timestamp when the process ended (completed or errored)
  endTime: number | null
  // Length of stdout content that has been reported
  lastReportedStdoutLength: number
  // Length of stderr content that has been reported
  lastReportedStderrLength: number
  // Last reported status
  lastReportedStatus: 'running' | 'completed' | 'error' | null
  // Path to file where stdout is being written (if specified)
  stdoutFile?: string
  // Path to file where stderr is being written (if specified)
  stderrFile?: string
}

/**
 * Global map storing information about active and completed background processes.
 * Keyed by the OS-assigned Process ID (PID).
 */
export const backgroundProcesses = new Map<number, BackgroundProcessInfo>()

/**
 * Gets output with context about whether there was previous content
 */
function getOutputWithContext(
  newContent: string,
  lastReportedLength: number,
): string {
  if (newContent) {
    const hasOldContent = lastReportedLength > 0
    return hasOldContent ? '[PREVIOUS OUTPUT]\n' + newContent : newContent
  }
  return '[NO NEW OUTPUT]'
}

/**
 * Formats a single background process's info into a string
 */
export function getBackgroundProcessInfoString(
  info: BackgroundProcessInfo,
): string {
  const newStdout = info.stdoutBuffer
    .join('')
    .slice(info.lastReportedStdoutLength)
  const newStderr = info.stderrBuffer
    .join('')
    .slice(info.lastReportedStderrLength)

  // Only report finished processes if there are changes
  if (
    info.status !== 'running' &&
    !newStdout &&
    !newStderr &&
    info.status === info.lastReportedStatus
  ) {
    return ''
  }

  // Calculate duration in milliseconds
  const duration = info.endTime
    ? info.endTime - info.startTime
    : Date.now() - info.startTime

  return buildArray(
    '<background_process>',
    `<process_id>${info.pid}${closeXml('process_id')}`,
    `<command>${info.command}${closeXml('command')}`,
    `<start_time_utc>${new Date(info.startTime).toISOString()}${closeXml('start_time_utc')}`,
    `<duration_ms>${duration}${closeXml('duration_ms')}`,
    newStdout &&
      `<stdout>${truncateStringWithMessage({
        str: getOutputWithContext(newStdout, info.lastReportedStdoutLength),
        maxLength: COMMAND_OUTPUT_LIMIT,
        remove: 'START',
      })}${closeXml('stdout')}`,
    newStderr &&
      `<stderr>${truncateStringWithMessage({
        str: getOutputWithContext(newStderr, info.lastReportedStderrLength),
        maxLength: COMMAND_OUTPUT_LIMIT,
        remove: 'START',
      })}${closeXml('stderr')}`,
    `<status>${info.status}${closeXml('status')}`,
    info.process.exitCode !== null &&
      `<exit_code>${info.process.exitCode}${closeXml('exit_code')}`,
    info.process.signalCode &&
      `<signal_code>${info.process.signalCode}${closeXml('signal_code')}`,
    closeXml('background_process'),
  ).join('\n')
}

/**
 * Gets updates from all background processes and updates tracking info
 */
export function getBackgroundProcessUpdates(): ToolResult[] {
  const updates = Array.from(backgroundProcesses.values())
    .map((bgProcess) => {
      return [getBackgroundProcessInfoString(bgProcess), bgProcess.toolCallId]
    })
    .filter(([update]) => Boolean(update))

  // Update tracking info after getting updates
  for (const process of backgroundProcesses.values()) {
    process.lastReportedStdoutLength = process.stdoutBuffer.join('').length
    process.lastReportedStderrLength = process.stderrBuffer.join('').length
    process.lastReportedStatus = process.status
  }

  // Clean up completed processes that we've already reported
  cleanupReportedProcesses()

  return updates.map(([update, toolCallId]) => {
    return {
      toolCallId,
      toolName: 'background_process_updates',
      output: { type: 'text', value: update },
    }
  })
}

function deleteFileIfExists(fileName: string) {
  try {
    unlinkSync(fileName)
  } catch {}
}

const zodMaybeNumber = z.preprocess((val) => {
  const n = Number(val)
  return typeof val === 'undefined' || isNaN(n) ? undefined : n
}, z.number().optional())

const lockFileSchema = z.object({
  parentPid: zodMaybeNumber,
})

type LockFileSchema = z.infer<typeof lockFileSchema>

/**
 * Creates a lock file for a background process with the current process's PID.
 * This allows tracking parent-child process relationships for cleanup.
 *
 * @param filePath - Path where the lock file should be created
 */
function createLockFile(filePath: string): void {
  const data: LockFileSchema = {
    parentPid: process.pid,
  }

  writeFileSync(filePath, JSON.stringify(data, null, 1))
}

/**
 * Checks if a process with the given PID is still running.
 *
 * @param pid - Process ID to check
 * @returns true if the process is running, false otherwise
 */
function isRunning(pid: number) {
  try {
    process.kill(pid, 0)
  } catch (error: any) {
    if (error.code === 'ESRCH') {
      return false
    }
  }

  return true
}

/**
 * Determines whether the process associated with a given PID should be
 * terminated, based on the lock file contents stored for that PID.
 *
 * If the parent process is no longer active or the file is invalid, the
 * function assumes the process is orphaned and should be killed.
 *
 * @param lockFile - The path of the lock file.
 * @returns `true` if the process should be killed (e.g. parent no longer exists or file is invalid),
 *          `false` if the parent process is still alive and the process should be kept running.
 */
function shouldKillProcessUsingLock(lockFile: string): boolean {
  const fileContents = String(readFileSync(lockFile))

  let data: LockFileSchema
  try {
    data = lockFileSchema.parse(JSON.parse(fileContents))
  } catch (error) {
    data = {
      parentPid: undefined,
    }
  }

  if (data.parentPid && isRunning(data.parentPid)) {
    return false
  }

  return true
}

export function spawnAndTrack(
  command: string,
  args: string[] = [],
  options: SpawnOptionsWithoutStdio,
): ChildProcessWithoutNullStreams {
  const child = spawn(command, args, {
    ...options,
    detached: true,
  })
  assert(child.pid !== undefined)
  logger.info(
    {
      eventId: AnalyticsEvent.BACKGROUND_PROCESS_START,
      pid: child.pid,
    },
    `Process start: \`${command} ${args.join(' ')}\``,
  )

  mkdirSync(LOCK_DIR, { recursive: true })
  const filePath = path.join(LOCK_DIR, `${child.pid}`)
  createLockFile(filePath)

  child.on('exit', () => {
    deleteFileIfExists(filePath)
    logger.info(
      { eventId: AnalyticsEvent.BACKGROUND_PROCESS_END, pid: child.pid },
      `Graceful exit: \`${command} ${args.join(' ')}\``,
    )
  })
  return child
}

/**
 * Removes completed processes that have been fully reported
 */
function cleanupReportedProcesses(): void {
  for (const [pid, info] of backgroundProcesses.entries()) {
    if (
      (info.status === 'completed' || info.status === 'error') &&
      info.lastReportedStatus === info.status &&
      info.lastReportedStdoutLength === info.stdoutBuffer.join('').length &&
      info.lastReportedStderrLength === info.stderrBuffer.join('').length
    ) {
      backgroundProcesses.delete(pid)
    }
  }
}

function waitForProcessExit(pid: number): Promise<boolean> {
  return new Promise((resolve) => {
    let resolved = false

    const interval = setInterval(() => {
      if (!isRunning(pid)) {
        clearInterval(interval)
        clearTimeout(timeout)
        resolved = true
        resolve(true)
      }
    }, POLLING_INTERVAL_MS)

    const timeout = setTimeout(() => {
      if (!resolved) {
        clearInterval(interval)
        resolve(false)
      }
    }, COMMAND_KILL_TIMEOUT_MS)
  })
}

function killProcessTreeSoftly(pid: number): void {
  if (process.platform === 'win32') {
    // /T = kill tree, no /F = soft kill
    spawn('taskkill', ['/PID', String(pid), '/T'], {
      stdio: 'ignore',
      detached: true,
    }).unref()
  } else {
    try {
      process.kill(-pid, 'SIGTERM')
    } catch (err) {
      if ((err as any)?.code !== 'ESRCH') throw err
    }
  }
}

async function killAndWait(pid: number): Promise<void> {
  try {
    killProcessTreeSoftly(pid)
    if (await waitForProcessExit(pid)) {
      return
    }
  } catch (error: any) {
    if (error.code === 'ESRCH') {
      return
    } else {
      throw error
    }
  }
  throw new Error(`Unable to kill process ${pid}`)
}

// Only to be run on exit
export function sendKillSignalToAllBackgroundProcesses(): void {
  for (const [pid, p] of backgroundProcesses.entries()) {
    if (p.status !== 'running') {
      continue
    }

    try {
      killProcessTreeSoftly(pid)
    } catch {}
  }
}

export async function killAllBackgroundProcesses(): Promise<void> {
  const killPromises = Array.from(backgroundProcesses.entries())
    .filter(([, p]) => p.status === 'running')
    .map(async ([pid, processInfo]) => {
      try {
        await killAndWait(pid)
        // console.log(gray(`Killed process: \`${processInfo.command}\``))
      } catch (error: any) {
        console.error(
          red(
            `Failed to kill: \`${processInfo.command}\` (pid ${pid}): ${error?.message || error}`,
          ),
        )
        logger.error(
          {
            errorMessage: error?.message || String(error),
            pid,
            command: processInfo.command,
          },
          'Failed to kill process',
        )
      }
    })

  await Promise.all(killPromises)
  backgroundProcesses.clear()
}

/**
 * Cleans up stale lock files and attempts to kill orphaned processes found in the lock directory.
 * This function is intended to run on startup to handle cases where the application might have
 * exited uncleanly, leaving orphaned processes or lock files.
 *
 * @returns Object containing:
 *   - shouldStartNewProcesses: boolean indicating if it's safe to start new processes
 *   - cleanUpPromise: Promise that resolves when cleanup is complete
 */
export function cleanupStoredProcesses(): {
  separateCodebuffInstanceRunning: boolean
  cleanUpPromise: Promise<any>
} {
  // Determine which processes to kill (sync)
  let separateCodebuffInstanceRunning = false
  const locksToProcess: string[] = []
  try {
    mkdirSync(LOCK_DIR, { recursive: true })
    const files = readdirSync(LOCK_DIR)

    for (const file of files) {
      const lockFile = path.join(LOCK_DIR, file)
      if (shouldKillProcessUsingLock(lockFile)) {
        locksToProcess.push(file)
      } else {
        separateCodebuffInstanceRunning = true
      }
    }
  } catch {}

  if (locksToProcess.length) {
    console.log(gray('Detected running codebuff processes. Cleaning...\n'))
    logger.info({
      eventId: AnalyticsEvent.BACKGROUND_PROCESS_LEFTOVER_DETECTED,
      pids: locksToProcess,
    })
  }

  // Actually kill processes (async)
  const processLockFile = async (pidName: string) => {
    const lockFile = path.join(LOCK_DIR, pidName)

    const pid = parseInt(pidName, 10)
    if (isNaN(pid)) {
      deleteFileIfExists(lockFile)
      logger.info(
        { eventId: AnalyticsEvent.BACKGROUND_PROCESS_END, pid },
        'Lock found but process not running.',
      )
      return
    }

    if (backgroundProcesses.has(pid)) {
      logger.error(
        { eventId: AnalyticsEvent.BACKGROUND_PROCESS_END, pid },
        'Process running in current session. Should not occur.',
      )
      return
    }

    try {
      killProcessTreeSoftly(pid)
      if (await waitForProcessExit(pid)) {
        deleteFileIfExists(lockFile)
        logger.info(
          { eventId: AnalyticsEvent.BACKGROUND_PROCESS_END, pid },
          'Process successfully killed.',
        )
      } else {
        logger.warn(
          { eventId: AnalyticsEvent.BACKGROUND_PROCESS_CONTINUE, pid },
          'Process unable to be killed. Leaving lock file.',
        )
      }
    } catch (err: any) {
      if (err.code === 'ESRCH') {
        deleteFileIfExists(lockFile)
        logger.info(
          { eventId: AnalyticsEvent.BACKGROUND_PROCESS_END, pid },
          'Leftover process (with lock) died naturally.',
        )
      } else {
        logger.error(
          { eventId: AnalyticsEvent.BACKGROUND_PROCESS_CONTINUE, err, pid },
          'Error killing process',
        )
      }
    }
  }

  const cleanUpPromise = Promise.all(locksToProcess.map(processLockFile))

  return {
    separateCodebuffInstanceRunning,
    cleanUpPromise,
  }
}

import path from 'path'

import { codebuffConfigFile } from '@codebuff/common/json-config/constants'
import { generateCompactId } from '@codebuff/common/util/string'
import { yellow } from 'picocolors'

import { runBackgroundCommand } from './terminal/background'

import type { StartupProcess } from '@codebuff/common/json-config/constants'

/**
 * Starts background development processes defined in the config file.
 * Processes are started asynchronously and their output is tracked.
 * Only enabled processes are started.
 *
 * @param processes - Array of startup process configurations
 * @param projectPath - Base path of the project
 */
export function startDevProcesses(
  processes: StartupProcess[],
  projectPath: string,
) {
  const toStart = processes.filter((process) => process.enabled)

  if (!toStart.length) {
    return
  }

  console.log(yellow(`Starting ${codebuffConfigFile} processes:`))

  for (const {
    name,
    command,
    cwd,
    enabled,
    stderrFile,
    stdoutFile,
  } of processes) {
    if (!enabled) {
      continue
    }

    // Resolve working directory
    const absoluteCwd = cwd
      ? path.isAbsolute(cwd)
        ? cwd
        : path.resolve(projectPath, cwd)
      : projectPath

    // Start the process
    runBackgroundCommand(
      {
        toolCallId: generateCompactId(),
        command,
        mode: 'user',
        cwd: absoluteCwd,
        stdoutFile,
        stderrFile,
      },
      ({ result }) => {
        const m = result.match(/<process_id>(\d+)<\/process_id>/)
        if (m) {
          console.log(yellow(`- ${name}: ${command}`))
        } else {
          console.log(yellow(`- ${name}: ${command} — failed to start`))
        }
      },
    )
  }

  console.log()
}

