/* ------------------------------------------------------------------ */
/* constants                                                          */
/* ------------------------------------------------------------------ */

const COMMAND_OUTPUT_LIMIT = 10_000
const IS_WINDOWS = os.platform() === 'win32'

/* ------------------------------------------------------------------ */
/* colour‑helper : adds "--color" style flags when missing            */
/* ------------------------------------------------------------------ */

function applyColorHints(cmd: string): string {
  /* don't touch complex pipelines – best effort */
  if (cmd.includes('|') || cmd.includes('>')) return cmd

  /* ---------- git -------------------------------------------------- */
  if (/^\s*git\b/.test(cmd) && !/--color\b/.test(cmd)) {
    if (/\bdiff\b/.test(cmd)) {
      // Insert --color=always after 'git diff' but before any file paths or other args
      return cmd.replace(/^(\s*git\s+diff)/, '$1 --color=always')
    }
    if (/\blog\b/.test(cmd)) {
      return cmd.replace(/^(\s*git\s+log)/, '$1 --color=always')
    }
    if (/\bshow\b/.test(cmd)) {
      return cmd.replace(/^(\s*git\s+show)/, '$1 --color=always')
    }
  }

  /* ---------- grep / ripgrep --------------------------------------- */
  if (/\b(rg|grep|egrep|fgrep)\b/.test(cmd) && !/--color\b/.test(cmd)) {
    return `${cmd} --color=always`
  }

  /* ---------- ls ---------------------------------------------------- */
  if (
    /^\s*ls\b/.test(cmd) && // plain "ls"
    !/[\s\-][1lCx]/.test(cmd) && // none of -1 -l -C -x present
    !/--color\b/.test(cmd) // and no colour flag yet
  ) {
    const colourFlag = IS_WINDOWS
      ? '--color=always' // Git‑coreutils on Win
      : process.platform === 'darwin'
        ? '-G' // BSD flag
        : '--color=always'

    /* -C forces multi‑column even when stdout isn't a TTY */
    return `${cmd} -C ${colourFlag}`
  }

  /* ---------- tree -------------------------------------------------- */
  if (/^\s*tree\b/.test(cmd) && !/\s\-C\b/.test(cmd)) {
    return `${cmd} -C`
  }

  return cmd
}

/* ------------------------------------------------------------------ */
/* helpers                                                            */
/* ------------------------------------------------------------------ */

/** Which family of shell are we launching? */
type UnixShell = 'bash' | 'zsh'
type WinShell = 'cmd.exe'

type ShellKind = UnixShell | WinShell

function basename(cmd: string) {
  return path.basename(cmd).toLowerCase()
}

/** Decide which concrete binary to start based on platform + env */
function selectShell(): ShellKind {
  if (IS_WINDOWS) {
    return 'cmd.exe'
  }

  const detectedShell = detectShell()
  // Prefer zsh if available, otherwise fallback to bash
  return detectedShell === 'zsh' ? 'zsh' : 'bash'
}

/** Build shell‑specific "initialisation" snippets. */
function buildInit(shell: ShellKind): string[] {
  if (IS_WINDOWS) {
    /* cmd.exe has nothing useful we can "source"                          */
    return []
  }

  switch (shell) {
    case 'zsh':
      return [
        'setopt aliases', // Enable alias expansion
        'source ~/.zshenv 2>/dev/null || true',
        'source ~/.zprofile 2>/dev/null || true',
        'source ~/.zshrc 2>/dev/null || true',
        'source ~/.zlogin 2>/dev/null || true',
      ]
    case 'bash':
    default:
      return [
        'shopt -s expand_aliases', // Enable alias expansion for non-interactive bash
        // Source standard rc files – some may short-circuit
        'source ~/.bash_profile 2>/dev/null || true',
        'source ~/.profile 2>/dev/null || true',
        'source ~/.bashrc 2>/dev/null || true',
        'source ~/.bash_aliases 2>/dev/null || true', // Handle Debian/Ubuntu systems
        // Reap any alias definitions that were skipped by the "return if not interactive" guard
        'if [ -f ~/.bashrc ]; then',
        '  eval "$(grep -E \\"^[[:space:]]*alias[[:space:]]+\\" ~/.bashrc)"',
        'fi',
      ]
  }
}

/** Build environment */
function buildEnv(shell: ShellKind): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {
    ...process.env,
    PAGER: 'cat',
    GIT_PAGER: 'cat',
    GIT_TERMINAL_PROMPT: '0',
    LESS: '-FRX',
    /* ---- colour‑forcing vars -------------------------------------- */
    FORCE_COLOR: '3', // chalk / picocolors / many Node CLIs
    CLICOLOR: '1', // coreutils (BSD) honour this
    CLICOLOR_FORCE: '1',
    GIT_CONFIG_PARAMETERS: `'color.ui=always'`,
    /* ---- width / height ------------------------------------------- */
    COLUMNS: String(process.stdout.columns || 80),
    LINES: String(process.stdout.rows || 24),
    LANG: 'en_US.UTF-8',
    LC_ALL: 'en_US.UTF-8',
  }

  if (IS_WINDOWS) {
    env.TERM = 'cygwin'
  } else {
    env.TERM = 'xterm-256color'
    env.SHELL = `/bin/${shell}` // Currently: bash or zsh
  }

  return env
}

/** Create a one‑shot wrapper script for Unix‑like shells. */
function createWrapperScript(
  shell: UnixShell,
  initLines: string[],
  userCmd: string,
) {
  const tmp = mkdtempSync(join(tmpdir(), 'codebuff-')) // safe unique dir
  const scriptPath = join(tmp, `cmd.${shell}`)

  const shebang = shell === 'zsh' ? '#!/usr/bin/env zsh' : '#!/usr/bin/env bash'

  const aliasEnable =
    shell === 'zsh' ? 'setopt aliases' : 'shopt -s expand_aliases'

  writeFileSync(
    scriptPath,
    [
      shebang,
      aliasEnable,
      ...initLines,
      '',
      userCmd,
      '', // final newline
    ].join('\n'),
    { mode: 0o755 },
  )

  return scriptPath
}

/** Windows : translate shell+init+cmd -> executable + argv */
function buildWinInvocation(
  shell: WinShell,
  initLines: string[],
  userCmd: string,
): { exe: string; args: string[] } {
  const init = initLines.join('; ')
  const cmdAll = init ? `${init}; ${userCmd}` : userCmd

  if (shell === 'cmd.exe') {
    return { exe: 'cmd.exe', args: ['/d', '/s', '/c', cmdAll] } // ﻿˅ doc  :contentReference[oaicite:0]{index=0}
  }

  /* PowerShell / pwsh -------------------------------------------------- */
  return {
    exe: shell,
    args: [
      '-NoLogo',
      '-NonInteractive',
      '-ExecutionPolicy',
      'Bypass',
      '-Command',
      cmdAll,
    ],
  }
}

/* ------------------------------------------------------------------ */
/* persistent‑process bookkeeping                                     */
/* ------------------------------------------------------------------ */

export type PersistentProcess = {
  type: 'process'
  shell: ShellKind
  childProcess: ChildProcessWithoutNullStreams | null
  timerId: NodeJS.Timeout | null
  globalOutputBuffer: string
  globalOutputLastReadLength: number
  env: NodeJS.ProcessEnv
  shellInitCommands: string[]
}

async function createPersistentProcess(
  dir: string,
): Promise<PersistentProcess> {
  const shell = selectShell()
  const env = buildEnv(shell)
  const shellInitCommands = buildInit(shell)

  logger.debug({ shell, shellInitCommands }, 'Initialised persistent shell')

  return {
    type: 'process',
    shell,
    childProcess: null,
    timerId: null,
    globalOutputBuffer: '',
    globalOutputLastReadLength: 0,
    env,
    shellInitCommands,
  }
}

/* ------------------------------------------------------------------ */
/* exported state + helpers                                           */
/* ------------------------------------------------------------------ */

export let persistentProcess: Awaited<
  ReturnType<typeof createPersistentProcess>
> | null = null

let commandIsRunning = false

export const isCommandRunning = () => commandIsRunning

export const recreateShell = async (cwd: string) => {
  persistentProcess = await createPersistentProcess(cwd)
  trackEvent(AnalyticsEvent.SHELL_RECREATED, { persistentProcess })
}

export const resetShell = async (cwd: string) => {
  commandIsRunning = false
  if (persistentProcess) {
    persistentProcess.timerId && clearTimeout(persistentProcess.timerId)
    persistentProcess.childProcess?.kill()
    persistentProcess.childProcess = null
  }
}

/* ------------------------------------------------------------------ */
/* formatting helper
/* ------------------------------------------------------------------ */

function formatResult(command: string, stdout: string, status: string): string {
  return buildArray(
    `<command>${command}${closeXml('command')}`,
    '<terminal_command_result>',
    `<output>${truncateStringWithMessage({
      str: stripColors(stdout),
      maxLength: COMMAND_OUTPUT_LIMIT,
      remove: 'MIDDLE',
    })}${closeXml('output')}`,
    `<status>${status}${closeXml('status')}`,
    `${closeXml('terminal_command_result')}`,
  ).join('\n')
}

/* ------------------------------------------------------------------ */
/* PUBLIC API – runTerminalCommand                                    */
/* ------------------------------------------------------------------ */

export const runTerminalCommand = async (
  toolCallId: string,
  command: string,
  mode: 'user' | 'assistant',
  processType: 'SYNC' | 'BACKGROUND',
  timeoutSeconds: number,
  cwd?: string,
  stdoutFile?: string,
  stderrFile?: string,
): Promise<{ result: string; stdout: string; exitCode: number | null }> => {
  const maybeTimeoutSeconds = timeoutSeconds < 0 ? null : timeoutSeconds
  const projectRoot = getProjectRoot()
  cwd = cwd
    ? // Make sure cwd is an absolute path.
      path.resolve(projectRoot, cwd)
    : mode === 'assistant'
      ? projectRoot
      : getWorkingDirectory()

  /* guard: shell must exist ------------------------------------------ */
  if (!persistentProcess)
    throw new Error('Shell not initialised – call recreateShell first')

  /* reset if concurrent ---------------------------------------------- */
  if (commandIsRunning) resetShell(cwd)
  commandIsRunning = true

  /* limit huge git logs, then add colour/width hints ----------------- */
  let modifiedCmd = command.trim() === 'git log' ? 'git log -n 5' : command
  modifiedCmd = applyColorHints(modifiedCmd)

  /* analytics wrapper ------------------------------------------------- */
  const resolveCommand = (value: {
    result: string
    stdout: string
    exitCode: number | null
  }) => {
    commandIsRunning = false
    trackEvent(AnalyticsEvent.TERMINAL_COMMAND_COMPLETED, {
      command,
      result: value.result,
      stdout: value.stdout,
      exitCode: value.exitCode,
      mode,
      processType,
    })
    return value
  }

  if (processType === 'BACKGROUND') {
    return new Promise((res) =>
      runBackgroundCommand(
        { toolCallId, command: modifiedCmd, mode, cwd, stdoutFile, stderrFile },
        (v) => res(resolveCommand(v)),
      ),
    )
  }

  /* sync mode --------------------------------------------------------- */
  return new Promise((resolve) =>
    runCommandChildProcess(
      persistentProcess!,
      modifiedCmd,
      mode,
      cwd!,
      maybeTimeoutSeconds,
      (v) => resolve(resolveCommand(v)),
    ),
  )
}

/* ------------------------------------------------------------------ */
/* core command runner                                                */
/* ------------------------------------------------------------------ */

const runCommandChildProcess = async (
  pp: PersistentProcess,
  command: string,
  mode: 'user' | 'assistant' | 'manager',
  cwd: string,
  maybeTimeoutSeconds: number | null,
  resolve: (value: {
    result: string
    stdout: string
    exitCode: number | null
  }) => void,
) => {
  const projectRoot = getProjectRoot()

  /* clear screen ----------------------------------------------------- */
  if (command.trim() === 'clear') {
    process.stdout.write('\u001b[2J\u001b[0;0H')
    resolve({
      result: formatResult(command, '', 'Complete'),
      stdout: '',
      exitCode: 0,
    })
    return
  }

  /* assistant prompt banner ----------------------------------------- */
  if (mode === 'assistant') {
    const displayDir = path.join(
      path.parse(projectRoot).base,
      path.relative(projectRoot, path.resolve(projectRoot, cwd)),
    )
    // Some models omit new lines.
    console.log()
    console.log()
    console.log(green(`${displayDir} > ${command}`))
  }

  /* build process invocation ---------------------------------------- */
  const shell = pp.shell
  const initLines = pp.shellInitCommands
  let child: ChildProcessWithoutNullStreams

  if (IS_WINDOWS) {
    const { exe, args } = buildWinInvocation(
      shell as WinShell,
      initLines,
      command,
    )
    child = spawn(exe, args, { cwd, env: pp.env })
  } else {
    const script = createWrapperScript(shell as UnixShell, initLines, command)
    child = spawn(shell, [script], { cwd, env: pp.env })

    /* cleanup tmp file */
    child.on('exit', () => {
      try {
        unlinkSync(script)
      } catch {
        /* ignore */
      }
    })
  }

  /* hook into persistent state -------------------------------------- */
  pp.childProcess = child

  /* timeout guard ---------------------------------------------------- */
  let timer: NodeJS.Timeout | null = null
  if (maybeTimeoutSeconds !== null) {
    timer = setTimeout(() => {
      resetShell(cwd)
      if (mode === 'assistant') {
        resolve({
          result: formatResult(
            command,
            '',
            `Command timed out after ${maybeTimeoutSeconds}s and was terminated.`,
          ),
          stdout: '',
          exitCode: 124,
        })
      }
    }, maybeTimeoutSeconds * 1_000)
    pp.timerId = timer
  }

  /* capture output --------------------------------------------------- */
  let cmdOut = ''
  const outHandler = (data: Buffer) => {
    const s = data.toString()
    cmdOut += s
    process.stdout.write(s)
    pp.globalOutputBuffer += s
  }
  child.stdout.on('data', outHandler)
  child.stderr.on('data', outHandler)

  /* close handler ---------------------------------------------------- */
  child.on('close', (code) => {
    timer && clearTimeout(timer)

    /* cd tracking for user‑mode -------------------------------------- */
    if (command.startsWith('cd ') && mode === 'user') {
      const target = command.split(' ').slice(1).join(' ')
      const resolved = path.resolve(cwd, target)
      if (!path.relative(projectRoot, resolved).startsWith('..')) {
        setWorkingDirectory(resolved)
        trackEvent(AnalyticsEvent.CHANGE_DIRECTORY, {
          from: cwd,
          to: resolved,
          isSubdir: isSubdir(cwd, resolved),
        })
      } else {
        console.log(`
Unable to cd outside of the project root (${projectRoot})

If you want to change the project root:
1. Exit Codebuff (type "exit")
2. Navigate into the target directory (type "cd ${target}")
3. Restart Codebuff`)
      }
    }

    /* build response ------------------------------------------------- */
    const status = code === 0 ? 'Complete' : `Failed with exit code: ${code}`
    const payload =
      mode === 'assistant'
        ? formatResult(
            command,
            cmdOut,
            buildArray([`cwd: ${path.resolve(projectRoot, cwd)}`, status]).join(
              '\n\n',
            ),
          )
        : formatResult(
            command,
            cmdOut,
            buildArray([
              `Starting cwd: ${cwd}`,
              `${status}\n`,
              `Final **user** cwd: ${getWorkingDirectory()} (Assistant's cwd is still project root)`,
            ]).join('\n'),
          )

    resolve({ result: payload, stdout: cmdOut, exitCode: code })
  })
}

/* ------------------------------------------------------------------ */
/* misc exports                                                       */
/* ------------------------------------------------------------------ */

export function killAndResetPersistentProcess() {
  persistentProcess?.childProcess?.kill()
  persistentProcess = null
}

export function clearScreen() {
  process.stdout.write('\u001b[2J\u001b[0;0H')
}

import assert from 'assert'
import { createWriteStream, mkdirSync } from 'fs'
import * as os from 'os'
import path, { dirname } from 'path'

import { stripColors } from '@codebuff/common/util/string'
import { closeXml } from '@codebuff/common/util/xml'
import { green } from 'picocolors'

import {
  backgroundProcesses,
  spawnAndTrack,
} from '../background-process-manager'

import type { BackgroundProcessInfo } from '../background-process-manager'
import type { WriteStream } from 'fs'

export function runBackgroundCommand(
  options: {
    toolCallId: string
    command: string
    mode: 'user' | 'assistant' | 'manager'
    cwd: string
    stdoutFile?: string
    stderrFile?: string
  },
  resolveCommand: (value: {
    result: string
    stdout: string
    exitCode: number | null
  }) => void,
): void {
  const { toolCallId, command, mode, cwd, stdoutFile, stderrFile } = options
  const isWindows = os.platform() === 'win32'
  const shell = isWindows ? 'cmd.exe' : 'bash'
  const shellArgs = isWindows ? ['/c'] : ['-c']

  if (mode === 'assistant') {
    console.log(green(`Running background process...\n> ${command}`))
  }

  const initialStdout = ''
  const initialStderr = ''

  try {
    const childProcess = spawnAndTrack(shell, [...shellArgs, command], {
      cwd,
      env: { ...process.env, FORCE_COLOR: '1' },
      // Ensure detached is always false to link child lifetime to parent
      detached: false,
      stdio: 'pipe',
    })

    // An error should have been thrown when we called `spawn`
    assert(
      childProcess.pid !== undefined,
      'Failed to spawn process: no PID assigned.',
    )

    const processId = childProcess.pid
    const processInfo: BackgroundProcessInfo = {
      pid: processId,
      toolCallId,
      command,
      process: childProcess,
      stdoutBuffer: [],
      stderrBuffer: [],
      status: 'running',
      startTime: Date.now(),
      endTime: null,
      lastReportedStdoutLength: 0,
      lastReportedStderrLength: 0,
      lastReportedStatus: null,
      stdoutFile,
      stderrFile,
    }
    backgroundProcesses.set(processId, processInfo)

    // Set up file streams if paths are provided
    let stdoutStream: WriteStream | undefined
    let stderrStream: WriteStream | undefined

    if (stdoutFile) {
      const stdoutAbs = path.isAbsolute(stdoutFile)
        ? stdoutFile
        : path.join(cwd, stdoutFile)
      mkdirSync(dirname(stdoutAbs), { recursive: true })
      stdoutStream = createWriteStream(stdoutAbs)
    }

    const realStderrFile = stderrFile || stdoutFile
    if (realStderrFile) {
      const stderrAbs = path.isAbsolute(realStderrFile)
        ? realStderrFile
        : path.join(cwd, realStderrFile)
      mkdirSync(dirname(stderrAbs), { recursive: true })
      stderrStream = createWriteStream(stderrAbs)
    }

    childProcess.stdout.on('data', (data: Buffer) => {
      const output = stripColors(data.toString())
      processInfo.stdoutBuffer.push(output)

      // Write to file if stream exists
      if (stdoutStream) {
        stdoutStream.write(output)
      }
    })

    childProcess.stderr.on('data', (data: Buffer) => {
      const output = stripColors(data.toString())
      processInfo.stderrBuffer.push(output)

      // Write to file if stream exists
      if (stderrStream) {
        stderrStream.write(output)
      }
    })

    childProcess.on('error', (error) => {
      processInfo.status = 'error'
      processInfo.stderrBuffer.push(
        `\nError spawning command: ${error.message}`,
      )
      processInfo.endTime = Date.now()

      // Close file streams
      stdoutStream?.end()
      stderrStream?.end()
    })

    let exitCode = null

    childProcess.on('close', (code) => {
      exitCode = code
      processInfo.status = code === 0 ? 'completed' : 'error'
      processInfo.endTime = Date.now()

      // Close file streams
      stdoutStream?.end()
      stderrStream?.end()
    })

    // Unreference the process so the parent can exit independently IF the child is the only thing keeping it alive.
    childProcess.unref()

    const resultMessage = `<background_process>
<process_id>${processId}${closeXml('process_id')}
<command>${command}${closeXml('command')}
<status>${processInfo.status}${closeXml('status')}
${closeXml('background_process')}`
    resolveCommand({
      result: resultMessage,
      stdout: initialStdout + initialStderr,
      exitCode,
    })
  } catch (error: any) {
    const errorMessage = `<background_process>\n<command>${command}${closeXml('command')}\n<error>${error.message}${closeXml('error')}\n${closeXml('background_process')}`
    resolveCommand({
      result: errorMessage,
      stdout: error.message,
      exitCode: null,
    })
  }
}

import * as fs from 'fs'

import { cyan, green } from 'picocolors'

import { getAllTsFiles, getAgentsDirectory } from './agent-utils'

import type { CodebuffConfig } from '@codebuff/common/json-config/constants'

export let loadedAgents: Record<string, any> = {}
export async function loadLocalAgents({
  verbose = false,
}: {
  verbose?: boolean
}): Promise<typeof loadedAgents> {
  loadedAgents = {}

  const agentsDir = getAgentsDirectory()

  if (!fs.existsSync(agentsDir)) {
    return loadedAgents
  }

  try {
    const tsFiles = getAllTsFiles(agentsDir)

    for (const fullPath of tsFiles) {
      let agentDefinition: any
      let agentModule: any
      try {
        agentModule = await require(fullPath)
      } catch (error: any) {
        if (verbose) {
          console.error(
            `Error importing agent: ${error.name} - ${error.message}\n${error.stack}`,
            fullPath,
          )
        }
        continue
      }
      delete require.cache[fullPath]

      try {
        agentDefinition = agentModule.default
      } catch (error: any) {
        const errorMessage =
          error instanceof Error
            ? error.stack || error.message
            : typeof error === 'string'
              ? error
              : JSON.stringify(error)
        console.error('Error loading agent from file:', fullPath, errorMessage)
        continue
      }

      if (!agentDefinition) continue

      // Validate that agent has required attributes
      if (!agentDefinition.id || !agentDefinition.model) {
        if (verbose) {
          console.error(
            'Agent definition missing required attributes (id, model):',
            fullPath,
            'Found:',
            { id: agentDefinition.id, model: agentDefinition.model },
          )
        }
        continue
      }

      // Convert handleSteps function to string if present
      let processedAgentDefinition = { ...agentDefinition }

      if (agentDefinition.handleSteps) {
        processedAgentDefinition.handleSteps =
          agentDefinition.handleSteps.toString()
      }

      loadedAgents[processedAgentDefinition.id] = processedAgentDefinition
    }
  } catch (error) {}
  return loadedAgents
}

export function getLoadedAgentNames(): Record<string, string> {
  return Object.fromEntries(
    Object.entries(loadedAgents).map(([agentType, agentConfig]) => {
      return [agentType, agentConfig.displayName]
    }),
  )
}

/**
 * Display loaded agents to the user
 */
export function displayLoadedAgents(codebuffConfig: CodebuffConfig) {
  const baseAgent = codebuffConfig.baseAgent
  if (baseAgent) {
    console.log(`\n${green('Configured base agent:')} ${cyan(baseAgent)}`)
  }

  const spawnableAgents = codebuffConfig.spawnableAgents
  if (spawnableAgents) {
    console.log(
      `${green('Configured spawnable agents:')} ${spawnableAgents
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (Object.keys(loadedAgents).length > 0) {
    const loadedAgentNames = Object.values(getLoadedAgentNames())
    console.log(
      `\n${green('Found custom agents:')} ${loadedAgentNames
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (baseAgent) {
    // One more new line.
    console.log()
  }
}

import { execFileSync } from 'child_process'
import { createHash } from 'crypto'
import fs from 'fs'
import os from 'os'
import path, { join } from 'path'

import { buildArray } from '@codebuff/common/util/array'

import { getProjectDataDir } from '../project-files'
import { gitCommandIsAvailable } from '../utils/git'
import { logger } from '../utils/logger'

// Dynamic import for isomorphic-git
async function getIsomorphicGit() {
  const git = await import('isomorphic-git')
  return git
}

const maxBuffer = 50 * 1024 * 1024 // 50 MB

/**
 * Generates a unique path for storing the bare git repository based on the project directory.
 * Uses SHA-256 hashing to create a unique identifier.
 * @param dir - The project directory path to hash
 * @returns The full path where the bare repo should be stored
 */
export function getBareRepoPath(dir: string): string {
  const bareRepoName = createHash('sha256').update(dir).digest('hex')
  return join(getProjectDataDir(), bareRepoName)
}

let nestedRepos: string[] = []
function exposeSubmodules({
  bareRepoPath,
  projectDir,
}: {
  bareRepoPath: string
  projectDir: string
}): void {
  while (true) {
    const submodulesOutput = execFileSync(
      'git',
      [
        '-c',
        'core.untrackedCache=false',
        '--git-dir',
        bareRepoPath,
        '--work-tree',
        projectDir,
        '-C',
        projectDir,
        'ls-files',
        '--stage',
        '--',
        '.',
        ':(exclude)**/*.codebuffbackup',
        ':(exclude)**/*.codebuffbackup/**',
      ],
      { stdio: ['ignore', 'pipe', 'inherit'], maxBuffer },
    ).toString()
    const submodules = buildArray(
      submodulesOutput
        .split('\n')
        .filter((line) => line.startsWith('160000'))
        .map((line) => line.split('\t')[1]),
    )

    if (submodules.length === 0) {
      return
    }

    for (const submodule of submodules) {
      try {
        if (!fs.existsSync(path.join(projectDir, submodule, '.git'))) {
          continue
        }
        fs.renameSync(
          path.join(projectDir, submodule, '.git'),
          path.join(projectDir, submodule, '.git.codebuffbackup'),
        )
        nestedRepos.push(submodule)
      } catch (error) {
        logger.error(
          {
            error,
            nestedRepo: submodule,
          },
          'Failed to backup .git directory for nested repo for checking status',
        )
      }
    }

    try {
      execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          '-C',
          projectDir,
          'rm',
          '-f',
          '--cached',
          ...submodules,
        ],
        { stdio: 'ignore', maxBuffer },
      )
    } catch (error) {
      logger.error(
        { error },
        'Error running git rm --cached while exposing submodules',
      )
    }
  }
}

function restoreSubmodules({ projectDir }: { projectDir: string }) {
  for (const nestedRepo of nestedRepos) {
    const codebuffBackup = path.join(
      projectDir,
      nestedRepo,
      '.git.codebuffbackup',
    )
    const gitDir = path.join(projectDir, nestedRepo, '.git')
    try {
      fs.renameSync(codebuffBackup, gitDir)
    } catch (error) {
      console.error(
        `Failed to restore .git directory for nested repo. Please rename ${codebuffBackup} to ${gitDir}\n${JSON.stringify({ error }, null, 2)}`,
      )
      logger.error(
        {
          error,
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          nestedRepo,
        },
        'Failed to restore .git directory for nested repo',
      )
    }
  }
  nestedRepos = []
}

/**
 * Checks if there are any uncommitted changes in the working directory.
 * First attempts to use native git commands, falling back to isomorphic-git if unavailable.
 * @param projectDir - The working tree directory path
 * @param bareRepoPath - The bare git repository path
 * @param relativeFilepaths - Array of file paths relative to projectDir to check
 * @returns Promise resolving to true if there are uncommitted changes, false otherwise
 */
export async function hasUnsavedChanges({
  projectDir,
  bareRepoPath,
  relativeFilepaths,
}: {
  projectDir: string
  bareRepoPath: string
  relativeFilepaths: Array<string>
}): Promise<boolean> {
  if (!gitCommandIsAvailable()) {
    return false
  }

  try {
    exposeSubmodules({ bareRepoPath, projectDir })

    try {
      const output = execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          '-C',
          projectDir,
          'status',
          '--porcelain',
          '--',
          '.',
          ':(exclude)**/*.codebuffbackup',
          ':(exclude)**/*.codebuffbackup/**',
        ],
        { stdio: ['ignore', 'pipe', 'ignore'], maxBuffer },
      ).toString()
      return !!output
    } catch (error) {
      logger.error(
        {
          error,
          projectDir,
          bareRepoPath,
        },
        'Error running git status for unsaved changes check',
      )
      return false
    }
  } finally {
    restoreSubmodules({ projectDir })
  }
}

/**
 * Gets the hash of the latest commit in the repository.
 * First attempts to use native git commands, falling back to isomorphic-git if unavailable.
 * @param bareRepoPath - The bare git repository path
 * @returns Promise resolving to the commit hash
 */
export async function getLatestCommit({
  bareRepoPath,
}: {
  bareRepoPath: string
}): Promise<string> {
  if (gitCommandIsAvailable()) {
    try {
      return execFileSync(
        'git',
        ['--git-dir', bareRepoPath, 'rev-parse', 'HEAD'],
        { stdio: ['ignore', 'pipe', 'ignore'], maxBuffer },
      )
        .toString()
        .trim()
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          bareRepoPath,
        },
        'Error getting latest commit with git command',
      )
    }
  }
  const { resolveRef } = await getIsomorphicGit()
  return await resolveRef({
    fs,
    gitdir: bareRepoPath,
    ref: 'HEAD',
  })
}

/**
 * Initializes a bare git repository for tracking file changes.
 * Creates the repository if it doesn't exist, otherwise uses the existing one.
 * Makes an initial commit of the current file state.
 * @param projectDir - The working tree directory path
 * @param relativeFilepaths - Array of file paths relative to projectDir to track
 */
export async function initializeCheckpointFileManager({
  projectDir,
  relativeFilepaths,
}: {
  projectDir: string
  relativeFilepaths: Array<string>
}): Promise<void> {
  if (projectDir === os.homedir()) {
    return
  }
  const bareRepoPath = getBareRepoPath(projectDir)

  // Create the bare repo directory if it doesn't exist
  fs.mkdirSync(bareRepoPath, { recursive: true })

  const { resolveRef, init } = await getIsomorphicGit()
  try {
    // Check if it's already a valid Git repo
    await resolveRef({ fs, gitdir: bareRepoPath, ref: 'HEAD' })
  } catch (error) {
    // Bare repo doesn't exist yet
    await init({
      fs,
      dir: projectDir,
      gitdir: bareRepoPath,
      bare: true,
      defaultBranch: 'master',
    })
  }

  // Commit the files in the bare repo
  await storeFileState({
    projectDir,
    bareRepoPath,
    message: 'Initial Commit',
    relativeFilepaths,
  })
}

/**
 * Stages all changes in the working directory.
 * First attempts to use native git commands, falling back to isomorphic-git if unavailable.
 * @param projectDir - The working tree directory path
 * @param bareRepoPath - The bare git repository path
 * @param relativeFilepaths - Array of file paths relative to projectDir to stage
 */
async function gitAddAll({
  projectDir,
  bareRepoPath,
  relativeFilepaths,
}: {
  projectDir: string
  bareRepoPath: string
  relativeFilepaths: Array<string>
}): Promise<void> {
  if (gitCommandIsAvailable()) {
    try {
      execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          '-C',
          projectDir,
          'add',
          '.',
          ':!**/*.codebuffbackup',
          ':!**/*.codebuffbackup/**',
        ],
        { stdio: 'ignore', maxBuffer },
      )
      return
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          projectDir,
          bareRepoPath,
        },
        'Failed to git add all files',
      )
    }
  }

  // Stage files with isomorphic-git
  const { statusMatrix, add, remove } = await getIsomorphicGit()

  // Get status of all files in the project directory
  const currStatusMatrix =
    (await statusMatrix({
      fs,
      dir: projectDir,
      gitdir: bareRepoPath,
      filepaths: relativeFilepaths,
    })) ?? []

  for (const [filepath, , workdirStatus, stageStatus] of currStatusMatrix) {
    if (workdirStatus === stageStatus) {
      continue
    }

    if (workdirStatus === 2) {
      // Existing file different from HEAD
      try {
        await add({ fs, dir: projectDir, gitdir: bareRepoPath, filepath })
      } catch (error) {
        logger.error(
          {
            errorMessage:
              error instanceof Error ? error.message : String(error),
            errorStack: error instanceof Error ? error.stack : undefined,
            filepath,
            projectDir,
            bareRepoPath,
          },
          'Error adding file to git',
        )
      }
    } else if (workdirStatus === 0) {
      // Deleted file
      try {
        await remove({ fs, dir: projectDir, gitdir: bareRepoPath, filepath })
      } catch (error) {
        logger.error(
          {
            errorMessage:
              error instanceof Error ? error.message : String(error),
            errorStack: error instanceof Error ? error.stack : undefined,
            filepath,
            projectDir,
            bareRepoPath,
          },
          'Error removing file from git',
        )
      }
    }
  }
}

async function gitAddAllIgnoringNestedRepos({
  projectDir,
  bareRepoPath,
  relativeFilepaths,
}: {
  projectDir: string
  bareRepoPath: string
  relativeFilepaths: Array<string>
}): Promise<void> {
  const nestedRepos: string[] = []
  try {
    exposeSubmodules({ bareRepoPath, projectDir })
    let output: string
    try {
      output = execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          'status',
          '--porcelain',
        ],
        { stdio: ['ignore', 'pipe', 'ignore'], maxBuffer },
      ).toString()
    } catch (error) {
      logger.error(
        { error, projectDir, bareRepoPath },
        'Failed to get git status while finding nested git repos',
      )
      return
    }

    if (!output) {
      return
    }

    const modifiedFiles = buildArray(output.split('\n'))
      .filter((line) => line[1] === 'M' || line[1] === '?' || line[1] === 'D')
      .map((line) => line.slice(3).trim())

    if (modifiedFiles.length === 0) {
      return
    }

    try {
      execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          '-C',
          projectDir,
          'rm',
          '--cached',
          '-rf',
          ...modifiedFiles,
        ],
        { stdio: 'ignore', maxBuffer },
      )
    } catch (error) {
      logger.error({ error }, 'Failed to run git rm --cached')
    }

    await gitAddAll({ projectDir, bareRepoPath, relativeFilepaths })
  } finally {
    restoreSubmodules({ projectDir })
  }
}

async function gitCommit({
  projectDir,
  bareRepoPath,
  message,
}: {
  projectDir: string
  bareRepoPath: string
  message: string
}): Promise<string> {
  if (gitCommandIsAvailable()) {
    try {
      execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          'commit',
          '-m',
          message,
        ],
        { stdio: 'ignore', maxBuffer },
      )
      return await getLatestCommit({ bareRepoPath })
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          projectDir,
          bareRepoPath,
          message,
        },
        'Failed to commit with git command, falling back to isomorphic-git',
      )
    }
  }

  const { commit, checkout } = await getIsomorphicGit()
  const commitHash: string = await commit({
    fs,
    dir: projectDir,
    gitdir: bareRepoPath,
    author: { name: 'Codebuff' },
    message,
    ref: '/refs/heads/master',
  })

  if (gitCommandIsAvailable()) {
    try {
      execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          'checkout',
          'master',
        ],
        { stdio: 'ignore', maxBuffer },
      )
      return commitHash
    } catch (error) {
      logger.error(
        {
          error,
          projectDir,
          bareRepoPath,
        },
        'Unable to checkout with git command',
      )
    }
  }

  await checkout({ fs, dir: projectDir, gitdir: bareRepoPath, ref: 'master' })

  return commitHash
}

/**
 * Creates a new commit with the current state of all tracked files.
 * Stages all changes and creates a commit with the specified message.
 * @param projectDir - The working tree directory path
 * @param bareRepoPath - The bare git repository path
 * @param message - The commit message
 * @param relativeFilepaths - Array of file paths relative to projectDir to commit
 * @returns Promise resolving to the new commit's hash
 */
export async function storeFileState({
  projectDir,
  bareRepoPath,
  message,
  relativeFilepaths: relativeFilepaths,
}: {
  projectDir: string
  bareRepoPath: string
  message: string
  relativeFilepaths: Array<string>
}): Promise<string> {
  await gitAddAllIgnoringNestedRepos({
    projectDir,
    bareRepoPath,
    relativeFilepaths,
  })

  return await gitCommit({ projectDir, bareRepoPath, message })
}

/**
 * Restores the working directory and index to match the specified commit.
 * Equivalent to `git reset --hard`
 * First attempts to use native git commands, falling back to isomorphic-git if unavailable.
 * @param projectDir - The working tree directory path
 * @param bareRepoPath - The bare git repository path
 * @param commit - The commit hash to restore to
 * @param relativeFilepaths - Array of file paths relative to projectDir to restore
 */
export async function restoreFileState({
  projectDir,
  bareRepoPath,
  commit,
  relativeFilepaths,
}: {
  projectDir: string
  bareRepoPath: string
  commit: string
  relativeFilepaths: Array<string>
}): Promise<void> {
  let resetDone = false
  if (gitCommandIsAvailable()) {
    try {
      execFileSync(
        'git',
        [
          '--git-dir',
          bareRepoPath,
          '--work-tree',
          projectDir,
          'reset',
          '--hard',
          commit,
        ],
        { maxBuffer },
      )
      return
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          projectDir,
          bareRepoPath,
          commit,
        },
        'Failed to use git reset, falling back to isomorphic-git',
      )
    }
  }

  const { checkout, resetIndex } = await getIsomorphicGit()
  // Update the working directory to reflect the specified commit
  await checkout({
    fs,
    dir: projectDir,
    gitdir: bareRepoPath,
    ref: commit,
    filepaths: relativeFilepaths,
    force: true,
  })

  // Reset the index to match the specified commit
  await Promise.all(
    relativeFilepaths.map((filepath) =>
      resetIndex({
        fs,
        dir: projectDir,
        gitdir: bareRepoPath,
        filepath,
        ref: commit,
      }),
    ),
  )
}

// Export fs for testing
export { fs }

// Modified from: https://github.com/andsmedeiros/hw-fingerprint

import { createHash, randomBytes } from 'node:crypto'
import { EOL, endianness } from 'node:os'

import {
  system,
  bios,
  baseboard,
  cpu,
  osInfo,
  // @ts-ignore
} from 'systeminformation'

const getFingerprintInfo = async () => {
  const { manufacturer, model, serial, uuid } = await system()
  const { vendor, version: biosVersion, releaseDate } = await bios()
  const {
    manufacturer: boardManufacturer,
    model: boardModel,
    serial: boardSerial,
  } = await baseboard()
  const {
    manufacturer: cpuManufacturer,
    brand,
    speedMax,
    cores,
    physicalCores,
    socket,
  } = await cpu()
  const { platform, arch } = await osInfo()

  return {
    EOL,
    endianness: endianness(),
    manufacturer,
    model,
    serial,
    uuid,
    vendor,
    biosVersion,
    releaseDate,
    boardManufacturer,
    boardModel,
    boardSerial,
    cpuManufacturer,
    brand,
    speedMax: speedMax.toFixed(2),
    cores,
    physicalCores,
    socket,
    platform,
    arch,
  } as Record<string, any>
}
export async function calculateFingerprint() {
  const fingerprintInfo = await getFingerprintInfo()
  const fingerprintString = JSON.stringify(fingerprintInfo)
  const fingerprintHash = createHash('sha256')
    .update(fingerprintString)
    .digest()
    .toString('base64url')

  // Add 8 random characters to make the fingerprint unique even on identical hardware
  const randomSuffix = randomBytes(6).toString('base64url').substring(0, 8)

  return `${fingerprintHash}-${randomSuffix}`
}

## Tools
Use the tools below to complete the user request, if applicable.

Tool calls use a specific XML and JSON-like format. Adhere *precisely* to this nested element structure:

<codebuff_tool_call>
