import { z } from 'zod/v4'

import { ALLOWED_MODEL_PREFIXES, models } from '../constants'
import { toolNames } from '../tools/constants'

import type { JSONSchema } from 'zod/v4/core'

// Filter models to only include those that begin with allowed prefixes
const filteredModels = Object.values(models).filter((model) =>
  ALLOWED_MODEL_PREFIXES.some((prefix) => model.startsWith(prefix)),
)

if (filteredModels.length === 0) {
  throw new Error('No valid models found with allowed prefixes')
}

// Simplified JSON Schema definition - supports object schemas with nested properties
const JsonSchemaSchema: z.ZodType<
  JSONSchema.BaseSchema,
  JSONSchema.BaseSchema
> = z.lazy(() =>
  z.looseObject({
    type: z
      .enum([
        'object',
        'array',
        'string',
        'number',
        'boolean',
        'null',
        'integer',
      ])
      .optional(),
    description: z.string().optional(),
    properties: z
      .record(z.string(), JsonSchemaSchema.or(z.boolean()))
      .optional(),
    required: z.string().array().optional(),
    enum: z
      .union([z.string(), z.number(), z.boolean(), z.null()])
      .array()
      .optional(),
  }),
)
const JsonObjectSchemaSchema = z.intersection(
  JsonSchemaSchema,
  z.object({ type: z.literal('object') }),
)

// Schema for the combined inputSchema object
const InputSchemaObjectSchema = z
  .looseObject({
    prompt: z
      .looseObject({
        type: z.literal('string'),
        description: z.string().optional(),
      })
      .optional(), // Optional JSON schema for prompt validation
    params: JsonObjectSchemaSchema.optional(), // Optional JSON schema for params validation
  })
  .optional()

// Schema for prompt fields that can be either a string or a path reference
const PromptFieldSchema = z.union([
  z.string(), // Direct string content
  z.object({ path: z.string() }), // Path reference to external file
])
export type PromptField = z.infer<typeof PromptFieldSchema>

const functionSchema = <T extends z.core.$ZodFunction>(schema: T) =>
  z.custom<Parameters<T['implement']>[0]>((fn: any) => schema.implement(fn))
// Schema for validating handleSteps function signature
const HandleStepsSchema = functionSchema(
  z.function({
    input: [
      z.object({
        agentState: z.object({
          agentId: z.string(),
          parentId: z.string(),
          messageHistory: z.array(z.any()),
        }),
        prompt: z.string().optional(),
        params: z.any().optional(),
      }),
    ],
    output: z.any(),
  }),
).optional()

// Validates the Typescript template file.
export const DynamicAgentDefinitionSchema = z.object({
  id: z
    .string()
    .regex(
      /^[a-z0-9-]+$/,
      'Agent ID must contain only lowercase letters, numbers, and hyphens',
    ), // The unique identifier for this agent
  version: z.string().optional(),
  publisher: z.string().optional(),

  // Required fields for new agents
  displayName: z.string(),
  model: z.string(),

  // Tools and spawnable agents
  toolNames: z.array(z.enum(toolNames)).optional().default([]),
  spawnableAgents: z.array(z.string()).optional().default([]),

  // Input and output
  inputSchema: InputSchemaObjectSchema,
  includeMessageHistory: z.boolean().default(false),
  outputMode: z
    .enum(['last_message', 'all_messages', 'structured_output'])
    .default('last_message'),
  outputSchema: JsonObjectSchemaSchema.optional(), // Optional JSON schema for output validation

  // Prompts
  spawnerPrompt: z.string().optional(),
  systemPrompt: z.string().optional(),
  instructionsPrompt: z.string().optional(),
  stepPrompt: z.string().optional(),

  // Optional generator function for programmatic agents
  handleSteps: z.union([z.string(), HandleStepsSchema]).optional(),
})
export type DynamicAgentDefinition = z.input<
  typeof DynamicAgentDefinitionSchema
>
export type DynamicAgentDefinitionParsed = z.infer<
  typeof DynamicAgentDefinitionSchema
>

export const DynamicAgentTemplateSchema = DynamicAgentDefinitionSchema.extend({
  systemPrompt: z.string(),
  instructionsPrompt: z.string(),
  stepPrompt: z.string(),
  handleSteps: z.string().optional(), // Converted to string after processing
})
  .refine(
    (data) => {
      // If outputSchema is provided, outputMode must be explicitly set to 'structured_output'
      if (data.outputSchema && data.outputMode !== 'structured_output') {
        return false
      }
      return true
    },
    {
      message:
        "outputSchema requires outputMode to be explicitly set to 'structured_output'.",
      path: ['outputMode'],
    },
  )
  .refine(
    (data) => {
      // If outputMode is 'structured_output', 'set_output' tool must be included
      if (
        data.outputMode === 'structured_output' &&
        !data.toolNames.includes('set_output')
      ) {
        return false
      }
      return true
    },
    {
      message:
        "outputMode 'structured_output' requires the 'set_output' tool. Add 'set_output' to toolNames.",
      path: ['toolNames'],
    },
  )
  .refine(
    (data) => {
      // If 'set_output' tool is included, outputMode must be 'structured_output'
      if (
        data.toolNames.includes('set_output') &&
        data.outputMode !== 'structured_output'
      ) {
        return false
      }
      return true
    },
    {
      message:
        "'set_output' tool requires outputMode to be 'structured_output'. Change outputMode to 'structured_output' or remove 'set_output' from toolNames.",
      path: ['outputMode'],
    },
  )
  .refine(
    (data) => {
      // If spawnableAgents array is non-empty, 'spawn_agents' tool must be included
      if (
        data.spawnableAgents.length > 0 &&
        !data.toolNames.includes('spawn_agents')
      ) {
        return false
      }
      return true
    },
    {
      message:
        "Non-empty spawnableAgents array requires the 'spawn_agents' tool. Add 'spawn_agents' to toolNames or remove spawnableAgents.",
      path: ['toolNames'],
    },
  )
export type DynamicAgentTemplate = z.infer<typeof DynamicAgentTemplateSchema>

import * as fs from 'fs'

import { cyan, green } from 'picocolors'

import { getAllTsFiles, getAgentsDirectory } from './agent-utils'

import type { CodebuffConfig } from '@codebuff/common/json-config/constants'

export let loadedAgents: Record<string, any> = {}
export async function loadLocalAgents({
  verbose = false,
}: {
  verbose?: boolean
}): Promise<typeof loadedAgents> {
  loadedAgents = {}

  const agentsDir = getAgentsDirectory()

  if (!fs.existsSync(agentsDir)) {
    return loadedAgents
  }

  try {
    const tsFiles = getAllTsFiles(agentsDir)

    for (const fullPath of tsFiles) {
      let agentDefinition: any
      let agentModule: any
      try {
        agentModule = await require(fullPath)
      } catch (error: any) {
        if (verbose) {
          console.error(
            `Error importing agent: ${error.name} - ${error.message}\n${error.stack}`,
            fullPath,
          )
        }
        continue
      }
      delete require.cache[fullPath]

      try {
        agentDefinition = agentModule.default
      } catch (error: any) {
        const errorMessage =
          error instanceof Error
            ? error.stack || error.message
            : typeof error === 'string'
              ? error
              : JSON.stringify(error)
        console.error('Error loading agent from file:', fullPath, errorMessage)
        continue
      }

      if (!agentDefinition) continue

      // Validate that agent has required attributes
      if (!agentDefinition.id || !agentDefinition.model) {
        if (verbose) {
          console.error(
            'Agent definition missing required attributes (id, model):',
            fullPath,
            'Found:',
            { id: agentDefinition.id, model: agentDefinition.model },
          )
        }
        continue
      }

      // Convert handleSteps function to string if present
      let processedAgentDefinition = { ...agentDefinition }

      if (agentDefinition.handleSteps) {
        processedAgentDefinition.handleSteps =
          agentDefinition.handleSteps.toString()
      }

      loadedAgents[processedAgentDefinition.id] = processedAgentDefinition
    }
  } catch (error) {}
  return loadedAgents
}

export function getLoadedAgentNames(): Record<string, string> {
  return Object.fromEntries(
    Object.entries(loadedAgents).map(([agentType, agentConfig]) => {
      return [agentType, agentConfig.displayName]
    }),
  )
}

/**
 * Display loaded agents to the user
 */
export function displayLoadedAgents(codebuffConfig: CodebuffConfig) {
  const baseAgent = codebuffConfig.baseAgent
  if (baseAgent) {
    console.log(`\n${green('Configured base agent:')} ${cyan(baseAgent)}`)
  }

  const spawnableAgents = codebuffConfig.spawnableAgents
  if (spawnableAgents) {
    console.log(
      `${green('Configured spawnable agents:')} ${spawnableAgents
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (Object.keys(loadedAgents).length > 0) {
    const loadedAgentNames = Object.values(getLoadedAgentNames())
    console.log(
      `\n${green('Found custom agents:')} ${loadedAgentNames
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (baseAgent) {
    // One more new line.
    console.log()
  }
}

import { AGENT_TEMPLATES_DIR } from '@codebuff/common/constants'
import { AgentTemplateTypes } from '@codebuff/common/types/session-state'
import { green, gray, red } from 'picocolors'

import { enterMiniChat } from './mini-chat'
import { CLI } from '../cli'

interface AgentRequirements {
  name: string
  purpose: string
  specialty: string
  model: string
}

const AGENT_CREATION_STEPS = [
  {
    question:
      "Hi! I'll help you create a custom agent. What would you like to name your agent?",
    field: 'name',
    placeholder: 'e.g., "Code Reviewer", "API Helper", "Test Generator"',
  },
  {
    question:
      "Great! What's the main purpose of this agent? What should it help you with?",
    field: 'purpose',
    placeholder:
      'e.g., "Review code for best practices", "Help with API integration"',
  },
  {
    question: "What's this agent's specialty or domain expertise?",
    field: 'specialty',
    placeholder:
      'e.g., "React development", "Database optimization", "Security auditing"',
  },
  {
    question:
      'Which model should this agent use? (Press Enter for default: anthropic/claude-4-sonnet-20250522)',
    field: 'model',
    placeholder:
      'anthropic/claude-4-sonnet-20250522, gpt-4o, gemini-2.0-flash-exp',
    defaultValue: 'anthropic/claude-4-sonnet-20250522',
  },
]

export function startAgentCreationChat(
  rl: any,
  onExit: () => void,
  onComplete: (requirements: AgentRequirements) => void,
) {
  enterMiniChat(rl, onExit, {
    title: '🤖 Agent Creation Assistant',
    steps: AGENT_CREATION_STEPS,
    onComplete: async (responses) => {
      const requirements: AgentRequirements = {
        name: responses.name || 'My Custom Agent',
        purpose:
          responses.purpose ||
          'A custom agent that helps with development tasks',
        specialty: responses.specialty || 'general development',
        model: responses.model || 'anthropic/claude-4-sonnet-20250522',
      }

      try {
        await createAgentFromRequirements(requirements)
      } catch (error) {
        console.error(red('\nError creating agent:'))
        console.error(error instanceof Error ? error.message : String(error))
        onExit() // Only exit on error
      }
    },
  })
}

export async function createAgentFromRequirements(
  requirements: AgentRequirements,
) {
  // Create a simple prompt for the agent builder with the requirements
  const prompt = `Create a new agent template with these requirements:

Agent Name: ${requirements.name}
Purpose: ${requirements.purpose}
Specialty: ${requirements.specialty}
Model: ${requirements.model}

Please create a complete TypeScript agent template file in the ${AGENT_TEMPLATES_DIR} directory with proper types and a comprehensive system prompt.`

  try {
    // Use the resetAgent helper to properly switch to agent-builder which automatically spawns the agent builder
    const cliInstance = CLI.getInstance()
    await cliInstance.resetAgent(
      AgentTemplateTypes.agent_builder,
      {
        name: requirements.name,
        purpose: requirements.purpose,
        specialty: requirements.specialty,
        model: requirements.model,
      },
      prompt,
    )

    console.log(
      green(
        `\n✅ Agent created! Check the ${AGENT_TEMPLATES_DIR} directory for your new agent.`,
      ),
    )
    console.log(
      gray(
        'Continue adjusting your agent here, or type "/agents" to switch agents and test it out.',
      ),
    )

    cliInstance.freshPrompt()
  } catch (error) {
    console.error(red('\nError during agent creation:'))
    console.error(
      'Error message:',
      error instanceof Error ? error.message : String(error),
    )
    throw error
  }
}

/**
 * Codebuff Agent Type Definitions
 *
 * This file provides TypeScript type definitions for creating custom Codebuff agents.
 * Import these types in your agent files to get full type safety and IntelliSense.
 *
 * Usage in .agents/your-agent.ts:
 *   import { AgentDefinition, ToolName, ModelName } from './types/agent-definition'
 *
 *   const definition: AgentDefinition = {
 *     // ... your agent configuration with full type safety ...
 *   }
 *
 *   export default definition
 */

// ============================================================================
// Agent Definition and Utility Types
// ============================================================================

export interface AgentDefinition {
  /** Unique identifier for this agent. Must contain only lowercase letters, numbers, and hyphens, e.g. 'code-reviewer' */
  id: string

  /** Version string (if not provided, will default to '0.0.1' and be bumped on each publish) */
  version?: string

  /** Publisher ID for the agent. Must be provided if you want to publish the agent. */
  publisher?: string

  /** Human-readable name for the agent */
  displayName: string

  /** AI model to use for this agent. Can be any model in OpenRouter: https://openrouter.ai/models */
  model: ModelName

  // ============================================================================
  // Tools and Subagents
  // ============================================================================

  /** Tools this agent can use. */
  toolNames?: ToolName[]

  /** Other agents this agent can spawn, like 'codebuff/file-picker@0.0.1'.
   *
   * Use the fully qualified agent id from the agent store, including publisher and version: 'codebuff/file-picker@0.0.1'
   * (publisher and version are required!)
   *
   * Or, use the agent id from a local agent file in your .agents directory: 'file-picker'.
   */
  spawnableAgents?: string[]

  // ============================================================================
  // Input and Output
  // ============================================================================

  /** The input schema required to spawn the agent. Provide a prompt string and/or a params object or none.
   * 80% of the time you want just a prompt string with a description:
   * inputSchema: {
   *   prompt: { type: 'string', description: 'A description of what info would be helpful to the agent' }
   * }
   */
  inputSchema?: {
    prompt?: { type: 'string'; description?: string }
    params?: JsonObjectSchema
  }

  /** Whether to include conversation history from the parent agent in context.
   *
   * Defaults to false.
   * Use this if the agent needs to know all the previous messages in the conversation.
   */
  includeMessageHistory?: boolean

  /** How the agent should output a response to its parent (defaults to 'last_message')
   *
   * last_message: The last message from the agent, typcically after using tools.
   *
   * all_messages: All messages from the agent, including tool calls and results.
   *
   * json: Make the agent output a JSON object. Can be used with outputSchema or without if you want freeform json output.
   */
  outputMode?: 'last_message' | 'all_messages' | 'structured_output'

  /** JSON schema for structured output (when outputMode is 'structured_output') */
  outputSchema?: JsonObjectSchema

  // ============================================================================
  // Prompts
  // ============================================================================

  /** Prompt for when and why to spawn this agent. Include the main purpose and use cases.
   *
   * This field is key if the agent is intended to be spawned by other agents. */
  spawnerPrompt?: string

  /** Background information for the agent. Fairly optional. Prefer using instructionsPrompt for agent instructions. */
  systemPrompt?: string

  /** Instructions for the agent.
   *
   * IMPORTANT: Updating this prompt is the best way to shape the agent's behavior.
   * This prompt is inserted after each user input. */
  instructionsPrompt?: string

  /** Prompt inserted at each agent step.
   *
   * Powerful for changing the agent's behavior, but usually not necessary for smart models.
   * Prefer instructionsPrompt for most instructions. */
  stepPrompt?: string

  // ============================================================================
  // Handle Steps
  // ============================================================================

  /** Programmatically step the agent forward and run tools.
   *
   * You can either yield:
   * - A tool call object with toolName and args properties.
   * - 'STEP' to run agent's model and generate one assistant message.
   * - 'STEP_ALL' to run the agent's model until it uses the end_turn tool or stops includes no tool calls in a message.
   *
   * Or use 'return' to end the turn.
   *
   * Example 1:
   * function* handleSteps({ agentStep, prompt, params}) {
   *   const { toolResult } = yield {
   *     toolName: 'read_files',
   *     args: { paths: ['file1.txt', 'file2.txt'] }
   *   }
   *   yield 'STEP_ALL'
   * }
   *
   * Example 2:
   * handleSteps: function* ({ agentState, prompt, params }) {
   *   while (true) {
   *     yield {
   *       toolName: 'spawn_agents',
   *       args: {
   *         agents: [
   *         {
   *           agent_type: 'thinker',
   *           prompt: 'Think deeply about the user request',
   *         },
   *       ],
   *     },
   *   }
   *   yield 'STEP'
   * }
   * }
   */
  handleSteps?: (
    context: AgentStepContext,
  ) => Generator<
    ToolCall | 'STEP' | 'STEP_ALL',
    void,
    { agentState: AgentState; toolResult: string | undefined }
  >
}

