  spawnableAgents: ['codebuff/file-picker@0.0.1'],
  inputSchema: {
    type: 'object',
    properties: {
      prompt: { type: 'string' },
      params: {
        type: 'object',
        properties: { prompts: { type: 'array', items: { type: 'string' }, minItems: 1, maxItems: 4 } },
        required: ['prompts']
      }
    },
    required: ['prompt', 'params']
  },
  outputMode: 'structured_output',
  outputSchema: {
    type: 'object',
    properties: { results: { type: 'string' } },
    required: ['results']
  },
  includeMessageHistory: false,
  handleSteps: async function* (input, tools, spawnAgent) {
    const { params: { prompts } } = input;
    const results = await Promise.all(
