import type { AgentDefinition } from '../types/agent-definition'

const definition: AgentDefinition = {
  id: 'git-committer',
  displayName: 'Intermediate Git Committer',
  model: 'anthropic/claude-4-sonnet-20250522',
  toolNames: ['read_files', 'run_terminal_command', 'add_message', 'end_turn'],
  inputSchema: {
    prompt: { type: 'string' },
  },
  systemPrompt: 'You are an expert software developer specializing in creating clear, concise git commit messages based on code changes.',
  handleSteps: async function* (context) {
    const { tools } = context as any

    const diff = await tools.run_terminal_command({ command: 'git diff' })
    const log = await tools.run_terminal_command({ command: 'git log --oneline -10' })

    await tools.add_message({ role: 'assistant', content: 'Based on the diff, I need to read the relevant files to understand the changes.' })
    yield { type: 'STEP' }

    await tools.add_message({ role: 'assistant', content: 'Now, with the file contents, I can create a good commit message.' })
    yield { type: 'STEP_ALL' }
  },
}

export default definition

