import type { AgentDefinition } from '../types/agent-definition'

const definition: AgentDefinition = {
  id: 'git-committer',
  displayName: 'Intermediate Git Committer',
  model: 'anthropic/claude-4-sonnet-20250522',
  toolNames: ['read_files', 'run_terminal_command', 'add_message', 'end_turn'],
  inputSchema: {
    type: 'object',
    properties: { prompt: { type: 'string', description: 'Describe the changes to commit' } },
    required: ['prompt'],
  },
  systemPrompt: 'You are an expert software developer specializing in creating clear, concise git commit messages based on code changes.',
  handleSteps: function* (context) {
    const { toolResult: diffResult } = yield { toolName: 'run_terminal_command', input: { command: 'git diff' } }
    const { toolResult: logResult } = yield { toolName: 'run_terminal_command', input: { command: 'git log --oneline -10' } }

    yield { toolName: 'add_message', input: { role: 'assistant', content: 'Based on the diff, I need to read the relevant files to understand the changes.' } }
    yield 'STEP'

    yield { toolName: 'add_message', input: { role: 'assistant', content: 'Now, with the file contents, I can create a good commit message.' } }
    yield 'STEP_ALL'
  },
}

export default definition

import type { AgentDefinition } from '../types/agent-definition'

const definition: AgentDefinition = {
  id: 'advanced-file-explorer',
  displayName: 'Dora the File Explorer',
  model: 'openai/gpt-5',
  toolNames: ['spawn_agents', 'set_output'],
  spawnableAgents: ['codebuff/file-picker@0.0.1'],
  inputSchema: {
    type: 'object',
    properties: {
      prompt: { type: 'string' },
      params: {
        type: 'object',
        properties: {
          prompts: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: 4,
          },
        },
        required: ['prompts'],
      },
    },
    required: ['prompt', 'params'],
  },
  outputMode: 'structured_output',
  outputSchema: {
    type: 'object',
    properties: {
      results: { type: 'string' },
    },
    required: ['results'],
  },
  includeMessageHistory: false,
  handleSteps: function* (context) {
    const { input } = context as any
    const { params: { prompts } } = input

    yield { 
      toolName: 'spawn_agents', 
      input: { 
        agents: prompts.map((p: string) => ({ 
          agent_type: 'codebuff/file-picker@0.0.1', 
          prompt: p 
        })) 
      } 
    }

    yield { toolName: 'set_output', input: { results: `File exploration completed for ${prompts.length} prompts` } }
  },
}

export default definition

