import { z } from 'zod'

import { CodebuffMessageSchema } from './message'
import { ProjectFileContextSchema } from '../util/file'

import type { CodebuffMessage } from './message'
import type { ProjectFileContext } from '../util/file'

export const toolCallSchema = z.object({
  toolName: z.string(),
  args: z.record(z.string(), z.any()),
  toolCallId: z.string(),
})
export type ToolCall = z.infer<typeof toolCallSchema>

export const toolResultSchema = z.object({
  toolName: z.string(),
  toolCallId: z.string(),
  result: z.string(),
})
export type ToolResult = z.infer<typeof toolResultSchema>

export const subgoalSchema = z.object({
  objective: z.string().optional(),
  status: z
    .enum(['NOT_STARTED', 'IN_PROGRESS', 'COMPLETE', 'ABORTED'])
    .optional(),
  plan: z.string().optional(),
  logs: z.string().array(),
})
export type Subgoal = z.infer<typeof subgoalSchema>

export const AgentStateSchema: z.ZodType<{
  agentId: string
  agentType: AgentTemplateType | null
  agentContext: Record<string, Subgoal>
  spawnableAgents: AgentState[]
  messageHistory: CodebuffMessage[]
  stepsRemaining: number
  output?: Record<string, any>
  parentId?: string
}> = z.lazy(() =>
  z.object({
    agentId: z.string(),
    agentType: z.string().nullable(),
    agentContext: z.record(z.string(), subgoalSchema),
    spawnableAgents: AgentStateSchema.array(),
    messageHistory: CodebuffMessageSchema.array(),
    stepsRemaining: z.number(),
    output: z.record(z.string(), z.any()).optional(),
    parentId: z.string().optional(),
  }),
)
export type AgentState = z.infer<typeof AgentStateSchema>

export const AgentTemplateTypeList = [
  // Base agents
  'base',
  'base_lite',
  'base_max',
  'base_experimental',
  'claude4_gemini_thinking',
  'superagent',
  'base_agent_builder',

  // Ask mode
  'ask',

  // Planning / Thinking
  'planner',
  'dry_run',
  'thinker',

  // Other agents
  'file_picker',
  'file_explorer',
  'researcher',
  'reviewer',
  'agent_builder',
  'example_programmatic',
] as const
type UnderscoreToDash<S extends string> = S extends `${infer L}_${infer R}`
  ? `${L}-${UnderscoreToDash<R>}` // recurse on the remainder
  : S
export const AgentTemplateTypes = Object.fromEntries(
  AgentTemplateTypeList.map((name) => [name, name.replaceAll('_', '-')]),
) as { [K in (typeof AgentTemplateTypeList)[number]]: UnderscoreToDash<K> }
const agentTemplateTypeSchema = z.enum(AgentTemplateTypeList)
// Allow dynamic agent types by extending the base enum with string
export type AgentTemplateType =
  | z.infer<typeof agentTemplateTypeSchema>
  | (string & {})

export const SessionStateSchema = z.object({
  fileContext: ProjectFileContextSchema,
  mainAgentState: AgentStateSchema,
})
export type SessionState = z.infer<typeof SessionStateSchema>

export function getInitialSessionState(
  fileContext: ProjectFileContext,
): SessionState {
  return {
    mainAgentState: {
      agentId: 'main-agent',
      agentType: null,
      agentContext: {},
      spawnableAgents: [],
      messageHistory: [],
      stepsRemaining: 12,
      output: undefined,
    },
    fileContext,
  }
}

import { schemaToJsonStr } from '@codebuff/common/util/zod-schema'
import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import type { AgentTemplateType } from '@codebuff/common/types/session-state'
import { getAgentTemplate } from './agent-registry'

export async function buildSpawnableAgentsDescription(
  spawnableAgents: AgentTemplateType[],
  agentTemplates: Record<string, AgentTemplate>,
): Promise<string> {
  if (spawnableAgents.length === 0) {
    return ''
  }

  const subAgentTypesAndTemplates = await Promise.all(
    spawnableAgents.map(async (agentType) => {
      return [
        agentType,
        await getAgentTemplate(agentType, agentTemplates),
      ] as const
    }),
  )

  const agentsDescription = subAgentTypesAndTemplates
    .map(([agentType, agentTemplate]) => {
      if (!agentTemplate) {
        // Fallback for unknown agents
        return `- ${agentType}: Dynamic agent (description not available)
prompt: {"description": "A coding task to complete", "type": "string"}
params: None`
      }
      const { inputSchema } = agentTemplate
      if (!inputSchema) {
        return `- ${agentType}: ${agentTemplate.parentPrompt}
prompt: None
params: None`
      }
      const { prompt, params } = inputSchema
      return `- ${agentType}: ${agentTemplate.parentPrompt}
prompt: ${schemaToJsonStr(prompt)}
params: ${schemaToJsonStr(params)}`
    })
    .filter(Boolean)
    .join('\n\n')

  return `\n\n## Spawnable Agents

Use the spawn_agents tool to spawn agents to help you complete the user request. Here are the available agents by their agent_type:

${agentsDescription}`
}

import { AgentTemplateTypes } from '../types/session-state'

export interface SubagentValidationResult {
  valid: boolean
  invalidAgents: string[]
}

/**
 * Centralized validation for spawnable agents.
 * Validates that all spawnable agents reference valid agent types.
 */
export function validateSpawnableAgents(
  spawnableAgents: string[],
  dynamicAgentIds: string[],
): SubagentValidationResult & { availableAgents: string[] } {
  // Build complete list of available agent types (normalized)
  const availableAgentTypes = [
    ...Object.values(AgentTemplateTypes),
    ...dynamicAgentIds,
  ]

  // Find invalid agents (those not in available types after normalization)
  const invalidAgents = spawnableAgents.filter(
    (agent, index) => !availableAgentTypes.includes(spawnableAgents[index]),
  )

  return {
    valid: invalidAgents.length === 0,
    invalidAgents,
    availableAgents: availableAgentTypes,
  }
}

/**
 * Formats a validation error message for spawnable agents
 */
export function formatSpawnableAgentError(
  invalidAgents: string[],
  availableAgents: string[],
): string {
  let message = `Invalid spawnable agents: ${invalidAgents.join(', ')}. Double check the id, including the org prefix if applicable.`

  message += `\n\nAvailable agents: ${availableAgents.join(', ')}`

  return message
}

/**
 * Formats validation errors into a user-friendly error message
 * @param validationErrors - Array of validation errors
 * @returns Formatted error message string or undefined if no errors
 */
export function formatValidationErrorMessage(
  validationErrors: Array<{ filePath: string; message: string }>,
): string | undefined {
  if (validationErrors.length === 0) return undefined

  return validationErrors
    .map((error) => `❌ ${error.filePath}: ${error.message}`)
    .join('\n')
}

