          mode: 'assistant' | 'user'
        }
      : K extends 'write_file' | 'str_replace' | 'create_plan'
        ? FileChange
        : CodebuffToolCall<K>['args']
  }
}[T] &
  Omit<ToolCallPart, 'type'>

