protec.use(async (action, clientSessionId, ws, userInfo) => {
  const userId = userInfo?.id
  const fingerprintId =
    'fingerprintId' in action ? action.fingerprintId : 'unknown-fingerprint'

  if (!userId || !fingerprintId) {
    logger.warn(
      {
        userId,
        fingerprintId,
        actionType: action.type,
      },
      'Missing user or fingerprint ID',
    )
    return {
      type: 'action-error',
      error: 'Missing user or fingerprint ID',
      message: 'Please log in to continue.',
    }
  }

  // Get user info for balance calculation
  const user = await db.query.user.findFirst({
    where: eq(schema.user.id, userId),
    columns: {
      next_quota_reset: true,
      stripe_customer_id: true,
    },
  })

  // Check and trigger monthly reset if needed
  await triggerMonthlyResetAndGrant(userId)

  // Check if we need to trigger auto top-up and get the amount added (if any)
  let autoTopupAdded: number | undefined = undefined
  try {
    autoTopupAdded = await checkAndTriggerAutoTopup(userId)
  } catch (error) {
    logger.error(
      {
        error:
          error instanceof Error
            ? {
                name: error.name,
                message: error.message,
                stack: error.stack,
              }
            : error,
        userId,
        clientSessionId,
        action: 'failed_user_auto_topup_check',
        errorType:
          error instanceof Error ? error.constructor.name : typeof error,
      },
      'Error during auto top-up check in middleware',
    )
    // Continue execution to check remaining balance
  }

  const { usageThisCycle, balance } = await calculateUsageAndBalance(
    userId,
    user?.next_quota_reset ?? new Date(0),
  )

  // Check if we have enough remaining credits
  if (balance.totalRemaining <= 0) {
    // If they have debt, show that in the message
    const message =
      balance.totalDebt > 0
        ? `You have a balance of negative ${pluralize(Math.abs(balance.totalDebt), 'credit')}. Please add credits to continue using Codebuff.`
        : `You do not have enough credits for this action. Please add credits or wait for your next cycle to begin.`

    return {
      type: 'action-error',
      error: 'Insufficient credits',
      message,
      remainingBalance: balance.netBalance,
    }
  }

  // Send initial usage info if we have sufficient credits
  sendAction(ws, {
    type: 'usage-response',
    usage: usageThisCycle,
    remainingBalance: balance.totalRemaining,
    balanceBreakdown: balance.breakdown,
    next_quota_reset: user?.next_quota_reset ?? null,
    autoTopupAdded, // Include the amount added by auto top-up (if any)
  })

  return undefined
})

import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { utils } from '@codebuff/internal'
import { eq } from 'drizzle-orm'

import { logger } from './logger'

import type { ServerAction } from '@codebuff/common/actions'
import type { Request, Response, NextFunction } from 'express'

export const checkAuth = async ({
  fingerprintId,
  authToken,
  clientSessionId,
}: {
  fingerprintId?: string
  authToken?: string
  clientSessionId: string
}): Promise<void | ServerAction> => {
  // Use shared auth check functionality
  const authResult = await utils.checkAuthToken({
    fingerprintId,
    authToken,
  })

  if (!authResult.success) {
    const errorMessage = authResult.error?.message || 'Authentication failed'
    logger.error({ clientSessionId, error: errorMessage }, errorMessage)
    return {
      type: 'action-error',
      message: errorMessage,
    }
  }

  // if (authResult.user) {
  //   // Log successful authentication if we have a user
  //   logger.debug(
  //     { clientSessionId, userId: authResult.user.id },
  //     'Authentication successful'
  //   )
  // }

  return
}

// Express middleware for checking admin access
export const checkAdmin = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  // Extract auth token from Authorization header
  const authHeader = req.headers.authorization
  if (!authHeader?.startsWith('Bearer ')) {
    return res
      .status(401)
      .json({ error: 'Missing or invalid Authorization header' })
  }
  const authToken = authHeader.substring(7) // Remove 'Bearer ' prefix

  // Generate a client session ID for this request
  const clientSessionId = `admin-relabel-${Date.now()}`

  // Check authentication
  const authResult = await checkAuth({
    authToken,
    clientSessionId,
  })

  if (authResult) {
    // checkAuth returns an error action if auth fails
    const errorMessage =
      authResult.type === 'action-error'
        ? authResult.message
        : 'Authentication failed'
    return res.status(401).json({ error: errorMessage })
  }

  // Get the user ID associated with this session token
  const user = await db
    .select({
      id: schema.user.id,
      email: schema.user.email,
    })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, authToken))
    .then((users) => users[0])

  if (!user) {
    return res.status(401).json({ error: 'Invalid session' })
  }

  // Check if user has admin access using shared utility
  const adminUser = await utils.checkUserIsCodebuffAdmin(user.id)
  if (!adminUser) {
    logger.warn(
      { userId: user.id, email: user.email, clientSessionId },
      'Unauthorized access attempt to admin endpoint',
    )
    return res.status(403).json({ error: 'Forbidden' })
  }

  // Store user info in request for handlers to use if needed
  // req.user = adminUser // TODO: ensure type check passes

  // Auth passed and user is admin, proceed to next middleware
  next()
  return
}

