      try {
        await callMainPrompt(ws, action, {
          userId,
          promptId,
          clientSessionId,
        })
      } catch (e) {
        logger.error(e, 'Error in mainPrompt')

        // Send a single prompt-error instead of multiple chunks
        sendAction(ws, getErrorResponseType(action, {
          message: e && typeof e === 'object' && 'message' in e 
            ? e.message 
            : 'An error occurred while processing your request',
          error: String(e),
        }))
      } finally {
        endUserInput(userId, promptId)
        const usageResponse = await genUsageResponse(
          fingerprintId,
          userId,
          undefined,
        )
        sendAction(ws, usageResponse)
      }
    },
  )
}
