  [UserState.CRITICAL]: {
    message: (credits: number) =>
      [
        yellow(`\n🪫 Only ${bold(pluralize(credits, 'credit'))} remaining!`),
        yellow(`Visit ${bold(websiteUrl + '/usage')} to add more credits.`),
      ].join('\n'),
    threshold: 85,
