  private setupSubscriptions() {
    this.webSocket.subscribe('action-error', (action) => {
      if (action.error === 'Insufficient credits') {
        console.error(['', red(`Error: ${action.message}`)].join('\n'))
        logger.info(
          {
            errorMessage: action.message,
          },
          'Action error insufficient credits',
        )
        console.error(
          `Visit ${blue(bold(process.env.NEXT_PUBLIC_APP_URL + '/usage'))} to add credits.`,
        )
      } else if (action.error === 'Auto top-up disabled') {
        console.error(['', red(`Error: ${action.message}`)].join('\n'))
        logger.info(
          {
            errorMessage: action.message,
          },
          'Auto top-up disabled error',
        )
        console.error(
          yellow(
            `Visit ${blue(bold(process.env.NEXT_PUBLIC_APP_URL + '/usage'))} to update your payment settings.`,
          ),
        )
      } else {
        console.error(['', red(`Error: ${action.message}`)].join('\n'))
        logger.error(
          {
            errorMessage: action.message,
          },
          'Unknown action error',
        )
      }
      this.freshPrompt()
      return
    })

    this.webSocket.subscribe('read-files', (a) => {
      const { filePaths, requestId } = a
      const files = getFiles(filePaths)

      sendActionAndHandleError(this.webSocket, {
        type: 'read-files-response',
        files,
        requestId,
      })
    })

    // Handle backend-initiated tool call requests
    this.webSocket.subscribe('tool-call-request', async (action) => {
      const { requestId, toolName, args, userInputId } = action

      // Check if the userInputId matches or is from a spawned agent
      const isValidUserInput = ASYNC_AGENTS_ENABLED
        ? this.nonCancelledUserInputIds.some((id) => userInputId.startsWith(id))
        : this.userInputId && userInputId.startsWith(this.userInputId)

      if (!isValidUserInput) {
        logger.warn(
          {
            requestId,
            toolName,
            currentUserInputId: this.userInputId,
            nonCancelledUserInputIds: this.nonCancelledUserInputIds,
            receivedUserInputId: userInputId,
          },
          'User input ID mismatch - rejecting tool call request',
        )

        sendActionAndHandleError(this.webSocket, {
          type: 'tool-call-response',
          requestId,
          success: false,
          error: ASYNC_AGENTS_ENABLED
            ? `User input ID mismatch: expected one of ${this.nonCancelledUserInputIds.join(', ')}, got ${userInputId}. That user input id might have been cancelled by the user.`
            : `User input ID mismatch: expected ${this.userInputId}, got ${userInputId}. Most likely cancelled by user.`,
        })
        return
      }

      try {
        // Execute the tool call using existing tool handlers
        const toolCall = {
          toolCallId: requestId,
          toolName,
          args,
        }

        Spinner.get().stop()
        const toolResult = await handleToolCall(toolCall as any)

        // Send successful response back to backend
        if (this.userInputId) {
          Spinner.get().start('Processing results...')
        }
        sendActionAndHandleError(this.webSocket, {
          type: 'tool-call-response',
          requestId,
          success: true,
          result: toolResult.result,
        })
      } catch (error) {
        logger.error(
          {
            requestId,
            toolName,
            error: error instanceof Error ? error.message : String(error),
            errorStack: error instanceof Error ? error.stack : undefined,
          },
          'Tool call execution failed - sending error response to backend',
        )

        // Send error response back to backend
        Spinner.get().start('Fixing...')
        sendActionAndHandleError(this.webSocket, {
          type: 'tool-call-response',
          requestId,
          success: false,
          error: error instanceof Error ? error.message : String(error),
        })
      }
    })

    this.webSocket.subscribe('message-cost-response', (action) => {
      const parsedAction = MessageCostResponseSchema.safeParse(action)
      if (!parsedAction.success) return
      const response = parsedAction.data

      // Store credits used for this prompt
      if (!this.creditsByPromptId[response.promptId]) {
        this.creditsByPromptId[response.promptId] = []
      }
      this.creditsByPromptId[response.promptId].push(response.credits)
    })

    this.webSocket.subscribe('usage-response', (action) => {
      const parsedAction = UsageReponseSchema.safeParse(action)
      if (!parsedAction.success) {
        console.error(
          red('Received invalid usage data from server:'),
          parsedAction.error.errors,
        )
        logger.error(
          {
            errorMessage: 'Received invalid usage data from server',
            errors: parsedAction.error.errors,
          },
          'Invalid usage data from server',
        )
        return
      }

      this.setUsage(parsedAction.data)

      // Store auto-topup amount if present, to be displayed when returning control to user
      if (parsedAction.data.autoTopupAdded) {
        this.pendingTopUpMessageAmount += parsedAction.data.autoTopupAdded
      }

      // Only show warning if the response is complete
      if (this.responseComplete) {
        this.showUsageWarning()
      }
    })

    // Used to handle server restarts gracefully
    this.webSocket.subscribe('request-reconnect', () => {
      this.reconnectWhenNextIdle()
    })

    // Handle subagent streaming messages
    this.webSocket.subscribe('subagent-response-chunk', (action) => {
      const { userInputId, agentId, agentType, chunk, prompt } = action

      // Store the chunk locally
      storeSubagentChunk({ agentId, agentType, chunk, prompt })

      // Refresh display if we're currently viewing this agent
      refreshSubagentDisplay(agentId)
    })
  }

  private showUsageWarning() {
    // Determine user state based on login status and credit balance
    const state = match({
      isLoggedIn: !!this.user,
      credits: this.usageData.remainingBalance,
    })
      .with({ isLoggedIn: false }, () => UserState.LOGGED_OUT)
      .with({ credits: P.number.gte(100) }, () => UserState.GOOD_STANDING)
      .with({ credits: P.number.gte(20) }, () => UserState.ATTENTION_NEEDED)
      .with({ credits: P.number.gte(1) }, () => UserState.CRITICAL)
      .otherwise(() => UserState.DEPLETED)

    const config = WARNING_CONFIG[state]

    // Reset warning percentage if in good standing
    if (state === UserState.GOOD_STANDING) {
      this.lastWarnedPct = 0
      return
    }

    // Show warning if we haven't warned at this threshold yet
    if (
      this.lastWarnedPct < config.threshold &&
      this.usageData.remainingBalance
    ) {
      const message = config.message(this.usageData.remainingBalance)
      console.warn(message)
      this.lastWarnedPct = config.threshold
      this.freshPrompt()
    }
  }

  async sendUserInput(prompt: string): Promise<{
    responsePromise: Promise<
      ServerAction & { type: 'prompt-response' | 'manager-prompt-response' } & {
        wasStoppedByUser: boolean
      }
    >
    stopResponse: () => void
  }> {
    if (!this.sessionState) {
      throw new Error('Agent state not initialized')
    }

    setMessages([
      ...this.sessionState.mainAgentState.messageHistory,
      {
        role: 'user',
        content: prompt,
      },
    ])

    this.sessionState.mainAgentState.stepsRemaining =
      loadCodebuffConfig().maxAgentSteps

    this.sessionState.fileContext.cwd = getWorkingDirectory()
    this.sessionState.fileContext.agentTemplates = await loadLocalAgents({})

    const userInputId =
      `mc-input-` + Math.random().toString(36).substring(2, 15)
    loggerContext.clientRequestId = userInputId
    const startTime = Date.now() // Capture start time

    // Add to non-cancelled list
    this.nonCancelledUserInputIds.push(userInputId)

    const f = this.subscribeToResponse.bind(this)

    const { responsePromise, stopResponse } = f(
      (chunk) => {
        if (this.userInputId !== userInputId) {
          return
        }
        if (typeof chunk === 'string') {
          if (chunk) {
            Spinner.get().stop()
          }
          DiffManager.receivedResponse()
          process.stdout.write(chunk)
        } else {
          if (chunk.type === 'error') {
            printModeLog(chunk)
          } else {
            printModeLog(chunk)
          }
        }
      },
      userInputId,
      () => {
        if (this.userInputId !== userInputId) {
          return
        }
        Spinner.get().stop()
        process.stdout.write('\n' + green(underline('Codebuff') + ': '))
      },
      prompt,
      startTime,
    )

    // Parse agent references from the prompt
    const cleanPrompt = this.parseAgentReferences(prompt)

    const urls = parseUrlsFromContent(cleanPrompt)
    const scrapedBlocks = await getScrapedContentBlocks(urls)
    const scrapedContent =
      scrapedBlocks.length > 0 ? scrapedBlocks.join('\n\n') + '\n\n' : ''

    // Append process updates to existing tool results
    const toolResults = buildArray(
      ...(this.lastToolResults || []),
      ...getBackgroundProcessUpdates(),
      scrapedContent && {
        toolName: 'web-scraper',
        toolCallId: generateCompactId(),
        result: scrapedContent,
      },
    )

    Spinner.get().start('Thinking...')

    // Get agent and params from CLI instance
    const cli = CLI.getInstance()
    const cliAgent = cli.agent
    const cliParams = cli.initialParams
    cli.initialParams = undefined

    const action: ClientAction = {
      type: 'prompt',
      promptId: userInputId,
      prompt: cleanPrompt,
      agentId: cliAgent, // Add explicit agent selection
      promptParams: cliParams, // Add parsed params
      sessionState: this.sessionState,
      toolResults,
      fingerprintId: await this.fingerprintId,
      authToken: process.env[API_KEY_ENV_VAR] || this.user?.authToken,
      costMode: this.costMode,
      model: this.model,
      repoUrl: loggerContext.repoUrl,
      // repoName: loggerContext.repoName,
    }
    sendActionAndHandleError(this.webSocket, action)

    return {
      responsePromise,
      stopResponse,
    }
  }

  private parseAgentReferences(prompt: string): string {
    let cleanPrompt = prompt

    // Create resolver with local agents (use cached version from getLoadedAgentNames)
    const localAgentNames = getLoadedAgentNames()
    const localAgentInfo = Object.fromEntries(
      Object.entries(localAgentNames).map(([id, displayName]) => [
        id,
        { displayName },
      ]),
    )
    const allAgentNames = getAllAgents(localAgentInfo).map(
      (agent) => agent.displayName,
    )

    // Create a regex pattern that matches any of the known agent names
    const agentNamePattern = allAgentNames
      .map(
        (name) => name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), // Escape special regex chars
      )
      .join('|')

    const agentRegex = new RegExp(
      `@(${agentNamePattern})(?=\\s|$|[,.!?])`,
      'gi',
    )

    // Replace each @agentName with @agentName (agentId)
    cleanPrompt = cleanPrompt.replace(agentRegex, (match) => {
      const agentName = match.substring(1).trim() // Remove @ and trim
      const agentId = resolveNameToId(agentName, localAgentInfo)

      if (agentId) {
        return `@${agentName} (agent type: ${agentId})`
      }
      return match // Return original if no agent ID found
    })

    return cleanPrompt
  }

  private handleInitializationComplete() {
    // Show the tips that were removed from the local handler
    console.log(
      cyan(
        `\n📋 What codebuff.json does:\n• ${bold(
          'startupProcesses',
        )}: Automatically runs development servers, databases, etc. when you start Codebuff\n• ${bold(
          'fileChangeHooks',
        )}: Runs tests, linting, and type checking when you modify files\n• ${bold(
          'maxAgentSteps',
        )}: Controls how many steps the AI can take before stopping\n\n💡 Tips:\n• Add your dev server command to startupProcesses to auto-start it\n• Configure fileChangeHooks to catch errors early\n• The AI will use these hooks to verify changes work correctly\n`,
      ),
    )

    // Start background processes if they were configured
    const config = loadCodebuffConfig()
    if (config?.startupProcesses?.length) {
      console.log(yellow('\n🚀 Starting background processes...'))
      logAndHandleStartup()
    }
  }

  public cancelCurrentInput() {
    if (!this.user) {
      return
    }
    if (!this.userInputId) {
      return
    }

    // Remove the cancelled input ID from the non-cancelled list
    this.nonCancelledUserInputIds = this.nonCancelledUserInputIds.filter(
      (id) => id !== this.userInputId,
    )

    sendActionAndHandleError(this.webSocket, {
      type: 'cancel-user-input',
      authToken: this.user?.authToken,
      promptId: this.userInputId,
    })
    this.userInputId = undefined
  }

  private subscribeToResponse(
    onChunk: (chunk: string | PrintModeEvent) => void,
    userInputId: string,
    onStreamStart: () => void,
    prompt: string,
    startTime: number,
  ) {
    const rawChunkBuffer: string[] = []
    let streamStarted = false
    let responseStopped = false
    let resolveResponse: (
      value: ServerAction & { type: 'prompt-response' } & {
        wasStoppedByUser: boolean
      },
    ) => void
    let rejectResponse: (reason?: any) => void
    let unsubscribeChunks: () => void
    let unsubscribeComplete: () => void

    const responsePromise = new Promise<
      ServerAction & { type: 'prompt-response' } & {
        wasStoppedByUser: boolean
      }
    >((resolve, reject) => {
      resolveResponse = resolve
      rejectResponse = reject
    })

    this.userInputId = userInputId

    const stopResponse = () => {
      responseStopped = true
      unsubscribeChunks()
      unsubscribeComplete()
      this.cancelCurrentInput()

      const additionalMessages = prompt
        ? [
            { role: 'user' as const, content: prompt },
            {
              role: 'user' as const,
              content: `<system><assistant_message>${rawChunkBuffer.join('')}${closeXml('assistant_message')}[RESPONSE_CANCELED_BY_USER]${closeXml('system')}`,
            },
          ]
        : []

      // Update the agent state with just the assistant's response
      const {
        mainAgentState: { messageHistory },
      } = this.sessionState!
      const newMessages = [...messageHistory, ...additionalMessages]
      this.sessionState = {
        ...this.sessionState!,
        mainAgentState: {
          ...this.sessionState!.mainAgentState,
          messageHistory: newMessages,
        },
      }
      setMessages(newMessages)

      resolveResponse({
        type: 'prompt-response',
        promptId: userInputId,
        sessionState: this.sessionState!,
        toolCalls: [],
        toolResults: [],
        wasStoppedByUser: true,
      })
    }

    const xmlStreamParser = createXMLStreamParser(toolRenderers, (chunk) => {
      onChunk(chunk)
    })

    unsubscribeChunks = this.webSocket.subscribe('response-chunk', (a) => {
      if (a.userInputId !== userInputId) return
      if (typeof a.chunk === 'string') {
        const { chunk } = a

        rawChunkBuffer.push(chunk)

        const trimmed = chunk.trim()
        for (const tag of ONE_TIME_TAGS) {
          if (
            trimmed.startsWith(`<${tag}>`) &&
            trimmed.endsWith(closeXml(tag))
          ) {
            if (this.oneTimeFlags[tag]) {
              return
            }
            Spinner.get().stop()
            const warningMessage = trimmed
              .replace(`<${tag}>`, '')
              .replace(closeXml(tag), '')
            process.stdout.write(yellow(`\n\n${warningMessage}\n\n`))
            this.oneTimeFlags[tag as (typeof ONE_TIME_LABELS)[number]] = true
            return
          }
        }

        if (chunk && chunk.trim()) {
          if (!streamStarted && chunk.trim()) {
            streamStarted = true
            onStreamStart()
          }
        }

        try {
          xmlStreamParser.write(chunk, 'utf8')
        } catch (e) {
          logger.error(
            {
              errorMessage: e instanceof Error ? e.message : String(e),
              errorStack: e instanceof Error ? e.stack : undefined,
              chunk,
            },
            'Error writing chunk to XML stream parser',
          )
        }
      } else {
        onChunk(a.chunk)
      }
    })

    let stepsCount = 0
    let toolCallsCount = 0
    unsubscribeComplete = this.webSocket.subscribe(
      'prompt-response',
      async (action) => {
        const parsedAction = PromptResponseSchema.safeParse(action)
        if (!parsedAction.success) {
          const message = [
            'Received invalid prompt response from server:',
            JSON.stringify(parsedAction.error.errors),
            'If this issues persists, please contact support@codebuff.com',
          ].join('\n')
          console.error(message)
          logger.error(
            {
              errorMessage: message,
              action,
              eventId: AnalyticsEvent.MALFORMED_PROMPT_RESPONSE,
            },
            'Malformed prompt response',
          )
          return
        }
        if (action.promptId !== userInputId) return
        const a = parsedAction.data
        this.responseComplete = true

        Spinner.get().stop()

        this.sessionState = a.sessionState
        const toolResults: ToolResult[] = []

        stepsCount++
        console.log('\n')

        // If we had any file changes, update the project context
        if (DiffManager.getChanges().length > 0) {
          this.fileContext = await getProjectFileContext(getProjectRoot(), {})
        }

        const endTime = Date.now()
        const latencyMs = endTime - startTime
        trackEvent(AnalyticsEvent.USER_INPUT_COMPLETE, {
          userInputId,
          latencyMs,
          stepsCount,
          toolCallsCount,
        })

        this.lastToolResults = toolResults

        askConfig: if (
          this.oneTimeFlags[SHOULD_ASK_CONFIG] &&
          !this.oneTimeFlags[ASKED_CONFIG]
        ) {
          this.oneTimeFlags[ASKED_CONFIG] = true
          if (existsSync(path.join(getProjectRoot(), CONFIG_FILE_NAME))) {
            break askConfig
          }

          console.log(
            '\n\n' +
              yellow(`✨ Recommended: run the 'init' command in order to create a configuration file!

If you would like background processes (like this one) to run automatically whenever Codebuff starts, creating a ${CONFIG_FILE_NAME} config file can improve your workflow.
Go to https://www.codebuff.com/config for more information.`) +
              '\n',
          )
        }

        if (this.sessionState) {
          setMessages(this.sessionState.mainAgentState.messageHistory)
        }

        // Mark any subagents as inactive when the main response completes
        // This is a simple heuristic - in practice you might want more sophisticated tracking
        const allSubagentIds = getAllSubagentIds()
        allSubagentIds.forEach((agentId: string) => {
          markSubagentInactive(agentId)
        })

        // Show total credits used for this prompt if significant
        const credits =
          this.creditsByPromptId[userInputId]?.reduce((a, b) => a + b, 0) ?? 0
        if (credits >= REQUEST_CREDIT_SHOW_THRESHOLD) {
          console.log(
            `\n\n${pluralize(credits, 'credit')} used for this request.`,
          )
        }

        if (DiffManager.getChanges().length > 0) {
          let checkpointAddendum = ''
          try {
            checkpointAddendum = ` or "checkpoint ${checkpointManager.getLatestCheckpoint().id}" to revert`
          } catch (error) {
            // No latest checkpoint, don't show addendum
            logger.info(
              {
                errorMessage:
                  error instanceof Error ? error.message : String(error),
                errorStack: error instanceof Error ? error.stack : undefined,
              },
              'No latest checkpoint for addendum',
            )
          }
          console.log(
            `\n\nComplete! Type "diff" to review changes${checkpointAddendum}.\n`,
          )

          if (this.isInitializing) {
            this.isInitializing = false
            // Show tips and start background processes
            this.handleInitializationComplete()
          }

          this.freshPrompt()
        }

        if (!ASYNC_AGENTS_ENABLED) {
          xmlStreamParser.end()
          unsubscribeChunks()
          unsubscribeComplete()
        }
        resolveResponse({ ...a, wasStoppedByUser: false })
      },
    )

    // Reset flags at the start of each response
    this.responseComplete = false

    return {
      responsePromise,
      stopResponse,
    }
  }

  public async getUsage() {
    try {
      // Check for organization coverage first
      const coverage = await this.checkRepositoryCoverage()

      const response = await fetch(`${backendUrl}/api/usage`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          fingerprintId: await this.fingerprintId,
          authToken: this.user?.authToken,
          ...(coverage.isCovered &&
            coverage.organizationId && { orgId: coverage.organizationId }),
        }),
      })

      const data = await response.json()

      // Use zod schema to validate response
      const parsedResponse = UsageReponseSchema.parse(data)

      if ((data as any).type === 'action-error') {
        console.error(red((data as any).message))
        logger.error(
          {
            errorMessage: (data as any).message,
          },
          'Action error',
        )
        return
      }

      this.setUsage(parsedResponse)

      // Calculate session usage and total for display
      const totalCreditsUsedThisSession = Object.values(this.creditsByPromptId)
        .flat()
        .reduce((sum, credits) => sum + credits, 0)

      let sessionUsageMessage = `Session usage: ${totalCreditsUsedThisSession.toLocaleString()}`
      if (this.usageData.remainingBalance !== null) {
        const remainingColor =
          this.usageData.remainingBalance === null
            ? yellow
            : this.usageData.remainingBalance <= 0
              ? red
              : this.usageData.remainingBalance <= LOW_BALANCE_THRESHOLD
                ? red
                : green
        sessionUsageMessage += `. Credits Remaining: ${remainingColor(this.usageData.remainingBalance.toLocaleString())}`
      } else {
        sessionUsageMessage += '.'
      }
      console.log(sessionUsageMessage)

      if (coverage.isCovered && coverage.organizationName) {
        // When covered by an organization, show organization information
        console.log(
          green(
            `🏢 Your usage in this repository is covered by ${bold(coverage.organizationName)}.`,
          ),
        )
        // Try to use organizationSlug from the coverage response
        if (coverage.organizationSlug) {
          const orgUsageLink = `${websiteUrl}/orgs/${coverage.organizationSlug}`
          console.log(
            `View your organization's usage details: ${underline(blue(orgUsageLink))}`,
          )
        }
      } else {
        // Only show personal usage details when not covered by an organization
        const usageLink = `${websiteUrl}/usage` // Personal usage link

        // Only show personal credit renewal if not covered by an organization
        if (this.usageData.next_quota_reset) {
          const resetDate = new Date(this.usageData.next_quota_reset)
          const today = new Date()
          const isToday = resetDate.toDateString() === today.toDateString()

          const dateDisplay = isToday
            ? resetDate.toLocaleString() // Show full date and time for today
            : resetDate.toLocaleDateString() // Just show date otherwise

          console.log(
            `Free credits will renew on ${dateDisplay}. Details: ${underline(blue(usageLink))}`,
          )
        }

        this.showUsageWarning()
      }
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
        },
        'Error checking usage',
      )
      console.error(
        red(
          `Error checking usage: Please reach out to ${process.env.NEXT_PUBLIC_SUPPORT_EMAIL} for help.`,
        ),
      )
      // Check if it's a ZodError for more specific feedback
      if (error instanceof z.ZodError) {
        console.error(red('Data validation failed:'), error.errors)
        logger.error(
          {
            errorMessage: 'Data validation failed',
            errors: error.errors,
          },
          'Data validation failed',
        )
      } else {
        console.error(error)
        logger.error(
          {
            errorMessage:
              error instanceof Error ? error.message : String(error),
            errorStack: error instanceof Error ? error.stack : undefined,
          },
          'Error checking usage',
        )
      }
    } finally {
      this.freshPrompt()
    }
  }

  public async warmContextCache() {
    const fileContext = await getProjectFileContext(getProjectRoot(), {})
    if (!fileContext) {
      throw new Error('Failed to initialize project file context')
    }

    await validateAgentConfigsIfAuthenticated(
      Object.values(fileContext.agentTemplates),
    )

    this.webSocket.subscribe('init-response', (a) => {
      const parsedAction = InitResponseSchema.safeParse(a)
      if (!parsedAction.success) {
        return
      }

      // Store agent names for tool renderer (merge backend and local agents)
      if (parsedAction.data.agentNames) {
        const localAgentNames = getLoadedAgentNames()
        this.agentNames = {
          ...parsedAction.data.agentNames,
          ...localAgentNames,
        }
      }

      // Log the message if it's defined
      if (parsedAction.data.message) {
        console.log(`\n${parsedAction.data.message}`)
        this.freshPrompt()
      }

      // Set initial usage data from the init response
      this.setUsage(parsedAction.data)
    })

    const initAction: Extract<ClientAction, { type: 'init' }> = {
      type: 'init',
      fingerprintId: await this.fingerprintId,
      authToken: this.user?.authToken,
      fileContext,
      // Add repoUrl here as per the diff for client.ts
      repoUrl: loggerContext.repoUrl,
    }
    sendActionAndHandleError(this.webSocket, initAction)

    await this.fetchStoredApiKeyTypes()
  }

  /**
   * Checks if the current repository is covered by an organization.
   * @param remoteUrl Optional remote URL. If not provided, will try to get from git config.
   * @returns Promise<{ isCovered: boolean; organizationName?: string; organizationId?: string; organizationSlug?: string; error?: string }>
   */
  public async checkRepositoryCoverage(remoteUrl?: string): Promise<{
    isCovered: boolean
    organizationName?: string
    organizationId?: string
    organizationSlug?: string
    error?: string
  }> {
    try {
      // Always use getRepoMetrics to get repo info, passing remoteUrl if provided
      let repoMetrics: Awaited<ReturnType<typeof getRepoMetrics>>
      try {
        repoMetrics = await getRepoMetrics(remoteUrl)
      } catch (error) {
        return {
          isCovered: false,
          error: 'Could not get repository information',
        }
      }

      const { repoUrl, owner, repo } = repoMetrics

      if (!repoUrl) {
        return { isCovered: false, error: 'No remote URL found' }
      }

      if (!owner || !repo) {
        return { isCovered: false, error: 'Could not parse repository URL' }
      }

      // Check if user is authenticated
      if (!this.user || !this.user.authToken) {
        return { isCovered: false, error: 'User not authenticated' }
      }

      // Call backend API to check if repo is covered by organization
      const response = await fetch(`${backendUrl}/api/orgs/is-repo-covered`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.user.authToken}`,
        },
        body: JSON.stringify({
          owner: owner.toLowerCase(),
          repo: repo.toLowerCase(),
          remoteUrl: repoUrl,
        }),
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        return {
          isCovered: false,
          error:
            (errorData as any).error ||
            `HTTP ${response.status}: ${response.statusText}`,
        }
      }

      const data: any = await response.json()
      return {
        isCovered: data.isCovered || false,
        organizationName: data.organizationName,
        organizationId: data.organizationId,
        organizationSlug: data.organizationSlug,
      }
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          remoteUrl,
        },
        'Error checking repository coverage',
      )
      return {
        isCovered: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      }
    }
  }
}

import { WEBSOCKET_URL } from './constants'
import { APIRealtimeClient } from '../../common/src/websockets/websocket-client'

import type { ServerAction, ClientAction } from '../../common/src/actions'
import type { WebSocket } from 'ws'

export type WebSocketHandlerOptions = {
  onWebsocketError?: (error: WebSocket.ErrorEvent) => void
  onWebsocketReconnect?: () => void
  onRequestReconnect?: () => Promise<void>
  onResponseError?: (
    error: Extract<ServerAction, { type: 'action-error' }>,
  ) => Promise<void>
  readFiles: (
    filePath: string[],
  ) => Promise<Extract<ClientAction, { type: 'read-files-response' }>['files']>
  handleToolCall: (
    action: Extract<ServerAction, { type: 'tool-call-request' }>,
  ) => Promise<
    Omit<
      Extract<ClientAction, { type: 'tool-call-response' }>,
      'type' | 'requestId'
    >
  >
  onCostResponse?: (
    action: Extract<ServerAction, { type: 'message-cost-response' }>,
  ) => Promise<void>

  onResponseChunk?: (
    action: Extract<ServerAction, { type: 'response-chunk' }>,
  ) => Promise<void>
  onSubagentResponseChunk?: (
    action: Extract<ServerAction, { type: 'subagent-response-chunk' }>,
  ) => Promise<void>

  onPromptResponse?: (
    action: Extract<ServerAction, { type: 'prompt-response' }>,
  ) => Promise<void>

  apiKey: string
}

type WebSocketHandlerOptionsWithDefaults = Required<WebSocketHandlerOptions>

export class WebSocketHandler {
  private cbWebSocket: APIRealtimeClient
  private onRequestReconnect: WebSocketHandlerOptionsWithDefaults['onRequestReconnect']

  private onResponseError: WebSocketHandlerOptionsWithDefaults['onResponseError']
  private readFiles: WebSocketHandlerOptionsWithDefaults['readFiles']
  private handleToolCall: WebSocketHandlerOptionsWithDefaults['handleToolCall']
  private onCostResponse: WebSocketHandlerOptionsWithDefaults['onCostResponse']
  private onResponseChunk: WebSocketHandlerOptionsWithDefaults['onResponseChunk']
  private onSubagentResponseChunk: WebSocketHandlerOptionsWithDefaults['onSubagentResponseChunk']
  private onPromptResponse: WebSocketHandlerOptionsWithDefaults['onPromptResponse']
  private apiKey: string
  private isConnected = false

  constructor({
    onWebsocketError = () => {},
    onWebsocketReconnect = () => {},
    onRequestReconnect = async () => {},
    onResponseError = async () => {},
    readFiles,
    handleToolCall,
    onCostResponse = async () => {},

    onResponseChunk = async () => {},
    onSubagentResponseChunk = async () => {},

    onPromptResponse = async () => {},

    apiKey,
  }: WebSocketHandlerOptions) {
    this.cbWebSocket = new APIRealtimeClient(
      WEBSOCKET_URL,
      onWebsocketError,
      onWebsocketReconnect,
    )
    this.onRequestReconnect = onRequestReconnect

    this.onResponseError = onResponseError
    this.readFiles = readFiles
    this.handleToolCall = handleToolCall
    this.onCostResponse = onCostResponse

    this.onResponseChunk = onResponseChunk
    this.onSubagentResponseChunk = onSubagentResponseChunk

    this.onPromptResponse = onPromptResponse

    this.apiKey = apiKey
  }

  public async connect() {
    if (!this.isConnected) {
      await this.cbWebSocket.connect()
      this.setupSubscriptions()
      this.isConnected = true
    }
  }

  public reconnect() {
    this.cbWebSocket.forceReconnect()
  }

  public close() {
    this.cbWebSocket.close()
  }

  private setupSubscriptions() {
    this.cbWebSocket.subscribe('action-error', this.onResponseError)

    this.cbWebSocket.subscribe('read-files', async (a) => {
      const { filePaths, requestId } = a
      const files = await this.readFiles(filePaths)

      this.cbWebSocket.sendAction({
        type: 'read-files-response',
        files,
        requestId,
      })
    })

    // Handle backend-initiated tool call requests
    this.cbWebSocket.subscribe('tool-call-request', async (action) => {
      const toolCallResult = await this.handleToolCall(action)

      this.cbWebSocket.sendAction({
        type: 'tool-call-response',
        requestId: action.requestId,
        ...toolCallResult,
      })
    })

    this.cbWebSocket.subscribe('message-cost-response', this.onCostResponse)

    // Used to handle server restarts gracefully
    this.cbWebSocket.subscribe('request-reconnect', this.onRequestReconnect)

    // Handle streaming messages
    this.cbWebSocket.subscribe('response-chunk', this.onResponseChunk)
    this.cbWebSocket.subscribe(
      'subagent-response-chunk',
      this.onSubagentResponseChunk,
    )

    // Handle full response from prompt
    this.cbWebSocket.subscribe('prompt-response', this.onPromptResponse)
  }

  private getInputDefaultOptions() {
    return {
      ...({
        type: 'prompt',
      } as const),
      authToken: this.apiKey,
    }
  }

  public sendInput(
    action: Omit<
      Extract<ClientAction, { type: 'prompt' }>,
      keyof ReturnType<typeof this.getInputDefaultOptions>
    >,
  ) {
    this.cbWebSocket.sendAction({
      ...action,
      ...this.getInputDefaultOptions(),
    })
  }

  public cancelInput({ promptId }: { promptId: string }) {
    this.cbWebSocket.sendAction({
      type: 'cancel-user-input',
      authToken: this.apiKey,
      promptId,
    })
  }
}

import { execFileSync } from 'child_process'
import os from 'os'

import { CODEBUFF_BINARY } from './constants'
import { changeFile } from './tools/change-file'
import { getFiles } from './tools/read-files'
import { WebSocketHandler } from './websocket-client'
import {
  PromptResponseSchema,
  type ServerAction,
} from '../../common/src/actions'
import { API_KEY_ENV_VAR } from '../../common/src/constants'
import { getInitialSessionState } from '../../common/src/types/session-state'

import type { PrintModeEvent } from '../../common/src/types/print-mode'
import type { SessionState } from '../../common/src/types/session-state'
import type { AgentConfig } from './types/agent-config'

type ClientToolName = 'write_file' | 'run_terminal_command'

export type CodebuffClientOptions = {
  // Provide an API key or set the CODEBUFF_API_KEY environment variable.
  apiKey?: string
  cwd: string
  onError: (error: { message: string }) => void
  overrideTools?: Partial<
    Record<
      ClientToolName,
      (
        args: Extract<ServerAction, { type: 'tool-call-request' }>['args'],
      ) => Promise<{ toolResultMessage: string }>
    > & {
      // Include read_files separately, since it has a different signature.
      read_files: (
        filePath: string[],
      ) => Promise<{ files: Record<string, string | null> }>
    }
  >
}

type RunState = {
  sessionState: SessionState
  toolResults: Extract<ServerAction, { type: 'prompt-response' }>['toolResults']
}

export class CodebuffClient {
  public cwd: string

  private readonly websocketHandler: WebSocketHandler
  private readonly overrideTools: NonNullable<
    CodebuffClientOptions['overrideTools']
  >
  private readonly fingerprintId = `codebuff-sdk-${Math.random().toString(36).substring(2, 15)}`

  private readonly promptIdToHandleEvent: Record<
    string,
    (event: PrintModeEvent) => void
  > = {}
  private readonly promptIdToResolveResponse: Record<
    string,
    { resolve: (response: any) => void; reject: (error: any) => void }
  > = {}

  constructor({ apiKey, cwd, onError, overrideTools }: CodebuffClientOptions) {
    // TODO: download binary automatically
    const isWindows = process.platform === 'win32'
    if (
      execFileSync(isWindows ? 'where' : 'which', [CODEBUFF_BINARY])
        .toString()
        .trim() === ''
    ) {
      throw new Error(
        `Could not find ${CODEBUFF_BINARY} in PATH. Please run "npm i -g codebuff" to install codebuff.`,
      )
    }
    const foundApiKey = apiKey ?? process.env[API_KEY_ENV_VAR]
    if (!foundApiKey) {
      throw new Error(
        `Codebuff API key not found. Please provide an apiKey in the constructor of CodebuffClient or set the ${API_KEY_ENV_VAR} environment variable.`,
      )
    }

    this.cwd = cwd
    this.overrideTools = overrideTools ?? {}
    this.websocketHandler = new WebSocketHandler({
      apiKey: foundApiKey,
      onWebsocketError: (error) => {
        onError({ message: error.message })
      },
      onWebsocketReconnect: () => {},
      onRequestReconnect: async () => {},
      onResponseError: async (error) => {
        onError({ message: error.message })
      },
      readFiles: this.readFiles.bind(this),
      handleToolCall: this.handleToolCall.bind(this),
      onCostResponse: async () => {},

      onResponseChunk: async (action) => {
        const { userInputId, chunk } = action
        const handleEvent = this.promptIdToHandleEvent[userInputId]
        if (handleEvent && typeof chunk === 'object') {
          handleEvent(chunk)
        }
      },
      onSubagentResponseChunk: async () => {},

      onPromptResponse: this.handlePromptResponse.bind(this),
    })
  }

  /**
   * Run a Codebuff agent with the specified options.
   *
   * @param agent - The agent to run. Use 'base' for the default agent, or specify a custom agent ID if you made your own agent config.
   * @param prompt - The user prompt describing what you want the agent to do.
   * @param params - (Optional) Additional parameters for the agent. Most agents don't use this, but some custom agents can take a JSON object as input in addition to the user prompt string.
   * @param handleEvent - (Optional) Callback function that receives every event during execution (assistant messages, tool calls, etc.). This allows you to stream the agent's progress in real-time. We will likely add a token-by-token streaming callback in the future.
   * @param previousRun - (Optional) JSON state returned from a previous run() call. Use this to continue a conversation or session with the agent, maintaining context from previous interactions.
   * @param projectFiles - (Optional) All the files in your project as a plain JavaScript object. Keys should be the full path from your current directory to each file, and values should be the string contents of the file. Example: { "src/index.ts": "console.log('hi')" }. This helps Codebuff pick good source files for context.
   * @param knowledgeFiles - (Optional) Knowledge files to inject into every run() call. Uses the same schema as projectFiles - keys are file paths and values are file contents. These files are added directly to the agent's context.
   * @param agentConfigs - (Optional) Array of custom agent configurations. Each object should satisfy the AgentConfig type.
   * @param maxAgentSteps - (Optional) Maximum number of steps the agent can take before stopping. Use this as a safety measure in case your agent starts going off the rails. A reasonable number is around 20.
   *
   * @returns A Promise that resolves to a RunState JSON object which you can pass to a subsequent run() call to continue the run.
   */
  public async run({
    agent,
    prompt,
    params,
    handleEvent,
    previousRun,
    projectFiles,
    knowledgeFiles,
    agentConfigs,
    maxAgentSteps,
  }: {
    agent: string
    prompt: string
    params?: Record<string, any>
    handleEvent?: (event: PrintModeEvent) => void
    previousRun?: RunState
    projectFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentConfigs?: AgentConfig[]
    maxAgentSteps?: number
  }): Promise<RunState> {
    await this.websocketHandler.connect()

    const promptId = Math.random().toString(36).substring(2, 15)
    const sessionState =
      previousRun?.sessionState ??
      initialSessionState(this.cwd, {
        knowledgeFiles,
        agentConfigs,
        projectFiles,
        maxAgentSteps,
      })
    const toolResults = previousRun?.toolResults ?? []
    if (handleEvent) {
      this.promptIdToHandleEvent[promptId] = handleEvent
    }
    this.websocketHandler.sendInput({
      promptId,
      prompt,
      promptParams: params,
      fingerprintId: this.fingerprintId,
      costMode: 'normal',
      sessionState,
      toolResults,
      agentId: agent,
    })

    return new Promise<RunState>((resolve, reject) => {
      this.promptIdToResolveResponse[promptId] = { resolve, reject }
    })
  }

  private async handlePromptResponse(
    action: Extract<ServerAction, { type: 'prompt-response' }>,
  ) {
    const promiseActions =
      this.promptIdToResolveResponse[action?.promptId ?? '']

    const parsedAction = PromptResponseSchema.safeParse(action)
    if (!parsedAction.success) {
      const message = [
        'Received invalid prompt response from server:',
        JSON.stringify(parsedAction.error.errors),
        'If this issues persists, please contact support@codebuff.com',
      ].join('\n')
      if (promiseActions) {
        promiseActions.reject(new Error(message))
      }
      return
    }

    if (promiseActions) {
      const { sessionState, toolResults } = parsedAction.data
      const state: RunState = {
        sessionState,
        toolResults,
      }
      promiseActions.resolve(state)

      delete this.promptIdToResolveResponse[action.promptId]
      delete this.promptIdToHandleEvent[action.promptId]
    }
  }

  private async readFiles(filePath: string[]) {
    const override = this.overrideTools.read_files
    if (override) {
      const overrideResult = await override(filePath)
      return overrideResult.files
    }
    return getFiles(filePath, this.cwd)
  }

  private async handleToolCall(
    action: Extract<ServerAction, { type: 'tool-call-request' }>,
  ) {
    const toolName = action.toolName
    const args = action.args
    let result: string
    try {
      let override = this.overrideTools[toolName as ClientToolName]
      if (!override && toolName === 'str_replace') {
        // Note: write_file and str_replace have the same implementation, so reuse their write_file override.
        override = this.overrideTools['write_file']
      }
      if (override) {
        const overrideResult = await override(args)
        result = overrideResult.toolResultMessage
      } else if (toolName === 'end_turn') {
        result = ''
      } else if (toolName === 'write_file' || toolName === 'str_replace') {
        const r = changeFile(args, this.cwd)
        result = r.toolResultMessage
      } else if (toolName === 'run_terminal_command') {
        throw new Error(
          'run_terminal_command not implemented in SDK yet; please provide an override.',
        )
      } else {
        throw new Error(
          `Tool not implemented in SDK. Please provide an override or modify your agent to not use this tool: ${toolName}`,
        )
      }
    } catch (error) {
      return {
        type: 'tool-call-response',
        requestId: action.requestId,
        success: false,
        result:
          error && typeof error === 'object' && 'message' in error
            ? error.message
            : typeof error === 'string'
              ? error
              : 'Unknown error',
      }
    }
    return {
      type: 'tool-call-response',
      requestId: action.requestId,
      success: true,
      result,
    }
  }
}

function initialSessionState(
  cwd: string,
  options: {
    // TODO: Parse projectFiles into fileTree, fileTokenScores, tokenCallers
    projectFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentConfigs?: AgentConfig[]
    maxAgentSteps?: number
  },
) {
  const { knowledgeFiles = {}, agentConfigs = [] } = options

  // Process agentConfigs array and convert handleSteps functions to strings
  const processedAgentTemplates: Record<string, any> = {}
  agentConfigs.forEach((config) => {
    const processedConfig = { ...config } as Record<string, any>
    if (
      processedConfig.handleSteps &&
      typeof processedConfig.handleSteps === 'function'
    ) {
      processedConfig.handleSteps = processedConfig.handleSteps.toString()
    }
    if (processedConfig.id) {
      processedAgentTemplates[processedConfig.id] = processedConfig
    }
  })

  const initialState = getInitialSessionState({
    projectRoot: cwd,
    cwd,
    fileTree: [],
    fileTokenScores: {},
    tokenCallers: {},
    knowledgeFiles,
    userKnowledgeFiles: {},
    agentTemplates: processedAgentTemplates,
    gitChanges: {
      status: '',
      diff: '',
      diffCached: '',
      lastCommitMessages: '',
    },
    changesSinceLastChat: {},
    shellConfigFiles: {},
    systemInfo: {
      platform: process.platform,
      shell: process.platform === 'win32' ? 'cmd.exe' : 'bash',
      nodeVersion: process.version,
      arch: process.arch,
      homedir: os.homedir(),
      cpus: os.cpus().length ?? 1,
    },
  })

  if (options.maxAgentSteps) {
    initialState.mainAgentState.stepsRemaining = options.maxAgentSteps
  }

  return initialState
}

