  public cancelCurrentInput() {
    if (!this.user) {
      return
    }
    if (!this.userInputId) {
      return
    }

    // Remove the cancelled input ID from the non-cancelled list
    this.nonCancelledUserInputIds = this.nonCancelledUserInputIds.filter(
      (id) => id !== this.userInputId,
    )

    sendActionAndHandleError(this.webSocket, {
      type: 'cancel-user-input',
      authToken: this.user?.authToken,
      promptId: this.userInputId,
    })
    this.userInputId = undefined
  }

  private subscribeToResponse(
    onChunk: (chunk: string | PrintModeEvent) => void,
    userInputId: string,
    onStreamStart: () => void,
    prompt: string,
    startTime: number,
  ) {
    const rawChunkBuffer: string[] = []
    let streamStarted = false
    let responseStopped = false
    let resolveResponse: (
      value: ServerAction & { type: 'prompt-response' } & {
        wasStoppedByUser: boolean
      },
    ) => void
    let rejectResponse: (reason?: any) => void
    let unsubscribeChunks: () => void
    let unsubscribeComplete: () => void

    const responsePromise = new Promise<
      ServerAction & { type: 'prompt-response' } & {
        wasStoppedByUser: boolean
      }
    >((resolve, reject) => {
      resolveResponse = resolve
      rejectResponse = reject
    })

    this.userInputId = userInputId

    const stopResponse = () => {
      responseStopped = true
      unsubscribeChunks()
      unsubscribeComplete()
      this.cancelCurrentInput()

      const additionalMessages = prompt
        ? [
            { role: 'user' as const, content: prompt },
            {
              role: 'user' as const,
              content: `<system><assistant_message>${rawChunkBuffer.join('')}${closeXml('assistant_message')}[RESPONSE_CANCELED_BY_USER]${closeXml('system')}`,
            },
          ]
        : []

      // Update the agent state with just the assistant's response
      const {
        mainAgentState: { messageHistory },
      } = this.sessionState!
      const newMessages = [...messageHistory, ...additionalMessages]
      this.sessionState = {
        ...this.sessionState!,
        mainAgentState: {
          ...this.sessionState!.mainAgentState,
          messageHistory: newMessages,
        },
      }
      setMessages(newMessages)

      resolveResponse({
        type: 'prompt-response',
        promptId: userInputId,
        sessionState: this.sessionState!,
        toolCalls: [],
        toolResults: [],
        wasStoppedByUser: true,
      })
    }

    const xmlStreamParser = createXMLStreamParser(toolRenderers, (chunk) => {
      onChunk(chunk)
    })

    unsubscribeChunks = this.webSocket.subscribe('response-chunk', (a) => {
      if (a.userInputId !== userInputId) return
      if (typeof a.chunk === 'string') {
        const { chunk } = a

        rawChunkBuffer.push(chunk)

        const trimmed = chunk.trim()
        for (const tag of ONE_TIME_TAGS) {
          if (
            trimmed.startsWith(`<${tag}>`) &&
            trimmed.endsWith(closeXml(tag))
          ) {
            if (this.oneTimeFlags[tag]) {
              return
            }
            Spinner.get().stop()
            const warningMessage = trimmed
              .replace(`<${tag}>`, '')
              .replace(closeXml(tag), '')
            process.stdout.write(yellow(`\n\n${warningMessage}\n\n`))
            this.oneTimeFlags[tag as (typeof ONE_TIME_LABELS)[number]] = true
            return
          }
        }

        if (chunk && chunk.trim()) {
          if (!streamStarted && chunk.trim()) {
            streamStarted = true
            onStreamStart()
          }
        }

        try {
          xmlStreamParser.write(chunk, 'utf8')
        } catch (e) {
          logger.error(
            {
              errorMessage: e instanceof Error ? e.message : String(e),
              errorStack: e instanceof Error ? e.stack : undefined,
              chunk,
            },
            'Error writing chunk to XML stream parser',
          )
        }
      } else {
        onChunk(a.chunk)
      }
    })

    let stepsCount = 0
    let toolCallsCount = 0
    unsubscribeComplete = this.webSocket.subscribe(
      'prompt-response',
      async (action) => {
        const parsedAction = PromptResponseSchema.safeParse(action)
        if (!parsedAction.success) {
          const message = [
            'Received invalid prompt response from server:',
            JSON.stringify(parsedAction.error.errors),
            'If this issues persists, please contact support@codebuff.com',
          ].join('\n')
          console.error(message)
          logger.error(
            {
              errorMessage: message,
              action,
              eventId: AnalyticsEvent.MALFORMED_PROMPT_RESPONSE,
            },
            'Malformed prompt response',
          )
          return
        }
        if (action.promptId !== userInputId) return
        const a = parsedAction.data
        this.responseComplete = true

        Spinner.get().stop()

        this.sessionState = a.sessionState
        const toolResults: ToolResult[] = []

        stepsCount++
        console.log('\n')

        // If we had any file changes, update the project context
        if (DiffManager.getChanges().length > 0) {
          this.fileContext = await getProjectFileContext(getProjectRoot(), {})
        }

        const endTime = Date.now()
        const latencyMs = endTime - startTime
        trackEvent(AnalyticsEvent.USER_INPUT_COMPLETE, {
          userInputId,
          latencyMs,
          stepsCount,
          toolCallsCount,
        })

        this.lastToolResults = toolResults

        askConfig: if (
          this.oneTimeFlags[SHOULD_ASK_CONFIG] &&
          !this.oneTimeFlags[ASKED_CONFIG]
        ) {
          this.oneTimeFlags[ASKED_CONFIG] = true
          if (existsSync(path.join(getProjectRoot(), CONFIG_FILE_NAME))) {
            break askConfig
          }

          console.log(
            '\n\n' +
              yellow(`✨ Recommended: run the 'init' command in order to create a configuration file!

If you would like background processes (like this one) to run automatically whenever Codebuff starts, creating a ${CONFIG_FILE_NAME} config file can improve your workflow.
Go to https://www.codebuff.com/config for more information.`) +
              '\n',
          )
        }

        if (this.sessionState) {
          setMessages(this.sessionState.mainAgentState.messageHistory)
        }

        // Mark any subagents as inactive when the main response completes
        // This is a simple heuristic - in practice you might want more sophisticated tracking
        const allSubagentIds = getAllSubagentIds()
        allSubagentIds.forEach((agentId: string) => {
          markSubagentInactive(agentId)
        })

        // Show total credits used for this prompt if significant
        const credits =
          this.creditsByPromptId[userInputId]?.reduce((a, b) => a + b, 0) ?? 0
        if (credits >= REQUEST_CREDIT_SHOW_THRESHOLD) {
          console.log(
            `\n\n${pluralize(credits, 'credit')} used for this request.`,
          )
        }

        if (DiffManager.getChanges().length > 0) {
          let checkpointAddendum = ''
          try {
            checkpointAddendum = ` or "checkpoint ${checkpointManager.getLatestCheckpoint().id}" to revert`
          } catch (error) {
            // No latest checkpoint, don't show addendum
            logger.info(
              {
                errorMessage:
                  error instanceof Error ? error.message : String(error),
                errorStack: error instanceof Error ? error.stack : undefined,
              },
              'No latest checkpoint for addendum',
            )
          }
          console.log(
            `\n\nComplete! Type "diff" to review changes${checkpointAddendum}.\n`,
          )

          if (this.isInitializing) {
            this.isInitializing = false
            // Show tips and start background processes
            this.handleInitializationComplete()
          }

          this.freshPrompt()
        }

        if (!ASYNC_AGENTS_ENABLED) {
          xmlStreamParser.end()
          unsubscribeChunks()
          unsubscribeComplete()
        }
        resolveResponse({ ...a, wasStoppedByUser: false })
      },
    )

    // Reset flags at the start of each response
    this.responseComplete = false

    return {
      responsePromise,
      stopResponse,
    }
  }

  public async getUsage() {
    try {
      // Check for organization coverage first
      const coverage = await this.checkRepositoryCoverage()

      const response = await fetch(`${backendUrl}/api/usage`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          fingerprintId: await this.fingerprintId,
          authToken: this.user?.authToken,
          ...(coverage.isCovered &&
            coverage.organizationId && { orgId: coverage.organizationId }),
        }),
      })

      const data = await response.json()

      // Use zod schema to validate response
      const parsedResponse = UsageReponseSchema.parse(data)

      if ((data as any).type === 'action-error') {
        console.error(red((data as any).message))
        logger.error(
          {
            errorMessage: (data as any).message,
          },
          'Action error',
        )
        return
      }

      this.setUsage(parsedResponse)

      // Calculate session usage and total for display
      const totalCreditsUsedThisSession = Object.values(this.creditsByPromptId)
        .flat()
        .reduce((sum, credits) => sum + credits, 0)

      let sessionUsageMessage = `Session usage: ${totalCreditsUsedThisSession.toLocaleString()}`
      if (this.usageData.remainingBalance !== null) {
        const remainingColor =
          this.usageData.remainingBalance === null
            ? yellow
            : this.usageData.remainingBalance <= 0
              ? red
              : this.usageData.remainingBalance <= LOW_BALANCE_THRESHOLD
                ? red
                : green
        sessionUsageMessage += `. Credits Remaining: ${remainingColor(this.usageData.remainingBalance.toLocaleString())}`
      } else {
        sessionUsageMessage += '.'
      }
      console.log(sessionUsageMessage)

      if (coverage.isCovered && coverage.organizationName) {
        // When covered by an organization, show organization information
        console.log(
          green(
            `🏢 Your usage in this repository is covered by ${bold(coverage.organizationName)}.`,
          ),
        )
        // Try to use organizationSlug from the coverage response
        if (coverage.organizationSlug) {
          const orgUsageLink = `${websiteUrl}/orgs/${coverage.organizationSlug}`
          console.log(
            `View your organization's usage details: ${underline(blue(orgUsageLink))}`,
          )
        }
      } else {
        // Only show personal usage details when not covered by an organization
        const usageLink = `${websiteUrl}/usage` // Personal usage link

        // Only show personal credit renewal if not covered by an organization
        if (this.usageData.next_quota_reset) {
          const resetDate = new Date(this.usageData.next_quota_reset)
          const today = new Date()
          const isToday = resetDate.toDateString() === today.toDateString()

          const dateDisplay = isToday
            ? resetDate.toLocaleString() // Show full date and time for today
            : resetDate.toLocaleDateString() // Just show date otherwise

          console.log(
            `Free credits will renew on ${dateDisplay}. Details: ${underline(blue(usageLink))}`,
          )
        }

        this.showUsageWarning()
      }
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
        },
        'Error checking usage',
      )
      console.error(
        red(
          `Error checking usage: Please reach out to ${process.env.NEXT_PUBLIC_SUPPORT_EMAIL} for help.`,
        ),
      )
      // Check if it's a ZodError for more specific feedback
      if (error instanceof z.ZodError) {
        console.error(red('Data validation failed:'), error.errors)
        logger.error(
          {
            errorMessage: 'Data validation failed',
            errors: error.errors,
          },
          'Data validation failed',
        )
      } else {
        console.error(error)
        logger.error(
          {
            errorMessage:
              error instanceof Error ? error.message : String(error),
            errorStack: error instanceof Error ? error.stack : undefined,
          },
          'Error checking usage',
        )
      }
    } finally {
      this.freshPrompt()
    }
  }

  public async warmContextCache() {
    const fileContext = await getProjectFileContext(getProjectRoot(), {})
    if (!fileContext) {
      throw new Error('Failed to initialize project file context')
    }

    await validateAgentConfigsIfAuthenticated(
      this.user,
      fileContext.agentTemplates,
    )

    this.webSocket.subscribe('init-response', (a) => {
      const parsedAction = InitResponseSchema.safeParse(a)
      if (!parsedAction.success) {
        return
      }

      // Store agent names for tool renderer (merge backend and local agents)
      if (parsedAction.data.agentNames) {
        const localAgentNames = getLoadedAgentNames()
        this.agentNames = {
          ...parsedAction.data.agentNames,
          ...localAgentNames,
        }
      }

      // Log the message if it's defined
      if (parsedAction.data.message) {
        console.log(`\n${parsedAction.data.message}`)
        this.freshPrompt()
      }

      // Set initial usage data from the init response
      this.setUsage(parsedAction.data)
    })

    const initAction: Extract<ClientAction, { type: 'init' }> = {
      type: 'init',
      fingerprintId: await this.fingerprintId,
      authToken: this.user?.authToken,
      fileContext,
      // Add repoUrl here as per the diff for client.ts
      repoUrl: loggerContext.repoUrl,
    }
    sendActionAndHandleError(this.webSocket, initAction)

    await this.fetchStoredApiKeyTypes()
  }

  /**
   * Checks if the current repository is covered by an organization.
   * @param remoteUrl Optional remote URL. If not provided, will try to get from git config.
   * @returns Promise<{ isCovered: boolean; organizationName?: string; organizationId?: string; organizationSlug?: string; error?: string }>
   */
  public async checkRepositoryCoverage(remoteUrl?: string): Promise<{
    isCovered: boolean
    organizationName?: string
    organizationId?: string
    organizationSlug?: string
    error?: string
  }> {
    try {
      // Always use getRepoMetrics to get repo info, passing remoteUrl if provided
      let repoMetrics: Awaited<ReturnType<typeof getRepoMetrics>>
      try {
        repoMetrics = await getRepoMetrics(remoteUrl)
      } catch (error) {
        return {
          isCovered: false,
          error: 'Could not get repository information',
        }
      }

      const { repoUrl, owner, repo } = repoMetrics

      if (!repoUrl) {
        return { isCovered: false, error: 'No remote URL found' }
      }

      if (!owner || !repo) {
        return { isCovered: false, error: 'Could not parse repository URL' }
      }

      // Check if user is authenticated
      if (!this.user || !this.user.authToken) {
        return { isCovered: false, error: 'User not authenticated' }
      }

      // Call backend API to check if repo is covered by organization
      const response = await fetch(`${backendUrl}/api/orgs/is-repo-covered`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${this.user.authToken}`,
        },
        body: JSON.stringify({
          owner: owner.toLowerCase(),
          repo: repo.toLowerCase(),
          remoteUrl: repoUrl,
        }),
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        return {
          isCovered: false,
          error:
            (errorData as any).error ||
            `HTTP ${response.status}: ${response.statusText}`,
        }
      }

      const data: any = await response.json()
      return {
        isCovered: data.isCovered || false,
        organizationName: data.organizationName,
        organizationId: data.organizationId,
        organizationSlug: data.organizationSlug,
      }
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          remoteUrl,
        },
        'Error checking repository coverage',
      )
      return {
        isCovered: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      }
    }
  }
}

fileStates.preContent:
import { exec } from 'child_process'
import fs, { existsSync, statSync } from 'fs'
import os from 'os'
import path, { isAbsolute } from 'path'
import { promisify } from 'util'
import { Worker } from 'worker_threads'

import { getFileTokenScores } from '@codebuff/code-map'
import {
  AGENT_TEMPLATES_DIR,
  FILE_READ_STATUS,
  toOptionalFile,
} from '@codebuff/common/old-constants'
import {
  codebuffConfigFile,
  codebuffConfigFileBackup,
} from '@codebuff/common/json-config/constants'
import {
  flattenTree,
  getProjectFileTree,
  parseGitignore,
} from '@codebuff/common/project-file-tree'
import { ensureDirectoryExists } from '@codebuff/common/util/file'
import { filterObject } from '@codebuff/common/util/object'
import { createPatch } from 'diff'
import { green } from 'picocolors'

import { loadedAgents, loadLocalAgents } from './agents/load-agents'
import { checkpointManager } from './checkpoints/checkpoint-manager'
import { CONFIG_DIR } from './credentials'
import { loadCodebuffConfig } from './json-config/parser'
import { findGitRoot, gitCommandIsAvailable } from './utils/git'
import { logger } from './utils/logger'
import { getSystemInfo } from './utils/system-info'
import { getScrapedContentBlocks, parseUrlsFromContent } from './web-scraper'

import type { ProjectFileContext } from '@codebuff/common/util/file'

// Global variables for chat management
// Initialize chat ID on first import with singleton pattern
let currentChatId: string | null = null

function initializeChatId(providedChatId?: string): string {
  if (currentChatId === null) {
    currentChatId =
      providedChatId || new Date().toISOString().replace(/:/g, '-')
  }
  return currentChatId
}

// Function to set chat ID from external source (like worker message)
export function setChatIdFromExternal(chatId: string): void {
  if (currentChatId === null) {
    currentChatId = chatId
  }
}

export function getCurrentChatId() {
  if (currentChatId === null) {
    initializeChatId()
  }
  return currentChatId!
}

export function startNewChat() {
  const oldId = currentChatId
  currentChatId = new Date().toISOString().replace(/:/g, '-')
  return currentChatId
}

// Get the project-specific data directory
export function getProjectDataDir(): string {
  const root = getProjectRoot()
  if (!root) {
    throw new Error('Project root not set. Call setProjectRoot() first.')
  }

  const baseName = path.basename(root)
  const baseDir = path.join(CONFIG_DIR, 'projects', baseName)

  // TODO: Need to handle duplicate project directories after adding automatic
  // feedback feature
  return baseDir
}

export function getCurrentChatDir(): string {
  const chatId = getCurrentChatId()
  const dir = path.join(getProjectDataDir(), 'chats', chatId)
  ensureDirectoryExists(dir)
  return dir
}

const execAsync = promisify(exec)

let projectRoot: string

export function setProjectRoot(dir: string, setCwd: boolean = false) {
  if (existsSync(dir)) {
    if (projectRoot && projectRoot !== dir) {
      checkpointManager.clearCheckpoints(true)

      console.log(
        '\n' + green('Directory change:'),
        `Codebuff will read and write files in "${dir}".\n`,
      )
    }
    projectRoot = dir
    if (setCwd) {
      setWorkingDirectory(dir)
    }
    return dir
  }
  if (setCwd) {
    setWorkingDirectory(projectRoot)
  }
  return projectRoot
}

export function getProjectRoot() {
  return projectRoot
}

let workingDirectory: string
export function setWorkingDirectory(dir: string) {
  workingDirectory = dir
  return workingDirectory
}

export function getWorkingDirectory() {
  return workingDirectory
}

export function getStartingDirectory(dir: string | undefined = undefined): {
  cwd: string
  shouldSearch: boolean
} {
  let base
  try {
    base = process.cwd()
  } catch (error) {
    throw new Error(
      'Failed to get current working directory. Is this directory deleted?',
      { cause: error },
    )
  }
  if (!dir) {
    return { cwd: base, shouldSearch: true }
  }
  const dirAbsolute = path.normalize(path.resolve(base, dir))
  if (!existsSync(dirAbsolute) || !statSync(dirAbsolute).isDirectory()) {
    console.log(`Could not find directory ${dirAbsolute}\n`)
    return { cwd: base, shouldSearch: true }
  }
  return { cwd: dirAbsolute, shouldSearch: false }
}

/**
 * Initialize project root for standalone commands that don't go through normal CLI setup
 * @param cwd Optional working directory override
 * @returns Object with projectRoot and workingDir paths
 */
export function initializeProjectRootAndWorkingDir(cwd?: string): {
  projectRoot: string
  workingDir: string
} {
  const { cwd: workingDir, shouldSearch } = getStartingDirectory(cwd)
  const gitRoot = shouldSearch
    ? findGitRoot(workingDir) ?? workingDir
    : workingDir
  const projectRoot = setProjectRoot(gitRoot)
  setWorkingDirectory(workingDir)
  return { projectRoot, workingDir }
}

/**
 * Transforms a relative filepath into an absolute one, using the project root as the base.
 * Handles '..' and '.' in paths correctly. Also handles Windows paths.
 *
 * @param filepath The relative filepath to transform
 * @param projectRoot The absolute path to the project root
 * @returns The absolute filepath
 */
export function toAbsolutePath(filepath: string, projectRoot: string): string {
  // If already absolute, normalize and return
  if (path.isAbsolute(filepath)) {
    return path.normalize(filepath)
  }

  // Handle '..' at the start by resolving against project root
  return path.normalize(path.resolve(projectRoot, filepath))
}

let cachedProjectFileContext: ProjectFileContext | undefined

export function clearCachedProjectFileContext() {
  cachedProjectFileContext = undefined
}

export function initProjectFileContextWithWorker(
  dir: string,
  resetCache: boolean = false,
) {
  if (resetCache) {
    cachedProjectFileContext = undefined
  }

  const workerRelativePath = './workers/project-context.ts'
  const worker = new Worker(
    process.env.IS_BINARY
      ? // Use relative path for compiled binary.
        workerRelativePath
      : // Use absolute path for dev (via bun URL).
        new URL(workerRelativePath, import.meta.url).href,
  )

  // Pass the current chat ID to the worker to ensure consistency
  const mainThreadChatId = getCurrentChatId()
  worker.postMessage({ dir, chatId: mainThreadChatId })

  return new Promise<ProjectFileContext>((resolve, reject) => {
    worker.on('error', (error) => {
      reject(error)
    })
    worker.on('message', (initFileContext) => {
      worker.terminate()
      cachedProjectFileContext = initFileContext
      resolve(initFileContext)
    })
  })
}

/**
 * Retrieves or updates the project file context for a given project.
 *
 * This function gathers comprehensive information about the project's files, structure,
 * and state. It either creates a new context if one doesn't exist for the specified
 * project root, or updates an existing cached context with new information.
 *
 * The context includes:
 * - File tree structure
 * - Token scores for code analysis
 * - Knowledge files (project-specific documentation)
 * - User knowledge files (from home directory)
 * - Git changes and status
 * - Changes since the last file version
 * - Shell configuration files
 * - System information
 *
 * @param {string} projectRoot - The root directory path of the project
 * @param {Record<string, string>} lastFileVersion - Record of the last known file versions
 * @param {FileVersion[][]} newFileVersions - Array of file version arrays, representing the history of file changes
 * @returns {Promise<ProjectFileContext>} A promise that resolves to the project file context object
 */
export const getProjectFileContext = async (
  projectRoot: string,
  lastFileVersion: Record<string, string>,
): Promise<ProjectFileContext> => {
  const gitChanges = await getGitChanges()
  const changesSinceLastChat = getChangesSinceLastFileVersion(lastFileVersion)

  if (
    !cachedProjectFileContext ||
    cachedProjectFileContext.projectRoot !== projectRoot
  ) {
    const fileTree = getProjectFileTree(projectRoot)
    const flattenedNodes = flattenTree(fileTree)
    const allFilePaths = flattenedNodes
      .filter((node) => node.type === 'file')
      .map((node) => node.filePath)
    const knowledgeFilePaths = allFilePaths.filter((filePath) => {
      const lowercaseFilePath = filePath.toLowerCase()
      return (
        lowercaseFilePath.endsWith('knowledge.md') ||
        lowercaseFilePath.endsWith('claude.md') ||
        lowercaseFilePath === codebuffConfigFile.toLowerCase() ||
        lowercaseFilePath === codebuffConfigFileBackup.toLowerCase()
      )
    })

    // Separate agent template files from knowledge files
    const agentTemplatePaths = allFilePaths.filter((filePath) => {
      const lowercaseFilePath = filePath.toLowerCase()
      return (
        filePath.startsWith(AGENT_TEMPLATES_DIR) &&
        (lowercaseFilePath.endsWith('.json') ||
          lowercaseFilePath.endsWith('.md'))
      )
    })

    // Filter out agent template paths from knowledge files to avoid duplication
    const filteredKnowledgeFilePaths = knowledgeFilePaths.filter(
      (filePath) => !filePath.startsWith(AGENT_TEMPLATES_DIR),
    )

    const knowledgeFiles = getExistingFiles(filteredKnowledgeFilePaths)
    const knowledgeFilesWithScrapedContent =
      await addScrapedContentToFiles(knowledgeFiles)

    // Load agent template files
    const agentTemplateFiles = getExistingFiles(agentTemplatePaths)
    const agentTemplateFilesWithScrapedContent =
      await addScrapedContentToFiles(agentTemplateFiles)

    // Get knowledge files from user's home directory
    const homeDir = os.homedir()
    const userKnowledgeFiles = findKnowledgeFilesInDir(homeDir)
    const userKnowledgeFilesWithScrapedContent =
      await addScrapedContentToFiles(userKnowledgeFiles)

    const shellConfigFiles = loadShellConfigFiles()

    const { tokenScores, tokenCallers } = await getFileTokenScores(
      projectRoot,
      allFilePaths,
    )

    // Load codebuff configuration
    const codebuffConfig = loadCodebuffConfig()

    cachedProjectFileContext = {
      projectRoot,
      cwd: projectRoot,
      fileTree,
      fileTokenScores: tokenScores,
      tokenCallers,
      knowledgeFiles: knowledgeFilesWithScrapedContent,
      agentTemplates: loadedAgents,
      codebuffConfig,
      shellConfigFiles,
      systemInfo: getSystemInfo(),
      userKnowledgeFiles: userKnowledgeFilesWithScrapedContent,
      gitChanges,
      changesSinceLastChat,
      fileVersions: [],
    }
  }

  return cachedProjectFileContext
}

/**
 * Retrieves information about the current state of the Git repository.
 *
 * This asynchronous function executes several Git commands to gather comprehensive
 * information about the repository's current state, including:
 * - Current status (modified files, untracked files, etc.)
 * - Uncommitted changes (diff)
 * - Staged changes (cached diff)
 * - Recent commit messages (from the last 10 commits)
 *
 * The function uses the global projectRoot variable to determine which repository
 * to query. If any Git command fails (e.g., if the directory is not a Git repository),
 * the function gracefully handles the error and returns empty strings for all properties.
 *
 * @returns {Promise<{status: string, diff: string, diffCached: string, lastCommitMessages: string}>}
 *          A promise that resolves to an object containing Git repository information:
 *          - status: Output of 'git status' command
 *          - diff: Output of 'git diff' command showing uncommitted changes
 *          - diffCached: Output of 'git diff --cached' command showing staged changes
 *          - lastCommitMessages: Recent commit messages, formatted as a newline-separated string
 */
async function getGitChanges(): Promise<{
  status: string
  diff: string
  diffCached: string
  lastCommitMessages: string
}> {
  if (!gitCommandIsAvailable()) {
    return { status: '', diff: '', diffCached: '', lastCommitMessages: '' }
  }
  const status = execAsync('git status', { cwd: projectRoot })
    .then(({ stdout }) => stdout)
    .catch((error) => {
      logger.error({ error }, 'Failed to get git status')
      return ''
    })

  const diff = execAsync('git diff', { cwd: projectRoot })
    .then(({ stdout }) => stdout)
    .catch((error) => {
      logger.error({ error }, 'Failed to get git diff')
      return ''
    })

  const diffCached = execAsync('git diff --cached', {
    cwd: projectRoot,
  })
    .then(({ stdout }) => stdout)
    .catch((error) => {
      logger.error({ error }, 'Failed to get git diff --cached')
      return ''
    })

  const lastCommitMessages = execAsync('git shortlog HEAD~10..HEAD', {
    cwd: projectRoot,
  })
    .then(({ stdout }) =>
      stdout
        .trim()
        .split('\n')
        .slice(1)
        .reverse()
        .map((line) => line.trim())
        .join('\n'),
    )
    .catch((error) => {
      logger.error({ error }, 'Failed to get lastCommitMessages')
      return ''
    })

  return {
    status: await status,
    diff: await diff,
    diffCached: await diffCached,
    lastCommitMessages: await lastCommitMessages,
  }
}

/**
 * Identifies changes between the last known version of files and their current state on disk.
 *
 * This function compares each file in the provided lastFileVersion record with its current
 * content on disk. For files that have changed, it generates a patch using the diff library's
 * createPatch function. Files that haven't changed or can't be read are filtered out from
 * the result.
 *
 * The function is used to track changes made to files since the last interaction or session,
 * which helps maintain context about what has changed in the project over time.
 *
 * @param {Record<string, string>} lastFileVersion - A record mapping file paths to their
 *        content as of the last known version
 * @returns {Record<string, string>} A record mapping file paths to patch strings for files
 *          that have changed since the last version. Files that haven't changed or couldn't
 *          be read are not included in the result.
 */
export function getChangesSinceLastFileVersion(
  lastFileVersion: Record<string, string>,
): Record<string, string> {
  const changes = Object.entries(lastFileVersion)
    .map(([filePath, lastContents]) => {
      const fullFilePath = path.join(getProjectRoot(), filePath)
      try {
        const currentContent = fs.readFileSync(fullFilePath, 'utf8')
        if (currentContent === lastContents) {
          return [filePath, null] as const
        }
        return [
          filePath,
          createPatch(filePath, lastContents, currentContent),
        ] as const
      } catch (error) {
        if (
          error instanceof Object &&
          'code' in error &&
          error.code === 'ENOENT'
        ) {
          return [filePath, createPatch(filePath, lastContents, '')]
        }
        logger.error({ error }, 'Error reading file while getting file changes')
        return [filePath, null] as const
      }
    })
    .filter(([_, diff]) => diff !== null) as [string, string][]
  return Object.fromEntries(changes)
}

export function getFiles(filePaths: string[]) {
  const result: Record<string, string | null> = {}
  const MAX_FILE_SIZE = 1024 * 1024 // 1MB in bytes
  const ig = parseGitignore(projectRoot, projectRoot)

  for (const filePath of filePaths) {
    if (!filePath) {
      continue
    }

    // Convert absolute paths within project to relative paths
    const relativePath = filePath.startsWith(projectRoot)
      ? path.relative(projectRoot, filePath)
      : filePath
    const fullPath = path.join(projectRoot, relativePath)
    if (isAbsolute(relativePath) || !fullPath.startsWith(projectRoot)) {
      result[relativePath] = FILE_READ_STATUS.OUTSIDE_PROJECT
      continue
    }
    try {
      if (ig.ignores(relativePath)) {
        result[relativePath] = FILE_READ_STATUS.IGNORED
        continue
      }
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          relativePath,
        },
        'Error checking if file is ignored',
      )
      result[relativePath] = FILE_READ_STATUS.ERROR
      continue
    }
    try {
      const stats = fs.statSync(fullPath)
      if (stats.size > MAX_FILE_SIZE) {
        result[relativePath] =
          FILE_READ_STATUS.TOO_LARGE +
          ` [${(stats.size / (1024 * 1024)).toFixed(2)}MB]`
      } else {
        const content = fs.readFileSync(fullPath, 'utf8')
        result[relativePath] = content
      }
    } catch (error) {
      if (
        error &&
        typeof error === 'object' &&
        'code' in error &&
        error.code === 'ENOENT'
      ) {
        result[relativePath] = FILE_READ_STATUS.DOES_NOT_EXIST
      } else {
        logger.error(
          {
            errorMessage:
              error instanceof Error ? error.message : String(error),
            errorStack: error instanceof Error ? error.stack : undefined,
            fullPath,
          },
          'Error reading file',
        )
        result[relativePath] = FILE_READ_STATUS.ERROR
      }
    }
  }
  return result
}
export function getFilesOrNull(filePaths: string[]) {
  const result = getFiles(filePaths)
  return Object.fromEntries(
    Object.entries(result).map(([filePath, content]) => [
      filePath,
      toOptionalFile(content),
    ]),
  )
}

export function getExistingFiles(filePaths: string[]) {
  return filterObject(
    getFilesOrNull(filePaths),
    (value) => value !== null,
  ) as Record<string, string>
}
export async function addScrapedContentToFiles(files: Record<string, string>) {
  const newFiles = { ...files }
  await Promise.all(
    Object.entries(files).map(async ([filePath, content]) => {
      const urls = parseUrlsFromContent(content)
      const scrapedContent = await getScrapedContentBlocks(urls)

      newFiles[filePath] =
        content +
        (scrapedContent.length > 0 ? '\n' : '') +
        scrapedContent.join('\n')
    }),
  )
  return newFiles
}

function findKnowledgeFilesInDir(dir: string): Record<string, string> {
  const result: Record<string, string> = {}
  try {
    const files = fs.readdirSync(dir, { withFileTypes: true })
    for (const file of files) {
      if (!file.isDirectory() && file.name.endsWith('knowledge.md')) {
        const fullPath = path.join(dir, file.name)
        try {
          const content = fs.readFileSync(fullPath, 'utf8')
          result[file.name] = content
        } catch (error) {
          // Skip files we can't read
          logger.error(
            {
              errorMessage:
                error instanceof Error ? error.message : String(error),
              errorStack: error instanceof Error ? error.stack : undefined,
              fullPath,
            },
            'Error reading knowledge file',
          )
        }
      }
    }
  } catch (error) {
    // Skip directories we can't read
    logger.error(
      {
        errorMessage: error instanceof Error ? error.message : String(error),
        errorStack: error instanceof Error ? error.stack : undefined,
        dir,
      },
      'Error reading directory for knowledge files',
    )
  }
  return result
}

export function getFilesAbsolutePath(filePaths: string[]) {
  const result: Record<string, string | null> = {}
  for (const filePath of filePaths) {
    try {
      const content = fs.readFileSync(filePath, 'utf8')
      result[filePath] = content
    } catch (error) {
      logger.error(
        {
          errorMessage: error instanceof Error ? error.message : String(error),
          errorStack: error instanceof Error ? error.stack : undefined,
          filePath,
        },
        'Error reading file by absolute path',
      )
      result[filePath] = null
    }
  }
  return result
}

export function setFiles(files: Record<string, string>) {
  for (const [filePath, content] of Object.entries(files)) {
    const fullPath = path.join(projectRoot, filePath)
    fs.writeFileSync(fullPath, content, 'utf8')
  }
}

const loadShellConfigFiles = () => {
  const homeDir = os.homedir()
  const configFiles = [
    path.join(homeDir, '.bashrc'),
    path.join(homeDir, '.bash_profile'),
    path.join(homeDir, '.bash_login'),
    path.join(homeDir, '.profile'),
    path.join(homeDir, '.zshrc'),
    path.join(homeDir, '.kshrc'),
  ]
  const files = getFilesAbsolutePath(configFiles)
  return filterObject(files, (value) => value !== null) as Record<
    string,
    string
  >
}

