import http from 'http'

import { setupBigQuery } from '@codebuff/bigquery'
import { flushAnalytics, initAnalytics } from '@codebuff/common/analytics'
import { env } from '@codebuff/internal'
import cors from 'cors'
import express from 'express'

import {
  getTracesForUserHandler,
  relabelForUserHandler,
} from './admin/relabelRuns'
import { isRepoCoveredHandler } from './api/org'
import usageHandler from './api/usage'
import { checkAdmin } from './util/check-auth'
import { logger } from './util/logger'
import {
  sendRequestReconnect,
  waitForAllClientsDisconnected,
  listen as webSocketListen,
} from './websockets/server'

const app = express()
const port = env.PORT

app.use(express.json())

app.get('/', (req, res) => {
  res.send('Codebuff Backend Server')
})

app.get('/healthz', (req, res) => {
  res.send('ok')
})

app.post('/api/usage', usageHandler)
app.post('/api/orgs/is-repo-covered', isRepoCoveredHandler)

// Enable CORS for preflight requests to the admin relabel endpoint
app.options('/api/admin/relabel-for-user', cors())

// Add the admin routes with CORS and auth
app.get(
  '/api/admin/relabel-for-user',
  cors(),
  checkAdmin,
  getTracesForUserHandler,
)

app.post(
  '/api/admin/relabel-for-user',
  cors(),
  checkAdmin,
  relabelForUserHandler,
)

app.use(
  (
    err: Error,
    req: express.Request,
    res: express.Response,
    next: express.NextFunction,
  ) => {
    logger.error({ err }, 'Something broke!')
    res.status(500).send('Something broke!')
  },
)

// Initialize BigQuery before starting the server
setupBigQuery().catch((err) => {
  logger.error(
    {
      error: err,
      stack: err.stack,
      message: err.message,
      name: err.name,
      code: err.code,
      details: err.details,
    },
    'Failed to initialize BigQuery client',
  )
})

initAnalytics()

const server = http.createServer(app)

server.listen(port, () => {
  logger.debug(`🚀 Server is running on port ${port}`)
  console.log(`🚀 Server is running on port ${port}`)
})

webSocketListen(server, '/ws')

let shutdownInProgress = false
// Graceful shutdown handler for both SIGTERM and SIGINT
function handleShutdown(signal: string) {
  flushAnalytics()
  if (env.NEXT_PUBLIC_CB_ENVIRONMENT === 'dev') {
    server.close((error) => {
      console.log('Received error closing server', { error })
    })
    process.exit(0)
  }
  if (shutdownInProgress) {
    console.log(`\nReceived ${signal}. Already shutting down...`)
    return
  }
  shutdownInProgress = true
  console.log(`\nReceived ${signal}. Starting graceful shutdown...`)

  // Don't shutdown, instead ask clients to disconnect from us
  sendRequestReconnect()

  waitForAllClientsDisconnected().then(() => {
    console.log('All clients disconnected. Shutting down...')
    process.exit(0)
  })

  // If graceful shutdown is not achieved after 5 minutes,
  // force exit the process
  setTimeout(() => {
    console.error(
      'Could not close connections in time, forcefully shutting down',
    )
    process.exit(1)
  }, 300000).unref()
}

process.on('SIGTERM', () => handleShutdown('SIGTERM'))
process.on('SIGINT', () => handleShutdown('SIGINT'))

process.on('unhandledRejection', (reason, promise) => {
  // Don't rethrow the error, just log it. Keep the server running.
  const stack = reason instanceof Error ? reason.stack : undefined
  const message = reason instanceof Error ? reason.message : undefined
  const name = reason instanceof Error ? reason.name : undefined
  console.error('unhandledRejection', message, reason, stack)
  logger.error(
    {
      reason,
      stack,
      message,
      name,
      promise,
    },
    `Unhandled promise rejection: ${reason instanceof Error ? reason.message : 'Unknown reason'}`,
  )
})

process.on('uncaughtException', (err, origin) => {
  console.error('uncaughtException', {
    error: err,
    message: err.message,
    stack: err.stack,
    name: err.name,
    origin,
  })
  logger.fatal(
    {
      err,
      stack: err.stack,
      message: err.message,
      name: err.name,
      origin,
    },
    'uncaught exception detected',
  )

  server.close(() => {
    process.exit(1)
  })

  // If a graceful shutdown is not achieved after 1 second,
  // shut down the process completely
  setTimeout(() => {
    process.abort() // exit immediately and generate a core dump file
  }, 1000).unref()
  process.exit(1)
})

import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { sql } from 'drizzle-orm'
import { NextResponse } from 'next/server'

import { logger } from '@/util/logger'

export async function GET() {
  try {
    // Get all published agents with their publisher info
    const agents = await db
      .select({
        id: schema.agentConfig.id,
        version: schema.agentConfig.version,
        data: schema.agentConfig.data,
        created_at: schema.agentConfig.created_at,
        publisher: {
          id: schema.publisher.id,
          name: schema.publisher.name,
          verified: schema.publisher.verified,
        },
      })
      .from(schema.agentConfig)
      .innerJoin(
        schema.publisher,
        sql`${schema.agentConfig.publisher_id} = ${schema.publisher.id}`
      )
      .orderBy(sql`${schema.agentConfig.created_at} DESC`) // Sort by date descending
      .limit(100) // Limit for performance

    // Transform the data to include parsed agent data and mock usage metrics
    const transformedAgents = agents.map((agent) => {
      const agentData = typeof agent.data === 'string' ? JSON.parse(agent.data) : agent.data

      // Mock usage metrics (in a real app, these would come from analytics/usage tables)
      const mockUsageCount = Math.floor(Math.random() * 50000) + 1000
      const mockTotalSpent = Math.floor(Math.random() * 5000) + 100 // $100-$5100
      const mockAvgCostPerInvocation = mockTotalSpent / mockUsageCount
      const mockResponseTime = Math.floor(Math.random() * 3000) + 500 // 500-3500ms

      return {
        id: agent.id,
        name: agentData.name || agent.id,
        description: agentData.description,
        publisher: agent.publisher,
        version: agent.version,
        created_at: agent.created_at,
        usage_count: mockUsageCount,
        total_spent: mockTotalSpent,
        avg_cost_per_invocation: mockAvgCostPerInvocation,
        avg_response_time: mockResponseTime,

        tags: agentData.tags || [],
      }
    })

    // Group by agent name and keep only the latest version of each
    const latestAgents = new Map()
    transformedAgents.forEach((agent) => {
      const key = `${agent.publisher.id}/${agent.name}`
      if (!latestAgents.has(key)) { // Since it's sorted, the first one is the latest
        latestAgents.set(key, agent)
      }
    })

    const result = Array.from(latestAgents.values())

    return NextResponse.json(result)
  } catch (error) {
    logger.error({ error }, 'Error fetching agents')
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import { calculateOrganizationUsageAndBalance } from '@codebuff/billing'
import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { stripeServer } from '@codebuff/common/util/stripe'
import { eq, and } from 'drizzle-orm'
import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import type { OrganizationDetailsResponse } from '@codebuff/common/types/organization'
import type { NextRequest } from 'next/server'

import { authOptions } from '@/app/api/auth/[...nextauth]/auth-options'
import { logger } from '@/util/logger'

interface RouteParams {
  params: { orgId: string }
}

export async function GET(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse<OrganizationDetailsResponse | { error: string }>> {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { orgId } = params

    // Check if user is a member of this organization
    const membership = await db
      .select({
        org: schema.org,
        role: schema.orgMember.role,
      })
      .from(schema.orgMember)
      .innerJoin(schema.org, eq(schema.orgMember.org_id, schema.org.id))
      .where(
        and(
          eq(schema.orgMember.org_id, orgId),
          eq(schema.orgMember.user_id, session.user.id)
        )
      )
      .limit(1)

    if (membership.length === 0) {
      return NextResponse.json(
        { error: 'Organization not found' },
        { status: 404 }
      )
    }

    const { org: organization, role } = membership[0]

    // Get member and repository counts
    const [memberCount, repositoryCount] = await Promise.all([
      db
        .select({ count: schema.orgMember.user_id })
        .from(schema.orgMember)
        .where(eq(schema.orgMember.org_id, orgId))
        .then((result) => result.length),
      db
        .select({ count: schema.orgRepo.id })
        .from(schema.orgRepo)
        .where(
          and(
            eq(schema.orgRepo.org_id, orgId),
            eq(schema.orgRepo.is_active, true)
          )
        )
        .then((result) => result.length),
    ])

    // Get organization credit balance
    let creditBalance: number | undefined
    try {
      const now = new Date()
      const quotaResetDate = new Date(now.getFullYear(), now.getMonth(), 1) // First of current month
      const { balance } = await calculateOrganizationUsageAndBalance(
        orgId,
        quotaResetDate,
        now
      )
      creditBalance = balance.netBalance
    } catch (error) {
      // If no credits exist yet, that's fine
      console.log('No organization credits found:', error)
    }

    const usageAndBalance = await calculateOrganizationUsageAndBalance(
      orgId,
      new Date(),
      new Date()
    )

    const response: OrganizationDetailsResponse = {
      id: organization.id,
      name: organization.name,
      slug: organization.slug,
      description: organization.description || undefined,
      userRole: role,
      memberCount,
      repositoryCount,
      creditBalance: usageAndBalance.balance.netBalance,
      hasStripeSubscription: !!organization.stripe_subscription_id,
      stripeSubscriptionId: organization.stripe_subscription_id || undefined,
    }

    return NextResponse.json(response)
  } catch (error) {
    console.error('Error fetching organization details:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function PATCH(request: NextRequest, { params }: RouteParams) {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { orgId } = params
    const body = await request.json()

    // Check if user is owner or admin
    const membership = await db
      .select({ role: schema.orgMember.role })
      .from(schema.orgMember)
      .where(
        and(
          eq(schema.orgMember.org_id, orgId),
          eq(schema.orgMember.user_id, session.user.id)
        )
      )
      .limit(1)

    if (membership.length === 0) {
      return NextResponse.json(
        { error: 'Organization not found' },
        { status: 404 }
      )
    }

    const { role } = membership[0]
    if (role !== 'owner' && role !== 'admin') {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      )
    }

    // Update organization
    const [updatedOrg] = await db
      .update(schema.org)
      .set({
        name: body.name,
        description: body.description,
        updated_at: new Date(),
      })
      .where(eq(schema.org.id, orgId))
      .returning()

    return NextResponse.json(updatedOrg)
  } catch (error) {
    console.error('Error updating organization:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function DELETE(request: NextRequest, { params }: RouteParams) {
  const { orgId } = params
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    // Check if user is the owner of this organization and get organization details
    const membership = await db
      .select({
        role: schema.orgMember.role,
        organization: schema.org,
      })
      .from(schema.orgMember)
      .innerJoin(schema.org, eq(schema.orgMember.org_id, schema.org.id))
      .where(
        and(
          eq(schema.orgMember.org_id, orgId),
          eq(schema.orgMember.user_id, session.user.id)
        )
      )
      .limit(1)

    if (membership.length === 0) {
      return NextResponse.json(
        { error: 'Organization not found' },
        { status: 404 }
      )
    }

    const { role, organization } = membership[0]
    if (role !== 'owner') {
      return NextResponse.json(
        { error: 'Only organization owners can delete organizations' },
        { status: 403 }
      )
    }

    // Clean up Stripe resources if they exist
    if (organization.stripe_customer_id) {
      try {
        logger.info(
          { orgId, stripeCustomerId: organization.stripe_customer_id },
          'Starting Stripe cleanup for organization deletion'
        )

        // First, cancel all active subscriptions
        const subscriptions = await stripeServer.subscriptions.list({
          customer: organization.stripe_customer_id,
          status: 'active',
        })

        for (const subscription of subscriptions.data) {
          await stripeServer.subscriptions.cancel(subscription.id)
          logger.info(
            { orgId, subscriptionId: subscription.id },
            'Cancelled Stripe subscription for organization'
          )
        }

        // Then delete the Stripe customer (this archives them if they have history)
        await stripeServer.customers.del(organization.stripe_customer_id)
        logger.info(
          { orgId, stripeCustomerId: organization.stripe_customer_id },
          'Deleted Stripe customer for organization'
        )
      } catch (stripeError) {
        // Log Stripe errors but continue with local deletion
        logger.error(
          {
            orgId,
            stripeCustomerId: organization.stripe_customer_id,
            error: stripeError,
          },
          'Failed to clean up Stripe resources during organization deletion'
        )
      }
    }

    // Delete organization (this will cascade to related tables due to foreign key constraints)
    await db.delete(schema.org).where(eq(schema.org.id, orgId))

    logger.info(
      { orgId, organizationName: organization.name },
      'Successfully deleted organization'
    )

    return NextResponse.json({ success: true })
  } catch (error) {
    logger.error({ orgId, error }, 'Error deleting organization')
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import { DrizzleAdapter } from '@auth/drizzle-adapter'
import { processAndGrantCredit } from '@codebuff/billing'
import { trackEvent } from '@codebuff/common/analytics'
import { DEFAULT_FREE_CREDITS_GRANT } from '@codebuff/common/constants'
import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { getNextQuotaReset } from '@codebuff/common/util/dates'
import { generateCompactId } from '@codebuff/common/util/string'
import { stripeServer } from '@codebuff/common/util/stripe'
import { logSyncFailure } from '@codebuff/common/util/sync-failure'
import { loops, env } from '@codebuff/internal'
import { eq } from 'drizzle-orm'
import GitHubProvider from 'next-auth/providers/github'

import type { NextAuthOptions } from 'next-auth'
import type { Adapter } from 'next-auth/adapters'

import { logger } from '@/util/logger'

async function createAndLinkStripeCustomer(
  userId: string,
  email: string | null,
  name: string | null
): Promise<string | null> {
  if (!email || !name) {
    logger.warn(
      { userId },
      'User email or name missing, cannot create Stripe customer.'
    )
    return null
  }
  try {
    const customer = await stripeServer.customers.create({
      email,
      name,
      metadata: {
        user_id: userId,
      },
    })

    // Create subscription with the usage price
    await stripeServer.subscriptions.create({
      customer: customer.id,
      items: [{ price: env.STRIPE_USAGE_PRICE_ID }],
    })

    await db
      .update(schema.user)
      .set({
        stripe_customer_id: customer.id,
        stripe_price_id: env.STRIPE_USAGE_PRICE_ID,
      })
      .where(eq(schema.user.id, userId))

    logger.info(
      { userId, customerId: customer.id },
      'Stripe customer created with usage subscription and linked to user.'
    )
    return customer.id
  } catch (error) {
    const errorMessage =
      error instanceof Error
        ? error.message
        : 'Unknown error creating Stripe customer'
    logger.error(
      { userId, error },
      'Failed to create Stripe customer or update user record.'
    )
    await logSyncFailure(userId, errorMessage)
    return null
  }
}

async function createInitialCreditGrant(
  userId: string,
  expiresAt: Date | null
): Promise<void> {
  try {
    const operationId = `free-${userId}-${generateCompactId()}`
    const nextQuotaReset = getNextQuotaReset(expiresAt)

    await processAndGrantCredit(
      userId,
      DEFAULT_FREE_CREDITS_GRANT,
      'free',
      'Initial free credits',
      nextQuotaReset,
      operationId
    )

    logger.info(
      {
        userId,
        operationId,
        creditsGranted: DEFAULT_FREE_CREDITS_GRANT,
        expiresAt: nextQuotaReset,
      },
      'Initial free credit grant created.'
    )
  } catch (grantError) {
    const errorMessage =
      grantError instanceof Error
        ? grantError.message
        : 'Unknown error creating initial credit grant'
    logger.error(
      { userId, error: grantError },
      'Failed to create initial credit grant.'
    )
    await logSyncFailure(userId, errorMessage)
  }
}

export const authOptions: NextAuthOptions = {
  adapter: DrizzleAdapter(db, {
    usersTable: schema.user,
    accountsTable: schema.account,
    sessionsTable: schema.session,
    verificationTokensTable: schema.verificationToken,
  }) as Adapter,
  providers: [
    GitHubProvider({
      clientId: env.CODEBUFF_GITHUB_ID,
      clientSecret: env.CODEBUFF_GITHUB_SECRET,
    }),
  ],
  session: {
    strategy: 'database',
    maxAge: 30 * 24 * 60 * 60, // 30 days
  },
  callbacks: {
    async session({ session, user }) {
      if (session.user) {
        session.user.id = user.id
        session.user.image = user.image
        session.user.name = user.name
        session.user.email = user.email
        session.user.stripe_customer_id = user.stripe_customer_id
        session.user.stripe_price_id = user.stripe_price_id
      }
      return session
    },
    async redirect({ url, baseUrl }) {
      const potentialRedirectUrl = new URL(url, baseUrl)
      const authCode = potentialRedirectUrl.searchParams.get('auth_code')

      if (authCode) {
        const onboardUrl = new URL(`${baseUrl}/onboard`)
        potentialRedirectUrl.searchParams.forEach((value, key) => {
          onboardUrl.searchParams.set(key, value)
        })
        logger.info(
          { url, authCode, redirectTarget: onboardUrl.toString() },
          'Redirecting CLI flow to /onboard'
        )
        return onboardUrl.toString()
      }

      if (url.startsWith('/') || potentialRedirectUrl.origin === baseUrl) {
        logger.info(
          { url, redirectTarget: potentialRedirectUrl.toString() },
          'Redirecting web flow to callbackUrl'
        )
        return potentialRedirectUrl.toString()
      }

      logger.info(
        { url, baseUrl, redirectTarget: baseUrl },
        'Callback URL is external or invalid, redirecting to baseUrl'
      )
      return baseUrl
    },
  },
  events: {
    createUser: async ({ user }) => {
      logger.info(
        { userId: user.id, email: user.email },
        'createUser event triggered'
      )

      // Get all user data we need upfront
      const userData = await db.query.user.findFirst({
        where: eq(schema.user.id, user.id),
        columns: {
          id: true,
          email: true,
          name: true,
          next_quota_reset: true,
        },
      })

      if (!userData) {
        logger.error({ userId: user.id }, 'User data not found after creation')
        return
      }

      const customerId = await createAndLinkStripeCustomer(
        userData.id,
        userData.email,
        userData.name
      )

      if (customerId) {
        await createInitialCreditGrant(userData.id, userData.next_quota_reset)
      }

      // Call the imported function
      await loops.sendSignupEventToLoops(
        userData.id,
        userData.email,
        userData.name
      )

      trackEvent(AnalyticsEvent.SIGNUP, userData.id)

      logger.info({ user }, 'createUser event processing finished.')
    },
  },
}

import { convertJsonSchemaToZod } from 'zod-from-json-schema'

import {
  formatSubagentError,
  validateSubagents,
} from '../util/agent-template-validation'
import { logger } from '../util/logger'
import {
  DynamicAgentConfigSchema,
  DynamicAgentTemplateSchema,
} from '../types/dynamic-agent-template'
import type { AgentTemplate } from '../types/agent-template'
import type { DynamicAgentTemplate } from '../types/dynamic-agent-template'

export interface DynamicAgentValidationError {
  filePath: string
  message: string
}

/**
 * Collect all agent IDs from template files without full validation
 */
export function collectAgentIds(
  agentTemplates: Record<string, DynamicAgentTemplate> = {},
): string[] {
  const agentIds: string[] = []
  const jsonFiles = Object.keys(agentTemplates)

  for (const filePath of jsonFiles) {
    try {
      const content = agentTemplates[filePath]
      if (!content) {
        continue
      }

      // Extract the agent ID if it exists
      if (content.id && typeof content.id === 'string') {
        agentIds.push(content.id)
      }
    } catch (error) {
      // Log but don't fail the collection process for other errors
      logger.debug(
        { filePath, error },
        'Failed to extract agent ID during collection phase',
      )
    }
  }

  return agentIds
}

/**
 * Validate and load dynamic agent templates from user-provided agentTemplates
 */
export function validateAgents(agentTemplates: Record<string, any> = {}): {
  templates: Record<string, AgentTemplate>
  validationErrors: DynamicAgentValidationError[]
} {
  const templates: Record<string, AgentTemplate> = {}
  const validationErrors: DynamicAgentValidationError[] = []

  const hasAgentTemplates = Object.keys(agentTemplates).length > 0

  if (!hasAgentTemplates) {
    return {
      templates,
      validationErrors,
    }
  }

  const agentKeys = Object.keys(agentTemplates)

  // Pass 1: Collect all agent IDs from template files
  const dynamicAgentIds = collectAgentIds(agentTemplates)

  // Pass 2: Load and validate each agent template
  for (const agentKey of agentKeys) {
    const content = agentTemplates[agentKey]
    try {
      if (!content) {
        continue
      }

      const validationResult = validateSingleAgent(content, {
        filePath: agentKey,
        dynamicAgentIds,
      })

      if (!validationResult.success) {
        validationErrors.push({
          filePath: agentKey,
          message: validationResult.error!,
        })
        continue
      }

      if (templates[validationResult.agentTemplate!.id]) {
        const agentContext = validationResult.agentTemplate!.displayName 
          ? `Agent "${validationResult.agentTemplate!.id}" (${validationResult.agentTemplate!.displayName})`
          : `Agent "${validationResult.agentTemplate!.id}"`

        validationErrors.push({
          filePath: agentKey,
          message: `${agentContext}: Duplicate agent ID`,
        })
        continue
      }
      templates[validationResult.agentTemplate!.id] =
        validationResult.agentTemplate!
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'

      // Try to extract agent context for better error messages
      const agentContext = content?.id 
        ? `Agent "${content.id}"${content.displayName ? ` (${content.displayName})` : ''}`
        : `Agent in ${agentKey}`

      validationErrors.push({
        filePath: agentKey,
        message: `${agentContext}: ${errorMessage}`,
      })

      logger.warn(
        { filePath: agentKey, error: errorMessage },
        'Failed to load dynamic agent template',
      )
    }
  }

  return {
    templates,
    validationErrors,
  }
}

/**
 * Validates a single dynamic agent template and converts it to an AgentTemplate.
 * This is a plain function equivalent to the core logic of loadSingleAgent.
 *
 * @param dynamicAgentIds - Array of all available dynamic agent IDs for validation
 * @param template - The raw agent template to validate (any type)
 * @param options - Optional configuration object
 * @param options.filePath - Optional file path for error context
 * @param options.skipSubagentValidation - Skip subagent validation when loading from database
 * @returns Validation result with either the converted AgentTemplate or an error
 */
export function validateSingleAgent(
  template: any,
  options?: {
    dynamicAgentIds?: string[]
    filePath?: string
    skipSubagentValidation?: boolean
  },
): {
  success: boolean
  agentTemplate?: AgentTemplate
  error?: string
} {
  const {
    filePath,
    skipSubagentValidation = true,
    dynamicAgentIds = [],
  } = options || {}

  try {
    // First validate against the Zod schema
    let validatedConfig: DynamicAgentTemplate
    try {
      const typedAgentConfig = DynamicAgentConfigSchema.parse(template)

      // Convert handleSteps function to string if present
      let handleStepsString: string | undefined
      if (template.handleSteps) {
        handleStepsString = template.handleSteps.toString()
      }

      validatedConfig = DynamicAgentTemplateSchema.parse({
        ...typedAgentConfig,
        systemPrompt: typedAgentConfig.systemPrompt || '',
        instructionsPrompt: typedAgentConfig.instructionsPrompt || '',
        stepPrompt: typedAgentConfig.stepPrompt || '',
        handleSteps: handleStepsString,
      })
    } catch (error: any) {
      // Try to extract agent context for better error messages
      const agentContext = template.id 
        ? `Agent "${template.id}"${template.displayName ? ` (${template.displayName})` : ''}`
        : filePath ? `Agent in ${filePath}` : 'Agent'

      return {
        success: false,
        error: `${agentContext}: Schema validation failed: ${error.message}`,
      }
    }
    // Validate subagents (skip if requested, e.g., for database agents)
    if (!skipSubagentValidation) {
      const subagentValidation = validateSubagents(
        validatedConfig.subagents,
        dynamicAgentIds,
      )
      if (!subagentValidation.valid) {
        return {
          success: false,
          error: formatSubagentError(
            subagentValidation.invalidAgents,
            subagentValidation.availableAgents,
          ),
        }
      }
    }

    // Convert schemas and handle validation errors
    let inputSchema: AgentTemplate['inputSchema']
    try {
      inputSchema = convertInputSchema(
        validatedConfig.inputSchema?.prompt,
        validatedConfig.inputSchema?.params,
        filePath,
      )
    } catch (error) {
      // Try to extract agent context for better error messages
      const agentContext = validatedConfig.id 
        ? `Agent "${validatedConfig.id}"${validatedConfig.displayName ? ` (${validatedConfig.displayName})` : ''}`
        : filePath ? `Agent in ${filePath}` : 'Agent'

      return {
        success: false,
        error: `${agentContext}: ${
          error instanceof Error ? error.message : 'Schema conversion failed'
        }`,
      }
    }

    // Convert outputSchema if present
    let outputSchema: AgentTemplate['outputSchema']
    if (validatedConfig.outputSchema) {
      try {
        outputSchema = convertJsonSchemaToZod(validatedConfig.outputSchema)
      } catch (error) {
        // Try to extract agent context for better error messages
        const agentContext = validatedConfig.id 
          ? `Agent "${validatedConfig.id}"${validatedConfig.displayName ? ` (${validatedConfig.displayName})` : ''}`
          : filePath ? `Agent in ${filePath}` : 'Agent'

        return {
          success: false,
          error: `${agentContext}: Failed to convert outputSchema to Zod: ${error instanceof Error ? error.message : 'Unknown error'}`,
        }
      }
    }

    // Validate handleSteps if present
    if (validatedConfig.handleSteps) {
      if (!isValidGeneratorFunction(validatedConfig.handleSteps)) {
        // Try to extract agent context for better error messages
        const agentContext = validatedConfig.id 
          ? `Agent "${validatedConfig.id}"${validatedConfig.displayName ? ` (${validatedConfig.displayName})` : ''}`
          : filePath ? `Agent in ${filePath}` : 'Agent'

        return {
          success: false,
          error: `${agentContext}: handleSteps must be a generator function: "function* (params) { ... }". Found: ${validatedConfig.handleSteps.substring(0, 50)}...`,
        }
      }
    }

    // Convert to internal AgentTemplate format
    const agentTemplate: AgentTemplate = {
      ...validatedConfig,
      outputSchema,
      inputSchema,
    }

    return {
      success: true,
      agentTemplate,
    }
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'

    // Try to extract agent context for better error messages
    const agentContext = template?.id 
      ? `Agent "${template.id}"${template.displayName ? ` (${template.displayName})` : ''}`
      : filePath ? `Agent in ${filePath}` : 'Agent'

    return {
      success: false,
      error: `${agentContext}: Error validating agent template: ${errorMessage}`,
    }
  }
}

/**
 * Validates if a string represents a valid generator function
 */
function isValidGeneratorFunction(code: string): boolean {
  const trimmed = code.trim()
  // Check if it's a generator function (must start with function*)
  return trimmed.startsWith('function*')
}

/**
 * Convert JSON schema to Zod schema format using json-schema-to-zod.
 * This is done once during loading to avoid repeated conversions.
 * Throws descriptive errors for validation failures.
 */
function convertInputSchema(
  inputPromptSchema?: Record<string, any>,
  paramsSchema?: Record<string, any>,
  filePath?: string,
): AgentTemplate['inputSchema'] {
  const result: any = {}
  const fileContext = filePath ? ` in ${filePath}` : ''

  // Handle prompt schema
  if (inputPromptSchema) {
    try {
      if (
        typeof inputPromptSchema !== 'object' ||
        Object.keys(inputPromptSchema).length === 0
      ) {
        throw new Error(
          `Invalid inputSchema.prompt${fileContext}: Schema must be a valid non-empty JSON schema object. Found: ${typeof inputPromptSchema}`,
        )
      }
      const promptZodSchema = convertJsonSchemaToZod(inputPromptSchema)
      // Validate that the schema results in string or undefined
      const testResult = promptZodSchema.safeParse('test')
      const testUndefined = promptZodSchema.safeParse(undefined)

      if (!testResult.success && !testUndefined.success) {
        const errorDetails =
          testResult.error?.issues?.[0]?.message || 'validation failed'
        throw new Error(
          `Invalid inputSchema.prompt${fileContext}: Schema must allow string or undefined values. ` +
            `Current schema validation error: ${errorDetails}. ` +
            `Please ensure your JSON schema accepts string types.`,
        )
      }

      result.prompt = promptZodSchema
    } catch (error) {
      if (error instanceof Error && error.message.includes('inputSchema')) {
        // Re-throw our custom validation errors
        throw error
      }

      // Handle json-schema-to-zod conversion errors
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'
      throw new Error(
        `Failed to convert inputSchema.prompt to Zod${fileContext}: ${errorMessage}. ` +
          `Please check that your inputSchema.prompt is a valid non-empty JSON schema object.`,
      )
    }
  }

  // Handle params schema
  if (paramsSchema) {
    try {
      if (
        typeof paramsSchema !== 'object' ||
        Object.keys(paramsSchema).length === 0
      ) {
        throw new Error(
          `Invalid inputSchema.params${fileContext}: Schema must be a valid non-empty JSON schema object. Found: ${typeof paramsSchema}`,
        )
      }
      const paramsZodSchema = convertJsonSchemaToZod(paramsSchema)
      result.params = paramsZodSchema
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'
      throw new Error(
        `Failed to convert inputSchema.params to Zod${fileContext}: ${errorMessage}. ` +
          `Please check that your inputSchema.params is a valid non-empty JSON schema object.`,
      )
    }
  }
  return result
}

import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { eq } from 'drizzle-orm'

// List of admin user emails - single source of truth
const CODEBUFF_ADMIN_USER_EMAILS = [
  'venkateshrameshkumar+1@gmail.com',
  'brandonchenjiacheng@gmail.com',
  'jahooma@gmail.com',
  'charleslien97@gmail.com',
]

/**
 * Check if an email corresponds to a Codebuff admin
 */
export function isCodebuffAdmin(email: string): boolean {
  return CODEBUFF_ADMIN_USER_EMAILS.includes(email)
}

export interface AdminUser {
  id: string
  email: string
  name: string | null
}

export interface AuthResult {
  success: boolean
  error?: {
    type: 'missing-credentials' | 'invalid-token'
    message: string
  }
  user?: {
    id: string
    email: string
    discord_id: string | null
  }
}

/**
 * Check authentication based on auth token and fingerprint ID
 * Returns structured result instead of throwing or logging directly
 */
export async function checkAuthToken({
  fingerprintId,
  authToken,
}: {
  fingerprintId?: string
  authToken?: string
}): Promise<AuthResult> {
  if (!authToken) {
    if (!fingerprintId) {
      return {
        success: false,
        error: {
          type: 'missing-credentials',
          message: 'Auth token and fingerprint ID are missing',
        },
      }
    }
    return { success: true }
  }

  const user = await db
    .select({
      id: schema.user.id,
      email: schema.user.email,
      discord_id: schema.user.discord_id,
    })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, authToken))
    .then((users) => {
      if (users.length === 1) {
        return users[0]
      }
      return undefined
    })

  if (!user) {
    return {
      success: false,
      error: {
        type: 'invalid-token',
        message: 'Invalid auth token',
      },
    }
  }

  return {
    success: true,
    user,
  }
}

/**
 * Check if the current user session corresponds to a Codebuff admin
 * Returns the admin user if authorized, null if not
 * This is a generic version that can be used with any session object
 */
export async function checkSessionIsAdmin(
  session: { user?: { id?: string } } | null,
): Promise<AdminUser | null> {
  if (!session?.user?.id) {
    return null
  }

  const result = await checkUserIsCodebuffAdmin(session.user.id)
  return result
}

/**
 * Check if a user ID corresponds to a Codebuff admin
 * Returns the admin user if authorized, null if not
 */
export async function checkUserIsCodebuffAdmin(
  userId: string,
): Promise<AdminUser | null> {
  try {
    // Get the user from the database to verify email
    const user = await db
      .select({
        id: schema.user.id,
        email: schema.user.email,
        name: schema.user.name,
      })
      .from(schema.user)
      .where(eq(schema.user.id, userId))
      .then((users: any) => users[0])

    if (!user?.email) {
      return null
    }

    const isAdmin = isCodebuffAdmin(user.email)
    if (!isAdmin) {
      return null
    }

    return {
      id: user.id,
      email: user.email,
      name: user.name,
    }
  } catch (error) {
    console.error('checkUserIsCodebuffAdmin: Database error', error)
    return null
  }
}

import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { utils } from '@codebuff/internal'
import { eq } from 'drizzle-orm'

import { logger } from './logger'

import type { ServerAction } from '@codebuff/common/actions'
import type { Request, Response, NextFunction } from 'express'

export const checkAuth = async ({
  fingerprintId,
  authToken,
  clientSessionId,
}: {
  fingerprintId?: string
  authToken?: string
  clientSessionId: string
}): Promise<void | ServerAction> => {
  // Use shared auth check functionality
  const authResult = await utils.checkAuthToken({
    fingerprintId,
    authToken,
  })

  if (!authResult.success) {
    const errorMessage = authResult.error?.message || 'Authentication failed'
    logger.error({ clientSessionId, error: errorMessage }, errorMessage)
    return {
      type: 'action-error',
      message: errorMessage,
    }
  }

  // if (authResult.user) {
  //   // Log successful authentication if we have a user
  //   logger.debug(
  //     { clientSessionId, userId: authResult.user.id },
  //     'Authentication successful'
  //   )
  // }

  return
}

// Express middleware for checking admin access
export const checkAdmin = async (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  // Extract auth token from Authorization header
  const authHeader = req.headers.authorization
  if (!authHeader?.startsWith('Bearer ')) {
    return res
      .status(401)
      .json({ error: 'Missing or invalid Authorization header' })
  }
  const authToken = authHeader.substring(7) // Remove 'Bearer ' prefix

  // Generate a client session ID for this request
  const clientSessionId = `admin-relabel-${Date.now()}`

  // Check authentication
  const authResult = await checkAuth({
    authToken,
    clientSessionId,
  })

  if (authResult) {
    // checkAuth returns an error action if auth fails
    const errorMessage =
      authResult.type === 'action-error'
        ? authResult.message
        : 'Authentication failed'
    return res.status(401).json({ error: errorMessage })
  }

  // Get the user ID associated with this session token
  const user = await db
    .select({
      id: schema.user.id,
      email: schema.user.email,
    })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, authToken))
    .then((users) => users[0])

  if (!user) {
    return res.status(401).json({ error: 'Invalid session' })
  }

  // Check if user has admin access using shared utility
  const adminUser = await utils.checkUserIsCodebuffAdmin(user.id)
  if (!adminUser) {
    logger.warn(
      { userId: user.id, email: user.email, clientSessionId },
      'Unauthorized access attempt to admin endpoint',
    )
    return res.status(403).json({ error: 'Forbidden' })
  }

  // Store user info in request for handlers to use if needed
  // req.user = adminUser // TODO: ensure type check passes

  // Auth passed and user is admin, proceed to next middleware
  next()
  return
}

import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { validateAgents } from '@codebuff/common/templates/agent-validation'
import { publishAgentsRequestSchema } from '@codebuff/common/types/api/agents/publish'
import {
  checkAuthToken,
  determineNextVersion,
  stringifyVersion,
  versionExists,
} from '@codebuff/internal'
import { eq, and, or } from 'drizzle-orm'
import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import { authOptions } from '../../auth/[...nextauth]/auth-options'

import type { DynamicAgentTemplate } from '@codebuff/common/types/dynamic-agent-template'
import type { Version } from '@codebuff/internal'
import type { NextRequest } from 'next/server'

import { logger } from '@/util/logger'

async function getPublishedAgentIds(publisherId: string) {
  const agents = await db
    .select({
      id: schema.agentConfig.id,
      version: schema.agentConfig.version,
    })
    .from(schema.agentConfig)
    .where(eq(schema.agentConfig.publisher_id, publisherId))

  return new Set(agents.map((a) => `${publisherId}/${a.id}@${a.version}`))
}

export async function POST(request: NextRequest) {
  try {
    // Parse request body
    const body = await request.json()
    const parseResult = publishAgentsRequestSchema.safeParse(body)
    if (!parseResult.success) {
      const errorMessages = parseResult.error.issues.map((issue) => {
        const path = issue.path.length > 0 ? `${issue.path.join('.')}: ` : ''
        return `${path}${issue.message}`
      })

      return NextResponse.json(
        {
          error: 'Invalid request body',
          details: errorMessages.join('; '),
          validationErrors: parseResult.error.issues,
        },
        { status: 400 }
      )
    }

    const { data, authToken } = parseResult.data
    const agents = data as DynamicAgentTemplate[] // data is now an array of agents

    // Try cookie-based auth first, then fall back to authToken validation using proper function
    let userId: string | undefined
    const session = await getServerSession(authOptions)

    if (session?.user?.id) {
      userId = session.user.id
    } else if (authToken) {
      const authResult = await checkAuthToken({ authToken })
      if (authResult.success && authResult.user) {
        userId = authResult.user.id
      }
    }

    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Check that all agents have publisher field set
    const agentsWithoutPublisher = agents.filter((agent) => !agent.publisher)
    if (agentsWithoutPublisher.length > 0) {
      const agentIds = agentsWithoutPublisher
        .map((agent) => agent.id)
        .join(', ')
      return NextResponse.json(
        {
          error: 'Publisher field required',
          details: `All agents must have the "publisher" field set. Missing for agents: ${agentIds}`,
        },
        { status: 400 }
      )
    }

    // Check that all agents use the same publisher
    const publisherIds = [...new Set(agents.map((agent) => agent.publisher))]
    if (publisherIds.length > 1) {
      return NextResponse.json(
        {
          error: 'Multiple publishers not allowed',
          details: `All agents in a single request must use the same publisher. Found: ${publisherIds.join(', ')}`,
        },
        { status: 400 }
      )
    }

    const requestedPublisherId = publisherIds[0]!

    // Validate all agents
    const agentMap = agents.reduce(
      (
        acc: Record<string, DynamicAgentTemplate>,
        agent: DynamicAgentTemplate
      ) => {
        acc[agent.id] = agent
        return acc
      },
      {} as Record<string, DynamicAgentTemplate>
    )

    const validationResult = validateAgents(agentMap)

    if (validationResult.validationErrors.length > 0) {
      const errorDetails = validationResult.validationErrors
        .map((err) => err.message)
        .join('\n')

      return NextResponse.json(
        {
          error: 'Agent config validation failed',
          details: errorDetails,
          validationErrors: validationResult.validationErrors,
        },
        { status: 400 }
      )
    }

    // Verify user has access to the requested publisher
    const publisherResult = await db
      .select({
        publisher: schema.publisher,
        organization: schema.org,
      })
      .from(schema.publisher)
      .leftJoin(schema.org, eq(schema.publisher.org_id, schema.org.id))
      .leftJoin(
        schema.orgMember,
        and(
          eq(schema.orgMember.org_id, schema.publisher.org_id),
          eq(schema.orgMember.user_id, userId)
        )
      )
      .where(
        and(
          eq(schema.publisher.id, requestedPublisherId),
          or(
            eq(schema.publisher.user_id, userId),
            and(
              eq(schema.orgMember.user_id, userId),
              or(
                eq(schema.orgMember.role, 'owner'),
                eq(schema.orgMember.role, 'admin')
              )
            )
          )
        )
      )
      .limit(1)

    if (publisherResult.length === 0) {
      return NextResponse.json(
        {
          error: 'Publisher not found or not accessible',
          details: `Publisher '${requestedPublisherId}' not found or you don't have permission to publish to it`,
        },
        { status: 403 }
      )
    }

    const publisher = publisherResult[0].publisher

    // Process all agents atomically
    const agentVersions: { id: string; version: Version; data: any }[] = []

    // First, determine versions for all agents and check for conflicts
    for (const agent of agents) {
      try {
        const version = await determineNextVersion(
          agent.id,
          publisher.id,
          agent.version
        )

        // Check if this version already exists
        const versionAlreadyExists = await versionExists(
          agent.id,
          version,
          publisher.id
        )
        if (versionAlreadyExists) {
          return NextResponse.json(
            {
              error: 'Version already exists',
              details: `Agent '${agent.id}' version '${stringifyVersion(version)}' already exists for publisher '${publisher.id}'`,
            },
            { status: 409 }
          )
        }

        agentVersions.push({
          id: agent.id,
          version,
          data: { ...agent, version: stringifyVersion(version) },
        })
      } catch (error) {
        return NextResponse.json(
          {
            error: 'Version determination failed',
            details: `Failed for agent '${agent.id}': ${error instanceof Error ? error.message : 'Unknown error'}`,
          },
          { status: 400 }
        )
      }
    }

    // Verify that all spawnable agents are either published or part of this request
    const publishingAgentIds = new Set(
      agentVersions.map(
        (agent) =>
          `${requestedPublisherId}/${agent.id}@${stringifyVersion(agent.version)}`
      )
    )
    const publishedAgentIds = await getPublishedAgentIds(requestedPublisherId)

    for (const agent of agents) {
      if (agent.subagents) {
        for (const subagent of agent.subagents) {
          const versionMatch = subagent.match(/^([^/]+)\/(.+)@(.+)$/)
          if (!versionMatch) {
            return NextResponse.json(
              {
                error: 'Invalid spawnable agent format',
                details: `Agent '${agent.id}' references spawnable agent '${subagent}' with an invalid format. Expected format: {publisherId}/{agentId}@{version}`,
              },
              { status: 400 }
            )
          }

          if (
            !publishingAgentIds.has(subagent) &&
            !publishedAgentIds.has(subagent)
          ) {
            return NextResponse.json(
              {
                error: 'Invalid spawnable agent',
                details: `Agent '${agent.id}' references spawnable agent '${subagent}' which is not published and not included in this request.`,
              },
              { status: 400 }
            )
          }
        }
      }
    }

    // If we get here, all agents can be published. Insert them all in a transaction
    const newAgents = await db.transaction(async (tx) => {
      const results = []
      for (const { id, version, data } of agentVersions) {
        const newAgent = await tx
          .insert(schema.agentConfig)
          .values({
            id,
            version: stringifyVersion(version),
            publisher_id: publisher.id,
            data,
          })
          .returning()
          .then((rows) => rows[0])
        results.push(newAgent)
      }
      return results
    })

    logger.info(
      {
        userId,
        publisherId: publisher.id,
        agentIds: newAgents.map((a) => a.id),
        agentCount: newAgents.length,
      },
      'Agents published successfully'
    )

    return NextResponse.json(
      {
        success: true,
        publisherId: publisher.id,
        agents: newAgents.map((agent) => ({
          id: agent.id,
          version: agent.version,
          displayName: (agent.data as any).displayName,
        })),
      },
      { status: 201 }
    )
  } catch (error: any) {
    logger.error(
      { name: error.name, message: error.message, stack: error.stack },
      'Error handling /api/agents/publish request'
    )
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { eq, and } from 'drizzle-orm'
import { NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'

import type { NextRequest } from 'next/server'

import { authOptions } from '@/app/api/auth/[...nextauth]/auth-options'

interface RouteParams {
  params: { orgId: string }
}

export async function GET(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse> {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { orgId } = params

    // Check if user is a member of this organization
    const membership = await db
      .select({ role: schema.orgMember.role })
      .from(schema.orgMember)
      .where(
        and(
          eq(schema.orgMember.org_id, orgId),
          eq(schema.orgMember.user_id, session.user.id)
        )
      )
      .limit(1)

    if (membership.length === 0) {
      return NextResponse.json(
        { error: 'Organization not found' },
        { status: 404 }
      )
    }

    const userRole = membership[0].role
    if (userRole !== 'owner' && userRole !== 'admin') {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      )
    }

    // Get organization details
    const organization = await db
      .select()
      .from(schema.org)
      .where(eq(schema.org.id, orgId))
      .limit(1)

    if (organization.length === 0) {
      return NextResponse.json(
        { error: 'Organization not found' },
        { status: 404 }
      )
    }

    const org = organization[0]

    // Return settings with default values for new fields
    const settings = {
      id: org.id,
      name: org.name,
      slug: org.slug,
      description: org.description,
      userRole,
      autoTopupEnabled: org.auto_topup_enabled || false,
      autoTopupThreshold: org.auto_topup_threshold || 500,
      autoTopupAmount: org.auto_topup_amount || 2000,
      creditLimit: org.credit_limit,
      billingAlerts: org.billing_alerts ?? true,
      usageAlerts: org.usage_alerts ?? true,
      weeklyReports: org.weekly_reports ?? false,
    }

    return NextResponse.json(settings)
  } catch (error) {
    console.error('Error fetching organization settings:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function PATCH(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse> {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { orgId } = params

    // Check if user is a member of this organization with admin/owner role
    const membership = await db
      .select({ role: schema.orgMember.role })
      .from(schema.orgMember)
      .where(
        and(
          eq(schema.orgMember.org_id, orgId),
          eq(schema.orgMember.user_id, session.user.id)
        )
      )
      .limit(1)

    if (membership.length === 0) {
      return NextResponse.json(
        { error: 'Organization not found' },
        { status: 404 }
      )
    }

    const userRole = membership[0].role
    if (userRole !== 'owner' && userRole !== 'admin') {
      return NextResponse.json(
        { error: 'Insufficient permissions' },
        { status: 403 }
      )
    }

    const body = await request.json()
    const {
      name,
      description,
      autoTopupEnabled,
      autoTopupThreshold,
      autoTopupAmount,
      creditLimit,
      billingAlerts,
      usageAlerts,
      weeklyReports,
    } = body

    // Update organization settings
    await db
      .update(schema.org)
      .set({
        name,
        description,
        auto_topup_enabled: autoTopupEnabled,
        auto_topup_threshold: autoTopupThreshold,
        auto_topup_amount: autoTopupAmount,
        credit_limit: creditLimit,
        billing_alerts: billingAlerts,
        usage_alerts: usageAlerts,
        weekly_reports: weeklyReports,
        updated_at: new Date(),
      })
      .where(eq(schema.org.id, orgId))

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('Error updating organization settings:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: RouteParams
): Promise<NextResponse> {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { orgId } = params

    // Check if user is the owner of this organization
    const membership = await db
      .select({ role: schema.orgMember.role })
      .from(schema.orgMember)
      .where(
        and(
          eq(schema.orgMember.org_id, orgId),
          eq(schema.orgMember.user_id, session.user.id)
        )
      )
      .limit(1)

    if (membership.length === 0) {
      return NextResponse.json(
        { error: 'Organization not found' },
        { status: 404 }
      )
    }

    const userRole = membership[0].role
    if (userRole !== 'owner') {
      return NextResponse.json(
        { error: 'Only organization owners can delete organizations' },
        { status: 403 }
      )
    }

    // Delete organization (this will cascade to related tables)
    await db.delete(schema.org).where(eq(schema.org.id, orgId))

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('Error deleting organization:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}

import { z } from 'zod'

import { ALLOWED_MODEL_PREFIXES, models } from '../constants'
import { toolNames } from '../tools/constants'

// Filter models to only include those that begin with allowed prefixes
const filteredModels = Object.values(models).filter((model) =>
  ALLOWED_MODEL_PREFIXES.some((prefix) => model.startsWith(prefix)),
)

if (filteredModels.length === 0) {
  throw new Error('No valid models found with allowed prefixes')
}

// Simplified JSON Schema definition - supports object schemas with nested properties
const JsonSchemaSchema: z.ZodType<any> = z.lazy(() =>
  z
    .object({
      type: z.literal('object'),
      description: z.string().optional(),
      properties: z
        .record(
          JsonSchemaSchema.or(
            z
              .object({
                type: z.enum([
                  'string',
                  'number',
                  'integer',
                  'boolean',
                  'array',
                ]),
                description: z.string().optional(),
                enum: z.array(z.any()).optional(),
              })
              .passthrough(),
          ),
        )
        .optional(),
      required: z.array(z.string()).optional(),
    })
    .passthrough(),
)

// Schema for the combined inputSchema object
const InputSchemaObjectSchema = z
  .object({
    prompt: z
      .object({
        type: z.literal('string'),
        description: z.string().optional(),
      })
      .passthrough()
      .optional(), // Optional JSON schema for prompt validation
    params: JsonSchemaSchema.optional(), // Optional JSON schema for params validation
  })
  .optional()

// Schema for prompt fields that can be either a string or a path reference
const PromptFieldSchema = z.union([
  z.string(), // Direct string content
  z.object({ path: z.string() }), // Path reference to external file
])
export type PromptField = z.infer<typeof PromptFieldSchema>

// Schema for validating handleSteps function signature
const HandleStepsSchema = z
  .function()
  .args(
    z.object({
      agentState: z.object({
        agentId: z.string(),
        parentId: z.string(),
        messageHistory: z.array(z.any()),
      }),
      prompt: z.string().optional(),
      params: z.any().optional(),
    }),
  )
  .returns(z.any())
  .optional()

// Validates the Typescript template file.
export const DynamicAgentConfigSchema = z.object({
  id: z
    .string()
    .regex(
      /^[a-z0-9-]+$/,
      'Agent ID must contain only lowercase letters, numbers, and hyphens',
    ), // The unique identifier for this agent
  version: z.string().optional(),
  publisher: z.string().optional(),

  // Required fields for new agents
  displayName: z.string(),
  model: z.string(),

  // Tools and subagents
  toolNames: z
    .array(z.enum(toolNames))
    .optional()
    .default([])
    .refine(
      (tools) => {
        if (!tools) return true
        const validToolNames = toolNames as readonly string[]
        const invalidTools = tools.filter(
          (tool) => !validToolNames.includes(tool),
        )
        return invalidTools.length === 0
      },
      (tools) => {
        if (!tools) return { message: 'Tools array is undefined' }
        const validToolNames = toolNames as readonly string[]
        const invalidTools = tools.filter(
          (tool) => !validToolNames.includes(tool),
        )
        return {
          message: `Invalid tool names: ${invalidTools.join(', ')}. Available tools: ${toolNames.join(', ')}`,
        }
      },
    ),
  subagents: z.array(z.string()).optional().default([]),

  // Input and output
  inputSchema: InputSchemaObjectSchema,
  includeMessageHistory: z.boolean().default(true),
  outputMode: z
    .enum(['last_message', 'all_messages', 'structured_output'])
    .default('last_message'),
  outputSchema: JsonSchemaSchema.optional(), // Optional JSON schema for output validation

  // Prompts
  parentPrompt: z.string().optional(),
  systemPrompt: z.string().optional(),
  instructionsPrompt: z.string().optional(),
  stepPrompt: z.string().optional(),

  // Optional generator function for programmatic agents
  handleSteps: z.union([HandleStepsSchema, z.string()]).optional(),
})
export type DynamicAgentConfig = z.input<typeof DynamicAgentConfigSchema>
export type DynamicAgentConfigParsed = z.infer<typeof DynamicAgentConfigSchema>

export const DynamicAgentTemplateSchema = DynamicAgentConfigSchema.extend({
  systemPrompt: z.string(),
  instructionsPrompt: z.string(),
  stepPrompt: z.string(),
  handleSteps: z.string().optional(), // Converted to string after processing
})
  .refine(
    (data) => {
      // If outputSchema is provided, outputMode must be explicitly set to 'structured_output'
      if (data.outputSchema && data.outputMode !== 'structured_output') {
        return false
      }
      return true
    },
    {
      message:
        "outputSchema requires outputMode to be explicitly set to 'structured_output'.",
      path: ['outputMode'],
    },
  )
  .refine(
    (data) => {
      // If outputMode is 'structured_output', 'set_output' tool must be included
      if (
        data.outputMode === 'structured_output' &&
        !data.toolNames.includes('set_output')
      ) {
        return false
      }
      return true
    },
    {
      message:
        "outputMode 'structured_output' requires the 'set_output' tool. Add 'set_output' to toolNames.",
      path: ['toolNames'],
    },
  )
  .refine(
    (data) => {
      // If 'set_output' tool is included, outputMode must be 'structured_output'
      if (
        data.toolNames.includes('set_output') &&
        data.outputMode !== 'structured_output'
      ) {
        return false
      }
      return true
    },
    {
      message:
        "'set_output' tool requires outputMode to be 'structured_output'. Change outputMode to 'structured_output' or remove 'set_output' from toolNames.",
      path: ['outputMode'],
    },
  )
  .refine(
    (data) => {
      // If subagents array is non-empty, 'spawn_agents' tool must be included
      if (
        data.subagents.length > 0 &&
        !data.toolNames.includes('spawn_agents')
      ) {
        return false
      }
      return true
    },
    {
      message:
        "Non-empty subagents array requires the 'spawn_agents' tool. Add 'spawn_agents' to toolNames or remove subagents.",
      path: ['toolNames'],
    },
  )
export type DynamicAgentTemplate = z.infer<typeof DynamicAgentTemplateSchema>

