import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function changeOrUpgrade(isUpgrade: boolean, planName?: string) {
  return isUpgrade ? 'upgrade' : 'change'
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max)
}

import { useQuery } from '@tanstack/react-query'
import { useSession } from 'next-auth/react'
import { useEffect } from 'react'

import type { UserProfile } from '@/types/user'

const USER_PROFILE_STORAGE_KEY = 'codebuff-user-profile'

// Helper functions for local storage
const getUserProfileFromStorage = (): UserProfile | null => {
  if (typeof window === 'undefined') return null

  try {
    const stored = localStorage.getItem(USER_PROFILE_STORAGE_KEY)
    if (!stored) return null

    const parsed = JSON.parse(stored)
    // Convert created_at string back to Date if it exists
    if (parsed.created_at) {
      parsed.created_at = new Date(parsed.created_at)
    }
    return parsed
  } catch {
    return null
  }
}

const setUserProfileToStorage = (profile: UserProfile) => {
  if (typeof window === 'undefined') return

  try {
    localStorage.setItem(USER_PROFILE_STORAGE_KEY, JSON.stringify(profile))
  } catch {
    // Silently fail if localStorage is not available
  }
}

const clearUserProfileFromStorage = () => {
  if (typeof window === 'undefined') return

  try {
    localStorage.removeItem(USER_PROFILE_STORAGE_KEY)
  } catch {
    // Silently fail if localStorage is not available
  }
}

export const useUserProfile = () => {
  const { data: session } = useSession()

  const query = useQuery<UserProfile>({
    queryKey: ['user-profile'],
    queryFn: async () => {
      const response = await fetch('/api/user/profile')
      if (!response.ok) {
        throw new Error('Failed to fetch user profile')
      }
      const data = await response.json()

      // Convert created_at string to Date if it exists
      if (data.created_at) {
        data.created_at = new Date(data.created_at)
      }

      return data
    },
    enabled: !!session?.user,
    staleTime: 5 * 60 * 1000, // 5 minutes
    initialData: () => {
      // Return undefined if no data, which is compatible with useQuery
      return getUserProfileFromStorage() ?? undefined
    },
  })

  // Persist to localStorage whenever data changes
  useEffect(() => {
    if (query.data) {
      setUserProfileToStorage(query.data)
    }
  }, [query.data])

  // Clear localStorage when user logs out
  useEffect(() => {
    if (!session?.user) {
      clearUserProfileFromStorage()
    }
  }, [session?.user])

  return {
    ...query,
    clearCache: clearUserProfileFromStorage,
  }
}

import { useQuery } from '@tanstack/react-query'
import { useSession } from 'next-auth/react'

export interface OrganizationDetails {
  id: string
  name: string
  slug: string
  description?: string
  owner_id: string
  created_at: string
  userRole: 'owner' | 'admin' | 'member'
  memberCount: number
  repositoryCount: number
  creditBalance: number // Made non-optional since API always provides a value
  hasStripeSubscription: boolean
  stripeSubscriptionId?: string
}

export interface BillingStatus {
  is_setup: boolean
  stripe_customer_id?: string
  billing_portal_url?: string
  user_role: string
}

// Query functions
const fetchOrganizationBySlug = async (
  slug: string
): Promise<OrganizationDetails> => {
  const response = await fetch(`/api/orgs/slug/${slug}`)

  if (!response.ok) {
    const error = await response.json()
    throw new Error(error.error || 'Failed to fetch organization')
  }

  return response.json()
}

const fetchBillingStatus = async (orgId: string): Promise<BillingStatus> => {
  const response = await fetch(`/api/orgs/${orgId}/billing/setup`)

  if (!response.ok) {
    const error = await response.json()
    throw new Error(error.error || 'Failed to fetch billing status')
  }

  return response.json()
}

export function useOrganizationData(orgSlug: string) {
  const { status } = useSession()

  // Query for organization details
  const {
    data: organization,
    isLoading: isLoadingOrg,
    error: orgError,
    isError: isOrgError,
  } = useQuery({
    queryKey: ['organization', orgSlug],
    queryFn: () => fetchOrganizationBySlug(orgSlug),
    enabled: status === 'authenticated' && !!orgSlug,
  })

  // Query for billing status (depends on organization data)
  const { data: billingStatus, isLoading: isLoadingBilling } = useQuery({
    queryKey: ['billing-status', organization?.id],
    queryFn: () => fetchBillingStatus(organization!.id),
    enabled: !!organization?.id,
  })

  const isLoading = isLoadingOrg || isLoadingBilling
  const error = isOrgError ? (orgError as Error)?.message : null

  return {
    organization,
    billingStatus,
    isLoading,
    error,
    isLoadingOrg,
    isLoadingBilling,
  }
}

