            prompt: `Analyze the codebase structure and research findings to develop a comprehensive documentation strategy. Consider information architecture, user journeys, and content organization for ${params?.audience || 'developers'}.`,
          },
        ],
      },
    }

    // Step 5: Create detailed plan
    yield {
      toolName: 'create_plan',
      args: {
        path: 'documentation-plan.md',
        plan: 'Based on research and codebase analysis, create a detailed plan for comprehensive documentation including structure, content types, examples, and delivery format.',
      },
    }

    // Step 6: Update subgoal and continue with implementation
    yield {
      toolName: 'update_subgoal',
      args: {
        id: '1',
        status: 'COMPLETE',
        log: 'Completed research and planning phase',
      },
    }

    // Step 7: Execute documentation creation
    yield {
      toolName: 'add_subgoal',
      args: {
        id: '2',
        objective: 'Create comprehensive documentation based on plan',
        status: 'IN_PROGRESS',
      },
    }

    // Step 8: Let the model continue with implementation
    yield 'STEP_ALL'
  },
}

export default config

import { publisher, version } from './constants'

import type { AgentConfig, AgentStepContext } from './types/agent-config'

const config: AgentConfig = {
  id: 'changes-reviewer',
  version,
  publisher,
  displayName: 'Changes Reviewer',
  model: 'x-ai/grok-4',

  includeMessageHistory: false,

  inputSchema: {
    prompt: {
      type: 'string',
      description:
        'Please provide a short description of the changes you want to review',
    },
  },
  outputMode: 'last_message',

  toolNames: ['read_files', 'run_terminal_command', 'end_turn'],

  parentPrompt: 'Spawn when you need to review code changes',

  systemPrompt:
    'You are an expert software developer. Your job is to review code changes and provide helpful feedback.',

  instructionsPrompt: `
Use the following guidelines to review the changes and suggest improvements:
- Find ways to simplify the code
- Reuse existing code as much as possible instead of writing new code
- Preserve as much behavior as possible in the existing code
- Prefer changing as few lines of code as possible
- Look for opportunities to improve the code's readability
- Look for logical errors in the code
- Look for missed cases in the code
- Look for any other bugs
    `.trim(),

  handleSteps: function* ({ agentState, prompt, params }: AgentStepContext) {
    // Step 1: Get list of changed files from git diff
    const { toolResult: gitDiffResult } = yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff HEAD --name-only',
        process_type: 'SYNC',
        timeout_seconds: 30,
      },
    }

    // Step 2: Get untracked files from git status
    const { toolResult: gitStatusResult } = yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git status --porcelain',
        process_type: 'SYNC',
        timeout_seconds: 30,
      },
    }

    // Step 3: Run full git diff to see the actual changes
    yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff HEAD',
        process_type: 'SYNC',
        timeout_seconds: 30,
      },
    }

    // Step 4: Extract file paths from git diff and status output
    const gitDiffOutput = gitDiffResult || ''
    const changedFiles = gitDiffOutput
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line && !line.startsWith('??') && !line.includes('OSC'))

    const gitStatusOutput = gitStatusResult || ''
    const untrackedFiles = gitStatusOutput
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line.startsWith('??'))
      .map((line) => line.substring(3).trim()) // Remove '?? ' prefix
      .filter((file) => file)

    const allFilesToRead = [...changedFiles, ...untrackedFiles].filter(
      (file) => file,
    )

    // Step 5: Read the files
    if (allFilesToRead.length > 0) {
      yield {
        toolName: 'read_files',
        args: {
          paths: allFilesToRead,
        },
      }
    }

    // Step 7: Let AI review the changes (and take as many steps as needed)
    yield 'STEP_ALL'
  },
}

