## Diff-Reviewer Level 2: Intermediate with HandleSteps

common/src/util/diff-reviewer-2.ts
```typescript
import type { AgentConfig } from './types/agent-config'

const config: AgentConfig = {
  id: 'diff-reviewer-2',
  displayName: 'Dana the Diff Reviewer (Level 2)',
  model: 'anthropic/claude-3.5-sonnet-20240620',

  toolNames: [
    'read_files',
    'run_terminal_command',
    'code_search',
    'spawn_agents',
    'set_output',
    'end_turn',
  ],

  subagents: ['file-picker'],

  inputSchema: {
    prompt: {
      type: 'string',
      description: 'Description of what to focus on when reviewing changes',
    },
    params: {
      type: 'object',
      properties: {
        includeTests: {
          type: 'boolean',
          description: 'Whether to check if tests were updated',
        },
        checkBreaking: {
          type: 'boolean',
          description: 'Whether to analyze for breaking changes',
        },
      },
    },
  },

  outputMode: 'structured_output',
  outputSchema: {
    type: 'object',
    properties: {
      summary: { type: 'string' },
      filesReviewed: { type: 'number' },
      criticalIssues: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            file: { type: 'string' },
            line: { type: 'string' },
            issue: { type: 'string' },
            suggestion: { type: 'string' },
            severity: { type: 'string' },
          },
        },
      },
      improvements: { type: 'array', items: { type: 'string' } },
      testCoverage: { type: 'string' },
      breakingChanges: { type: 'array', items: { type: 'string' } },
    },
  },

  parentPrompt: 'Reviews git changes with intermediate analysis including test coverage and breaking changes.',

  systemPrompt: `# Dana the Diff Reviewer (Level 2)

You are an experienced code reviewer who analyzes git diffs systematically:

- **Change Analysis**: Understand what changed and why
- **Impact Assessment**: Identify affected components
- **Quality Review**: Check code quality and patterns
- **Test Coverage**: Verify tests were updated
- **Breaking Changes**: Flag API or behavior changes

## Review Philosophy
- Systematic multi-phase analysis
- Context-aware feedback
- Balance thoroughness with practicality
- Focus on preventing bugs`,

  instructionsPrompt: `Review git changes systematically:

1. **Gather Changes**: Use git diff and git status to find all modifications
2. **Analyze Files**: Read changed files and understand the modifications
3. **Search Related Code**: Use code_search to find related functions/imports
4. **Check Tests**: If requested, verify test files were updated
5. **Identify Issues**: Flag critical issues, improvements, and breaking changes
6. **Provide Output**: Structured review with categorized feedback`,

  handleSteps: function* ({ agentState, prompt, params }) {
    // Step 1: Get git diff to see what files changed
    const { toolResult: gitDiff } = yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff HEAD --name-only',
        process_type: 'SYNC',
        timeout_seconds: 30,
      },
    }

    // Step 2: Get git status for untracked files
    const { toolResult: gitStatus } = yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git status --porcelain',
        process_type: 'SYNC',
        timeout_seconds: 30,
      },
    }

    // Step 3: Get actual diff content
    yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff HEAD',
        process_type: 'SYNC',
        timeout_seconds: 30,
      },
    }

    // Step 4: Use file-picker to find related files if needed
    if (params?.checkBreaking) {
      yield {
        toolName: 'spawn_agents',
        args: {
          agents: [
            {
              agent_type: 'file-picker',
              prompt: `Find files that might be affected by changes to: ${gitDiff}. Look for imports, usages, and related tests.`,
            },
          ],
        },
      }
    }

    // Step 5: Let AI analyze and provide review
    yield 'STEP_ALL'
  },
}

export default config
```

## Diff-Reviewer Level 3: Advanced with Complex Orchestration

common/src/util/diff-reviewer-3.ts
```typescript
import type { AgentConfig } from './types/agent-config'

const config: AgentConfig = {
  id: 'diff-reviewer-3',
  displayName: 'Dexter the Diff Reviewer (Level 3)',
  model: 'google/gemini-2.5-pro',

  toolNames: [
    'read_files',
    'run_terminal_command',
    'code_search',
    'spawn_agents',
    'web_search',
    'create_plan',
    'add_subgoal',
    'update_subgoal',
    'think_deeply',
    'set_output',
    'end_turn',
  ],

  subagents: ['file-explorer', 'file-picker', 'thinker', 'reviewer'],

  includeMessageHistory: true,

  inputSchema: {
    prompt: {
      type: 'string',
      description: 'Specific areas to focus on or comprehensive review request',
    },
    params: {
      type: 'object',
      properties: {
        reviewDepth: {
          type: 'string',
          description: 'Review depth: quick, standard, or comprehensive',
        },
        checkSecurity: {
          type: 'boolean',
          description: 'Whether to perform security analysis',
        },
        checkPerformance: {
          type: 'boolean',
          description: 'Whether to analyze performance implications',
        },
        researchPatterns: {
          type: 'boolean',
          description: 'Whether to research best practices for changed code',
        },
      },
    },
  },

  outputMode: 'structured_output',
  outputSchema: {
    type: 'object',
    properties: {
      summary: { type: 'string' },
      changeScope: {
        type: 'object',
        properties: {
          filesModified: { type: 'number' },
          linesAdded: { type: 'number' },
          linesRemoved: { type: 'number' },
          components: { type: 'array', items: { type: 'string' } },
        },
      },
      criticalIssues: { type: 'array', items: { type: 'object' } },
      securityConcerns: { type: 'array', items: { type: 'string' } },
      performanceImpact: { type: 'string' },
      architectureInsights: { type: 'array', items: { type: 'string' } },
      recommendations: { type: 'array', items: { type: 'string' } },
      testingGuidance: { type: 'array', items: { type: 'string' } },
    },
  },

  parentPrompt:
    'Performs comprehensive diff review with deep analysis, research, and multi-agent orchestration. Advanced complexity for thorough code reviews.',

  systemPrompt: `# Dexter the Diff Reviewer (Level 3)

You are a senior code reviewer and architect who performs comprehensive diff analysis:

- **Deep Analysis**: Multi-layered review of changes
- **Impact Assessment**: Understand ripple effects across codebase
- **Research Integration**: Research best practices for patterns
- **Security Focus**: Identify security implications
- **Performance Analysis**: Assess performance impact
- **Architecture Review**: Evaluate design decisions

## Review Philosophy
- Comprehensive multi-phase analysis
- Research-backed recommendations
- Holistic impact assessment
- Proactive issue prevention
- Knowledge synthesis from multiple sources

## Advanced Capabilities
- Orchestrate multiple specialized reviewers
- Research industry best practices
- Analyze cross-cutting concerns
- Provide architectural guidance
- Generate detailed test plans`,

  instructionsPrompt: `Perform comprehensive diff review with systematic approach:

1. **Planning Phase**
   - Create review plan based on change scope
   - Identify areas requiring deep analysis
   - Set up review subgoals

2. **Discovery Phase**
   - Explore changed files and dependencies
   - Use file-explorer to understand impact
   - Analyze git history for context

3. **Analysis Phase**
   - Deep thinking on complex changes
   - Research best practices if requested
   - Security and performance analysis
   - Review related tests

4. **Synthesis Phase**
   - Aggregate findings from sub-reviews
   - Generate comprehensive recommendations
   - Provide architectural insights
   - Suggest testing strategies`,

  handleSteps: function* ({ agentState, prompt, params }) {
    // Step 1: Create review plan
    yield {
      toolName: 'add_subgoal',
      args: {
        id: '1',
        objective: 'Analyze git changes and plan comprehensive review',
        status: 'IN_PROGRESS',
      },
    }

    // Step 2: Get git diff information
    yield {
      toolName: 'run_terminal_command',
      args: {
        command: 'git diff HEAD --stat',
        process_type: 'SYNC',
        timeout_seconds: 30,
      },
    }

    // Step 3: Explore affected areas
    yield {
      toolName: 'spawn_agents',
      args: {
        agents: [
          {
            agent_type: 'file-explorer',
            prompt: `Explore the codebase to understand the scope of changes: ${prompt}`,
            params: {
              prompts: [
                'Changed files and their dependencies',
                'Related test files and test coverage',
                'API boundaries and public interfaces',
                'Configuration and deployment files affected',
              ],
            },
          },
        ],
      },
    }

    // Step 4: Deep analysis with thinker
    yield {
      toolName: 'spawn_agents',
      args: {
        agents: [
          {
            agent_type: 'thinker',
            prompt: `Analyze the architectural implications and potential issues in these changes. Consider: ${params?.checkSecurity ? 'security concerns, ' : ''}${params?.checkPerformance ? 'performance impact, ' : ''}breaking changes, and design patterns.`,
          },
        ],
      },
    }

    // Step 5: Research best practices if requested
    if (params?.researchPatterns) {
      yield {
        toolName: 'web_search',
        args: {
          query: `Best practices for ${prompt} code patterns`,
        },
      }
    }

    // Step 6: Create detailed review plan
    yield {
