      return gray(content)
    },
  },
  find_files: {
    ...defaultToolCallRenderer,
  },
  think_deeply: {
    ...defaultToolCallRenderer,
  },
  create_plan: {
    ...defaultToolCallRenderer,
    onParamStart: (paramName) => {
      if (paramName === 'path') {
        return gray('Editing plan at ')
      }
      return null
    },
    onParamChunk: (content, paramName) => {
      if (paramName === 'path') {
        return gray(content)
      }
      return null
    },
    onParamEnd: (paramName) => {
      if (paramName === 'path') {
        return gray('...') + '\n'
      }
      return null
    },
  },
  write_file: {
    ...defaultToolCallRenderer,
    onParamStart: (paramName) => {
      if (paramName === 'path') {
        return gray('Editing file at ')
      }
      return null
    },
    onParamChunk: (content, paramName, toolName) => {
      return null
    },
    onParamEnd: (paramName, toolName, content) => {
      if (paramName === 'path') {
        return isFileIgnored(content, getProjectRoot())
          ? gray(strikethrough(content) + ' (blocked)')
          : gray(content + '...')
      }
      if (paramName === 'instructions') {
        return gray('\n' + content)
      }
      return null
    },
  },
  str_replace: {
    onToolStart: (toolName) => {
      toolStart = true
      return '\n\n' + gray(`[${bold('Edit File')}]`) + '\n'
    },
    onParamStart: (paramName) => {
      if (paramName === 'path') {
        return gray('Editing file at ')
      }
      return null
    },
    onParamChunk: (content, paramName) => {
      if (paramName === 'path') {
        return gray(content)
      }
      return null
    },
    onParamEnd: (paramName) =>
      paramName === 'path' ? gray('...') + '\n' : null,
  },
  add_subgoal: {
    ...defaultToolCallRenderer,
    onParamStart: (paramName, toolName) => {
      if (paramName === 'id') {
        return null
      }
      return gray(capitalize(paramName) + ': ')
    },
    onParamChunk: (content, paramName, toolName) => {
      if (paramName === 'id') {
        return null
      }
      return gray(content)
    },
    onParamEnd: (paramName) => {
      const paramsWithNewLine = ['objective', 'status']
      if (paramsWithNewLine.includes(paramName)) {
        return '\n'
      }
      return null
    },
  },
  update_subgoal: {
    ...defaultToolCallRenderer,
    onParamStart: (paramName, toolName) => {
      if (paramName === 'id') {
        return null
      }
      return gray(capitalize(paramName) + ': ')
    },
    onParamChunk: (content, paramName, toolName) => {
      if (paramName === 'id') {
        return null
      }
      return gray(content)
    },
    onParamEnd: (paramName) => {
      const paramsWithNewLine = ['status']
      if (paramsWithNewLine.includes(paramName)) {
        return '\n'
      }
      return null
    },
  },
  spawn_agents: {
    onToolStart: (toolName) => {
      return '\n\n' + gray(`[${bold('Spawn Agents')}]`) + '\n'
    },
    onParamEnd: renderSpawnAgentsParam,
    onToolEnd: () => {
      return () => {
        Spinner.get().start('Agents running...')
        return '\n'
      }
    },
  },
  spawn_agents_async: {
    onToolStart: (toolName) => {
      return '\n\n' + gray(`[${bold('Spawn Agents')}]`) + '\n'
    },
    onParamEnd: renderSpawnAgentsParam,
    onToolEnd: () => {
      return () => {
        Spinner.get().start('Agents running...')
        return '\n'
      }
    },
  },
  spawn_agent_inline: {
    onToolStart: (toolName) => {
      return '\n\n' + gray(`[${bold('Spawn Agent Inline')}]`) + '\n'
    },
    onParamEnd: (paramName, toolName, content) => {
      if (paramName === 'agent_type') {
        const client = Client.getInstance(false)
        const agentName =
          (client?.agentNames && client.agentNames[content]) || content
        return gray(`@${bold(agentName)}\n`)
      }
      if (paramName === 'prompt') {
        return gray(content + '\n')
      }
      return null
    },
    onToolEnd: () => {
      return () => {
        Spinner.get().start('Agent running inline...')
        return '\n'
      }
    },
  },
  add_message: {
    // Don't render anything
  },
  set_messages: {
    // Don't render anything
  },
  set_output: {
    ...defaultToolCallRenderer,
    onToolStart: (toolName) => {
      toolStart = true
      return '\n\n' + gray(`[${bold('Set Output')}]`) + '\n'
    },
    onParamChunk: (content, paramName, toolName) => {
      if (paramName === 'message') {
        return gray(content)
      }
      return null
    },
  },
}

