# Code Sketch for spawn_agent_inline Implementation

## Key Implementation Strategy

The core insight is that the child agent should **share the same messageHistory array reference** with the parent, not create a copy. This means:
1. Child's `agentState.messageHistory` points to the same array as parent's
2. Any messages added by the child are automatically visible to the parent
3. After child completes, we clean up temporary messages using `expireMessages`

## File Changes

### backend/src/tools/handlers/tool/spawn-agent-inline.ts
```typescript
import { generateCompactId } from '@codebuff/common/util/string'
import { getAgentTemplate } from '../../../templates/agent-registry'
import { logger } from '../../../util/logger'
import { expireMessages } from '../../../util/messages'

import type { CodebuffToolCall } from '../../constants'
import type { CodebuffToolHandlerFunction } from '../handler-function-type'
import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import type { AgentState } from '@codebuff/common/types/session-state'
import type { WebSocket } from 'ws'

export const handleSpawnAgentInline = ((params: {
  previousToolCallFinished: Promise<void>
  toolCall: CodebuffToolCall<'spawn_agent_inline'>
  fileContext: ProjectFileContext
  clientSessionId: string
  userInputId: string
  getLatestState: () => { messages: CodebuffMessage[] }
  state: {
    ws?: WebSocket
    fingerprintId?: string
    userId?: string
    agentTemplate?: AgentTemplate
    localAgentTemplates?: Record<string, AgentTemplate>
    messages?: CodebuffMessage[]
    agentState?: AgentState
  }
}): { result: Promise<undefined>; state: {} } => {
  const { previousToolCallFinished, toolCall, fileContext, clientSessionId, userInputId, state } = params
  const { agent_type: agentTypeStr, prompt, params: agentParams } = toolCall.args

  // Validate required state
  if (!state.ws) throw new Error('Internal error for spawn_agent_inline: Missing WebSocket in state')
  if (!state.fingerprintId) throw new Error('Internal error for spawn_agent_inline: Missing fingerprintId in state')
  if (!state.agentTemplate) throw new Error('Internal error for spawn_agent_inline: Missing agentTemplate in state')
  if (!state.agentState) throw new Error('Internal error for spawn_agent_inline: Missing agentState in state')
  if (!state.localAgentTemplates) throw new Error('Internal error for spawn_agent_inline: Missing localAgentTemplates in state')

  const { ws, fingerprintId, userId, agentTemplate: parentAgentTemplate, localAgentTemplates, agentState: parentAgentState } = state

  const triggerInlineAgent = async () => {
    const agentType = agentTypeStr as AgentTemplateType
    const agentTemplate = await getAgentTemplate(agentType, localAgentTemplates)

    if (!agentTemplate) {
      throw new Error(`Agent type ${agentTypeStr} not found.`)
    }

    // Validate parent can spawn this child
    if (!parentAgentTemplate.subagents.includes(agentType)) {
      throw new Error(
        `Agent type ${parentAgentTemplate.id} is not allowed to spawn child agent type ${agentType}.`
      )
    }

    // Validate prompt and params against agent's input schema
    if (agentTemplate.inputSchema.prompt) {
      const result = agentTemplate.inputSchema.prompt.safeParse(prompt)
      if (!result.success) {
        throw new Error(
          `Invalid prompt for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`
        )
      }
    }

    if (agentTemplate.inputSchema.params) {
      const result = agentTemplate.inputSchema.params.safeParse(agentParams)
      if (!result.success) {
        throw new Error(
          `Invalid params for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`
        )
      }
    }

    const agentId = generateCompactId()

    // KEY: Create child state that shares the SAME messageHistory array reference
    const childAgentState: AgentState = {
      agentId,
      agentType,
      agentContext: parentAgentState.agentContext, // Share context
      subagents: [],
      messageHistory: parentAgentState.messageHistory, // SHARED REFERENCE - not a copy!
      stepsRemaining: 20,
      output: undefined,
      parentId: parentAgentState.agentId,
    }

    logger.debug(
      { agentTemplate, prompt, agentParams, agentId, parentId: childAgentState.parentId },
      `Spawning inline agent — ${agentType} (${agentId})`
    )

    // Import loopAgentSteps dynamically to avoid circular dependency
    const { loopAgentSteps } = await import('../../../run-agent-step')

    // Execute child agent - it will modify the shared messageHistory directly
    const result = await loopAgentSteps(ws, {
      userInputId: `${userInputId}-${agentType}${agentId}`,
      prompt: prompt || '',
      params: agentParams,
      agentType: agentTemplate.id,
      agentState: childAgentState,
      fingerprintId,
      fileContext,
      localAgentTemplates,
      toolResults: [],
      userId,
      clientSessionId,
      onResponseChunk: () => {}, // No streaming for inline agents
    })

    // After child completes, clean up temporary messages with timeToLive: 'userPrompt'
    // This removes any ephemeral messages added during child execution
    parentAgentState.messageHistory = expireMessages(
      parentAgentState.messageHistory,
      'userPrompt'
    )

    // Update parent's agent state reference in state object
    state.agentState = parentAgentState

    logger.debug(
      { agentId, messageCount: parentAgentState.messageHistory.length },
      `Inline agent ${agentType} completed`
    )

    return undefined
  }

  return {
    result: previousToolCallFinished.then(triggerInlineAgent),
    state: {},
  }
}) satisfies CodebuffToolHandlerFunction<'spawn_agent_inline'>
```

