import fs from 'fs/promises'
import path from 'path'

import { FILE_READ_STATUS } from '../../../common/src/constants'

export async function getFiles(
  filePaths: string[],
  cwd: string,
): Promise<Record<string, string | null>> {
  const result: Record<string, string | null> = {}
  const MAX_FILE_SIZE = 1024 * 1024

  for (const filePath of filePaths) {
    if (!filePath) {
      continue
    }

    const resolvedPath = path.resolve(cwd, filePath)

    if (!resolvedPath.startsWith(cwd)) {
      result[filePath] = FILE_READ_STATUS.OUTSIDE_PROJECT
      continue
    }

    try {
      await fs.access(resolvedPath)
    } catch (error: any) {
      if (error.code === 'ENOENT') {
        result[filePath] = FILE_READ_STATUS.DOES_NOT_EXIST
      } else {
        result[filePath] = FILE_READ_STATUS.ERROR
      }
      continue
    }

    try {
      const stats = await fs.stat(resolvedPath)
      if (stats.size > MAX_FILE_SIZE) {
        result[filePath] = `${FILE_READ_STATUS.TOO_LARGE} (size: ${(stats.size / (1024 * 1024)).toFixed(2)} MB)`
      } else {
        const content = await fs.readFile(resolvedPath, 'utf8')
        result[filePath] = content
      }
    } catch (error) {
      result[filePath] = FILE_READ_STATUS.ERROR
    }
  }

  return result
}

