# Type Definition Refactoring Sketch

Here's how to refactor the type definitions to separate `read_files` override from the other client tools:

## sdk/src/client.ts

```typescript
// Define the restricted client tool names (without read_files)
export type ClientToolName = 'write_file' | 'run_terminal_command'

// Define the read_files override separately
export type ReadFilesOverride = (
  filePaths: string[],
) => Promise<{ files: Record<string, string | null> }>

// Define the override tools type
export type OverrideTools = Record<
  ClientToolName,
  (
    args: Extract<ServerAction, { type: 'tool-call-request' }>['args'],
  ) => Promise<{ toolResultMessage: string }>
>

// Update CodebuffClientOptions to make overrideTools partial and readFiles required
export type CodebuffClientOptions = {
  cwd: string
  onError: (error: { message: string }) => void
  overrideTools?: Partial<OverrideTools>
  readFiles: ReadFilesOverride
}

export class CodebuffClient {
  // Update private field type
  private readonly overrideTools: CodebuffClientOptions['overrideTools']
  private readonly readFilesOverride: CodebuffClientOptions['readFiles']

  constructor({ cwd, onError, overrideTools, readFiles }: CodebuffClientOptions) {
    // ... existing validation code ...

    this.cwd = cwd
    this.overrideTools = overrideTools
    this.readFilesOverride = readFiles

    this.websocketHandler = new WebSocketHandler({
      // ... other options ...
      readFiles: this.readFiles.bind(this),
      // ... other options ...
    })
  }

  private async readFiles(filePath: string[]) {
    // Use the separate readFiles override
    const overrideResult = await this.readFilesOverride(filePath)
    return overrideResult.files
  }

  private async handleToolCall(
    action: Extract<ServerAction, { type: 'tool-call-request' }>,
  ) {
    const toolName = action.toolName
    const args = action.args
    let result: string
    try {
      // Check if we have an override for this tool
      let override = this.overrideTools?.[toolName as ClientToolName]

      if (!override && toolName === 'str_replace') {
        override = this.overrideTools?.['write_file']
      }

      if (override) {
        const overrideResult = await override(args)
        result = overrideResult.toolResultMessage
      } else if (toolName === 'end_turn') {
        result = ''
      } else if (toolName === 'write_file' || toolName === 'str_replace') {
        const r = changeFile(args, this.cwd)
        result = r.toolResultMessage
      } else if (toolName === 'run_terminal_command') {
        throw new Error(
          'run_terminal_command not implemented in SDK yet; please provide an override.',
        )
      } else {
        throw new Error(
          `Tool not implemented in SDK. Please provide an override or modify your agent to not use this tool: ${toolName}`,
        )
      }
    } catch (error) {
      // ... existing error handling ...
    }
    return {
      type: 'tool-call-response',
      requestId: action.requestId,
      success: true,
      result,
    }
  }
}
```

## Key Changes:

1. **Separated `ClientToolName`**: Now only includes `'write_file'` and `'run_terminal_command'`
2. **New `ReadFilesOverride` type**: Dedicated type for the read_files override with cleaner signature
3. **New `OverrideTools` type**: Explicit type for the tool overrides record
4. **Updated `CodebuffClientOptions`**:
   - `overrideTools` is now `Partial<OverrideTools>` (optional)
   - `readFiles` is a separate required field using `ReadFilesOverride` type
5. **Refactored class fields**: Split into `overrideTools` and `readFilesOverride` 
6. **Updated `readFiles` method**: Uses the dedicated `readFilesOverride` field
7. **Updated `handleToolCall`**: Uses optional chaining (`?.`) to safely access potentially undefined overrides

This maintains backwards compatibility while making the type system more precise and the API clearer.

