import { execFileSync } from 'child_process'
import os from 'os'

import { CODEBUFF_BINARY } from './constants'
import { changeFile } from './tools/change-file'
import { WebSocketHandler } from './websocket-client'
import { API_KEY_ENV_VAR } from '../../common/src/constants'
import {
  PromptResponseSchema,
  type ServerAction,
} from '../../common/src/actions'
import {
  getInitialSessionState,
  SessionState,
} from '../../common/src/types/session-state'
import { getFiles } from '../../npm-app/src/project-files'

export type ClientToolName =
  | 'read_files'
  | 'write_file'
  | 'str_replace'
  | 'run_terminal_command'

export type CodebuffClientOptions = {
  cwd: string
  onError: (error: { message: string }) => void
  overrideTools: Record<
    ClientToolName,
    (
      args: Extract<ServerAction, { type: 'tool-call-request' }>['args'],
    ) => Promise<{ toolResultMessage: string }>
  > & {
    readFiles: (
      filePath: string[],
    ) => Promise<{ files: Record<string, string | null> }>
  }
}

type RunState = {
  sessionState: SessionState
  toolResults: Extract<ServerAction, { type: 'prompt-response' }>['toolResults']
}

export class CodebuffClient {
  public cwd: string
  private readonly websocketHandler: WebSocketHandler
  private readonly overrideTools: CodebuffClientOptions['overrideTools']
  private readonly fingerprintId = `codebuff-sdk-${Math.random().toString(36).substring(2, 15)}`
  private readonly promptIdToResolveResponse: Record<
    string,
    { resolve: (response: any) => void; reject: (error: any) => void }
  > = {}

  constructor({ cwd, onError, overrideTools }: CodebuffClientOptions) {
    // TODO: download binary automatically
    if (execFileSync('which', [CODEBUFF_BINARY]).toString().trim() === '') {
      throw new Error(
        `Could not find ${CODEBUFF_BINARY} in PATH. Please run "npm i -g codebuff" to install the codebuff.`,
      )
    }
    if (!process.env[API_KEY_ENV_VAR]) {
      throw new Error(
        `Codebuff API key not found. Please set the ${API_KEY_ENV_VAR} environment variable.`,
      )
    }
    const apiKey = process.env[API_KEY_ENV_VAR]

    this.cwd = cwd
    this.overrideTools = overrideTools
    this.websocketHandler = new WebSocketHandler({
      apiKey,
      onWebsocketError: () => {},
      onWebsocketReconnect: () => {},
      onRequestReconnect: async () => {},
      onResponseError: async (error) => {
        onError({ message: error.message })
      },
      readFiles: this.readFiles.bind(this),
      handleToolCall: this.handleToolCall.bind(this),
      onCostResponse: async () => {},
      onUsageResponse: async () => {},

      onResponseChunk: async () => {},
      onSubagentResponseChunk: async () => {},

      onPromptResponse: this.handlePromptResponse.bind(this),
    })
  }

  /**
   * Run an agent.
   *
   * Pass an agent id, a prompt, and an event handler, plus options.
   *
   * Returns the state of the run, which can be passed to a subsequent run to continue the run.
   *
   * @param agent - The agent to run, e.g. 'base' or 'codebuff/file-picker@0.0.1'
   * @param prompt - The user prompt, e.g. 'Add a console.log to the index file'
   * @param params - (Optional) The parameters to pass to the agent.
   * @param handleEvent - A function to handle events.
   *
   * @param previousState - (Optional) Continue a previous run with the return value of a previous run.
   *
   * @param allFiles - (Optional) All the files in the project, in an object of file path to file content. Improves codebuff's ability to locate files.
   * @param knowledgeFiles - (Optional) The knowledge files to pass to the agent.
   * @param agentTemplates - (Optional) The agent templates to pass to the agent.
   * @param maxAgentSteps - (Optional) The maximum number of agent steps the main agent can run before stopping.
   */
  public async run({
    agent,
    prompt,
    params,
    handleEvent,
    previousState,
    allFiles,
    knowledgeFiles,
    agentConfig,
    maxAgentSteps,
  }: {
    agent: string
    prompt: string
    params?: Record<string, any>
    handleEvent: (event: any) => void
    previousState?: RunState
    allFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentConfig?: Record<string, any>
    maxAgentSteps?: number
  }): Promise<RunState> {
    const promptId = Math.random().toString(36).substring(2, 15)
    const sessionState =
      previousState?.sessionState ??
      initialSessionState(this.cwd, {
        knowledgeFiles,
        agentConfig,
        allFiles,
        maxAgentSteps,
      })
    const toolResults = previousState?.toolResults ?? []
    this.websocketHandler.sendInput({
      promptId,
      prompt,
      promptParams: params,
      fingerprintId: this.fingerprintId,
      costMode: 'normal',
      sessionState,
      toolResults,
      agentId: agent,
    })

    return new Promise<RunState>((resolve, reject) => {
      this.promptIdToResolveResponse[promptId] = { resolve, reject }
    })
  }

  private async handlePromptResponse(
    action: Extract<ServerAction, { type: 'prompt-response' }>,
  ) {
    const promiseActions =
      this.promptIdToResolveResponse[action?.promptId ?? '']

    const parsedAction = PromptResponseSchema.safeParse(action)
    if (!parsedAction.success) {
      const message = [
        'Received invalid prompt response from server:',
        JSON.stringify(parsedAction.error.errors),
        'If this issues persists, please contact support@codebuff.com',
      ].join('\n')
      if (promiseActions) {
        promiseActions.reject(new Error(message))
      }
      return
    }

    if (promiseActions) {
      const { sessionState, toolResults } = action
      const state: RunState = {
        sessionState,
        toolResults,
      }
      promiseActions.resolve(state)
    }
  }

  private async readFiles(filePath: string[]) {
    const override = this.overrideTools.readFiles
    if (override) {
      const overrideResult = await override(filePath)
      return overrideResult.files
    }
    return getFiles(filePath)
  }

  private async handleToolCall(
    action: Extract<ServerAction, { type: 'tool-call-request' }>,
  ) {
    const toolName = action.toolName
    const args = action.args
    let result: string
    try {
      const override = this.overrideTools[toolName as ClientToolName]
      if (override) {
        const overrideResult = await override(args)
        result = overrideResult.toolResultMessage
      } else if (toolName === 'end_turn') {
        result = ''
      } else if (toolName === 'write_file' || toolName === 'str_replace') {
        const r = changeFile(args, this.cwd)
        result = r.toolResultMessage
      } else if (toolName === 'run_terminal_command') {
        throw new Error(
          'run_terminal_command not implemented in SDK yet; please provide an override.',
        )
      } else {
        throw new Error(
          `Tool not implemented in sdk. Please provide an override or modify your agent to not use this tool: ${toolName}`,
        )
      }
    } catch (error) {
      return {
        type: 'tool-call-response',
        requestId: action.requestId,
        success: false,
        result:
          error && typeof error === 'object' && 'message' in error
            ? error.message
            : typeof error === 'string'
              ? error
              : 'Unknown error',
      }
    }
    return {
      type: 'tool-call-response',
      requestId: action.requestId,
      success: true,
      result,
    }
  }
}

function initialSessionState(
  cwd: string,
  options: {
    allFiles?: Record<string, string>
    knowledgeFiles?: Record<string, string>
    agentConfig?: Record<string, any>
    maxAgentSteps?: number
  },
) {
  const { knowledgeFiles = {}, agentConfig = {} } = options

  const initialState = getInitialSessionState({
    projectRoot: cwd,
    cwd,
    fileTree: [],
    fileTokenScores: {},
    tokenCallers: {},
    knowledgeFiles,
    userKnowledgeFiles: {},
    agentTemplates: agentConfig,
    gitChanges: {
      status: '',
      diff: '',
      diffCached: '',
      lastCommitMessages: '',
    },
    changesSinceLastChat: {},
    shellConfigFiles: {},
    systemInfo: {
      platform: process.platform,
      shell: 'bash',
      nodeVersion: process.version,
      arch: process.arch,
      homedir: os.homedir(),
      cpus: 16,
    },
  })

  if (options.maxAgentSteps) {
    initialState.mainAgentState.stepsRemaining = options.maxAgentSteps
  }

  return initialState
}

import { WEBSOCKET_URL } from './constants'
import { APIRealtimeClient } from '../../common/src/websockets/websocket-client'

import type { ServerAction, ClientAction } from '../../common/src/actions'
import type { WebSocket } from 'ws'

export type WebSocketHandlerOptions = {
  onWebsocketError?: (error: WebSocket.ErrorEvent) => void
  onWebsocketReconnect?: () => void
  onRequestReconnect?: () => Promise<void>
  onResponseError?: (
    error: Extract<ServerAction, { type: 'action-error' }>,
  ) => Promise<void>
  readFiles: (
    filePath: string[],
  ) => Promise<Extract<ClientAction, { type: 'read-files-response' }>['files']>
  handleToolCall: (
    action: Extract<ServerAction, { type: 'tool-call-request' }>,
  ) => Promise<
    Omit<
      Extract<ClientAction, { type: 'tool-call-response' }>,
      'type' | 'requestId'
    >
  >
  onCostResponse?: (
    action: Extract<ServerAction, { type: 'message-cost-response' }>,
  ) => Promise<void>
  onUsageResponse?: (
    action: Extract<ServerAction, { type: 'usage-response' }>,
  ) => Promise<void>

  onResponseChunk?: (
    action: Extract<ServerAction, { type: 'response-chunk' }>,
  ) => Promise<void>
  onSubagentResponseChunk?: (
    action: Extract<ServerAction, { type: 'subagent-response-chunk' }>,
  ) => Promise<void>

  onPromptResponse?: (
    action: Extract<ServerAction, { type: 'prompt-response' }>,
  ) => Promise<void>

  apiKey: string
}

type WebSocketHandlerOptionsWithDefaults = Required<WebSocketHandlerOptions>

export class WebSocketHandler {
  private cbWebSocket: APIRealtimeClient
  private onRequestReconnect: WebSocketHandlerOptionsWithDefaults['onRequestReconnect']

  private onResponseError: WebSocketHandlerOptionsWithDefaults['onResponseError']
  private readFiles: WebSocketHandlerOptionsWithDefaults['readFiles']
  private handleToolCall: WebSocketHandlerOptionsWithDefaults['handleToolCall']
  private onCostResponse: WebSocketHandlerOptionsWithDefaults['onCostResponse']
  private onUsageResponse: WebSocketHandlerOptionsWithDefaults['onUsageResponse']
  private onResponseChunk: WebSocketHandlerOptionsWithDefaults['onResponseChunk']
  private onSubagentResponseChunk: WebSocketHandlerOptionsWithDefaults['onSubagentResponseChunk']
  private onPromptResponse: WebSocketHandlerOptionsWithDefaults['onPromptResponse']
  private apiKey: string

  constructor({
    onWebsocketError = () => {},
    onWebsocketReconnect = () => {},
    onRequestReconnect = async () => {},
    onResponseError = async () => {},
    readFiles,
    handleToolCall,
    onCostResponse = async () => {},
    onUsageResponse = async () => {},

    onResponseChunk = async () => {},
    onSubagentResponseChunk = async () => {},

    onPromptResponse = async () => {},

    apiKey,
  }: WebSocketHandlerOptions) {
    this.cbWebSocket = new APIRealtimeClient(
      WEBSOCKET_URL,
      onWebsocketError,
      onWebsocketReconnect,
    )
    this.onRequestReconnect = onRequestReconnect

    this.onResponseError = onResponseError
    this.readFiles = readFiles
    this.handleToolCall = handleToolCall
    this.onCostResponse = onCostResponse
    this.onUsageResponse = onUsageResponse

    this.onResponseChunk = onResponseChunk
    this.onSubagentResponseChunk = onSubagentResponseChunk

    this.onPromptResponse = onPromptResponse

    this.apiKey = apiKey
  }

  public async connect() {
    await this.cbWebSocket.connect()
    this.setupSubscriptions()
  }

  public reconnect() {
    this.cbWebSocket.forceReconnect()
  }

  public close() {
    this.cbWebSocket.close()
  }

  private setupSubscriptions() {
    this.cbWebSocket.subscribe('action-error', this.onResponseError)

    this.cbWebSocket.subscribe('read-files', async (a) => {
      const { filePaths, requestId } = a
      const files = await this.readFiles(filePaths)

      this.cbWebSocket.sendAction({
        type: 'read-files-response',
        files,
        requestId,
      })
    })

    // Handle backend-initiated tool call requests
    this.cbWebSocket.subscribe('tool-call-request', async (action) => {
      const toolCallResult = await this.handleToolCall(action)

      this.cbWebSocket.sendAction({
        type: 'tool-call-response',
        requestId: action.requestId,
        ...toolCallResult,
      })
    })

    this.cbWebSocket.subscribe('message-cost-response', this.onCostResponse)

    this.cbWebSocket.subscribe('usage-response', this.onUsageResponse)

    // Used to handle server restarts gracefully
    this.cbWebSocket.subscribe('request-reconnect', this.onRequestReconnect)

    // Handle streaming messages
    this.cbWebSocket.subscribe('response-chunk', this.onResponseChunk)
    this.cbWebSocket.subscribe(
      'subagent-response-chunk',
      this.onSubagentResponseChunk,
    )

    // Handle full response from prompt
    this.cbWebSocket.subscribe('prompt-response', this.onPromptResponse)
  }

  private getInputDefaultOptions() {
    return {
      ...({
        type: 'prompt',
      } as const),
      authToken: this.apiKey,
    }
  }

  public sendInput(
    action: Omit<
      Extract<ClientAction, { type: 'prompt' }>,
      keyof ReturnType<typeof this.getInputDefaultOptions>
    >,
  ) {
    this.cbWebSocket.sendAction({
      ...action,
      ...this.getInputDefaultOptions(),
    })
  }

  public cancelInput({ promptId }: { promptId: string }) {
    this.cbWebSocket.sendAction({
      type: 'cancel-user-input',
      authToken: this.apiKey,
      promptId,
    })
  }
}

import z from 'zod'
import fs from 'fs'
import path from 'path'
import { applyPatch } from '@codebuff/common/util/patch'

const FileChangeSchema = z.object({
  type: z.enum(['patch', 'file']),
  path: z.string(),
  content: z.string(),
})

export function changeFile(
  parameters: unknown,
  cwd: string,
): { toolResultMessage: string } {
  const fileChange = FileChangeSchema.parse(parameters)
  const lines = fileChange.content.split('\n')

  const { created, modified, invalid } = applyChanges(cwd, [fileChange])

  const results: string[] = []

  for (const file of created) {
    results.push(
      `Created ${file} successfully. Changes made:\n${lines.join('\n')}`,
    )
  }

  for (const file of modified) {
    results.push(
      `Wrote to ${file} successfully. Changes made:\n${lines.join('\n')}`,
    )
  }

  for (const file of invalid) {
    results.push(
      `Failed to write to ${file}; file path caused an error or file could not be written`,
    )
  }

  return { toolResultMessage: results.join('\n') }
}

function applyChanges(
  projectRoot: string,
  changes: {
    type: 'patch' | 'file'
    path: string
    content: string
  }[],
) {
  const created: string[] = []
  const modified: string[] = []
  const invalid: string[] = []

  for (const change of changes) {
    const { path: filePath, content, type } = change
    try {
      const fullPath = path.join(projectRoot, filePath)
      const fileExists = fs.existsSync(fullPath)
      if (!fileExists) {
        const dirPath = path.dirname(fullPath)
        fs.mkdirSync(dirPath, { recursive: true })
      }

      if (type === 'file') {
        fs.writeFileSync(fullPath, content)
      } else {
        const oldContent = fs.readFileSync(fullPath, 'utf-8')
        const newContent = applyPatch(oldContent, content)
        fs.writeFileSync(fullPath, newContent)
      }

      if (fileExists) {
        modified.push(filePath)
      } else {
        created.push(filePath)
      }
    } catch (error) {
      console.error(`Failed to apply patch to ${filePath}:`, error, content)
      invalid.push(filePath)
    }
  }

  return { created, modified, invalid }
}

export const applyPatch = (oldContent: string, patch: string): string => {
  const lines = oldContent.split('\n')

  const patchLines = patch.split('\n').filter((line) => !line.startsWith('\\'))
  const indexOfFirstHunk = patchLines.findIndex((line) => line.startsWith('@@'))
  patchLines.splice(0, indexOfFirstHunk)
  if (patch.endsWith('\n')) {
    patchLines.pop()
  }

  const newLines: string[] = []
  let oldIndex = 0

  for (let i = 0; i < patchLines.length; i++) {
    while (lines[oldIndex] === REMOVED_LINE) {
      oldIndex++
    }

    const patchLine = patchLines[i]

    if (patchLine.startsWith('@@')) {
      const { contextLines, startIndex, headline } = parseHunk(patchLines, i)
      const maybeStartIndex =
        startIndex === undefined || startIndex < oldIndex
          ? undefined
          : startIndex
      const headlineIndex = headline ? lines.indexOf(headline) : undefined
      const matchIndex = getMatchIndex(
        lines,
        contextLines,
        oldIndex,
        maybeStartIndex,
        headlineIndex,
      )

      // Add lines from old content up to the match
      newLines.push(...lines.slice(oldIndex, matchIndex))
      oldIndex = matchIndex
    } else if (patchLine.startsWith('-')) {
      const lineContent = patchLine.slice(1)
      if (oldIndex >= lines.length) {
        // Do nothing, just skip the line.
      } else if (lineContent.trim() === lines[oldIndex].trim()) {
        // Remove line (skip it in the output)
        oldIndex++
      } else {
        for (let j = 0; j < 10; j++) {
          if (oldIndex + j >= lines.length) {
            break
          }
          if (lineContent.trim() === lines[oldIndex + j].trim()) {
            // Remove matching line if it's later in the file.
            lines[oldIndex + j] = REMOVED_LINE
            break
          }
        }
      }
    } else if (patchLine.startsWith('+')) {
      // Add new line
      newLines.push(patchLine.slice(1))
    } else {
      const nextHunkDist = patchLines
        .slice(i + 1)
        .findIndex((line) => line.startsWith('@@'))
      const nextHunkIndex =
        nextHunkDist === -1 ? patchLines.length : i + nextHunkDist + 1
      if (
        patchLines
          .slice(i + 1, nextHunkIndex)
          .every((line) => !line.startsWith('+') && !line.startsWith('-'))
      ) {
        // Skip ending context lines
        continue
      }
      const lineContent = patchLine.slice(1)
      // Context line
      for (let j = 0; j < 10; j++) {
        if (oldIndex + j >= lines.length) {
          if (oldIndex < lines.length) {
            // No match, just use the corresponding old line.
            newLines.push(lines[oldIndex])
            oldIndex++
          }
          break
        }
        const oldLine = lines[oldIndex + j]
        if (lineContent.trim() === oldLine.trim()) {
          // Remove matching line if it's later in the file.
          lines[oldIndex + j] = REMOVED_LINE
          newLines.push(oldLine)
          break
        }
      }
    }
  }

  // Add any remaining lines from the old content
  newLines.push(...lines.slice(oldIndex))

  return newLines.filter((line) => line !== REMOVED_LINE).join('\n')
}

const REMOVED_LINE = '[REMOVED_LINE]'

const parseHunkHeader = (line: string) => {
  let startIndex: number | undefined = undefined
  let lineCount: number | undefined = undefined
  let headline: string | undefined = undefined

  const lineNumberMatch = line.match(/@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@/)
  const headlineMatch = line.match(/@@ -\d+(?:,\d+)? \+\d+(?:,\d+)? @@ (.*)/)
  if (lineNumberMatch) {
    const startLine = parseInt(lineNumberMatch[1], 10)
    startIndex = startLine - 1 // Adjust for 0-based index
    lineCount = parseInt(lineNumberMatch[2], 10)
  } else {
    // console.error('Failed to parse hunk header:', line)
  }
  if (headlineMatch) {
    headline = headlineMatch[1]
  }

  return {
    startIndex,
    lineCount,
    headline,
  }
}

const parseHunk = (patchLines: string[], startIndex: number) => {
  const header = parseHunkHeader(patchLines[startIndex])

  const contextLines: string[] = []
  let j = startIndex + 1
  while (j < patchLines.length && !patchLines[j].startsWith('@@')) {
    if (!patchLines[j].startsWith('+')) {
      contextLines.push(patchLines[j].slice(1))
      j++
    } else break
  }

  return {
    ...header,
    contextLines,
  }
}

const findContextMatch = (
  lines: string[],
  contextLines: string[],
  startIndex: number,
) => {
  for (let i = startIndex; i <= lines.length - contextLines.length; i++) {
    if (contextLines.every((line, j) => lines[i + j] === line)) {
      return i
    }
  }
  return undefined
}
const findContextMatchTrimmed = (
  lines: string[],
  contextLines: string[],
  startIndex: number,
) => {
  for (let i = startIndex; i <= lines.length - contextLines.length; i++) {
    if (
      // Match without whitespace, or if the context line is blank.
      contextLines.every(
        (line, j) => lines[i + j].trim() === line.trim() || line.trim() === '',
      )
    ) {
      return i
    }
  }
  return undefined
}

const findPartialContextMatch = (
  lines: string[],
  contextLines: string[],
  startIndex: number,
) => {
  const window = contextLines.length
  const contextSet = new Set(contextLines.map((line) => line.trim()))

  let maxMatchCount = 0
  let maxMatchIndex: number | undefined = undefined
  for (let i = startIndex; i < lines.length - window; i++) {
    let matchCount = 0
    for (let j = 0; j < window; j++) {
      if (contextSet.has(lines[i + j].trim())) {
        matchCount++
      }
    }
    if (maxMatchCount === undefined || matchCount > maxMatchCount) {
      maxMatchCount = matchCount
      maxMatchIndex = i
    }
  }
  return maxMatchIndex
}

const getMatchIndex = (
  lines: string[],
  contextLines: string[],
  oldIndex: number,
  startIndex: number | undefined,
  headlineIndex: number | undefined,
): number => {
  let matchIndex: number | undefined

  if (
    startIndex !== undefined &&
    (headlineIndex === undefined || startIndex > headlineIndex)
  ) {
    matchIndex = findContextMatch(lines, contextLines, startIndex)
  }
  if (
    matchIndex === undefined &&
    headlineIndex !== undefined &&
    headlineIndex > oldIndex
  ) {
    matchIndex = findContextMatch(lines, contextLines, headlineIndex)
  }
  if (matchIndex === undefined) {
    matchIndex = findContextMatch(lines, contextLines, oldIndex)
  }
  if (
    startIndex !== undefined &&
    (headlineIndex === undefined || startIndex > headlineIndex)
  ) {
    matchIndex = findContextMatchTrimmed(lines, contextLines, startIndex)
  }
  if (
    matchIndex === undefined &&
    headlineIndex !== undefined &&
    headlineIndex > oldIndex
  ) {
    matchIndex = findContextMatchTrimmed(lines, contextLines, headlineIndex)
  }
  if (
    matchIndex === undefined &&
    headlineIndex !== undefined &&
    headlineIndex > oldIndex
  ) {
    matchIndex = findContextMatchTrimmed(lines, contextLines, oldIndex)
  }
  if (
    matchIndex === undefined &&
    headlineIndex !== undefined &&
    headlineIndex > oldIndex
  ) {
    matchIndex = findPartialContextMatch(lines, contextLines, headlineIndex)
  }
  if (matchIndex === undefined) {
    matchIndex = findPartialContextMatch(lines, contextLines, oldIndex)
  }
  if (
    matchIndex === undefined &&
    startIndex !== undefined &&
    startIndex > oldIndex
  ) {
    // We didn't find a match, just try anyway with the parsed line number.
    matchIndex = startIndex
  }

  return matchIndex ?? oldIndex
}

import fs from 'fs'
import path from 'path'

import { isFileIgnored } from '../project-file-tree'
import { applyPatch } from './patch'

import type { FileChanges } from '../actions'

export function applyChanges(projectRoot: string, changes: FileChanges) {
  const created: string[] = []
  const modified: string[] = []
  const ignored: string[] = []
  const invalid: string[] = []

  for (const change of changes) {
    const { path: filePath, content, type } = change
    try {
      if (isFileIgnored(filePath, projectRoot)) {
        ignored.push(filePath)
        continue
      }
    } catch {
      // File path caused an error.
      invalid.push(filePath)
      continue
    }
    try {
      const fullPath = path.join(projectRoot, filePath)
      const fileExists = fs.existsSync(fullPath)
      if (!fileExists) {
        // Create directories in the path if they don't exist
        const dirPath = path.dirname(fullPath)
        fs.mkdirSync(dirPath, { recursive: true })
      }

      if (type === 'file') {
        fs.writeFileSync(fullPath, content)
      } else {
        const oldContent = fs.readFileSync(fullPath, 'utf-8')
        const newContent = applyPatch(oldContent, content)
        fs.writeFileSync(fullPath, newContent)
      }
      if (fileExists) {
        modified.push(filePath)
      } else {
        created.push(filePath)
      }
    } catch (error) {
      console.error(`Failed to apply patch to ${filePath}:`, error, content)
      invalid.push(filePath)
    }
  }

  return { created, modified, ignored, invalid }
}

export async function applyAndRevertChanges(
  projectRoot: string,
  changes: FileChanges,
  onApply: () => Promise<void>,
) {
  const filesChanged = changes.map((change) => change.path)
  const files = Object.fromEntries(
    filesChanged.map((filePath) => {
      const fullPath = path.join(projectRoot, filePath)
      const oldContent = fs.existsSync(fullPath)
        ? fs.readFileSync(fullPath, 'utf-8')
        : '[DOES_NOT_EXIST]'
      return [filePath, oldContent]
    }),
  )
  applyChanges(projectRoot, changes)
  try {
    await onApply()
  } catch (error) {
    console.error(`Failed to apply changes:`, error)
  }
  for (const [filePath, oldContent] of Object.entries(files)) {
    if (oldContent === '[DOES_NOT_EXIST]') {
      if (fs.existsSync(path.join(projectRoot, filePath))) {
        fs.unlinkSync(path.join(projectRoot, filePath))
      }
    } else {
      fs.writeFileSync(path.join(projectRoot, filePath), oldContent)
    }
  }
}

import { geminiModels, openaiModels } from '@codebuff/common/constants'
import { buildArray } from '@codebuff/common/util/array'
import {
  parseFileBlocks,
  parseMarkdownCodeBlock,
} from '@codebuff/common/util/file'
import { generateCompactId, hasLazyEdit } from '@codebuff/common/util/string'

import { promptFlashWithFallbacks } from './llm-apis/gemini-with-fallbacks'
import { promptRelaceAI } from './llm-apis/relace-api'
import { promptAiSdk } from './llm-apis/vercel-ai-sdk/ai-sdk'
import { logger } from './util/logger'

import type { CodebuffMessage } from '@codebuff/common/types/message'

export async function fastRewrite(
  initialContent: string,
  editSnippet: string,
  filePath: string,
  instructions: string | undefined,
  clientSessionId: string,
  fingerprintId: string,
  userInputId: string,
  userId: string | undefined,
  userMessage: string | undefined,
) {
  const relaceStartTime = Date.now()
  const messageId = generateCompactId('cb-')
  let response = await promptRelaceAI(
    initialContent,
    editSnippet,
    instructions,
    {
      clientSessionId,
      fingerprintId,
      userInputId,
      userId,
      userMessage,
      messageId,
    },
  )
  const relaceDuration = Date.now() - relaceStartTime

  // Check if response still contains lazy edits
  if (
    hasLazyEdit(editSnippet) &&
    !hasLazyEdit(initialContent) &&
    hasLazyEdit(response)
  ) {
    const relaceResponse = response
    response = await rewriteWithOpenAI(
      initialContent,
      editSnippet,
      filePath,
      clientSessionId,
      fingerprintId,
      userInputId,
      userId,
      userMessage,
    )
    logger.debug(
      { filePath, relaceResponse, openaiResponse: response, messageId },
      `Relace output contained lazy edits, trying GPT-4o-mini ${filePath}`,
    )
  }

  logger.debug(
    {
      initialContent,
      editSnippet,
      response,
      userMessage,
      messageId,
      relaceDuration,
    },
    `fastRewrite of ${filePath}`,
  )

  return response
}

// Gemini flash can only output 8k tokens, openai models can do at least 16k tokens.
export async function rewriteWithOpenAI(
  oldContent: string,
  editSnippet: string,
  filePath: string,
  clientSessionId: string,
  fingerprintId: string,
  userInputId: string,
  userId: string | undefined,
  userMessage: string | undefined,
): Promise<string> {
  const prompt = `You are an expert programmer tasked with implementing changes to a file. Please rewrite the file to implement the changes shown in the edit snippet, while preserving the original formatting and behavior of unchanged parts.

Old file content:
\`\`\`
${oldContent}
\`\`\`

Edit snippet (the update to implement):
\`\`\`
${editSnippet}
\`\`\`

Integrate the edit snippet into the old file content to produce one coherent new file.

Important:
1. Preserve the original formatting, indentation, and comments of the old file. Please include all comments from the original file.
2. Only implement the changes shown in the edit snippet
3. Do not include any placeholder comments in your output (like "// ... existing code ..." or "# ... rest of the file ...")

Please output just the complete updated file content with the edit applied and no additional text.`

  const response = await promptAiSdk({
    messages: [
      { role: 'user', content: prompt },
      { role: 'assistant', content: '```\n' },
    ],
    model: openaiModels.o3mini,
    clientSessionId,
    fingerprintId,
    userInputId,
    userId,
  })

  return parseMarkdownCodeBlock(response) + '\n'
}

/**
 * This whole function is about checking for a specific case where claude
 * sketches an update to a single function, but forgets to add ... existing code ...
 * above and below the function.
 */
export const shouldAddFilePlaceholders = async (
  filePath: string,
  oldContent: string,
  rewrittenNewContent: string,
  messageHistory: CodebuffMessage[],
  fullResponse: string,
  userId: string | undefined,
  clientSessionId: string,
  fingerprintId: string,
  userInputId: string,
) => {
  const fileBlocks = parseFileBlocks(
    messageHistory
      .map((message) =>
        typeof message.content === 'string'
          ? message.content
          : message.content.map((c) => ('text' in c ? c.text : '')).join('\n'),
      )
      .join('\n') + fullResponse,
  )
  const fileWasPreviouslyEdited = Object.keys(fileBlocks).includes(filePath)
  if (!fileWasPreviouslyEdited) {
    // If Claude hasn't edited this file before, it's almost certainly not a local-only change.
    // Usually, it's only when Claude is editing a function for a second or third time that
    // it forgets to add ${EXISTING_CODE_MARKER}s above and below the function.
    return false
  }

  const prompt = `
Here's the original file:

\`\`\`
${oldContent}
\`\`\`

And here's the proposed new content for the file:

\`\`\`
${rewrittenNewContent}
\`\`\`

Consider the above information and conversation and answer the following question.
Most likely, the assistant intended to replace the entire original file with the new content. If so, write "REPLACE_ENTIRE_FILE".
In other cases, the assistant forgot to include the rest of the file and just wrote in one section of the file to be edited. Typically this happens if the new content focuses on the change of a single function or section of code with the intention to edit just this section, but keep the rest of the file unchanged. For example, if the new content is just a single function whereas the original file has multiple functions, and the conversation does not imply that the other functions should be deleted.
If you believe this is the scenario, please write "LOCAL_CHANGE_ONLY". Otherwise, write "REPLACE_ENTIRE_FILE".
Do not write anything else.
`.trim()

  const startTime = Date.now()

  const messages = buildArray(
    ...messageHistory,
    fullResponse && {
      role: 'assistant' as const,
      content: fullResponse,
    },
    {
      role: 'user' as const,
      content: prompt,
    },
  )
  const response = await promptFlashWithFallbacks(messages, {
    clientSessionId,
    fingerprintId,
    userInputId,
    model: geminiModels.gemini2flash,
    userId,
  })
  const shouldAddPlaceholderComments = response.includes('LOCAL_CHANGE_ONLY')
  logger.debug(
    {
      response,
      shouldAddPlaceholderComments,
      oldContent,
      rewrittenNewContent,
      filePath,
      duration: Date.now() - startTime,
    },
    `shouldAddFilePlaceholders response for ${filePath}`,
  )

  return shouldAddPlaceholderComments
}

import type { FileChange, FileChanges } from '@codebuff/common/actions'

/**
 * Singleton class for managing file changes and diffs throughout the application.
 * Provides centralized functionality for tracking, displaying, and managing file modifications.
 */
export class DiffManager {
  private static userInputChanges: FileChanges = []
  private static hookFiles: string[] = []
  private static userInputBeginning: boolean = false

  public static setChanges(userInputChanges: FileChanges): void {
    this.userInputChanges = [...userInputChanges]
  }

  public static startUserInput(): void {
    this.userInputBeginning = true
  }

  public static receivedResponse(): void {
    if (this.userInputBeginning) {
      this.userInputBeginning = false
      this.clearAllChanges()
    }
  }

  public static addChange(change: FileChange): void {
    if (this.userInputBeginning) {
      this.userInputBeginning = false
      this.clearAllChanges()
    }
    this.userInputChanges.push(change)
    this.hookFiles.push(change.path)
  }

  public static getChanges(): FileChanges {
    return [...this.userInputChanges]
  }

  public static getHookFiles(): string[] {
    return [...this.hookFiles]
  }

  public static clearAllChanges(): void {
    this.userInputChanges = []
    this.hookFiles = []
  }

  public static clearHookFiles(): void {
    this.hookFiles = []
  }
}

import { models } from '@codebuff/common/constants'
import {
  createMarkdownFileBlock,
  createSearchReplaceBlock,
} from '@codebuff/common/util/file'

import { promptAiSdk } from './llm-apis/vercel-ai-sdk/ai-sdk'
import { logger } from './util/logger'

export const parseAndGetDiffBlocksSingleFile = (
  newContent: string,
  oldFileContent: string,
) => {
  const diffBlocksThatDidntMatch: {
    searchContent: string
    replaceContent: string
  }[] = []
  const diffBlocks: { searchContent: string; replaceContent: string }[] = []
  const blockRegex =
    /<<<<<<< SEARCH\n([\s\S]*?)=======\n([\s\S]*?)>>>>>>> REPLACE/g
  let blockMatch

  while ((blockMatch = blockRegex.exec(newContent)) !== null) {
    const change = {
      searchContent: blockMatch[1],
      replaceContent: blockMatch[2],
    }

    if (oldFileContent.includes(change.searchContent)) {
      diffBlocks.push(change)
    } else {
      const newChange = tryToDoStringReplacementWithExtraIndentation(
        oldFileContent,
        change.searchContent,
        change.replaceContent,
      )
      if (newChange) {
        logger.debug('Matched with indentation modification')
        diffBlocks.push(newChange)
      } else {
        // Try matching without any whitespace as a last resort
        const noWhitespaceSearch = change.searchContent.replace(/\s+/g, '')
        const noWhitespaceOld = oldFileContent.replace(/\s+/g, '')
        const noWhitespaceIndex = noWhitespaceOld.indexOf(noWhitespaceSearch)

        if (noWhitespaceIndex >= 0) {
          // Count non-whitespace characters to find the real position
          let realIndex = 0
          let nonWhitespaceCount = 0
          while (nonWhitespaceCount < noWhitespaceIndex) {
            if (oldFileContent[realIndex].match(/\S/)) {
              nonWhitespaceCount++
            }
            realIndex++
          }

          // Count non-whitespace characters in search content to find length
          let searchLength = 0
          let nonWhitespaceSearchCount = 0
          while (
            nonWhitespaceSearchCount < noWhitespaceSearch.length &&
            realIndex + searchLength < oldFileContent.length
          ) {
            if (oldFileContent[realIndex + searchLength].match(/\S/)) {
              nonWhitespaceSearchCount++
            }
            searchLength++
          }

          // Find the actual content with original whitespace
          const actualContent = oldFileContent.slice(
            realIndex,
            realIndex + searchLength,
          )
          if (oldFileContent.includes(actualContent)) {
            logger.debug('Matched with whitespace removed')
            diffBlocks.push({
              searchContent: actualContent,
              replaceContent: change.replaceContent,
            })
          }
        } else {
          diffBlocksThatDidntMatch.push(change)
        }
      }
    }
  }
  return {
    diffBlocks,
    diffBlocksThatDidntMatch,
  }
}

export const tryToDoStringReplacementWithExtraIndentation = (
  oldFileContent: string,
  searchContent: string,
  replaceContent: string,
) => {
  for (let i = 1; i <= 12; i++) {
    const searchContentWithIndentation = searchContent
      .split('\n')
      .map((line) => (line ? ' '.repeat(i) + line : line))
      .join('\n')
    if (oldFileContent.includes(searchContentWithIndentation)) {
      return {
        searchContent: searchContentWithIndentation,
        replaceContent: replaceContent
          .split('\n')
          .map((line) => (line ? ' '.repeat(i) + line : line))
          .join('\n'),
      }
    }
  }
  for (let i = 1; i <= 6; i++) {
    const searchContentWithIndentation = searchContent
      .split('\n')
      .map((line) => (line ? '\t'.repeat(i) + line : line))
      .join('\n')
    if (oldFileContent.includes(searchContentWithIndentation)) {
      return {
        searchContent: searchContentWithIndentation,
        replaceContent: replaceContent
          .split('\n')
          .map((line) => (line ? '\t'.repeat(i) + line : line))
          .join('\n'),
      }
    }
  }
  return null
}

export async function retryDiffBlocksPrompt(
  filePath: string,
  oldContent: string,
  clientSessionId: string,
  fingerprintId: string,
  userInputId: string,
  userId: string | undefined,
  diffBlocksThatDidntMatch: { searchContent: string; replaceContent: string }[],
) {
  const newPrompt =
    `The assistant failed to find a match for the following changes. Please help the assistant understand what the changes should be.

Here is the old file content:
${createMarkdownFileBlock(filePath, oldContent)}

The assistant generated the following SEARCH/REPLACE blocks where the search content did not match the old file contents:

${diffBlocksThatDidntMatch.map((change) => createSearchReplaceBlock(change.searchContent, change.replaceContent)).join('\n\n')}

The search content needs to match an exact substring of the old file content, which will be replaced by the replace content. Use the minimal possible search content that matches the intended location in the old file content. Be extra careful when matching whitespace, single quotes, double quotes, and backticks.

Provide a new set of SEARCH/REPLACE changes to make the intended edit from the old file.`.trim()

  const response = await promptAiSdk({
    messages: [{ role: 'user', content: newPrompt }],
    model: models.openrouter_claude_sonnet_4,
    clientSessionId,
    fingerprintId,
    userInputId,
    userId,
  })
  const {
    diffBlocks: newDiffBlocks,
    diffBlocksThatDidntMatch: newDiffBlocksThatDidntMatch,
  } = parseAndGetDiffBlocksSingleFile(response, oldContent)

  if (newDiffBlocksThatDidntMatch.length > 0) {
    logger.error(
      {
        response,
        diffBlocksThatDidntMatch,
        newDiffBlocks,
        newDiffBlocksThatDidntMatch,
        filePath,
      },
      `retryDiffBlocksPrompt failed ${filePath}`,
    )
  } else {
    logger.debug(
      {
        response,
        diffBlocksThatDidntMatch,
        newDiffBlocks,
        newDiffBlocksThatDidntMatch,
        filePath,
      },
      `retryDiffBlocksPrompt result ${filePath}`,
    )
  }

  return { newDiffBlocks, newDiffBlocksThatDidntMatch }
}

