```typescript
'use client'

import { useQuery } from '@tanstack/react-query'
import { useState, useMemo } from 'react'
import { motion } from 'framer-motion'
import { Bot, Search } from 'lucide-react'
import Link from 'next/link'

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { formatCompact, formatCurrency } from '@/lib/number-format'

interface Publisher {
  id: string
  name: string
  verified: boolean
  avatar_url?: string
}

interface UsageMetrics {
  usage_count: number
  total_spent: number
  avg_cost_per_invocation: number
  avg_response_time: number
}

interface Agent {
  id: string
  version: string
  publisher_id: string
  name: string
  description: string
  tags: string[]
  publisher: Publisher
  metrics: UsageMetrics
  created_at: string
}

type SortOption = 'most_used' | 'newest' | 'name' | 'total_spent'

const AgentsPage = () => {
  const [searchQuery, setSearchQuery] = useState('')
  const [sortBy, setSortBy] = useState<SortOption>('most_used')

  const { data: agents, isLoading, isError } = useQuery<Agent[]>({
    queryKey: ['agents'],
    queryFn: async () => {
      const response = await fetch('/api/agents')
      if (!response.ok) throw new Error('Failed to fetch agents')
      return response.json()
    },
    staleTime: 5 * 60 * 1000,
  })

  const filteredAndSortedAgents = useMemo(() => {
    if (!agents) return []

    // Filter by search query
    let filtered = agents
    if (searchQuery) {
      const query = searchQuery.toLowerCase()
      filtered = agents.filter(agent => 
        agent.name.toLowerCase().includes(query) ||
        agent.description.toLowerCase().includes(query) ||
        agent.tags.some(tag => tag.toLowerCase().includes(query))
      )
    }

    // Sort
    const sorted = [...filtered].sort((a, b) => {
      switch (sortBy) {
        case 'most_used':
          return b.metrics.usage_count - a.metrics.usage_count
        case 'newest':
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
        case 'name':
          return a.name.localeCompare(b.name)
        case 'total_spent':
          return b.metrics.total_spent - a.metrics.total_spent
        default:
          return 0
      }
    })

    return sorted
  }, [agents, searchQuery, sortBy])

  return (
    <div className="container mx-auto py-6 px-4 sm:py-10 sm:px-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold flex items-center gap-2">
            <Bot className="h-8 w-8" />
            Agent Store
          </h1>
          <p className="text-muted-foreground mt-2">
            Discover and use community-built AI agents
          </p>
        </div>

        {/* Search and Filters */}
        <div className="flex flex-col sm:flex-row gap-4 mb-6">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search agents by name, description, or tags..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
            />
          </div>
          <Select value={sortBy} onValueChange={(value) => setSortBy(value as SortOption)}>
            <SelectTrigger className="w-full sm:w-48">
              <SelectValue placeholder="Sort by" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="most_used">Most Used</SelectItem>
              <SelectItem value="newest">Newest</SelectItem>
              <SelectItem value="name">Name</SelectItem>
              <SelectItem value="total_spent">Total Spent</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Loading State */}
        {isLoading && <AgentGridSkeleton />}

        {/* Error State */}
        {isError && (
          <Card className="border-destructive">
            <CardHeader>
              <CardTitle className="text-destructive">Error Loading Agents</CardTitle>
            </CardHeader>
            <CardContent>
              <p>Could not load agents. Please try refreshing the page.</p>
            </CardContent>
          </Card>
        )}

        {/* Empty State */}
        {!isLoading && !isError && filteredAndSortedAgents.length === 0 && (
          <Card className="border-dashed">
            <CardContent className="flex flex-col items-center justify-center py-12">
              <Bot className="h-12 w-12 text-muted-foreground mb-4" />
              <p className="text-lg font-semibold mb-2">No agents found</p>
              <p className="text-muted-foreground">
                {searchQuery ? 'Try adjusting your search query' : 'No agents available yet'}
              </p>
            </CardContent>
          </Card>
        )}

        {/* Agent Grid */}
        {!isLoading && !isError && filteredAndSortedAgents.length > 0 && (
          <motion.div 
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
            layout
          >
            {filteredAndSortedAgents.map((agent) => (
              <AgentCard key={`${agent.publisher_id}-${agent.id}-${agent.version}`} agent={agent} />
            ))}
          </motion.div>
        )}
      </div>
    </div>
  )
}

const AgentCard = ({ agent }: { agent: Agent }) => {
  const maxVisibleTags = 3
  const visibleTags = agent.tags.slice(0, maxVisibleTags)
  const remainingCount = agent.tags.length - maxVisibleTags

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ y: -4 }}
      transition={{ duration: 0.2 }}
    >
      <Link href={`/publishers/${agent.publisher_id}/agents/${agent.id}/${agent.version}`}>
        <Card className="h-full hover:shadow-lg transition-shadow cursor-pointer">
          <CardHeader>
            <CardTitle className="text-lg">{agent.name}</CardTitle>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <span>{agent.publisher.name}</span>
              {agent.publisher.verified && (
                <Badge variant="secondary" className="text-xs">
                  ✓ Verified
                </Badge>
              )}
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Description */}
            <p className="text-sm text-muted-foreground line-clamp-2">
              {agent.description}
            </p>

            {/* Stats Grid (2x2) */}
            <div className="grid grid-cols-2 gap-3">
              <div className="text-sm">
                <div className="text-muted-foreground">Usage</div>
                <div className="font-semibold">{formatCompact(agent.metrics.usage_count)}</div>
              </div>
              <div className="text-sm">
                <div className="text-muted-foreground">Total Spent</div>
                <div className="font-semibold">{formatCurrency(agent.metrics.total_spent / 100, { currency: 'USD' })}</div>
              </div>
              <div className="text-sm">
                <div className="text-muted-foreground">Avg Cost</div>
                <div className="font-semibold">{formatCurrency(agent.metrics.avg_cost_per_invocation / 100, { currency: 'USD' })}</div>
              </div>
              <div className="text-sm">
                <div className="text-muted-foreground">Version</div>
                <Badge variant="outline" className="text-xs">v{agent.version}</Badge>
              </div>
            </div>

            {/* Tags */}
            {agent.tags.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {visibleTags.map((tag) => (
                  <Badge key={tag} variant="secondary" className="text-xs">
                    {tag}
                  </Badge>
                ))}
                {remainingCount > 0 && (
                  <Badge variant="secondary" className="text-xs">
                    +{remainingCount}
                  </Badge>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </Link>
    </motion.div>
  )
}

const AgentGridSkeleton = () => (
  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
    {Array.from({ length: 6 }).map((_, i) => (
      <Card key={i} className="animate-pulse">
