import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { desc, eq, sql } from 'drizzle-orm'
import { NextResponse } from 'next/server'

function hashString(str: string): number {
  let hash = 0
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i)
    hash = (hash << 5) - hash + char
    hash = hash & hash
  }
  return Math.abs(hash)
}

function generateMockMetrics(agentId: string, publisherId: string, createdAt: Date) {
  const seed = hashString(`${publisherId}/${agentId}`)
  const ageDays = Math.max(1, Math.floor((Date.now() - createdAt.getTime()) / (1000 * 60 * 60 * 24)))

  const baseUsage = Math.log(ageDays + 1) * 100
  const usageVariance = (seed % 60) - 30
  const usage_count = Math.floor(Math.max(0, baseUsage * (1 + usageVariance / 100)))

  const costSeed = (seed * 17) % 100
  const avg_cost_per_invocation = Math.floor((5 + (costSeed < 80 ? costSeed / 10 : costSeed / 2)))

  const total_spent = usage_count * avg_cost_per_invocation

  const timeSeed = (seed * 31) % 100
  const avg_response_time = Math.floor(1000 + (timeSeed < 70 ? timeSeed * 25 : timeSeed * 100))

  return {
    usage_count,
    total_spent,
    avg_cost_per_invocation,
    avg_response_time,
  }
}

export async function GET() {
  try {
    const latestAgentsSubquery = db
      .select({
        publisher_id: schema.agentConfig.publisher_id,
        id: schema.agentConfig.id,
        max_major: sql<number>`MAX(${schema.agentConfig.major})`.as('max_major'),
      })
      .from(schema.agentConfig)
      .groupBy(schema.agentConfig.publisher_id, schema.agentConfig.id)
      .as('latest_versions')

    const agents = await db
      .select({
        id: schema.agentConfig.id,
        version: schema.agentConfig.version,
        publisher_id: schema.agentConfig.publisher_id,
        data: schema.agentConfig.data,
        created_at: schema.agentConfig.created_at,
        major: schema.agentConfig.major,
        publisher: {
          id: schema.publisher.id,
          name: schema.publisher.name,
          verified: schema.publisher.verified,
          avatar_url: schema.publisher.avatar_url,
        },
      })
      .from(schema.agentConfig)
      .innerJoin(
        schema.publisher,
        eq(schema.agentConfig.publisher_id, schema.publisher.id)
      )
      .innerJoin(
        latestAgentsSubquery,
        and(
          eq(schema.agentConfig.publisher_id, latestAgentsSubquery.publisher_id),
          eq(schema.agentConfig.id, latestAgentsSubquery.id),
          eq(schema.agentConfig.major, latestAgentsSubquery.max_major)
        )
      )
      .orderBy(desc(schema.agentConfig.created_at))
      .limit(100)

    const formattedAgents = agents.map((agent) => {
      const agentData = agent.data as any

      const name = agentData.displayName || agentData.name || agent.id
      const description = agentData.description || ''
      const tags = Array.isArray(agentData.tags) ? agentData.tags : []

      const metrics = generateMockMetrics(agent.id, agent.publisher_id, agent.created_at)

      return {
        id: agent.id,
        version: agent.version,
        publisher_id: agent.publisher_id,
        name,
        description,
        tags,
        publisher: agent.publisher,
        metrics,
        created_at: agent.created_at.toISOString(),
      }
    })

    return NextResponse.json({ agents: formattedAgents }, { status: 200 })
  } catch (error) {
    console.error('Error fetching agents:', error)
    return NextResponse.json(
      { error: 'Failed to fetch agents' },
      { status: 500 }
    )
  }
}

export interface CompactNumberOptions {
  locale?: string
  maximumFractionDigits?: number
}

export interface CurrencyOptions {
  locale?: string
  currency?: string
  minimumFractionDigits?: number
  maximumFractionDigits?: number
}

export const formatCompactNumber = (
  value: number | null | undefined,
  options: CompactNumberOptions = {}
): string => {
  if (value == null) return '—'

  const { locale = 'en-US', maximumFractionDigits = 1 } = options

  return new Intl.NumberFormat(locale, {
    notation: 'compact',
    compactDisplay: 'short',
    maximumFractionDigits,
  }).format(value)
}

export const formatCurrency = (
  value: number | null | undefined,
  options: CurrencyOptions = {}
): string => {
  if (value == null) return '—'

  const {
    locale = 'en-US',
    currency = 'USD',
    minimumFractionDigits = 2,
    maximumFractionDigits = 2,
  } = options

  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    minimumFractionDigits,
    maximumFractionDigits,
  }).format(value)
}

'use client'

import { useQuery } from '@tanstack/react-query'
import { useState, useMemo } from 'react'
import { motion } from 'framer-motion'
import { Bot, Search, CheckCircle2 } from 'lucide-react'
import Link from 'next/link'

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'

interface Publisher {
  id: string
  name: string
  verified: boolean
  avatar_url: string | null
}

interface UsageMetrics {
  usage_count: number
  total_spent: number
  avg_cost_per_invocation: number
  avg_response_time: number
}

interface Agent {
  id: string
  version: string
  name: string
  description: string
  tags: string[]
  publisher: Publisher
  usage_metrics: UsageMetrics
  created_at: string
}

type SortOption = 'most_used' | 'newest' | 'name' | 'total_spent'

const formatCompactNumber = (value: number): string => {
  if (value >= 1000000) {
    return `${(value / 1000000).toFixed(1)}M`
  }
  if (value >= 1000) {
    return `${(value / 1000).toFixed(1)}K`
  }
  return value.toString()
}

const formatCurrency = (value: number): string => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value / 100)
}

const AgentsPage = () => {
  const [searchQuery, setSearchQuery] = useState('')
  const [sortBy, setSortBy] = useState<SortOption>('most_used')

  const {
    data: response,
    isLoading,
    isError,
  } = useQuery<{ agents: Agent[] }>({
    queryKey: ['agents'],
    queryFn: async () => {
      const res = await fetch('/api/agents')
      if (!res.ok) throw new Error('Failed to fetch agents')
      return res.json()
    },
    staleTime: 5 * 60 * 1000,
  })

  const agents = response?.agents || []

  const filteredAndSortedAgents = useMemo(() => {
    if (!agents.length) return []

    let filtered = agents
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim()
      filtered = agents.filter(
        (agent) =>
          agent.name.toLowerCase().includes(query) ||
          agent.description.toLowerCase().includes(query) ||
          agent.tags.some((tag) => tag.toLowerCase().includes(query))
      )
    }

    const sorted = [...filtered].sort((a, b) => {
      switch (sortBy) {
        case 'most_used':
          return b.usage_metrics.usage_count - a.usage_metrics.usage_count
        case 'newest':
          return (
            new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
          )
        case 'name':
          return a.name.localeCompare(b.name)
        case 'total_spent':
          return b.usage_metrics.total_spent - a.usage_metrics.total_spent
        default:
          return 0
      }
    })

    return sorted
  }, [agents, searchQuery, sortBy])

  return (
    <div className="container mx-auto py-6 px-4 sm:py-10 sm:px-6">
      <div className="max-w-7xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold flex items-center gap-3">
            <Bot className="h-8 w-8 text-primary" />
            Agent Store
          </h1>
          <p className="text-muted-foreground mt-2">
            Discover and use community-built AI agents
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 mb-8">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search agents by name, description, or tags..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10"
            />
          </div>
          <Select
            value={sortBy}
            onValueChange={(value) => setSortBy(value as SortOption)}
          >
            <SelectTrigger className="w-full sm:w-48">
              <SelectValue placeholder="Sort by" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="most_used">Most Used</SelectItem>
              <SelectItem value="newest">Newest</SelectItem>
              <SelectItem value="name">Name</SelectItem>
              <SelectItem value="total_spent">Total Spent</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {isLoading && <AgentGridSkeleton />}

        {isError && (
          <Card className="border-destructive">
            <CardHeader>
              <CardTitle className="text-destructive">
                Error Loading Agents
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p>Could not load agents. Please try refreshing the page.</p>
            </CardContent>
          </Card>
        )}

        {!isLoading && !isError && filteredAndSortedAgents.length === 0 && (
          <Card className="border-dashed border-2">
            <CardContent className="flex flex-col items-center justify-center py-12">
              <Bot className="h-12 w-12 text-muted-foreground mb-4" />
              <p className="text-lg font-semibold mb-2">No agents found</p>
              <p className="text-muted-foreground text-center">
                {searchQuery.trim()
                  ? 'Try adjusting your search query'
                  : 'No agents available yet'}
              </p>
            </CardContent>
          </Card>
        )}

        {!isLoading && !isError && filteredAndSortedAgents.length > 0 && (
          <motion.div
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"
            layout
          >
            {filteredAndSortedAgents.map((agent) => (
              <AgentCard
                key={`${agent.publisher.id}-${agent.id}-${agent.version}`}
                agent={agent}
              />
            ))}
          </motion.div>
        )}
      </div>
    </div>
  )
}

const AgentCard = ({ agent }: { agent: Agent }) => {
  const maxVisibleTags = 3
  const visibleTags = agent.tags.slice(0, maxVisibleTags)
  const remainingCount = agent.tags.length - maxVisibleTags

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ y: -4, transition: { duration: 0.2 } }}
      transition={{ duration: 0.3 }}
      layout
    >
      <Link
        href={`/publishers/${agent.publisher.id}/agents/${agent.id}/${agent.version}`}
      >
        <Card className="h-full hover:shadow-lg transition-shadow cursor-pointer">
          <CardHeader className="space-y-2">
            <CardTitle className="text-lg line-clamp-1">
              {agent.name}
            </CardTitle>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <span className="truncate">{agent.publisher.name}</span>
              {agent.publisher.verified && (
                <div className="flex items-center gap-1 flex-shrink-0">
                  <CheckCircle2 className="h-4 w-4 text-blue-500" />
                  <span className="text-xs text-blue-500">Verified</span>
                </div>
              )}
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-sm text-muted-foreground line-clamp-2 min-h-[2.5rem]">
              {agent.description || 'No description available'}
            </p>

            <div className="grid grid-cols-2 gap-3">
              <div className="text-sm space-y-1">
                <div className="text-muted-foreground text-xs">Usage</div>
                <div className="font-semibold">
                  {formatCompactNumber(agent.usage_metrics.usage_count)}
                </div>
              </div>
              <div className="text-sm space-y-1">
                <div className="text-muted-foreground text-xs">Total Spent</div>
                <div className="font-semibold">
                  {formatCurrency(agent.usage_metrics.total_spent)}
                </div>
              </div>
              <div className="text-sm space-y-1">
                <div className="text-muted-foreground text-xs">Avg Cost</div>
                <div className="font-semibold">
                  {formatCurrency(agent.usage_metrics.avg_cost_per_invocation)}
                </div>
              </div>
              <div className="text-sm space-y-1">
                <div className="text-muted-foreground text-xs">Version</div>
                <Badge variant="outline" className="text-xs w-fit">
                  v{agent.version}
                </Badge>
              </div>
            </div>

            {agent.tags.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {visibleTags.map((tag) => (
                  <Badge
                    key={tag}
                    variant="secondary"
                    className="text-xs truncate max-w-[120px]"
                  >
                    {tag}
                  </Badge>
                ))}
                {remainingCount > 0 && (
                  <Badge variant="secondary" className="text-xs">
                    +{remainingCount}
                  </Badge>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </Link>
    </motion.div>
  )
}

const AgentGridSkeleton = () => (
  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
    {Array.from({ length: 6 }).map((_, i) => (
      <Card key={i} className="animate-pulse">
        <CardHeader className="space-y-2">
          <Skeleton className="h-6 w-3/4" />
          <Skeleton className="h-4 w-1/2" />
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Skeleton className="h-4 w-full" />
            <Skeleton className="h-4 w-2/3" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <Skeleton className="h-14 w-full" />
            <Skeleton className="h-14 w-full" />
            <Skeleton className="h-14 w-full" />
            <Skeleton className="h-14 w-full" />
          </div>
          <div className="flex gap-2">
            <Skeleton className="h-6 w-16" />
            <Skeleton className="h-6 w-16" />
            <Skeleton className="h-6 w-20" />
          </div>
        </CardContent>
      </Card>
    ))}
  </div>
)

export default AgentsPage

