export function supportsCacheControl(model: Model): boolean {
  if (!isExplicitlyDefinedModel(model)) {
    // Default to no cache control for unknown models
    return false
  }
  return !nonCacheableModels.includes(model)
}

export const TEST_USER_ID = 'test-user-id'

export function getModelFromShortName(
  modelName: string | undefined,
): Model | undefined {
  if (!modelName) return undefined
  if (modelName && !(modelName in shortModelNames)) {
    throw new Error(
      `Unknown model: ${modelName}. Please use a valid model. Valid models are: ${Object.keys(
        shortModelNames,
      ).join(', ')}`,
    )
  }

  return shortModelNames[modelName as keyof typeof shortModelNames]
}

export const providerDomains = {
  google: 'google.com',
  anthropic: 'anthropic.com',
  openai: 'chatgpt.com',
  deepseek: 'deepseek.com',
  xai: 'x.ai',
} as const

export function getLogoForModel(modelName: string): string | undefined {
  let domain: string | undefined

  if (Object.values(geminiModels).includes(modelName as GeminiModel))
    domain = providerDomains.google
  else if (Object.values(openaiModels).includes(modelName as OpenAIModel))
    domain = providerDomains.openai
  else if (Object.values(deepseekModels).includes(modelName as DeepseekModel))
    domain = providerDomains.deepseek
  else if (modelName.includes('claude')) domain = providerDomains.anthropic
  else if (modelName.includes('grok')) domain = providerDomains.xai

  return domain
    ? `https://www.google.com/s2/favicons?domain=${domain}&sz=256`
    : undefined
}

import { AsyncLocalStorage } from 'async_hooks'

export interface LoggerContext {
  userId?: string
  userEmail?: string
  clientSessionId?: string
  fingerprintId?: string
  clientRequestId?: string
  messageId?: string
  discordId?: string
  costMode?: string
  [key: string]: any // Allow for future extensions
}

export interface RequestContextData {
  // The user ID for whom this context is established
  currentUserId?: string

  // The specific organization ID under which the repoUrl was approved for the currentUserId
  approvedOrgIdForRepo?: string

  // The repository URL that was processed for approval
  processedRepoUrl?: string

  // The owner of the repository, parsed from processedRepoUrl
  processedRepoOwner?: string

  // The base name of the repository, parsed from processedRepoUrl
  processedRepoName?: string

  // The full repository identifier in "owner/repo" format
  processedRepoId?: string

  // Flag indicating if the processedRepoUrl is approved for the currentUserId within the approvedOrgIdForRepo
  isRepoApprovedForUserInOrg?: boolean
}

export interface AppContext {
  logger: LoggerContext
  request: RequestContextData
}

export const appContextStore = new AsyncLocalStorage<AppContext>()

/**
 * Helper function to run a callback with a new app context.
 * This establishes both logger and request contexts in a single call.
 */
export function withAppContext<T>(
  loggerData: Partial<LoggerContext>,
  requestData: RequestContextData,
  callback: () => T,
): T {
  const existingContext = appContextStore.getStore()
  return appContextStore.run(
    {
      logger: { ...existingContext?.logger, ...loggerData },
      request: { ...existingContext?.request, ...requestData },
    },
    callback,
  )
}

/**
 * Helper function to update the current app context.
 */
export function updateAppContext(updates: {
  logger?: Partial<LoggerContext>
  request?: Partial<RequestContextData>
}): void {
  const store = appContextStore.getStore()
  if (store) {
    if (updates.logger) {
      Object.assign(store.logger, updates.logger)
    }
    if (updates.request) {
      Object.assign(store.request, updates.request)
    }
  }
}

/**
 * Helper function to get the current app context.
 */
export function getAppContext(): AppContext | undefined {
  return appContextStore.getStore()
}

/**
 * Helper function to get just the logger context.
 */
export function getLoggerContext(): LoggerContext | undefined {
  return appContextStore.getStore()?.logger
}

/**
 * Helper function to get just the request context.
 */
export function getRequestContext(): RequestContextData | undefined {
  return appContextStore.getStore()?.request
}

/**
 * Helper function to update just the request context.
 */
export function updateRequestContext(
  updates: Partial<RequestContextData>,
): void {
  updateAppContext({ request: updates })
}

import { z } from 'zod'

import { CodebuffMessageSchema } from './message'
import { ProjectFileContextSchema } from '../util/file'

import type { CodebuffMessage } from './message'
import type { ProjectFileContext } from '../util/file'

export const toolCallSchema = z.object({
  toolName: z.string(),
  args: z.record(z.string(), z.any()),
  toolCallId: z.string(),
})
export type ToolCall = z.infer<typeof toolCallSchema>

export const toolResultSchema = z.object({
  toolName: z.string(),
  toolCallId: z.string(),
  result: z.string(),
})
export type ToolResult = z.infer<typeof toolResultSchema>

export const subgoalSchema = z.object({
  objective: z.string().optional(),
  status: z
    .enum(['NOT_STARTED', 'IN_PROGRESS', 'COMPLETE', 'ABORTED'])
    .optional(),
  plan: z.string().optional(),
  logs: z.string().array(),
})
export type Subgoal = z.infer<typeof subgoalSchema>

export const AgentStateSchema: z.ZodType<{
  agentId: string
  agentType: AgentTemplateType | null
  agentContext: Record<string, Subgoal>
  subagents: AgentState[]
  messageHistory: CodebuffMessage[]
  stepsRemaining: number
  output?: Record<string, any>
  parentId?: string
}> = z.lazy(() =>
  z.object({
    agentId: z.string(),
    agentType: z.string().nullable(),
    agentContext: z.record(z.string(), subgoalSchema),
    subagents: AgentStateSchema.array(),
    messageHistory: CodebuffMessageSchema.array(),
    stepsRemaining: z.number(),
    output: z.record(z.string(), z.any()).optional(),
    parentId: z.string().optional(),
  }),
)
export type AgentState = z.infer<typeof AgentStateSchema>

export const AgentTemplateTypeList = [
  // Base agents
  'base',
  'base_lite',
  'base_max',
  'base_experimental',
  'claude4_gemini_thinking',
  'superagent',
  'base_agent_builder',

  // Ask mode
  'ask',

  // Planning / Thinking
  'planner',
  'dry_run',
  'thinker',

  // Other agents
  'file_picker',
  'file_explorer',
  'researcher',
  'reviewer',
  'agent_builder',
  'example_programmatic',
] as const
type UnderscoreToDash<S extends string> = S extends `${infer L}_${infer R}`
  ? `${L}-${UnderscoreToDash<R>}` // recurse on the remainder
  : S
export const AgentTemplateTypes = Object.fromEntries(
  AgentTemplateTypeList.map((name) => [name, name.replaceAll('_', '-')]),
) as { [K in (typeof AgentTemplateTypeList)[number]]: UnderscoreToDash<K> }
const agentTemplateTypeSchema = z.enum(AgentTemplateTypeList)
// Allow dynamic agent types by extending the base enum with string
export type AgentTemplateType =
  | z.infer<typeof agentTemplateTypeSchema>
  | (string & {})

export const SessionStateSchema = z.object({
  fileContext: ProjectFileContextSchema,
  mainAgentState: AgentStateSchema,
})
export type SessionState = z.infer<typeof SessionStateSchema>

export function getInitialSessionState(
  fileContext: ProjectFileContext,
): SessionState {
  return {
    mainAgentState: {
      agentId: 'main-agent',
      agentType: null,
      agentContext: {},
      subagents: [],
      messageHistory: [],
      stepsRemaining: 12,
      output: undefined,
    },
    fileContext,
  }
}

import { WEBSOCKET_URL } from './constants'
import { APIRealtimeClient } from '../../common/src/websockets/websocket-client'

import type { ServerAction, ClientAction } from '../../common/src/actions'
import type { WebSocket } from 'ws'

export type WebSocketHandlerOptions = {
  onWebsocketError?: (error: WebSocket.ErrorEvent) => void
  onWebsocketReconnect?: () => void
  onRequestReconnect?: () => Promise<void>
  onResponseError?: (
    error: Extract<ServerAction, { type: 'action-error' }>,
  ) => Promise<void>
  readFiles: (
    filePath: string[],
  ) => Promise<Extract<ClientAction, { type: 'read-files-response' }>['files']>
  handleToolCall: (
    action: Extract<ServerAction, { type: 'tool-call-request' }>,
  ) => Promise<
    Omit<
      Extract<ClientAction, { type: 'tool-call-response' }>,
      'type' | 'requestId'
    >
  >
  onCostResponse?: (
    action: Extract<ServerAction, { type: 'message-cost-response' }>,
  ) => Promise<void>
  onUsageResponse?: (
    action: Extract<ServerAction, { type: 'usage-response' }>,
  ) => Promise<void>

  onResponseChunk?: (
    action: Extract<ServerAction, { type: 'response-chunk' }>,
  ) => Promise<void>
  onSubagentResponseChunk?: (
    action: Extract<ServerAction, { type: 'subagent-response-chunk' }>,
  ) => Promise<void>

  onPromptResponse?: (
    action: Extract<ServerAction, { type: 'prompt-response' }>,
  ) => Promise<void>

  apiKey: string
}

type InternalWebSocketHandlerOptions = Required<WebSocketHandlerOptions>

export class WebSocketHandler {
  private cbWebSocket: APIRealtimeClient
  private onRequestReconnect: InternalWebSocketHandlerOptions['onRequestReconnect']
  private onResponseError: InternalWebSocketHandlerOptions['onResponseError']
  private readFiles: InternalWebSocketHandlerOptions['readFiles']
  private handleToolCall: InternalWebSocketHandlerOptions['handleToolCall']
  private onCostResponse: InternalWebSocketHandlerOptions['onCostResponse']
  private onUsageResponse: InternalWebSocketHandlerOptions['onUsageResponse']
  private onResponseChunk: InternalWebSocketHandlerOptions['onResponseChunk']
  private onSubagentResponseChunk: InternalWebSocketHandlerOptions['onSubagentResponseChunk']
  private onPromptResponse: InternalWebSocketHandlerOptions['onPromptResponse']
  private apiKey: string

  constructor({
    onWebsocketError = () => {},
    onWebsocketReconnect = () => {},
    onRequestReconnect = async () => {},
    onResponseError = async () => {},
    readFiles,
    handleToolCall,
    onCostResponse = async () => {},
    onUsageResponse = async () => {},

    onResponseChunk = async () => {},
    onSubagentResponseChunk = async () => {},

    onPromptResponse = async () => {},

    apiKey,
  }: WebSocketHandlerOptions) {
    this.cbWebSocket = new APIRealtimeClient(
      WEBSOCKET_URL,
      onWebsocketError,
      onWebsocketReconnect,
    )
    this.onRequestReconnect = onRequestReconnect

    this.onResponseError = onResponseError
    this.readFiles = readFiles
    this.handleToolCall = handleToolCall
    this.onCostResponse = onCostResponse
    this.onUsageResponse = onUsageResponse

    this.onResponseChunk = onResponseChunk
    this.onSubagentResponseChunk = onSubagentResponseChunk

    this.onPromptResponse = onPromptResponse

    this.apiKey = apiKey
  }

  public async connect() {
    await this.cbWebSocket.connect()
    this.setupSubscriptions()
  }

  public reconnect() {
    this.cbWebSocket.forceReconnect()
  }

  public close() {
    this.cbWebSocket.close()
  }

  private setupSubscriptions() {
    this.cbWebSocket.subscribe('action-error', this.onResponseError)

    this.cbWebSocket.subscribe('read-files', async (a) => {
      const { filePaths, requestId } = a
      const files = await this.readFiles(filePaths)

      this.cbWebSocket.sendAction({
        type: 'read-files-response',
        files,
        requestId,
      })
    })

    // Handle backend-initiated tool call requests
    this.cbWebSocket.subscribe('tool-call-request', async (action) => {
      const toolCallResult = await this.handleToolCall(action)

      this.cbWebSocket.sendAction({
        type: 'tool-call-response',
        requestId: action.requestId,
        ...toolCallResult,
      })
    })

    this.cbWebSocket.subscribe('message-cost-response', this.onCostResponse)

    this.cbWebSocket.subscribe('usage-response', this.onUsageResponse)

    // Used to handle server restarts gracefully
    this.cbWebSocket.subscribe('request-reconnect', this.onRequestReconnect)

    // Handle streaming messages
    this.cbWebSocket.subscribe('response-chunk', this.onResponseChunk)
    this.cbWebSocket.subscribe(
      'subagent-response-chunk',
      this.onSubagentResponseChunk,
    )

    // Handle full response from prompt
    this.cbWebSocket.subscribe('prompt-response', this.onPromptResponse)
  }

  private getInputDefaultOptions() {
    return {
      ...({
        type: 'prompt',
        fingerprintId: 'codebuff-sdk',
      } as const),
      authToken: this.apiKey,
    }
  }

  public sendInput(
    action: Omit<
      Extract<ClientAction, { type: 'prompt' }>,
      keyof ReturnType<typeof this.getInputDefaultOptions>
    >,
  ) {
    this.cbWebSocket.sendAction({
      ...action,
      ...this.getInputDefaultOptions(),
    })
  }

  public cancelInput({ promptId }: { promptId: string }) {
    this.cbWebSocket.sendAction({
      type: 'cancel-user-input',
      authToken: this.apiKey,
      promptId,
    })
  }
}

