import { z } from 'zod'

import { costModes } from './constants'
import { GrantTypeValues } from './types/grant'
import { printModeEventSchema } from './types/print-mode'
import {
  SessionStateSchema,
  toolCallSchema,
  toolResultSchema,
} from './types/session-state'
import { FileVersionSchema, ProjectFileContextSchema } from './util/file'

export const FileChangeSchema = z.object({
  type: z.enum(['patch', 'file']),
  path: z.string(),
  content: z.string(),
})
export type FileChange = z.infer<typeof FileChangeSchema>
export const CHANGES = z.array(FileChangeSchema)
export type FileChanges = z.infer<typeof CHANGES>

export const CLIENT_ACTION_SCHEMA = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('prompt'),
    promptId: z.string(),
    prompt: z.string().or(z.undefined()),
    promptParams: z.record(z.string(), z.any()).optional(), // Additional json params.
    fingerprintId: z.string(),
    authToken: z.string().optional(),
    costMode: z.enum(costModes).optional().default('normal'),
    sessionState: SessionStateSchema,
    toolResults: z.array(toolResultSchema),
    model: z.string().optional(),
    repoUrl: z.string().optional(),
    agentId: z.string().optional(),
  }),
  z.object({
    type: z.literal('read-files-response'),
    files: z.record(z.string(), z.union([z.string(), z.null()])),
    requestId: z.string().optional(),
  }),
  z.object({
    type: z.literal('init'),
    fingerprintId: z.string(),
    authToken: z.string().optional(),
    fileContext: ProjectFileContextSchema,
    repoUrl: z.string().optional(),
  }),
  z.object({
    type: z.literal('generate-commit-message'),
    fingerprintId: z.string(),
    authToken: z.string().optional(),
    stagedChanges: z.string(),
  }),
  z.object({
    type: z.literal('tool-call-response'),
    requestId: z.string(),
    success: z.boolean(),
    result: z.any().optional(), // Tool execution result
    error: z.string().optional(), // Error message if execution failed
  }),
  z.object({
    type: z.literal('cancel-user-input'),
    authToken: z.string(),
    promptId: z.string(),
  }),
])

export type ClientAction = z.infer<typeof CLIENT_ACTION_SCHEMA>

export const UsageReponseSchema = z.object({
  type: z.literal('usage-response'),
  usage: z.number(),
  remainingBalance: z.number(),
  balanceBreakdown: z
    .record(
      z.enum([GrantTypeValues[0], ...GrantTypeValues.slice(1)]),
      z.number(),
    )
    .optional(),
  next_quota_reset: z.coerce.date().nullable(),
  autoTopupAdded: z.number().optional(),
})
export type UsageResponse = z.infer<typeof UsageReponseSchema>

export const InitResponseSchema = z
  .object({
    type: z.literal('init-response'),
    message: z.string().optional(),
    agentNames: z.record(z.string(), z.string()).optional(),
  })
  .merge(
    UsageReponseSchema.omit({
      type: true,
    }),
  )
export type InitResponse = z.infer<typeof InitResponseSchema>

export const ResponseCompleteSchema = z
  .object({
    type: z.literal('response-complete'),
    userInputId: z.string(),
    response: z.string(),
    changes: CHANGES,
    changesAlreadyApplied: CHANGES,
    addedFileVersions: z.array(FileVersionSchema),
    resetFileVersions: z.boolean(),
  })
  .merge(
    UsageReponseSchema.omit({
      type: true,
    }).partial(),
  )

export const MessageCostResponseSchema = z.object({
  type: z.literal('message-cost-response'),
  promptId: z.string(),
  credits: z.number(),
})
export type MessageCostResponse = z.infer<typeof MessageCostResponseSchema>

export const PromptResponseSchema = z.object({
  type: z.literal('prompt-response'),
  promptId: z.string(),
  sessionState: SessionStateSchema,
  toolCalls: z.array(toolCallSchema),
  toolResults: z.array(toolResultSchema),
})
export type PromptResponse = z.infer<typeof PromptResponseSchema>

export const SERVER_ACTION_SCHEMA = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('response-chunk'),
    userInputId: z.string(),
    chunk: z.union([z.string(), printModeEventSchema]),
  }),
  z.object({
    type: z.literal('subagent-response-chunk'),
    userInputId: z.string(),
    agentId: z.string(),
    agentType: z.string(),
    chunk: z.string(),
    prompt: z.string().optional(),
  }),
  ResponseCompleteSchema,
  PromptResponseSchema,
  z.object({
    type: z.literal('read-files'),
    filePaths: z.array(z.string()),
    requestId: z.string(),
  }),
  z.object({
    type: z.literal('tool-call-request'),
    userInputId: z.string(),
    requestId: z.string(),
    toolName: z.string(),
    args: z.record(z.any()),
    timeout: z.number().optional(),
  }),
  z.object({
    type: z.literal('tool-call'),
    userInputId: z.string(),
    response: z.string(),
    data: toolCallSchema,
    changes: CHANGES,
    changesAlreadyApplied: CHANGES,
    addedFileVersions: z.array(FileVersionSchema),
    resetFileVersions: z.boolean(),
  }),
  z.object({
    type: z.literal('terminal-command-result'),
    userInputId: z.string(),
    result: z.string(),
  }),
  z.object({
    type: z.literal('npm-version-status'),
    isUpToDate: z.boolean(),
    latestVersion: z.string(),
  }),
  InitResponseSchema,
  UsageReponseSchema,
  MessageCostResponseSchema,
  z.object({
    type: z.literal('action-error'),
    message: z.string(),
    error: z.string().optional(),
    remainingBalance: z.number().optional(),
  }),
  z.object({
    type: z.literal('commit-message-response'),
    commitMessage: z.string(),
  }),
  z.object({
    // The server is imminently going to shutdown, and the client should reconnect
    type: z.literal('request-reconnect'),
  }),
])

export type ServerAction = z.infer<typeof SERVER_ACTION_SCHEMA>

import { WebSocket } from 'ws'

import type { ClientAction, ServerAction } from '../actions'
import type {
  ClientMessage,
  ClientMessageType,
  ServerMessage,
} from './websocket-schema'

// mqp: useful for debugging
const VERBOSE_LOGGING = false

const TIMEOUT_MS = 120_000

const RECONNECT_WAIT_MS = 5_000

type ConnectingState = typeof WebSocket.CONNECTING
type OpenState = typeof WebSocket.OPEN
type ClosingState = typeof WebSocket.CLOSING
type ClosedState = typeof WebSocket.CLOSED

export type ReadyState =
  | OpenState
  | ConnectingState
  | ClosedState
  | ClosingState

export function formatState(state: ReadyState) {
  switch (state) {
    case WebSocket.CONNECTING:
      return 'connecting'
    case WebSocket.OPEN:
      return 'open'
    case WebSocket.CLOSING:
      return 'closing'
    case WebSocket.CLOSED:
      return 'closed'
    default:
      throw new Error('Invalid websocket state.')
  }
}

type OutstandingTxn = {
  resolve: () => void
  reject: (err: Error) => void
  timeout?: any
}

/** Client for the API websocket realtime server. Automatically manages reconnection
 * and resubscription on disconnect, and allows subscribers to get a callback
 * when something is broadcasted. */
export class APIRealtimeClient {
  ws!: WebSocket
  url: string
  // Callbacks subscribed to individual actions.
  subscribers: Map<ServerAction['type'], ((action: ServerAction) => void)[]>
  txid: number
  // all txns that are in flight, with no ack/error/timeout
  txns: Map<number, OutstandingTxn>
  connectTimeout?: any
  heartbeat?: any
  hadError = false
  onError: () => void
  onReconnect: () => void

  constructor(url: string, onError: () => void, onReconnect: () => void) {
    this.url = url
    this.txid = 0
    this.txns = new Map()
    this.subscribers = new Map()
    this.onError = onError
    this.onReconnect = onReconnect
  }

  get state() {
    return this.ws.readyState as ReadyState
  }

  close() {
    this.ws.close(1000, 'Closed manually.')
    clearTimeout(this.connectTimeout)
  }

  connect() {
    // you may wish to refer to https://websockets.spec.whatwg.org/
    // in order to check the semantics of events etc.
    this.ws = new WebSocket(this.url)
    this.ws.onmessage = (ev) => {
      if (this.hadError) {
        this.hadError = false
        this.onReconnect()
      }
      this.receiveMessage(JSON.parse(ev.data as any))
    }
    this.ws.onerror = (ev) => {
      if (!this.hadError) {
        this.onError()
        this.hadError = true
      }
      // this can fire without an onclose if this is the first time we ever try
      // to connect, so we need to turn on our reconnect in that case
      this.waitAndReconnect()
    }
    this.ws.onclose = (ev) => {
      // note that if the connection closes due to an error, onerror fires and then this
      if (VERBOSE_LOGGING) {
        console.info(`API websocket closed with code=${ev.code}: ${ev.reason}`)
      }
      clearInterval(this.heartbeat)

      // mqp: we might need to change how the txn stuff works if we ever want to
      // implement "wait until i am subscribed, and then do something" in a component.
      // right now it cannot be reliably used to detect that in the presence of reconnects
      for (const txn of Array.from(this.txns.values())) {
        clearTimeout(txn.timeout)
        // NOTE (James): Don't throw an error when the websocket is closed...
        // This seems to be happening, but the client can recover.
        txn.resolve()
        // txn.reject(new Error('Websocket was closed.'))
      }
      this.txns.clear()

      // 1000 is RFC code for normal on-purpose closure
      if (ev.code !== 1000) {
        this.waitAndReconnect()
      }
    }
    return new Promise<void>((resolve) => {
      this.ws.onopen = (_ev) => {
        if (VERBOSE_LOGGING) {
          console.info('API websocket opened.')
        }
        this.heartbeat = setInterval(
          async () => this.sendMessage('ping', {}).catch(() => {}),
          30000,
        )

        resolve()
      }
    })
  }

  waitAndReconnect() {
    if (this.connectTimeout == null) {
      this.connectTimeout = setTimeout(() => {
        this.connectTimeout = undefined
        this.connect()
      }, RECONNECT_WAIT_MS)
    }
  }

  forceReconnect() {
    // Close the current connection if it's open
    if (this.ws && this.state !== WebSocket.CLOSED) {
      this.ws.close(1000, 'Forced reconnection due to server shutdown notice')
    }

    // Immediately attempt to reconnect
    this.connect().catch((err) => {
      console.error('Failed to reconnect after server shutdown notice:', err)
      // Still set up delayed reconnect as fallback
      this.waitAndReconnect()
    })
  }

  receiveMessage(msg: ServerMessage) {
    if (VERBOSE_LOGGING) {
      console.info('< Incoming API websocket message: ', msg)
    }
    switch (msg.type) {
      case 'action': {
        const action = msg.data
        const subscribers = this.subscribers.get(action.type) ?? []
        for (const callback of subscribers) {
          callback(action)
        }
        return
      }
      case 'ack': {
        if (msg.txid != null) {
          const txn = this.txns.get(msg.txid)
          if (txn == null) {
            // mqp: only reason this should happen is getting an ack after timeout
            console.warn(`Websocket message with old txid=${msg.txid}.`)
          } else {
            clearTimeout(txn.timeout)
            if (msg.error != null) {
              txn.reject(new Error(msg.error))
            } else {
              txn.resolve()
            }
            this.txns.delete(msg.txid)
          }
        }
        return
      }
      default:
        console.warn(`Unknown API websocket message type received: ${msg}`)
    }
  }

  async sendMessage<T extends ClientMessageType>(
    type: T,
    data: Omit<ClientMessage<T>, 'type' | 'txid'>,
  ) {
    if (VERBOSE_LOGGING) {
      console.info(`> Outgoing API websocket ${type} message: `, data)
    }
    if (this.state === WebSocket.OPEN) {
      return new Promise<void>((resolve, reject) => {
        const txid = this.txid++
        const timeout = setTimeout(() => {
          this.txns.delete(txid)
          reject(new Error(`Websocket message with txid ${txid} timed out.`))
        }, TIMEOUT_MS)
        this.txns.set(txid, { resolve, reject, timeout })
        this.ws.send(JSON.stringify({ type, txid, ...data }))
      })
    } else {
      // expected if components in the code try to subscribe or unsubscribe
      // while the socket is closed -- in this case we expect to get the state
      // fixed up in the websocket onopen handler when we reconnect
    }
  }

  async sendAction(action: ClientAction) {
    try {
      return await this.sendMessage('action', {
        data: action,
      })
    } catch (e) {
      // Print the error message for debugging.
      console.error(
        'Error sending action:',
        action.type,
        typeof e === 'object' && e !== null && 'message' in e ? e.message : e,
      )

      console.log()
      console.log('Codebuff is exiting due to an error.')
      console.log('Make sure you are on the latest version of Codebuff!')
      console.log('-----------------------------------')
      console.log('Please run: npm install -g codebuff')
      console.log('-----------------------------------')

      process.exit(1)
    }
  }

  subscribe<T extends ServerAction['type']>(
    action: T,
    callback: (action: Extract<ServerAction, { type: T }>) => void,
  ) {
    const currSubscribers = this.subscribers.get(action) ?? []
    this.subscribers.set(action, [
      ...currSubscribers,
      callback as (action: ServerAction) => void,
    ])

    return () => {
      const newSubscribers = currSubscribers.filter((cb) => cb !== callback)
      this.subscribers.set(action, newSubscribers)
    }
  }
}

