export async function GET() {
  const session = await getServerSession(authOptions)

  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  try {
    const user = await db.query.user.findFirst({
      where: eq(schema.user.id, session.user.id),
      columns: {
        handle: true,
        referral_code: true,
        auto_topup_enabled: true,
        auto_topup_threshold: true,
        auto_topup_amount: true,
        created_at: true,  // Add this field to the query
      },
    })

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 })
    }

    const { blockedReason: auto_topup_blocked_reason } =
      await validateAutoTopupStatus(session.user.id)

    const response: Partial<UserProfile> = {
      handle: user.handle,
      referral_code: user.referral_code,
      auto_topup_enabled: user.auto_topup_enabled && !auto_topup_blocked_reason,
      auto_topup_threshold: user.auto_topup_threshold ?? 500,
      auto_topup_amount: user.auto_topup_amount ?? 2000,
      auto_topup_blocked_reason,
      createdAt: user.created_at ? user.created_at.toISOString() : null,  // Serialize to ISO string
    }

    return NextResponse.json(response)
  } catch (error) {
    // ... existing error handling
  }
}
```

### web/src/hooks/use-user-profile.ts
```typescript
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useSession } from 'next-auth/react'
import { useEffect, useCallback } from 'react'

import type { UserProfile } from '@/types/user'

const CACHE_KEY = 'userProfile'
const QUERY_KEY = ['userProfile']

// Helper to safely access localStorage
function getLocalStorage(): Storage | null {
  try {
    return typeof window !== 'undefined' ? window.localStorage : null
  } catch {
    return null
  }
}

// Serialize profile for localStorage (convert Date to ISO string)
function serializeProfile(profile: UserProfile): string {
  const serialized = {
    ...profile,
    createdAt: profile.createdAt ? profile.createdAt.toISOString() : null,
  }
  return JSON.stringify(serialized)
}

// Deserialize profile from localStorage (convert ISO string to Date)
function deserializeProfile(data: string): UserProfile | null {
  try {
    const parsed = JSON.parse(data)
    return {
      ...parsed,
      createdAt: parsed.createdAt ? new Date(parsed.createdAt) : null,
    }
  } catch {
    return null
  }
}

// Get cached profile from localStorage
function getCachedProfile(): UserProfile | null {
  const storage = getLocalStorage()
  if (!storage) return null

  try {
    const cached = storage.getItem(CACHE_KEY)
    if (!cached) return null
    return deserializeProfile(cached)
  } catch {
    return null
  }
}

// Save profile to localStorage
function setCachedProfile(profile: UserProfile): void {
  const storage = getLocalStorage()
  if (!storage) return

  try {
    storage.setItem(CACHE_KEY, serializeProfile(profile))
  } catch {
    // Silently fail if localStorage is unavailable
  }
}

// Clear profile from localStorage
function clearCachedProfile(): void {
  const storage = getLocalStorage()
  if (!storage) return

  try {
    storage.removeItem(CACHE_KEY)
  } catch {
    // Silently fail
  }
}

interface UseUserProfileResult {
  data: UserProfile | undefined
  isLoading: boolean
  error: Error | null
  refetch: () => void
  clearCache: () => void
}

export function useUserProfile(): UseUserProfileResult {
  const queryClient = useQueryClient()
  const { data: session, status } = useSession()
  const isAuthenticated = status === 'authenticated' && !!session?.user

  // Query for user profile
  const { data, isLoading, error, refetch } = useQuery<UserProfile>({
    queryKey: QUERY_KEY,
    queryFn: async () => {
      const response = await fetch('/api/user/profile')
      if (!response.ok) throw new Error('Failed to fetch profile')
      const apiData = await response.json()

      // Convert createdAt from ISO string to Date
      const profile: UserProfile = {
        ...apiData,
        createdAt: apiData.createdAt ? new Date(apiData.createdAt) : null,
      }

      // Cache to localStorage on successful fetch
      setCachedProfile(profile)

      return profile
    },
    enabled: isAuthenticated,
    // Use cached data as initial data if available
    initialData: () => getCachedProfile() || undefined,
    staleTime: 5 * 60 * 1000, // 5 minutes
  })

  // Clear cache function
  const clearCache = useCallback(() => {
    clearCachedProfile()
    queryClient.invalidateQueries({ queryKey: QUERY_KEY })
    queryClient.removeQueries({ queryKey: QUERY_KEY })
  }, [queryClient])

  // Automatically clear cache on logout (when session becomes unauthenticated)
  useEffect(() => {
    if (status === 'unauthenticated') {
      clearCache()
    }
  }, [status, clearCache])

  return {
    data,
    isLoading,
    error: error as Error | null,
    refetch,
    clearCache,
  }
}
```

## Key Design Decisions

1. **Date Serialization**: Convert `Date` objects to ISO strings for localStorage, and parse them back to `Date` objects when reading. This ensures proper type safety and avoids serialization issues.

2. **localStorage Fallback**: All localStorage operations are wrapped in try-catch blocks and return gracefully if localStorage is unavailable (e.g., private browsing mode).

3. **Initial Data Pattern**: Use React Query's `initialData` option to provide cached data immediately on mount, reducing perceived loading time.

4. **Automatic Logout Detection**: Listen to NextAuth's session status changes. When status becomes 'unauthenticated', automatically clear both localStorage and React Query cache.

5. **Manual Cache Clearing**: Expose a `clearCache` function for manual invalidation when needed (e.g., after profile updates or manual logout flows).

6. **Consistent with Existing Patterns**: Follows the same structure as `useAutoTopup` with similar error handling, query configuration, and state management.

7. **SSR-Safe**: All localStorage access is guarded with `typeof window !== 'undefined'` checks to avoid Next.js hydration issues.

