type UsageData = Omit<MakeNullable<UsageResponse, 'remainingBalance'>, 'type'>

interface ClientOptions {
  websocketUrl: string
  onWebSocketError: () => void
  onWebSocketReconnect: () => void
  freshPrompt: () => void
  reconnectWhenNextIdle: () => void
