import { uniq } from 'lodash'
import type { WebSocket } from 'ws'

import { renderToolResults } from '@codebuff/common/tools/utils'
import { AgentTemplateTypes } from '@codebuff/common/types/session-state'

import { checkTerminalCommand } from './check-terminal-command'
import { loopAgentSteps } from './run-agent-step'
import { getAgentTemplate } from './templates/agent-registry'
import { logger } from './util/logger'
import { expireMessages } from './util/messages'
import { requestToolCall } from './websockets/websocket-action'

import type { ClientToolCall } from './tools/constants'
import type { ClientAction } from '@codebuff/common/actions'
import type { CostMode } from '@codebuff/common/constants'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  SessionState,
  ToolResult,
  AgentTemplateType,
} from '@codebuff/common/types/session-state'
import { AgentTemplate } from './templates/types'

export interface MainPromptOptions {
  userId: string | undefined
  clientSessionId: string
  onResponseChunk: (chunk: string | PrintModeEvent) => void
  localAgentTemplates: Record<string, AgentTemplate>
}

export const mainPrompt = async (
  ws: WebSocket,
  action: Extract<ClientAction, { type: 'prompt' }>,
  options: MainPromptOptions,
): Promise<{
  sessionState: SessionState
  toolCalls: Array<ClientToolCall>
  toolResults: Array<ToolResult>
}> => {
  const { userId, clientSessionId, onResponseChunk, localAgentTemplates } =
    options

  const {
    prompt,
    sessionState: sessionState,
    fingerprintId,
    costMode,
    promptId,
    agentId,
    promptParams,
  } = action
  const { fileContext, mainAgentState } = sessionState

  if (prompt) {
    // Check if this is a direct terminal command
    const startTime = Date.now()
    const terminalCommand = await checkTerminalCommand(prompt, {
      clientSessionId,
      fingerprintId,
      userInputId: promptId,
      userId,
    })
    const duration = Date.now() - startTime

    if (terminalCommand) {
      logger.debug(
        {
          duration,
          prompt,
        },
        `Detected terminal command in ${duration}ms, executing directly: ${prompt}`,
      )

      const response = await requestToolCall(
        ws,
        promptId,
        'run_terminal_command',
        {
          command: terminalCommand,
          mode: 'user',
          process_type: 'SYNC',
          timeout_seconds: -1,
        },
      )

      const toolResult = response.success ? response.result : response.error
      if (response.success) {
        mainAgentState.messageHistory.push({
          role: 'user',
          content: renderToolResults([toolResult]),
        })
      }

      const newSessionState = {
        ...sessionState,
        messageHistory: expireMessages(
          mainAgentState.messageHistory,
          'userPrompt',
        ),
      }

      return {
        sessionState: newSessionState,
        toolCalls: [],
        toolResults: [],
      }
    }
  }

  const availableAgents = Object.keys(localAgentTemplates)

  // Determine agent type - prioritize CLI agent selection, then config base agent, then cost mode
  let agentType: AgentTemplateType

  if (agentId) {
    if (!(await getAgentTemplate(agentId, localAgentTemplates))) {
      throw new Error(
        `Invalid agent ID: "${agentId}". Available agents: ${availableAgents.join(', ')}`,
      )
    }

    agentType = agentId
    logger.info(
      {
        agentId,
        promptParams,
        prompt: prompt?.slice(0, 50),
      },
      `Using CLI-specified agent: ${agentId}`,
    )
  } else {
    // Check for base agent in config
    const configBaseAgent = fileContext.codebuffConfig?.baseAgent
    if (configBaseAgent) {
      if (!(await getAgentTemplate(configBaseAgent, localAgentTemplates))) {
        throw new Error(
          `Invalid base agent in config: "${configBaseAgent}". Available agents: ${availableAgents.join(', ')}`,
        )
      }
      agentType = configBaseAgent
      logger.info(
        {
          configBaseAgent,
          promptParams,
          prompt: prompt?.slice(0, 50),
        },
        `Using config-specified base agent: ${configBaseAgent}`,
      )
    } else {
      // Fall back to cost mode mapping
      agentType = (
        {
          ask: AgentTemplateTypes.ask,
          lite: AgentTemplateTypes.base_lite,
          normal: AgentTemplateTypes.base,
          max: AgentTemplateTypes.base_max,
          experimental: AgentTemplateTypes.base_experimental,
        } satisfies Record<CostMode, AgentTemplateType>
      )[costMode]
    }
  }

  mainAgentState.agentType = agentType

  let mainAgentTemplate = await getAgentTemplate(agentType, localAgentTemplates)
  if (!mainAgentTemplate) {
    throw new Error(`Agent template not found for type: ${agentType}`)
  }

  // Update the main agent template with subagents from codebuff config or add all dynamic agents
  const updatedSubagents =
    fileContext.codebuffConfig?.subagents ??
    uniq([...mainAgentTemplate.subagents, ...availableAgents])
  mainAgentTemplate.subagents = updatedSubagents
  localAgentTemplates[agentType] = mainAgentTemplate

  const { agentState } = await loopAgentSteps(ws, {
    userInputId: promptId,
    prompt,
    params: promptParams,
    agentType,
    agentState: mainAgentState,
    fingerprintId,
    fileContext,
    toolResults: [],
    userId,
    clientSessionId,
    onResponseChunk,
    localAgentTemplates,
  })

  return {
    sessionState: {
      fileContext,
      mainAgentState: agentState,
    },
    toolCalls: [],
    toolResults: [],
  }
}

import { calculateUsageAndBalance } from '@codebuff/billing'
import { trackEvent } from '@codebuff/common/analytics'
import {
  ASYNC_AGENTS_ENABLED,
  toOptionalFile,
} from '@codebuff/common/constants'
import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import db from '@codebuff/common/db/index'
import * as schema from '@codebuff/common/db/schema'
import { formatValidationErrorMessage } from '@codebuff/common/util/agent-template-validation'
import { buildArray } from '@codebuff/common/util/array'
import { ensureEndsWithNewline } from '@codebuff/common/util/file'
import { generateCompactId } from '@codebuff/common/util/string'
import { eq } from 'drizzle-orm'

import { asyncAgentManager } from '../async-agent-manager'
import {
  cancelUserInput,
  checkLiveUserInput,
  endUserInput,
  startUserInput,
} from '../live-user-inputs'
import { mainPrompt } from '../main-prompt'
import { protec } from './middleware'
import { sendMessage } from './server'
import { assembleLocalAgentTemplates } from '../templates/agent-registry'
import { logger, withLoggerContext } from '../util/logger'
import { asSystemMessage } from '../util/messages'

import type {
  ClientAction,
  ServerAction,
  UsageResponse,
} from '@codebuff/common/actions'
import type { ClientMessage } from '@codebuff/common/websockets/websocket-schema'
import type { WebSocket } from 'ws'

/**
 * Sends an action to the client via WebSocket
 * @param ws - The WebSocket connection to send the action to
 * @param action - The server action to send
 */
export const sendAction = (ws: WebSocket, action: ServerAction) => {
  sendMessage(ws, {
    type: 'action',
    data: action,
  })
}

/**
 * Retrieves a user ID from an authentication token
 * @param authToken - The authentication token to validate
 * @returns The user ID if found, undefined otherwise
 */
export const getUserIdFromAuthToken = async (
  authToken?: string,
): Promise<string | undefined> => {
  if (!authToken) return undefined

  const userId = await db
    .select({ userId: schema.user.id })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, authToken))
    .then((users) => {
      if (users.length === 1) {
        return users[0].userId
      }
      return undefined
    })

  return userId
}

/**
 * Generates a usage response object for the client
 * @param fingerprintId - The fingerprint ID for the user/device
 * @param userId - user ID for authenticated users
 * @param clientSessionId - Optional session ID
 * @returns A UsageResponse object containing usage metrics and referral information
 */
export async function genUsageResponse(
  fingerprintId: string,
  userId: string,
  clientSessionId: string | undefined,
): Promise<UsageResponse> {
  const logContext = { fingerprintId, userId, sessionId: clientSessionId }
  const defaultResp = {
    type: 'usage-response' as const,
    usage: 0,
    remainingBalance: 0,
    balanceBreakdown: {},
    next_quota_reset: null,
  }

  return withLoggerContext(logContext, async () => {
    const user = await db.query.user.findFirst({
      where: eq(schema.user.id, userId),
      columns: {
        next_quota_reset: true,
      },
    })

    if (!user) {
      return defaultResp
    }

    try {
      // Get the usage data
      const { balance: balanceDetails, usageThisCycle } =
        await calculateUsageAndBalance(userId, new Date())

      return {
        type: 'usage-response' as const,
        usage: usageThisCycle,
        remainingBalance: balanceDetails.totalRemaining,
        balanceBreakdown: balanceDetails.breakdown,
        next_quota_reset: user.next_quota_reset,
      }
    } catch (error) {
      logger.error(
        { error, usage: defaultResp },
        'Error generating usage response, returning default',
      )
    }

    return defaultResp
  })
}

/**
 * Handles prompt actions from the client
 * @param action - The prompt action from the client
 * @param clientSessionId - The client's session ID
 * @param ws - The WebSocket connection
 */
const onPrompt = async (
  action: Extract<ClientAction, { type: 'prompt' }>,
  clientSessionId: string,
  ws: WebSocket,
) => {
  const { fingerprintId, authToken, promptId, prompt, costMode } = action

  await withLoggerContext(
    { fingerprintId, clientRequestId: promptId, costMode },
    async () => {
      const userId = await getUserIdFromAuthToken(authToken)
      if (!userId) {
        throw new Error('User not found')
      }

      if (prompt) {
        logger.info(`USER INPUT: ${prompt}`)
        trackEvent(AnalyticsEvent.USER_INPUT, userId, {
          prompt,
          promptId,
        })
      }

      startUserInput(userId, promptId)

      try {
        await callMainPrompt(ws, action, {
          userId,
          promptId,
          clientSessionId,
        })
      } catch (e) {
        logger.error(e, 'Error in mainPrompt')
        let response =
          e && typeof e === 'object' && 'message' in e ? `\n\n${e.message}` : ''

        const newMessages = buildArray(
          ...action.sessionState.mainAgentState.messageHistory,
          prompt && {
            role: 'user' as const,
            content: prompt,
          },
          {
            role: 'user' as const,
            content: asSystemMessage(`Received error from server: ${response}`),
          },
        )

        sendAction(ws, {
          type: 'response-chunk',
          userInputId: promptId,
          chunk: { type: 'error', message: response },
        })
        sendAction(ws, {
          type: 'response-chunk',
          userInputId: promptId,
          chunk: response,
        })
        setTimeout(() => {
          sendAction(ws, {
            type: 'prompt-response',
            promptId,
            // Send back original sessionState.
            sessionState: {
              ...action.sessionState,
              mainAgentState: {
                ...action.sessionState.mainAgentState,
                messageHistory: newMessages,
              },
            },
            toolCalls: [],
            toolResults: [],
          })
        }, 100)
      } finally {
        endUserInput(userId, promptId)
        const usageResponse = await genUsageResponse(
          fingerprintId,
          userId,
          undefined,
        )
        sendAction(ws, usageResponse)
      }
    },
  )
}

export const callMainPrompt = async (
  ws: WebSocket,
  action: Extract<ClientAction, { type: 'prompt' }>,
  options: {
    userId: string
    promptId: string
    clientSessionId: string
  },
) => {
  const { userId, promptId, clientSessionId } = options
  const { fileContext } = action.sessionState

  // Assemble local agent templates from fileContext
  const { agentTemplates: localAgentTemplates } =
    assembleLocalAgentTemplates(fileContext)

  const result = await mainPrompt(ws, action, {
    userId,
    clientSessionId,
    localAgentTemplates,
    onResponseChunk: (chunk) => {
      if (checkLiveUserInput(userId, promptId, clientSessionId)) {
        sendAction(ws, {
          type: 'response-chunk',
          userInputId: promptId,
          chunk,
        })
      }
    },
  })

  const { sessionState, toolCalls, toolResults } = result
  // Send prompt data back
  sendAction(ws, {
    type: 'prompt-response',
    promptId,
    sessionState,
    toolCalls: toolCalls as any[],
    toolResults,
  })

  return result
}

/**
 * Handles initialization actions from the client
 * @param fileContext - The file context information
 * @param fingerprintId - The fingerprint ID for the user/device
 * @param authToken - The authentication token
 * @param clientSessionId - The client's session ID
 * @param ws - The WebSocket connection
 */
const onInit = async (
  {
    fileContext,
    fingerprintId,
    authToken,
  }: Extract<ClientAction, { type: 'init' }>,
  clientSessionId: string,
  ws: WebSocket,
) => {
  await withLoggerContext({ fingerprintId }, async () => {
    const userId = await getUserIdFromAuthToken(authToken)

    if (!userId) {
      sendAction(ws, {
        usage: 0,
        remainingBalance: 0,
        balanceBreakdown: {},
        next_quota_reset: null,
        type: 'init-response',
      })
      return
    }

    // Assemble local agent templates from fileContext
    const { agentTemplates, validationErrors } =
      assembleLocalAgentTemplates(fileContext)

    if (validationErrors.length > 0) {
      logger.warn(
        { errorCount: validationErrors.length },
        'Agent template validation errors found',
      )
    }

    const errorMessage = formatValidationErrorMessage(validationErrors)

    // Get all agent names for frontend
    const allAgentNames: Record<string, string> = {}
    for (const [id, template] of Object.entries(agentTemplates)) {
      allAgentNames[id] = template.displayName
    }

    // Send combined init and usage response
    const usageResponse = await genUsageResponse(
      fingerprintId,
      userId,
      clientSessionId,
    )
    sendAction(ws, {
      ...usageResponse,
      type: 'init-response',
      message: errorMessage
        ? `**Agent Template Validation Errors:**\n${errorMessage}`
        : undefined,
      agentNames: allAgentNames,
    })
  })
}

const onCancelUserInput = async ({
  authToken,
  promptId,
}: Extract<ClientAction, { type: 'cancel-user-input' }>) => {
  const userId = await getUserIdFromAuthToken(authToken)
  if (!userId) {
    logger.error({ authToken }, 'User id not found for authToken')
    return
  }
  cancelUserInput(userId, promptId)
  if (ASYNC_AGENTS_ENABLED) {
    asyncAgentManager.cleanupUserInputAgents(promptId)
  }
}

/**
 * Storage for action callbacks organized by action type
 */
const callbacksByAction = {} as Record<
  ClientAction['type'],
  ((action: ClientAction, clientSessionId: string, ws: WebSocket) => void)[]
>

/**
 * Subscribes a callback function to a specific action type
 * @param type - The action type to subscribe to
 * @param callback - The callback function to execute when the action is received
 * @returns A function to unsubscribe the callback
 */
export const subscribeToAction = <T extends ClientAction['type']>(
  type: T,
  callback: (
    action: Extract<ClientAction, { type: T }>,
    clientSessionId: string,
    ws: WebSocket,
  ) => void,
) => {
  callbacksByAction[type] = (callbacksByAction[type] ?? []).concat(
    callback as (
      action: ClientAction,
      clientSessionId: string,
      ws: WebSocket,
    ) => void,
  )
  return () => {
    callbacksByAction[type] = (callbacksByAction[type] ?? []).filter(
      (cb) => cb !== callback,
    )
  }
}

/**
 * Handles WebSocket action messages from clients
 * @param ws - The WebSocket connection
 * @param clientSessionId - The client's session ID
 * @param msg - The action message from the client
 */
export const onWebsocketAction = async (
  ws: WebSocket,
  clientSessionId: string,
  msg: ClientMessage & { type: 'action' },
) => {
  await withLoggerContext({ clientSessionId }, async () => {
    const callbacks = callbacksByAction[msg.data.type] ?? []
    try {
      await Promise.all(
        callbacks.map((cb) => cb(msg.data, clientSessionId, ws)),
      )
    } catch (e) {
      logger.error(
        {
          message: msg,
          error: e && typeof e === 'object' && 'message' in e ? e.message : e,
        },
        'Got error running subscribeToAction callback',
      )
    }
  })
}

// Register action handlers
subscribeToAction('prompt', protec.run(onPrompt))
subscribeToAction('init', protec.run(onInit, { silent: true }))
subscribeToAction('cancel-user-input', protec.run(onCancelUserInput))

/**
 * Requests multiple files from the client
 * @param ws - The WebSocket connection
 * @param filePaths - Array of file paths to request
 * @returns Promise resolving to an object mapping file paths to their contents
 */
export async function requestFiles(ws: WebSocket, filePaths: string[]) {
  return new Promise<Record<string, string | null>>((resolve) => {
    const requestId = generateCompactId()
    const unsubscribe = subscribeToAction('read-files-response', (action) => {
      for (const [filename, contents] of Object.entries(action.files)) {
        action.files[filename] = ensureEndsWithNewline(contents)
      }
      if (action.requestId === requestId) {
        unsubscribe()
        resolve(action.files)
      }
    })
    sendAction(ws, {
      type: 'read-files',
      filePaths,
      requestId,
    })
  })
}

/**
 * Requests a single file from the client
 * @param ws - The WebSocket connection
 * @param filePath - The path of the file to request
 * @returns Promise resolving to the file contents or null if not found
 */
export async function requestFile(ws: WebSocket, filePath: string) {
  const files = await requestFiles(ws, [filePath])
  return files[filePath] ?? null
}

export async function requestOptionalFile(ws: WebSocket, filePath: string) {
  const file = await requestFile(ws, filePath)
  return toOptionalFile(file)
}

/**
 * Requests a tool call execution from the client with timeout support
 * @param ws - The WebSocket connection
 * @param toolName - Name of the tool to execute
 * @param args - Arguments for the tool (can include timeout)
 * @returns Promise resolving to the tool execution result
 */
export async function requestToolCall<T = any>(
  ws: WebSocket,
  userInputId: string,
  toolName: string,
  args: Record<string, any> & { timeout_seconds?: number },
): Promise<{ success: boolean; result?: T; error?: string }> {
  return new Promise((resolve, reject) => {
    const requestId = generateCompactId()
    const timeoutInSeconds =
      (args.timeout_seconds || 30) < 0 ? undefined : args.timeout_seconds || 30

    // Set up timeout
    const timeoutHandle =
      timeoutInSeconds === undefined
        ? undefined
        : setTimeout(
            () => {
              unsubscribe()
              reject(
                new Error(
                  `Tool call '${toolName}' timed out after ${timeoutInSeconds}s`,
                ),
              )
            },
            timeoutInSeconds * 1000 + 5000, // Convert to ms and add a small buffer
          )

    // Subscribe to response
    const unsubscribe = subscribeToAction('tool-call-response', (action) => {
      if (action.requestId === requestId) {
        clearTimeout(timeoutHandle)
        unsubscribe()
        resolve({
          success: action.success,
          result: action.result,
          error: action.error,
        })
      }
    })

    // Send the request
    sendAction(ws, {
      type: 'tool-call-request',
      requestId,
      userInputId,
      toolName,
      args,
      timeout:
        timeoutInSeconds === undefined ? undefined : timeoutInSeconds * 1000, // Send timeout in milliseconds
    })
  })
}

import { z } from 'zod'

import { costModes } from './constants'
import { GrantTypeValues } from './types/grant'
import { printModeEventSchema } from './types/print-mode'
import {
  SessionStateSchema,
  toolCallSchema,
  toolResultSchema,
} from './types/session-state'
import { FileVersionSchema, ProjectFileContextSchema } from './util/file'

export const FileChangeSchema = z.object({
  type: z.enum(['patch', 'file']),
  path: z.string(),
  content: z.string(),
})
export type FileChange = z.infer<typeof FileChangeSchema>
export const CHANGES = z.array(FileChangeSchema)
export type FileChanges = z.infer<typeof CHANGES>

export const CLIENT_ACTION_SCHEMA = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('prompt'),
    promptId: z.string(),
    prompt: z.string().or(z.undefined()),
    promptParams: z.record(z.string(), z.any()).optional(), // Additional json params.
    fingerprintId: z.string(),
    authToken: z.string().optional(),
    costMode: z.enum(costModes).optional().default('normal'),
    sessionState: SessionStateSchema,
    toolResults: z.array(toolResultSchema),
    model: z.string().optional(),
    repoUrl: z.string().optional(),
    agentId: z.string().optional(),
  }),
  z.object({
    type: z.literal('read-files-response'),
    files: z.record(z.string(), z.union([z.string(), z.null()])),
    requestId: z.string().optional(),
  }),
  z.object({
    type: z.literal('init'),
    fingerprintId: z.string(),
    authToken: z.string().optional(),
    fileContext: ProjectFileContextSchema,
    repoUrl: z.string().optional(),
  }),
  z.object({
    type: z.literal('generate-commit-message'),
    fingerprintId: z.string(),
    authToken: z.string().optional(),
    stagedChanges: z.string(),
  }),
  z.object({
    type: z.literal('tool-call-response'),
    requestId: z.string(),
    success: z.boolean(),
    result: z.any().optional(), // Tool execution result
    error: z.string().optional(), // Error message if execution failed
  }),
  z.object({
    type: z.literal('cancel-user-input'),
    authToken: z.string(),
    promptId: z.string(),
  }),
])

export type ClientAction = z.infer<typeof CLIENT_ACTION_SCHEMA>

export const UsageReponseSchema = z.object({
  type: z.literal('usage-response'),
  usage: z.number(),
  remainingBalance: z.number(),
  balanceBreakdown: z
    .record(
      z.enum([GrantTypeValues[0], ...GrantTypeValues.slice(1)]),
      z.number(),
    )
    .optional(),
  next_quota_reset: z.coerce.date().nullable(),
  autoTopupAdded: z.number().optional(),
})
export type UsageResponse = z.infer<typeof UsageReponseSchema>

export const InitResponseSchema = z
  .object({
    type: z.literal('init-response'),
    message: z.string().optional(),
    agentNames: z.record(z.string(), z.string()).optional(),
  })
  .merge(
    UsageReponseSchema.omit({
      type: true,
    }),
  )
export type InitResponse = z.infer<typeof InitResponseSchema>

export const ResponseCompleteSchema = z
  .object({
    type: z.literal('response-complete'),
    userInputId: z.string(),
    response: z.string(),
    changes: CHANGES,
    changesAlreadyApplied: CHANGES,
    addedFileVersions: z.array(FileVersionSchema),
    resetFileVersions: z.boolean(),
  })
  .merge(
    UsageReponseSchema.omit({
      type: true,
    }).partial(),
  )

export const MessageCostResponseSchema = z.object({
  type: z.literal('message-cost-response'),
  promptId: z.string(),
  credits: z.number(),
})
export type MessageCostResponse = z.infer<typeof MessageCostResponseSchema>

export const PromptResponseSchema = z.object({
  type: z.literal('prompt-response'),
  promptId: z.string(),
  sessionState: SessionStateSchema,
  toolCalls: z.array(toolCallSchema),
  toolResults: z.array(toolResultSchema),
})
export type PromptResponse = z.infer<typeof PromptResponseSchema>

export const SERVER_ACTION_SCHEMA = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('response-chunk'),
    userInputId: z.string(),
    chunk: z.union([z.string(), printModeEventSchema]),
  }),
  z.object({
    type: z.literal('subagent-response-chunk'),
    userInputId: z.string(),
    agentId: z.string(),
    agentType: z.string(),
    chunk: z.string(),
    prompt: z.string().optional(),
  }),
  ResponseCompleteSchema,
  PromptResponseSchema,
  z.object({
    type: z.literal('read-files'),
    filePaths: z.array(z.string()),
    requestId: z.string(),
  }),
  z.object({
    type: z.literal('tool-call-request'),
    userInputId: z.string(),
    requestId: z.string(),
    toolName: z.string(),
    args: z.record(z.any()),
    timeout: z.number().optional(),
  }),
  z.object({
    type: z.literal('tool-call'),
    userInputId: z.string(),
    response: z.string(),
    data: toolCallSchema,
    changes: CHANGES,
    changesAlreadyApplied: CHANGES,
    addedFileVersions: z.array(FileVersionSchema),
    resetFileVersions: z.boolean(),
  }),
  z.object({
    type: z.literal('terminal-command-result'),
    userInputId: z.string(),
    result: z.string(),
  }),
  z.object({
    type: z.literal('npm-version-status'),
    isUpToDate: z.boolean(),
    latestVersion: z.string(),
  }),
  InitResponseSchema,
  UsageReponseSchema,
  MessageCostResponseSchema,
  z.object({
    type: z.literal('action-error'),
    message: z.string(),
    error: z.string().optional(),
    remainingBalance: z.number().optional(),
  }),
  z.object({
    type: z.literal('commit-message-response'),
    commitMessage: z.string(),
  }),
  z.object({
    // The server is imminently going to shutdown, and the client should reconnect
    type: z.literal('request-reconnect'),
  }),
])

export type ServerAction = z.infer<typeof SERVER_ACTION_SCHEMA>

