  // Called when a tool tag starts
  onToolStart?: (
    toolName: string,
    attributes: Record<string, string>,
  ) => string | null | (() => void)

  // Called when a parameter tag is found within a tool
  onParamStart?: (
    paramName: string,
    toolName: string,
  ) => string | null | (() => void)

  // Called when parameter content is received
  onParamChunk?: (
    content: string,
    paramName: string,
    toolName: string,
  ) => string | null | (() => void)

  // Called when a parameter tag ends
  onParamEnd?: (
    paramName: string,
    toolName: string,
    content: string,
  ) => string | null | (() => void)

  // Called when a tool tag ends
