import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { and, desc, eq } from 'drizzle-orm'

import { ProjectFileContext } from '@codebuff/common/util/file'
import { logger } from '../util/logger'
import { agentTemplates as staticTemplates } from './agent-list'
import {
  DynamicAgentValidationError,
  validateAgents,
  validateSingleAgent,
} from '@codebuff/common/templates/agent-validation'
import { DynamicAgentTemplate } from '@codebuff/common/types/dynamic-agent-template'

export type AgentRegistry = Record<string, AgentTemplate>

// Global database cache - only state in the system
const databaseAgentCache = new Map<string, AgentTemplate | null>()

/**
 * Parse agent ID to extract publisher, agent name, and version
 */
function parseAgentId(fullAgentId: string): {
  publisherId: string
  agentId: string
  version?: string
} | null {
  // Check if it's in the publisher/agent-id[@version] format
  const parts = fullAgentId.split('/')
  if (parts.length !== 2) {
    return null
  }

  const [publisherId, agentNameWithVersion] = parts

  // Check for version suffix
  const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
  if (versionMatch) {
    const [, agentId, version] = versionMatch
    return { publisherId, agentId, version }
  }

  return { publisherId, agentId: agentNameWithVersion }
}

/**
 * Fetch an agent from the database by publisher/agent-id[@version] format
 */
async function fetchAgentFromDatabase(parsedAgentId: {
  publisherId: string
  agentId: string
  version?: string
}): Promise<AgentTemplate | null> {
  const { publisherId, agentId, version } = parsedAgentId

  try {
    let agentConfig

    if (version && version !== 'latest') {
      // Query for specific version
      agentConfig = await db
        .select()
        .from(schema.agentConfig)
        .where(
          and(
            eq(schema.agentConfig.id, agentId),
            eq(schema.agentConfig.publisher_id, publisherId),
            eq(schema.agentConfig.version, version),
          ),
        )
        .then((rows) => rows[0])
    } else {
      // Query for latest version
      agentConfig = await db
        .select()
        .from(schema.agentConfig)
        .where(
          and(
            eq(schema.agentConfig.id, agentId),
            eq(schema.agentConfig.publisher_id, publisherId),
          ),
        )
        .orderBy(
          desc(schema.agentConfig.major),
          desc(schema.agentConfig.minor),
          desc(schema.agentConfig.patch),
        )
        .limit(1)
        .then((rows) => rows[0])
    }

    if (!agentConfig) {
      logger.debug(
        { publisherId, agentId, version },
        'fetchAgentFromDatabase: Agent not found in database',
      )
      return null
    }

    const rawAgentData = agentConfig.data as DynamicAgentTemplate

    // Ensure the agent has the full publisher/agent-id@version as its ID
    const agentDataWithId = {
      ...rawAgentData,
      id: `${publisherId}/${agentId}@${agentConfig.version}`,
    }

    // Use validateSingleAgent to convert to AgentTemplate type
    const validationResult = validateSingleAgent(agentDataWithId, {
      filePath: `${publisherId}/${agentId}@${agentConfig.version}`,
      skipSubagentValidation: true,
    })

    if (!validationResult.success) {
      logger.error(
        {
          publisherId,
          agentId,
          version: agentConfig.version,
          fullAgentId: agentDataWithId.id,
          error: validationResult.error,
        },
        'fetchAgentFromDatabase: Agent validation failed',
      )
      return null
    }

    logger.debug(
      {
        publisherId,
        agentId,
        version: agentConfig.version,
        fullAgentId: agentDataWithId.id,
        agentConfig,
      },
      'fetchAgentFromDatabase: Successfully loaded and validated agent from database',
    )

    return validationResult.agentTemplate!
  } catch (error) {
    logger.error(
      { publisherId, agentId, version, error },
      'fetchAgentFromDatabase: Error fetching agent from database',
    )
    return null
  }
}

/**
 * Single function to look up an agent template with clear priority order:
 * 1. localAgentTemplates (dynamic agents + static templates)
 * 2. Database cache
 * 3. Database query
 */
export async function getAgentTemplate(
  agentId: string,
  localAgentTemplates: Record<string, AgentTemplate>,
): Promise<AgentTemplate | null> {
  // 1. Check localAgentTemplates first (dynamic agents + static templates)
  if (localAgentTemplates[agentId]) {
    return localAgentTemplates[agentId]
  }
  // 2. Check database cache
  const cacheKey = agentId
  if (databaseAgentCache.has(cacheKey)) {
    return databaseAgentCache.get(cacheKey) || null
  }

  const parsed = parseAgentId(agentId)
  if (!parsed) {
    logger.debug({ agentId }, 'getAgentTemplate: Failed to parse agent ID')
    return null
  }

  // 3. Query database (only for publisher/agent-id format)
  const dbAgent = await fetchAgentFromDatabase(parsed)
  if (dbAgent && parsed.version && parsed.version !== 'latest') {
    // Cache only specific versions to avoid stale 'latest' results
    databaseAgentCache.set(cacheKey, dbAgent)
  }
  return dbAgent
}

/**
 * Assemble local agent templates from fileContext + static templates
 */
export function assembleLocalAgentTemplates(fileContext: ProjectFileContext): {
  agentTemplates: Record<string, AgentTemplate>
  validationErrors: DynamicAgentValidationError[]
} {
  // Load dynamic agents using the service
  const { templates: dynamicTemplates, validationErrors } = validateAgents(
    fileContext.agentTemplates || {},
  )

  // Combine static and dynamic templates
  const agentTemplates = { ...staticTemplates, ...dynamicTemplates }

  return { agentTemplates, validationErrors }
}

/**
 * Clear the database agent cache (useful for testing)
 */
export function clearDatabaseCache(): void {
  databaseAgentCache.clear()
}

#!/usr/bin/env node

import { type CostMode } from '@codebuff/common/constants'
import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import { Command, Option } from 'commander'
import { red } from 'picocolors'

import { displayLoadedAgents, loadLocalAgents } from './agents/load-agents'
import { CLI } from './cli'
import { cliArguments, cliOptions } from './cli-definitions'
import { handlePublish } from './cli-handlers/publish'
import { npmAppVersion } from './config'
import { createTemplateProject } from './create-template-project'
import { printModeLog, setPrintMode } from './display/print-mode'
import { enableSquashNewlines } from './display/squash-newlines'
import { loadCodebuffConfig } from './json-config/parser'
import {
  getProjectRoot,
  getWorkingDirectory,
  initializeProjectRootAndWorkingDir,
  initProjectFileContextWithWorker,
} from './project-files'
import { rageDetectors } from './rage-detectors'
import { logAndHandleStartup } from './startup-process-handler'
import { recreateShell } from './terminal/run-command'
import { initAnalytics, trackEvent } from './utils/analytics'
import { logger } from './utils/logger'

import type { CliOptions } from './types'

async function codebuff({
  initialInput,
  git,
  costMode,
  runInitFlow,
  model,
  agent,
  params,
  print,
  cwd,
  trace,
}: CliOptions) {
  enableSquashNewlines()
  const workingDir = getWorkingDirectory()
  const projectRoot = getProjectRoot()
  await recreateShell(workingDir)

  // Kill all processes we failed to kill before
  const processCleanupPromise = logAndHandleStartup()

  initAnalytics()
  rageDetectors.startupTimeDetector.start()

  const initFileContextPromise = initProjectFileContextWithWorker(projectRoot)

  const readyPromise = Promise.all([
    initFileContextPromise,
    processCleanupPromise,

    loadLocalAgents({ verbose: true }).then(() =>
      displayLoadedAgents(codebuffConfig),
    ),
  ])

  const codebuffConfig = loadCodebuffConfig()

  // Initialize the CLI singleton
  CLI.initialize(readyPromise, {
    git,
    costMode,
    model,
    agent,
    params,
    print,
    trace,
  })
  const cli = CLI.getInstance()

  await cli.printInitialPrompt({ initialInput, runInitFlow })

  rageDetectors.startupTimeDetector.end()
}

if (require.main === module) {
  const program = new Command()

  program.name('codebuff').version(npmAppVersion || '0.0.0')

  // Add arguments from shared definitions
  cliArguments.forEach((arg) => {
    // For hidden arguments, just skip adding them to the help text
    if (!arg.hidden) {
      program.argument(arg.flags, arg.description)
    }
  })

  // Add options from shared definitions
  cliOptions.forEach((opt) => {
    const optionInstance = new Option(opt.flags, opt.description)
    if (opt.hidden) {
      optionInstance.hideHelp(true)
    }
    program.addOption(optionInstance)
  })

  program.addHelpText(
    'after',
    `
Examples:
  $ codebuff                                  # Start in current directory
  $ codebuff -p "tell me about the codebase"  # Print mode (non-interactive)
  $ codebuff --cwd my-project                 # Start in specific directory
  $ codebuff --trace                          # Enable subagent trace logging to .agents/traces/*.log
  $ codebuff --create nextjs my-app           # Create and scaffold a new Next.js project
  $ codebuff publish my-agent                 # Publish agent template to store
  $ codebuff --agent file-picker "find relevant files for authentication"
  $ codebuff --agent reviewer --params '{"focus": "security"}' "review this code"

For all commands and options, run 'codebuff' and then type 'help'.
`,
  )

  program.parse()

  const options = program.opts()
  const args = program.args // Handle template creation

  // Initialize project root and working directory
  initializeProjectRootAndWorkingDir(options.cwd)

  if (options.create) {
    const template = options.create
    const projectDir = args[0] || '.'
    const projectName = args[1] || template
    createTemplateProject(template, projectDir, projectName)
    process.exit(0)
  }

  // Handle publish command
  if (args[0] === 'publish') {
    const agentNames = args.slice(1)
    await handlePublish(agentNames)
    process.exit(0)
  }

  // Handle deprecated --pro flag
  if (options.pro) {
    console.error(
      red(
        'Warning: The --pro flag is deprecated. Please restart codebuff and use the --max option instead.',
      ),
    )
    logger.error(
      {
        errorMessage:
          'The --pro flag is deprecated. Please restart codebuff and use the --max option instead.',
      },
      'Deprecated --pro flag used',
    )
    process.exit(1)
  }

  // Determine cost mode
  let costMode: CostMode = 'normal'
  if (options.lite) {
    costMode = 'lite'
  } else if (options.max) {
    costMode = 'max'
  } else if (options.experimental) {
    costMode = 'experimental'
  } else if (options.ask) {
    costMode = 'ask'
  }

  // Handle git integration
  const git = options.git === 'stage' ? ('stage' as const) : undefined

  // Validate print mode requirements
  if (options.print) {
    const hasPrompt = args.length > 0
    const hasParams = options.params

    setPrintMode(true)
    trackEvent(AnalyticsEvent.PRINT_MODE, {
      args,
      options,
    })

    if (!hasPrompt && !hasParams) {
      printModeLog({
        type: 'error',
        message: 'Error: Print mode requires a prompt to be set',
      })
      process.exit(1)
    }
  }

  // Parse agent params if provided
  let parsedAgentParams: Record<string, any> | undefined
  if (options.params) {
    try {
      parsedAgentParams = JSON.parse(options.params)
    } catch (error) {
      console.error(red(`Error parsing --params JSON: ${error}`))
      process.exit(1)
    }
  }

  // Remove the first argument if it's the compiled binary path which bun weirdly injects (starts with /$bunfs)
  const filteredArgs = args[0]?.startsWith('/$bunfs') ? args.slice(1) : args

  // If first arg is a command like 'publish', don't treat it as initial input
  const isCommand = filteredArgs[0] === 'publish'
  const initialInput = isCommand ? '' : filteredArgs.join(' ')

  codebuff({
    initialInput,
    git,
    costMode,
    runInitFlow: options.init,
    model: options.model,
    agent: options.agent,
    params: parsedAgentParams,
    print: options.print,
    cwd: options.cwd,
    trace: options.trace,
  })
}

import * as fs from 'fs'
import * as path from 'path'

import { cyan, green } from 'picocolors'

import { getAllTsFiles, getAgentsDirectory } from './agent-utils'

import type { CodebuffConfig } from '@codebuff/common/json-config/constants'

export let loadedAgents: Record<string, any> = {}
export async function loadLocalAgents({
  verbose = false,
}: {
  verbose?: boolean
}): Promise<typeof loadedAgents> {
  loadedAgents = {}

  const agentsDir = getAgentsDirectory()

  if (!fs.existsSync(agentsDir)) {
    return loadedAgents
  }

  try {
    const tsFiles = getAllTsFiles(agentsDir)

    for (const fullPath of tsFiles) {
      const relativePath = path.relative(agentsDir, fullPath)
      const fileName = relativePath.replace(/\.ts$/, '').replace(/[/\\]/g, '-')

      let agentConfig: any
      let agentModule: any
      try {
        agentModule = await require(fullPath)
      } catch (error: any) {
        if (verbose) {
          console.error('Error importing agent:', error)
        }
        continue
      }
      delete require.cache[fullPath]

      try {
        agentConfig = agentModule.default
      } catch (error: any) {
        console.error('Error loading agent from file:', fullPath, error)
        continue
      }

      if (!agentConfig) continue

      // Convert handleSteps function to string if present
      let processedAgentConfig = { ...agentConfig }
      if (agentConfig.handleSteps) {
        processedAgentConfig.handleSteps = agentConfig.handleSteps.toString()
      }

      loadedAgents[fileName] = processedAgentConfig
    }
  } catch (error) {}

  return loadedAgents
}

export function getLoadedAgentNames(): Record<string, string> {
  return Object.fromEntries(
    Object.entries(loadedAgents).map(([agentType, agentConfig]) => {
      return [agentType, agentConfig.displayName]
    }),
  )
}

/**
 * Display loaded agents to the user
 */
export function displayLoadedAgents(codebuffConfig: CodebuffConfig) {
  const baseAgent = codebuffConfig.baseAgent
  if (baseAgent) {
    console.log(`\n${green('Configured base agent:')} ${cyan(baseAgent)}`)
  }

  const subagents = codebuffConfig.subagents
  if (subagents) {
    console.log(
      `${green('Configured subagents:')} ${subagents
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (Object.keys(loadedAgents).length > 0) {
    const loadedAgentNames = Object.values(getLoadedAgentNames())
    console.log(
      `\n${green('Found custom agents:')} ${loadedAgentNames
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (baseAgent) {
    // One more new line.
    console.log()
  }
}

import { convertJsonSchemaToZod } from 'zod-from-json-schema'

import {
  formatSubagentError,
  validateSubagents,
} from '../util/agent-template-validation'
import { logger } from '../util/logger'
import {
  DynamicAgentConfigSchema,
  DynamicAgentTemplateSchema,
} from '../types/dynamic-agent-template'
import type { AgentTemplate } from '../types/agent-template'
import type { DynamicAgentTemplate } from '../types/dynamic-agent-template'

export interface DynamicAgentValidationError {
  filePath: string
  message: string
}

/**
 * Collect all agent IDs from template files without full validation
 */
export function collectAgentIds(
  agentTemplates: Record<string, DynamicAgentTemplate> = {},
): string[] {
  const agentIds: string[] = []
  const jsonFiles = Object.keys(agentTemplates)

  for (const filePath of jsonFiles) {
    try {
      const content = agentTemplates[filePath]
      if (!content) {
        continue
      }

      // Extract the agent ID if it exists
      if (content.id && typeof content.id === 'string') {
        agentIds.push(content.id)
      }
    } catch (error) {
      // Log but don't fail the collection process for other errors
      logger.debug(
        { filePath, error },
        'Failed to extract agent ID during collection phase',
      )
    }
  }

  return agentIds
}

/**
 * Validate and load dynamic agent templates from user-provided agentTemplates
 */
export function validateAgents(agentTemplates: Record<string, any> = {}): {
  templates: Record<string, AgentTemplate>
  validationErrors: DynamicAgentValidationError[]
} {
  const templates: Record<string, AgentTemplate> = {}
  const validationErrors: DynamicAgentValidationError[] = []

  const hasAgentTemplates = Object.keys(agentTemplates).length > 0

  if (!hasAgentTemplates) {
    return {
      templates,
      validationErrors,
    }
  }

  const agentKeys = Object.keys(agentTemplates)

  // Pass 1: Collect all agent IDs from template files
  const dynamicAgentIds = collectAgentIds(agentTemplates)

  // Pass 2: Load and validate each agent template
  for (const agentKey of agentKeys) {
    const content = agentTemplates[agentKey]
    try {
      if (!content) {
        continue
      }

      const validationResult = validateSingleAgent(content, {
        filePath: agentKey,
        dynamicAgentIds,
      })

      if (!validationResult.success) {
        validationErrors.push({
          filePath: agentKey,
          message: validationResult.error!,
        })
        continue
      }

      if (templates[validationResult.agentTemplate!.id]) {
        const agentContext = validationResult.agentTemplate!.displayName 
          ? `Agent "${validationResult.agentTemplate!.id}" (${validationResult.agentTemplate!.displayName})`
          : `Agent "${validationResult.agentTemplate!.id}"`

        validationErrors.push({
          filePath: agentKey,
          message: `${agentContext}: Duplicate agent ID`,
        })
        continue
      }
      templates[validationResult.agentTemplate!.id] =
        validationResult.agentTemplate!
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'

      // Try to extract agent context for better error messages
      const agentContext = content?.id 
        ? `Agent "${content.id}"${content.displayName ? ` (${content.displayName})` : ''}`
        : `Agent in ${agentKey}`

      validationErrors.push({
        filePath: agentKey,
        message: `${agentContext}: ${errorMessage}`,
      })

      logger.warn(
        { filePath: agentKey, error: errorMessage },
        'Failed to load dynamic agent template',
      )
    }
  }

  return {
    templates,
    validationErrors,
  }
}

/**
 * Validates a single dynamic agent template and converts it to an AgentTemplate.
 * This is a plain function equivalent to the core logic of loadSingleAgent.
 *
 * @param dynamicAgentIds - Array of all available dynamic agent IDs for validation
 * @param template - The raw agent template to validate (any type)
 * @param options - Optional configuration object
 * @param options.filePath - Optional file path for error context
 * @param options.skipSubagentValidation - Skip subagent validation when loading from database
 * @returns Validation result with either the converted AgentTemplate or an error
 */
export function validateSingleAgent(
  template: any,
  options?: {
    dynamicAgentIds?: string[]
    filePath?: string
    skipSubagentValidation?: boolean
  },
): {
  success: boolean
  agentTemplate?: AgentTemplate
  error?: string
} {
  const {
    filePath,
    skipSubagentValidation = true,
    dynamicAgentIds = [],
  } = options || {}

  try {
    // First validate against the Zod schema
    let validatedConfig: DynamicAgentTemplate
    try {
      const typedAgentConfig = DynamicAgentConfigSchema.parse(template)

      // Convert handleSteps function to string if present
      let handleStepsString: string | undefined
      if (template.handleSteps) {
        handleStepsString = template.handleSteps.toString()
      }

      validatedConfig = DynamicAgentTemplateSchema.parse({
        ...typedAgentConfig,
        systemPrompt: typedAgentConfig.systemPrompt || '',
        instructionsPrompt: typedAgentConfig.instructionsPrompt || '',
        stepPrompt: typedAgentConfig.stepPrompt || '',
        handleSteps: handleStepsString,
      })
    } catch (error: any) {
      // Try to extract agent context for better error messages
      const agentContext = template.id 
        ? `Agent "${template.id}"${template.displayName ? ` (${template.displayName})` : ''}`
        : filePath ? `Agent in ${filePath}` : 'Agent'

      return {
        success: false,
        error: `${agentContext}: Schema validation failed: ${error.message}`,
      }
    }
    // Validate subagents (skip if requested, e.g., for database agents)
    if (!skipSubagentValidation) {
      const subagentValidation = validateSubagents(
        validatedConfig.subagents,
        dynamicAgentIds,
      )
      if (!subagentValidation.valid) {
        return {
          success: false,
          error: formatSubagentError(
            subagentValidation.invalidAgents,
            subagentValidation.availableAgents,
          ),
        }
      }
    }

    // Convert schemas and handle validation errors
    let inputSchema: AgentTemplate['inputSchema']
    try {
      inputSchema = convertInputSchema(
        validatedConfig.inputSchema?.prompt,
        validatedConfig.inputSchema?.params,
        filePath,
      )
    } catch (error) {
      // Try to extract agent context for better error messages
      const agentContext = validatedConfig.id 
        ? `Agent "${validatedConfig.id}"${validatedConfig.displayName ? ` (${validatedConfig.displayName})` : ''}`
        : filePath ? `Agent in ${filePath}` : 'Agent'

      return {
        success: false,
        error: `${agentContext}: ${
          error instanceof Error ? error.message : 'Schema conversion failed'
        }`,
      }
    }

    // Convert outputSchema if present
    let outputSchema: AgentTemplate['outputSchema']
    if (validatedConfig.outputSchema) {
      try {
        outputSchema = convertJsonSchemaToZod(validatedConfig.outputSchema)
      } catch (error) {
        // Try to extract agent context for better error messages
        const agentContext = validatedConfig.id 
          ? `Agent "${validatedConfig.id}"${validatedConfig.displayName ? ` (${validatedConfig.displayName})` : ''}`
          : filePath ? `Agent in ${filePath}` : 'Agent'

        return {
          success: false,
          error: `${agentContext}: Failed to convert outputSchema to Zod: ${error instanceof Error ? error.message : 'Unknown error'}`,
        }
      }
    }

    // Validate handleSteps if present
    if (validatedConfig.handleSteps) {
      if (!isValidGeneratorFunction(validatedConfig.handleSteps)) {
        // Try to extract agent context for better error messages
        const agentContext = validatedConfig.id 
          ? `Agent "${validatedConfig.id}"${validatedConfig.displayName ? ` (${validatedConfig.displayName})` : ''}`
          : filePath ? `Agent in ${filePath}` : 'Agent'

        return {
          success: false,
          error: `${agentContext}: handleSteps must be a generator function: "function* (params) { ... }". Found: ${validatedConfig.handleSteps.substring(0, 50)}...`,
        }
      }
    }

    // Convert to internal AgentTemplate format
    const agentTemplate: AgentTemplate = {
      ...validatedConfig,
      outputSchema,
      inputSchema,
    }

    return {
      success: true,
      agentTemplate,
    }
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'

    // Try to extract agent context for better error messages
    const agentContext = template?.id 
      ? `Agent "${template.id}"${template.displayName ? ` (${template.displayName})` : ''}`
      : filePath ? `Agent in ${filePath}` : 'Agent'

    return {
      success: false,
      error: `${agentContext}: Error validating agent template: ${errorMessage}`,
    }
  }
}

/**
 * Validates if a string represents a valid generator function
 */
function isValidGeneratorFunction(code: string): boolean {
  const trimmed = code.trim()
  // Check if it's a generator function (must start with function*)
  return trimmed.startsWith('function*')
}

/**
 * Convert JSON schema to Zod schema format using json-schema-to-zod.
 * This is done once during loading to avoid repeated conversions.
 * Throws descriptive errors for validation failures.
 */
function convertInputSchema(
  inputPromptSchema?: Record<string, any>,
  paramsSchema?: Record<string, any>,
  filePath?: string,
): AgentTemplate['inputSchema'] {
  const result: any = {}
  const fileContext = filePath ? ` in ${filePath}` : ''

  // Handle prompt schema
  if (inputPromptSchema) {
    try {
      if (
        typeof inputPromptSchema !== 'object' ||
        Object.keys(inputPromptSchema).length === 0
      ) {
        throw new Error(
          `Invalid inputSchema.prompt${fileContext}: Schema must be a valid non-empty JSON schema object. Found: ${typeof inputPromptSchema}`,
        )
      }
      const promptZodSchema = convertJsonSchemaToZod(inputPromptSchema)
      // Validate that the schema results in string or undefined
      const testResult = promptZodSchema.safeParse('test')
      const testUndefined = promptZodSchema.safeParse(undefined)

      if (!testResult.success && !testUndefined.success) {
        const errorDetails =
          testResult.error?.issues?.[0]?.message || 'validation failed'
        throw new Error(
          `Invalid inputSchema.prompt${fileContext}: Schema must allow string or undefined values. ` +
            `Current schema validation error: ${errorDetails}. ` +
            `Please ensure your JSON schema accepts string types.`,
        )
      }

      result.prompt = promptZodSchema
    } catch (error) {
      if (error instanceof Error && error.message.includes('inputSchema')) {
        // Re-throw our custom validation errors
        throw error
      }

      // Handle json-schema-to-zod conversion errors
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'
      throw new Error(
        `Failed to convert inputSchema.prompt to Zod${fileContext}: ${errorMessage}. ` +
          `Please check that your inputSchema.prompt is a valid non-empty JSON schema object.`,
      )
    }
  }

  // Handle params schema
  if (paramsSchema) {
    try {
      if (
        typeof paramsSchema !== 'object' ||
        Object.keys(paramsSchema).length === 0
      ) {
        throw new Error(
          `Invalid inputSchema.params${fileContext}: Schema must be a valid non-empty JSON schema object. Found: ${typeof paramsSchema}`,
        )
      }
      const paramsZodSchema = convertJsonSchemaToZod(paramsSchema)
      result.params = paramsZodSchema
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'
      throw new Error(
        `Failed to convert inputSchema.params to Zod${fileContext}: ${errorMessage}. ` +
          `Please check that your inputSchema.params is a valid non-empty JSON schema object.`,
      )
    }
  }
  return result
}

import { calculateUsageAndBalance } from '@codebuff/billing'
import { trackEvent } from '@codebuff/common/analytics'
import {
  ASYNC_AGENTS_ENABLED,
  toOptionalFile,
} from '@codebuff/common/constants'
import { AnalyticsEvent } from '@codebuff/common/constants/analytics-events'
import db from '@codebuff/common/db/index'
import * as schema from '@codebuff/common/db/schema'
import { formatValidationErrorMessage } from '@codebuff/common/util/agent-template-validation'
import { buildArray } from '@codebuff/common/util/array'
import { ensureEndsWithNewline } from '@codebuff/common/util/file'
import { generateCompactId } from '@codebuff/common/util/string'
import { eq } from 'drizzle-orm'

import { asyncAgentManager } from '../async-agent-manager'
import {
  cancelUserInput,
  checkLiveUserInput,
  endUserInput,
  startUserInput,
} from '../live-user-inputs'
import { mainPrompt } from '../main-prompt'
import { protec } from './middleware'
import { sendMessage } from './server'
import { assembleLocalAgentTemplates } from '../templates/agent-registry'
import { logger, withLoggerContext } from '../util/logger'
import { asSystemMessage } from '../util/messages'

import type {
  ClientAction,
  ServerAction,
  UsageResponse,
} from '@codebuff/common/actions'
import type { ClientMessage } from '@codebuff/common/websockets/websocket-schema'
import type { WebSocket } from 'ws'

/**
 * Sends an action to the client via WebSocket
 * @param ws - The WebSocket connection to send the action to
 * @param action - The server action to send
 */
export const sendAction = (ws: WebSocket, action: ServerAction) => {
  sendMessage(ws, {
    type: 'action',
    data: action,
  })
}

/**
 * Retrieves a user ID from an authentication token
 * @param authToken - The authentication token to validate
 * @returns The user ID if found, undefined otherwise
 */
export const getUserIdFromAuthToken = async (
  authToken?: string,
): Promise<string | undefined> => {
  if (!authToken) return undefined

  const userId = await db
    .select({ userId: schema.user.id })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, authToken))
    .then((users) => {
      if (users.length === 1) {
        return users[0].userId
      }
      return undefined
    })

  return userId
}

/**
 * Generates a usage response object for the client
 * @param fingerprintId - The fingerprint ID for the user/device
 * @param userId - user ID for authenticated users
 * @param clientSessionId - Optional session ID
 * @returns A UsageResponse object containing usage metrics and referral information
 */
export async function genUsageResponse(
  fingerprintId: string,
  userId: string,
  clientSessionId: string | undefined,
): Promise<UsageResponse> {
  const logContext = { fingerprintId, userId, sessionId: clientSessionId }
  const defaultResp = {
    type: 'usage-response' as const,
    usage: 0,
    remainingBalance: 0,
    balanceBreakdown: {},
    next_quota_reset: null,
  }

  return withLoggerContext(logContext, async () => {
    const user = await db.query.user.findFirst({
      where: eq(schema.user.id, userId),
      columns: {
        next_quota_reset: true,
      },
    })

    if (!user) {
      return defaultResp
    }

    try {
      // Get the usage data
      const { balance: balanceDetails, usageThisCycle } =
        await calculateUsageAndBalance(userId, new Date())

      return {
        type: 'usage-response' as const,
        usage: usageThisCycle,
        remainingBalance: balanceDetails.totalRemaining,
        balanceBreakdown: balanceDetails.breakdown,
        next_quota_reset: user.next_quota_reset,
      }
    } catch (error) {
      logger.error(
        { error, usage: defaultResp },
        'Error generating usage response, returning default',
      )
    }

    return defaultResp
  })
}

/**
 * Handles prompt actions from the client
 * @param action - The prompt action from the client
 * @param clientSessionId - The client's session ID
 * @param ws - The WebSocket connection
 */
const onPrompt = async (
  action: Extract<ClientAction, { type: 'prompt' }>,
  clientSessionId: string,
  ws: WebSocket,
) => {
  const { fingerprintId, authToken, promptId, prompt, costMode } = action

  await withLoggerContext(
    { fingerprintId, clientRequestId: promptId, costMode },
    async () => {
      const userId = await getUserIdFromAuthToken(authToken)
      if (!userId) {
        throw new Error('User not found')
      }

      if (prompt) {
        logger.info(`USER INPUT: ${prompt}`)
        trackEvent(AnalyticsEvent.USER_INPUT, userId, {
          prompt,
          promptId,
        })
      }

      startUserInput(userId, promptId)

      try {
        await callMainPrompt(ws, action, {
          userId,
          promptId,
          clientSessionId,
        })
      } catch (e) {
        logger.error(e, 'Error in mainPrompt')
        let response =
          e && typeof e === 'object' && 'message' in e ? `\n\n${e.message}` : ''

        const newMessages = buildArray(
          ...action.sessionState.mainAgentState.messageHistory,
          prompt && {
            role: 'user' as const,
            content: prompt,
          },
          {
            role: 'user' as const,
            content: asSystemMessage(`Received error from server: ${response}`),
          },
        )

        sendAction(ws, {
          type: 'response-chunk',
          userInputId: promptId,
          chunk: { type: 'error', message: response },
        })
        sendAction(ws, {
          type: 'response-chunk',
          userInputId: promptId,
          chunk: response,
        })
        setTimeout(() => {
          sendAction(ws, {
            type: 'prompt-response',
            promptId,
            // Send back original sessionState.
            sessionState: {
              ...action.sessionState,
              mainAgentState: {
                ...action.sessionState.mainAgentState,
                messageHistory: newMessages,
              },
            },
            toolCalls: [],
            toolResults: [],
          })
        }, 100)
      } finally {
        endUserInput(userId, promptId)
        const usageResponse = await genUsageResponse(
          fingerprintId,
          userId,
          undefined,
        )
        sendAction(ws, usageResponse)
      }
    },
  )
}

export const callMainPrompt = async (
  ws: WebSocket,
  action: Extract<ClientAction, { type: 'prompt' }>,
  options: {
    userId: string
    promptId: string
    clientSessionId: string
  },
) => {
  const { userId, promptId, clientSessionId } = options
  const { fileContext } = action.sessionState

  // Assemble local agent templates from fileContext
  const { agentTemplates: localAgentTemplates } = assembleLocalAgentTemplates(fileContext)

  const result = await mainPrompt(ws, action, {
    userId,
    clientSessionId,
    localAgentTemplates,
    onResponseChunk: (chunk) => {
      if (checkLiveUserInput(userId, promptId, clientSessionId)) {
        sendAction(ws, {
          type: 'response-chunk',
          userInputId: promptId,
          chunk,
        })
      }
    },
  })

  const { sessionState, toolCalls, toolResults } = result
  // Send prompt data back
  sendAction(ws, {
    type: 'prompt-response',
    promptId,
    sessionState,
    toolCalls: toolCalls as any[],
    toolResults,
  })

  return result
}

/**
 * Handles initialization actions from the client
 * @param fileContext - The file context information
 * @param fingerprintId - The fingerprint ID for the user/device
 * @param authToken - The authentication token
 * @param clientSessionId - The client's session ID
 * @param ws - The WebSocket connection
 */
const onInit = async (
  {
    fileContext,
    fingerprintId,
    authToken,
  }: Extract<ClientAction, { type: 'init' }>,
  clientSessionId: string,
  ws: WebSocket,
) => {
  await withLoggerContext({ fingerprintId }, async () => {
    const userId = await getUserIdFromAuthToken(authToken)

    if (!userId) {
      sendAction(ws, {
        usage: 0,
        remainingBalance: 0,
        balanceBreakdown: {},
        next_quota_reset: null,
        type: 'init-response',
      })
      return
    }

    // Assemble local agent templates from fileContext
    const { agentTemplates, validationErrors } =
      assembleLocalAgentTemplates(fileContext)

    if (validationErrors.length > 0) {
      logger.warn(
        { errorCount: validationErrors.length },
        'Agent template validation errors found',
      )
    }

    const errorMessage = formatValidationErrorMessage(validationErrors)

    // Get all agent names for frontend
    const allAgentNames: Record<string, string> = {}
    for (const [id, template] of Object.entries(agentTemplates)) {
      allAgentNames[id] = template.displayName
    }

    // Send combined init and usage response
    const usageResponse = await genUsageResponse(
      fingerprintId,
      userId,
      clientSessionId,
    )
    sendAction(ws, {
      ...usageResponse,
      type: 'init-response',
      message: errorMessage
        ? `**Agent Template Validation Errors:**\n${errorMessage}`
        : undefined,
      agentNames: allAgentNames,
    })
  })
}

const onCancelUserInput = async ({
  authToken,
  promptId,
}: Extract<ClientAction, { type: 'cancel-user-input' }>) => {
  const userId = await getUserIdFromAuthToken(authToken)
  if (!userId) {
    logger.error({ authToken }, 'User id not found for authToken')
    return
  }
  cancelUserInput(userId, promptId)
  if (ASYNC_AGENTS_ENABLED) {
    asyncAgentManager.cleanupUserInputAgents(promptId)
  }
}

/**
 * Storage for action callbacks organized by action type
 */
const callbacksByAction = {} as Record<
  ClientAction['type'],
  ((action: ClientAction, clientSessionId: string, ws: WebSocket) => void)[]
>

/**
 * Subscribes a callback function to a specific action type
 * @param type - The action type to subscribe to
 * @param callback - The callback function to execute when the action is received
 * @returns A function to unsubscribe the callback
 */
export const subscribeToAction = <T extends ClientAction['type']>(
  type: T,
  callback: (
    action: Extract<ClientAction, { type: T }>,
    clientSessionId: string,
    ws: WebSocket,
  ) => void,
) => {
  callbacksByAction[type] = (callbacksByAction[type] ?? []).concat(
    callback as (
      action: ClientAction,
      clientSessionId: string,
      ws: WebSocket,
    ) => void,
  )
  return () => {
    callbacksByAction[type] = (callbacksByAction[type] ?? []).filter(
      (cb) => cb !== callback,
    )
  }
}

/**
 * Handles WebSocket action messages from clients
 * @param ws - The WebSocket connection
 * @param clientSessionId - The client's session ID
 * @param msg - The action message from the client
 */
export const onWebsocketAction = async (
  ws: WebSocket,
  clientSessionId: string,
  msg: ClientMessage & { type: 'action' },
) => {
  await withLoggerContext({ clientSessionId }, async () => {
    const callbacks = callbacksByAction[msg.data.type] ?? []
    try {
      await Promise.all(
        callbacks.map((cb) => cb(msg.data, clientSessionId, ws)),
      )
    } catch (e) {
      logger.error(
        {
          message: msg,
          error: e && typeof e === 'object' && 'message' in e ? e.message : e,
        },
        'Got error running subscribeToAction callback',
      )
    }
  })
}

// Register action handlers
subscribeToAction('prompt', protec.run(onPrompt))
subscribeToAction('init', protec.run(onInit, { silent: true }))
subscribeToAction('cancel-user-input', protec.run(onCancelUserInput))

/**
 * Requests multiple files from the client
 * @param ws - The WebSocket connection
 * @param filePaths - Array of file paths to request
 * @returns Promise resolving to an object mapping file paths to their contents
 */
export async function requestFiles(ws: WebSocket, filePaths: string[]) {
  return new Promise<Record<string, string | null>>((resolve) => {
    const requestId = generateCompactId()
    const unsubscribe = subscribeToAction('read-files-response', (action) => {
      for (const [filename, contents] of Object.entries(action.files)) {
        action.files[filename] = ensureEndsWithNewline(contents)
      }
      if (action.requestId === requestId) {
        unsubscribe()
        resolve(action.files)
      }
    })
    sendAction(ws, {
      type: 'read-files',
      filePaths,
      requestId,
    })
  })
}

/**
 * Requests a single file from the client
 * @param ws - The WebSocket connection
 * @param filePath - The path of the file to request
 * @returns Promise resolving to the file contents or null if not found
 */
export async function requestFile(ws: WebSocket, filePath: string) {
  const files = await requestFiles(ws, [filePath])
  return files[filePath] ?? null
}

export async function requestOptionalFile(ws: WebSocket, filePath: string) {
  const file = await requestFile(ws, filePath)
  return toOptionalFile(file)
}

/**
 * Requests a tool call execution from the client with timeout support
 * @param ws - The WebSocket connection
 * @param toolName - Name of the tool to execute
 * @param args - Arguments for the tool (can include timeout)
 * @returns Promise resolving to the tool execution result
 */
export async function requestToolCall<T = any>(
  ws: WebSocket,
  userInputId: string,
  toolName: string,
  args: Record<string, any> & { timeout_seconds?: number },
): Promise<{ success: boolean; result?: T; error?: string }> {
  return new Promise((resolve, reject) => {
    const requestId = generateCompactId()
    const timeoutInSeconds =
      (args.timeout_seconds || 30) < 0 ? undefined : args.timeout_seconds || 30

    // Set up timeout
    const timeoutHandle =
      timeoutInSeconds === undefined
        ? undefined
        : setTimeout(
            () => {
              unsubscribe()
              reject(
                new Error(
                  `Tool call '${toolName}' timed out after ${timeoutInSeconds}s`,
                ),
              )
            },
            timeoutInSeconds * 1000 + 5000, // Convert to ms and add a small buffer
          )

    // Subscribe to response
    const unsubscribe = subscribeToAction('tool-call-response', (action) => {
      if (action.requestId === requestId) {
        clearTimeout(timeoutHandle)
        unsubscribe()
        resolve({
          success: action.success,
          result: action.result,
          error: action.error,
        })
      }
    })

    // Send the request
    sendAction(ws, {
      type: 'tool-call-request',
      requestId,
      userInputId,
      toolName,
      args,
      timeout:
        timeoutInSeconds === undefined ? undefined : timeoutInSeconds * 1000, // Send timeout in milliseconds
    })
  })
}

import { assembleLocalAgentTemplates } from './templates/agent-registry'
import { logger } from './util/logger'

import type { AgentState } from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'
import type { WebSocket } from 'ws'

export interface AsyncAgentInfo {
  agentState: AgentState
  sessionId: string
  userId: string
  fingerprintId: string
  userInputId: string
  ws: WebSocket
  fileContext: ProjectFileContext
  startTime: Date
  status: 'running' | 'completed' | 'failed' | 'cancelled'
  promise?: Promise<{ agentState: AgentState; hasEndTurn?: boolean }>
}

export interface AsyncAgentMessage {
  fromAgentId: string
  toAgentId: string
  prompt: string
  params?: Record<string, any>
  timestamp: Date
}

/**
 * Manages asynchronous agent spawning and communication
 */
export class AsyncAgentManager {
  private agents = new Map<string, AsyncAgentInfo>()
  private messageQueues = new Map<string, AsyncAgentMessage[]>()
  private sessionAgents = new Map<string, Set<string>>() // sessionId -> agentIds

  /**
   * Register a new agent
   */
  registerAgent(agentInfo: AsyncAgentInfo): void {
    const { agentState, sessionId } = agentInfo
    const { agentId, agentType } = agentState
    this.agents.set(agentId, agentInfo)

    // Track agents by session for cleanup
    if (!this.sessionAgents.has(sessionId)) {
      this.sessionAgents.set(sessionId, new Set())
    }
    this.sessionAgents.get(sessionId)!.add(agentId)
  }

  /**
   * Update agent state and status
   */
  updateAgentState(
    agentState: AgentState,
    status: AsyncAgentInfo['status'],
  ): void {
    const agent = this.agents.get(agentState.agentId)
    if (agent) {
      agent.status = status
      agent.agentState = agentState
    }
  }

  /**
   * Get agent info by ID
   */
  getAgent(agentId: string): AsyncAgentInfo | undefined {
    return this.agents.get(agentId)
  }

  /**
   * Get all agents for a session
   */
  getSessionAgents(sessionId: string): AsyncAgentInfo[] {
    const agentIds = this.sessionAgents.get(sessionId) || new Set()
    return Array.from(agentIds)
      .map((id) => this.agents.get(id))
      .filter((agent): agent is AsyncAgentInfo => agent !== undefined)
  }

  /**
   * Get child agents of a parent
   */
  getChildAgents(parentAgentId: string): AsyncAgentInfo[] {
    return Array.from(this.agents.values()).filter(
      (agent) => agent.agentState.parentId === parentAgentId,
    )
  }

  /**
   * Check if agent has running children
   */
  hasRunningChildren(agentId: string): boolean {
    return this.getChildAgents(agentId).some(
      (child) => child.status === 'running',
    )
  }

  /**
   * Send message to an agent and trigger execution if not running
   */
  sendMessage(message: AsyncAgentMessage): void {
    const queue = this.messageQueues.get(message.toAgentId) || []
    queue.push(message)
    this.messageQueues.set(message.toAgentId, queue)

    logger.debug(
      {
        fromAgentId: message.fromAgentId,
        toAgentId: message.toAgentId,
        prompt: message.prompt.slice(0, 50) + '...',
      },
      'Queued message for async agent',
    )

    // Trigger agent execution if not currently running (fire and forget)
    this.triggerAgentIfIdle(message.toAgentId).catch((error) => {
      logger.error(
        { agentId: message.toAgentId, error },
        'Failed to trigger agent',
      )
    })
  }

  /**
   * Trigger agent execution if it's not currently running
   */
  private async triggerAgentIfIdle(agentId: string): Promise<void> {
    const agent = this.agents.get(agentId)
    if (!agent) {
      logger.debug(
        { agentId },
        'Agent not found in async manager - may be a parent agent that will be triggered by normal agent loop',
      )
      return
    }

    // Atomic check and update to prevent race conditions
    if (agent.status === 'running') {
      return // Already running, nothing to do
    }

    logger.debug({ agentId }, 'Triggering idle agent due to new message')

    const { ws, userId, sessionId, userInputId } = agent

    let agentPromise: Promise<{ agentState: AgentState; hasEndTurn?: boolean }>
    try {
      if (agent.agentState.agentId === 'main-agent') {
        // Dynamic import to avoid circular dependency
        const { callMainPrompt } = await import('./websockets/websocket-action')
        const mainAgentPromise = callMainPrompt(
          ws,
          {
            type: 'prompt',
            prompt: undefined,
            promptId: userInputId,
            fingerprintId: agent.fingerprintId,
            costMode: 'normal',
            agentId: agent.agentState.agentType!,
            sessionState: {
              ...agent.agentState,
              fileContext: agent.fileContext,
              mainAgentState: agent.agentState,
            },
            toolResults: [],
          },
          {
            userId,
            promptId: userInputId,
            clientSessionId: sessionId,
          },
        )
        agentPromise = mainAgentPromise.then(({ sessionState }) => ({
          agentState: sessionState.mainAgentState,
          hasEndTurn: true,
        }))
      } else {
        // Import loopAgentSteps dynamically to avoid circular dependency
        const { loopAgentSteps } = await import('./run-agent-step')
        const { agentTemplates: localAgentTemplates } =
          assembleLocalAgentTemplates(agent.fileContext)

        agentPromise = loopAgentSteps(ws, {
          userInputId,
          prompt: undefined, // No initial prompt, will get messages from queue
          params: undefined,
          agentType: agent.agentState.agentType!,
          agentState: agent.agentState,
          fingerprintId: agent.fingerprintId,
          fileContext: agent.fileContext,
          localAgentTemplates,
          toolResults: [],
          userId: agent.userId,
          clientSessionId: sessionId,
          onResponseChunk: () => {}, // Async agents don't stream to parent
        })
      }
      // Store the promise and handle completion
      agent.promise = agentPromise
      await agentPromise
      agent.promise = undefined

      logger.debug(
        { agentId },
        'Agent completed execution after message trigger',
      )
    } catch (error) {
      // Reset status to allow retry and clean up promise
      agent.status = 'failed' // Allow retry by setting to completed
      agent.promise = undefined
      logger.error(
        { agentId, error },
        'Agent failed during message-triggered execution',
      )
    }
  }

  /**
   * Get pending messages for an agent, without clearing them.
   */
  getMessages(agentId: string): AsyncAgentMessage[] {
    return [...(this.messageQueues.get(agentId) || [])]
  }

  /**
   * Retrieve pending messages for an agent, and clear them.
   */
  getAndClearMessages(agentId: string): AsyncAgentMessage[] {
    const messages = this.messageQueues.get(agentId) || []
    this.messageQueues.set(agentId, []) // Clear queue after reading
    return messages
  }

  /**
   * Remove agent and cleanup
   */
  removeAgent(agentId: string): void {
    const agent = this.agents.get(agentId)
    if (agent) {
      // Remove from session tracking
      const sessionAgents = this.sessionAgents.get(agent.sessionId)
      if (sessionAgents) {
        sessionAgents.delete(agentId)
        if (sessionAgents.size === 0) {
          this.sessionAgents.delete(agent.sessionId)
        }
      }

      // Clear message queue
      this.messageQueues.delete(agentId)

      // Remove agent
      this.agents.delete(agentId)
    }
  }

  /**
   * Cleanup all agents for a session (e.g., on disconnect)
   */
  cleanupSession(sessionId: string): void {
    const agentIds = this.sessionAgents.get(sessionId) || new Set()

    for (const agentId of agentIds) {
      const agent = this.agents.get(agentId)
      if (agent && agent.status === 'running') {
        agent.status = 'cancelled'
        // Note: We don't terminate the WebSocket here as it might be shared
        // The actual cleanup should happen in the agent execution loop
      }
      this.removeAgent(agentId)
    }

    logger.debug(
      { sessionId, agentCount: agentIds.size },
      'Cleaned up session agents',
    )
  }

  /**
   * Cleanup all agents associated with a specific user input ID
   */
  cleanupUserInputAgents(userInputId: string): void {
    const agentsToCleanup: string[] = []

    // Find all agents with the matching userInputId
    for (const [agentId, agent] of this.agents.entries()) {
      if (agent.userInputId.startsWith(userInputId)) {
        agentsToCleanup.push(agentId)
      }
    }

    // Cancel and remove the agents
    for (const agentId of agentsToCleanup) {
      const agent = this.agents.get(agentId)
      if (agent && agent.status === 'running') {
        agent.status = 'cancelled'
        // Note: We don't terminate the WebSocket here as it might be shared
        // The actual cleanup should happen in the agent execution loop
      }
      this.removeAgent(agentId)
    }

    logger.debug(
      { userInputId, agentCount: agentsToCleanup.length },
      'Cleaned up agents for user input ID',
    )
  }

  /**
   * Get all running agents
   */
  getRunningAgents(): AsyncAgentInfo[] {
    return Array.from(this.agents.values()).filter(
      (agent) => agent.status === 'running',
    )
  }

  /**
   * Get agent statistics
   */
  getStats(): {
    totalAgents: number
    runningAgents: number
    completedAgents: number
    failedAgents: number
    cancelledAgents: number
    activeSessions: number
  } {
    const agents = Array.from(this.agents.values())
    return {
      totalAgents: agents.length,
      runningAgents: agents.filter((a) => a.status === 'running').length,
      completedAgents: agents.filter((a) => a.status === 'completed').length,
      failedAgents: agents.filter((a) => a.status === 'failed').length,
      cancelledAgents: agents.filter((a) => a.status === 'cancelled').length,
      activeSessions: this.sessionAgents.size,
    }
  }
}

// Global instance
export const asyncAgentManager = new AsyncAgentManager()

