    it('should validate template with parentInstructions', () => {
      const template = {
        ...validBaseTemplate,
        parentInstructions: {
          researcher: 'Spawn when you need research',
          [AgentTemplateTypes.file_picker]: 'Spawn when you need files',
          base: 'Spawn for general tasks',
        },
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(true)
    })
  })

  describe('Invalid Templates', () => {
    it('should reject template with missing required fields', () => {
      const template = {
        id: 'test-agent',
        // Missing other required fields
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(false)
    })

    it('should reject template with invalid outputMode', () => {
      const template = {
        ...validBaseTemplate,
        outputMode: 'invalid_mode',
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(false)
    })

    it('should reject template with invalid inputSchema type', () => {
      const template = {
        ...validBaseTemplate,
        inputSchema: 'not an object',
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(false)
    })

    it('should reject template with invalid paramsSchema type', () => {
      const template = {
        ...validBaseTemplate,
        inputSchema: { params: 'not an object' },
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(false)
    })

    it('should reject template with null schemas', () => {
      const template = {
        ...validBaseTemplate,
        inputSchema: null,
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(false)
    })

    it('should reject template with invalid prompt field structure', () => {
      const template = {
        ...validBaseTemplate,
        systemPrompt: { invalidField: 'value' }, // Should be string only
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(false)
    })

    it('should reject template with invalid agent ID format', () => {
      const invalidIds = [
        'Test_Agent', // uppercase and underscore
        'test agent', // space
        'test.agent', // dot
        'test@agent', // special character
        'Test-Agent', // uppercase
        '123_test', // underscore
        'test/agent', // slash
      ]

      invalidIds.forEach((id) => {
        const template = {
          ...validBaseTemplate,
          id,
        }

        const result = DynamicAgentConfigSchema.safeParse(template)
        expect(result.success).toBe(false)
        if (!result.success) {
          expect(result.error.issues[0].message).toContain(
            'lowercase letters, numbers, and hyphens',
          )
        }
      })
    })

    it('should accept template with valid agent ID format', () => {
      const validIds = [
        'test-agent',
        'test123',
        'agent-v2',
        'my-custom-agent-123',
        'a',
        '123',
        'test-agent-with-many-hyphens',
      ]

      validIds.forEach((id) => {
        const template = {
          ...validBaseTemplate,
          id,
        }

        const result = DynamicAgentConfigSchema.safeParse(template)
        expect(result.success).toBe(true)
      })
    })

    it('should reject template with outputMode json but missing set_output tool', () => {
      const template = {
        ...validBaseTemplate,
        outputMode: 'json' as const,
        toolNames: ['end_turn', 'read_files'], // Missing set_output
      }

      const result = DynamicAgentTemplateSchema.safeParse(template)
      expect(result.success).toBe(false)
      if (!result.success) {
        // Find the specific error about set_output tool
        const setOutputError = result.error.issues.find((issue) =>
          issue.message.includes(
            "outputMode 'json' requires the 'set_output' tool",
          ),
        )
        expect(setOutputError).toBeDefined()
        expect(setOutputError?.message).toContain(
          "outputMode 'json' requires the 'set_output' tool",
        )
      }
    })

    it('should accept template with outputMode json and set_output tool', () => {
      const template = {
        ...validBaseTemplate,
        outputMode: 'json' as const,
        toolNames: ['end_turn', 'set_output'],
      }

      const result = DynamicAgentTemplateSchema.safeParse(template)
      expect(result.success).toBe(true)
    })
  })

  describe('Edge Cases', () => {
    it('should handle empty schemas', () => {
      const template = {
        ...validBaseTemplate,
        inputSchema: {},
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(true)
    })

    it('should handle schemas with additional properties', () => {
      const template = {
        ...validBaseTemplate,
        inputSchema: {
          prompt: {
            type: 'string',
            description: 'A test prompt',
            customProperty: 'custom value',
            anotherProperty: { nested: 'object' },
          },
        },
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(true)
    })

    it('should handle very long schema definitions', () => {
      const largeSchema: any = {
        type: 'object',
        properties: {},
      }

      // Create a large schema with many properties
      for (let i = 0; i < 100; i++) {
        largeSchema.properties[`property${i}`] = {
          type: 'string',
          description: `Property ${i} description`,
        }
      }

      const template = {
        ...validBaseTemplate,
        inputSchema: {
          params: largeSchema,
        },
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(true)
    })
  })
})

import { getAgentTemplate } from '../../../templates/agent-registry'
import { logger } from '../../../util/logger'

import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import type { CodebuffToolCall } from '../../constants'
import type { CodebuffToolHandlerFunction } from '../handler-function-type'
import type { AgentState } from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'

export const handleSetOutput = ((params: {
  previousToolCallFinished: Promise<void>
  toolCall: CodebuffToolCall<'set_output'>
  fileContext: ProjectFileContext
  state: {
    agentState?: AgentState
    localAgentTemplates?: Record<string, AgentTemplate>
  }
}): {
  result: Promise<string>
  state: { agentState: AgentState }
} => {
  const { previousToolCallFinished, toolCall, state } = params
  const output = toolCall.args
  const { agentState, localAgentTemplates } = state

  if (!agentState) {
    throw new Error(
      'Internal error for set_output: Missing agentState in state',
    )
  }

  if (!localAgentTemplates) {
    throw new Error(
      'Internal error for set_output: Missing localAgentTemplates in state',
    )
  }

  const triggerSetOutput = async () => {
    // Validate output against outputSchema if defined
    let agentTemplate = null
    if (agentState.agentType) {
      agentTemplate = await getAgentTemplate(
        agentState.agentType,
        localAgentTemplates,
      )
    }
    if (agentTemplate?.outputSchema) {
      try {
        agentTemplate.outputSchema.parse(output)
      } catch (error) {
        const errorMessage = `Output validation failed for agent ${agentState.agentType}: ${error}`
        logger.error(
          {
            output,
            agentType: agentState.agentType,
            agentId: agentState.agentId,
            error,
          },
          'set_output validation error',
        )
        throw new Error(errorMessage)
      }
    }

    // Set the output (completely replaces previous output)
    agentState.output = output

    logger.debug(
      {
        output,
        agentType: agentState.agentType,
        agentId: agentState.agentId,
        updatedOutput: agentState.output,
      },
      'set_output tool call completed',
    )

    return 'Output set'
  }

  return {
    result: previousToolCallFinished.then(triggerSetOutput),
    state: { agentState: agentState },
  }
}) satisfies CodebuffToolHandlerFunction<'set_output'>

import { ASYNC_AGENTS_ENABLED } from '@codebuff/common/constants'
import { generateCompactId } from '@codebuff/common/util/string'

import { handleSpawnAgents } from './spawn-agents'
import { asyncAgentManager } from '../../../async-agent-manager'
import { getAgentTemplate } from '../../../templates/agent-registry'
import { logger } from '../../../util/logger'

import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import type { CodebuffToolCall } from '../../constants'
import type { CodebuffToolHandlerFunction } from '../handler-function-type'
import type { SendSubagentChunk } from './spawn-agents'
import type { CodebuffMessage } from '@codebuff/common/types/message'
import type { PrintModeEvent } from '@codebuff/common/types/print-mode'
import type {
  AgentState,
  AgentTemplateType,
} from '@codebuff/common/types/session-state'
import type { ProjectFileContext } from '@codebuff/common/util/file'
import type { WebSocket } from 'ws'

export const handleSpawnAgentsAsync = ((params: {
  previousToolCallFinished: Promise<void>
  toolCall: CodebuffToolCall<'spawn_agents_async'>

  fileContext: ProjectFileContext
  clientSessionId: string
  userInputId: string

  getLatestState: () => { messages: CodebuffMessage[] }
  state: {
    ws?: WebSocket
    fingerprintId?: string
    userId?: string
    agentTemplate?: AgentTemplate
    localAgentTemplates?: Record<string, AgentTemplate>
    sendSubagentChunk?: SendSubagentChunk
    messages?: CodebuffMessage[]
    agentState?: AgentState
  }
}): { result: Promise<string>; state: {} } => {
  if (!ASYNC_AGENTS_ENABLED) {
    return handleSpawnAgents({
      ...params,
      toolCall: {
        ...params.toolCall,
        toolName: 'spawn_agents',
      },
    })
  }

  const {
    previousToolCallFinished,
    toolCall,

    fileContext,
    clientSessionId,
    userInputId,
    getLatestState,
    state,
  } = params
  const { agents } = toolCall.args
  const {
    ws,
    fingerprintId,
    userId,
    agentTemplate: parentAgentTemplate,
    localAgentTemplates,
    sendSubagentChunk,
    messages,
  } = state
  let { agentState } = state

  if (!ws) {
    throw new Error(
      'Internal error for spawn_agents_async: Missing WebSocket in state',
    )
  }
  if (!fingerprintId) {
    throw new Error(
      'Internal error for spawn_agents_async: Missing fingerprintId in state',
    )
  }
  if (!parentAgentTemplate) {
    throw new Error(
      'Internal error for spawn_agents_async: Missing agentTemplate in state',
    )
  }
  if (!messages) {
    throw new Error(
      'Internal error for spawn_agents_async: Missing messages in state',
    )
  }
  if (!agentState) {
    throw new Error(
      'Internal error for spawn_agents: Missing agentState in state',
    )
  }
  if (!sendSubagentChunk) {
    throw new Error(
      'Internal error for spawn_agents_async: Missing sendSubagentChunk in state',
    )
  }

  if (!localAgentTemplates) {
    throw new Error(
      'Internal error for spawn_agents_async: Missing localAgentTemplates in state',
    )
  }

  const triggerSpawnAgentsAsync = async () => {
    const results: Array<{
      agentType: string
      success: boolean
      agentId?: string
      error?: string
    }> = []

    const conversationHistoryMessage: CodebuffMessage = {
      role: 'user',
      content: `For context, the following is the conversation history between the user and an assistant:\n\n${JSON.stringify(
        getLatestState().messages,
        null,
        2,
      )}`,
    }

    // Validate and spawn agents asynchronously
    for (const { agent_type: agentTypeStr, prompt, params } of agents) {
      try {
        const agentType = agentTypeStr as AgentTemplateType
        const agentTemplate = await getAgentTemplate(
          agentType,
          localAgentTemplates,
        )

        if (!agentTemplate) {
          throw new Error(`Agent type ${agentTypeStr} not found.`)
        }

        if (!parentAgentTemplate.subagents.includes(agentType)) {
          throw new Error(
            `Agent type ${parentAgentTemplate.id} is not allowed to spawn child agent type ${agentType}.`,
          )
        }

        // Validate prompt and params against agent's schema
        const { inputSchema } = agentTemplate

        // Validate prompt requirement
        if (inputSchema.prompt) {
          const result = inputSchema.prompt.safeParse(prompt)
          if (!result.success) {
            throw new Error(
              `Invalid prompt for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
            )
          }
        }

        // Validate params if schema exists
        if (inputSchema.params) {
          const result = inputSchema.params.safeParse(params)
          if (!result.success) {
            throw new Error(
              `Invalid params for agent ${agentType}: ${JSON.stringify(result.error.issues, null, 2)}`,
            )
          }
        }

        logger.debug(
          { agentTemplate, prompt, params },
          `Spawning async agent — ${agentType}`,
        )

        const subAgentMessages: CodebuffMessage[] = []
        if (agentTemplate.includeMessageHistory) {
          subAgentMessages.push(conversationHistoryMessage)
        }

        const agentId = generateCompactId()
        agentState = {
          agentId,
          agentType,
          agentContext: {},
          subagents: [],
          messageHistory: subAgentMessages,
          stepsRemaining: 20, // MAX_AGENT_STEPS
          output: undefined,
          // Add parent ID to agent state for communication
          parentId: agentState!.agentId,
        }

        // Start the agent asynchronously
        const agentPromise = (async () => {
          try {
            // Import loopAgentSteps dynamically to avoid circular dependency
            const { loopAgentSteps } = await import('../../../run-agent-step')

            const result = await loopAgentSteps(ws, {
              userInputId: `${userInputId}-async-${agentType}-${agentId}`,
              prompt: prompt || '',
              params,
              agentType: agentTemplate.id,
              agentState,
              fingerprintId: fingerprintId!,
              fileContext,
              localAgentTemplates: localAgentTemplates,
              toolResults: [],
              userId,
              clientSessionId,
              onResponseChunk: (chunk: string | PrintModeEvent) => {
                if (typeof chunk !== 'string') {
                  return
                }
                sendSubagentChunk({
                  userInputId,
                  agentId,
                  agentType,
                  chunk,
                  prompt,
                })
              },
            })

            // Send completion message to parent if agent has appropriate output mode
            if (agentState.parentId) {
              const { outputMode } = agentTemplate
              if (
                outputMode === 'last_message' ||
                outputMode === 'all_messages'
              ) {
                try {
                  let messageContent = ''

                  if (outputMode === 'last_message') {
                    const assistantMessages =
                      result.agentState.messageHistory.filter(
                        (message) => message.role === 'assistant',
                      )
                    const lastAssistantMessage =
                      assistantMessages[assistantMessages.length - 1]
                    if (lastAssistantMessage) {
                      if (typeof lastAssistantMessage.content === 'string') {
                        messageContent = lastAssistantMessage.content
                      } else {
                        messageContent = JSON.stringify(
                          lastAssistantMessage.content,
                          null,
                          2,
                        )
                      }
                    } else {
                      messageContent = 'No response from agent'
                    }
                  } else if (outputMode === 'all_messages') {
                    // Remove the first message, which includes the previous conversation history
                    const agentMessages =
                      result.agentState.messageHistory.slice(1)
                    messageContent = `Agent messages:\n\n${JSON.stringify(agentMessages, null, 2)}`
                  }

                  // Send the message to the parent agent
                  const { asyncAgentManager } = await import(
                    '../../../async-agent-manager'
                  )
                  asyncAgentManager.sendMessage({
                    fromAgentId: agentId,
                    toAgentId: agentState.parentId,
                    prompt: `Agent ${agentType} completed with output:\n\n${messageContent}`,
                    params: {
                      agentType,
                      agentId,
                      outputMode,
                      completed: true,
                    },
                    timestamp: new Date(),
                  })

                  logger.debug(
                    {
                      agentId,
                      parentId: agentState.parentId,
                      agentType,
                      outputMode,
                      messageContent,
                    },
                    'Sent completion message to parent agent',
                  )
                } catch (error) {
                  logger.error(
                    {
                      agentId,
                      parentId: agentState.parentId,
                      error,
                    },
                    'Failed to send completion message to parent agent',
                  )
                }
              }
            }

            return result
          } catch (error) {
            logger.error({ agentId, error }, 'Async agent failed')
            throw error
          }
        })()

        // Store the promise in the agent info
        const agentInfo = asyncAgentManager.getAgent(agentId)
        if (agentInfo) {
          agentInfo.promise = agentPromise
        }

        results.push({ agentType: agentTypeStr, success: true, agentId })
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : String(error)
        results.push({
          agentType: agentTypeStr,
          success: false,
          error: errorMessage,
        })
        logger.error(
          { agentType: agentTypeStr, error },
          'Failed to spawn async agent',
        )
        // Continue with other agents even if one fails
      }
    }

    const successful = results.filter((r) => r.success)

    let result = `Agent spawn results (${successful.length}/${results.length} successful):\n`

    results.forEach(({ agentType, success, agentId, error }) => {
      if (success) {
        result += `✓ ${agentType}: spawned (${agentId})\n`
      } else {
        result += `✗ ${agentType}: failed - ${error}\n`
      }
    })

    return result.trim()
  }

  return {
    result: previousToolCallFinished.then(triggerSpawnAgentsAsync),
    state: {},
  }
}) satisfies CodebuffToolHandlerFunction<'spawn_agents_async'>

