export const DynamicAgentTemplateSchema = DynamicAgentConfigSchema.extend({
  systemPrompt: z.string(),
  instructionsPrompt: z.string(),
  stepPrompt: z.string(),
  handleSteps: z.string().optional(),
})
  // Existing refinement for outputSchema requiring json outputMode
  .refine(
    (data) => {
      if (data.outputSchema && data.outputMode !== 'json') {
        return false
      }
      return true
    },
    {
      message:
        "outputSchema requires outputMode to be explicitly set to 'json'.",
      path: ['outputMode'],
    },
  )
  // NEW: If outputMode is 'json', require 'set_output' tool (error on toolNames)
  .refine(
    (data) => {
      if (
        data.outputMode === 'json' &&
        !data.toolNames.includes('set_output')
      ) {
        return false
      }
      return true
    },
    {
      message:
        'The "set_output" tool requires outputMode to be "json". Change outputMode to "json" or remove "set_output" from toolNames.',
      path: ['toolNames'],
    },
  )
  // NEW: If 'set_output' tool is present, require outputMode to be 'json' (error on outputMode)
  .refine(
    (data) => {
      if (
        data.toolNames.includes('set_output') &&
        data.outputMode !== 'json'
      ) {
        return false
      }
      return true
    },
    {
      message:
        'The "set_output" tool requires outputMode to be "json". Change outputMode to "json" or remove "set_output" from toolNames.',
      path: ['outputMode'],
    },
  )
  // NEW: If subagents array is non-empty, require 'spawn_agents' tool (error on toolNames)
  .refine(
    (data) => {
      if (
        data.subagents.length > 0 &&
        !data.toolNames.includes('spawn_agents')
      ) {
        return false
      }
      return true
    },
    {
      message:
        'A non-empty subagents array requires the "spawn_agents" tool. Add "spawn_agents" to toolNames or empty the subagents array.',
      path: ['toolNames'],
    },
  )
  // NEW: If subagents array is non-empty, require 'spawn_agents' tool (error on subagents)
  .refine(
    (data) => {
      if (
        data.subagents.length > 0 &&
        !data.toolNames.includes('spawn_agents')
      ) {
        return false
      }
      return true
    },
    {
      message:
        'A non-empty subagents array requires the "spawn_agents" tool. Add "spawn_agents" to toolNames or empty the subagents array.',
      path: ['subagents'],
    },
  )
