        ...validBaseTemplate,
        inputSchema: {
          prompt: {
            type: 'string',
            description: 'A test prompt',
          },
        },
      }

      const result = DynamicAgentConfigSchema.safeParse(template)
      expect(result.success).toBe(true)
    })

    it('should validate template with paramsSchema', () => {
      const template = {
        ...validBaseTemplate,
        inputSchema: {
          params: {
            type: 'object',
            properties: {
              temperature: {
                type: 'number',
