import { normalizeAgentNames } from './agent-name-normalization'
import { DynamicAgentTemplateSchema } from '../types/dynamic-agent-template'
import { AgentTemplateTypes } from '../types/session-state'

import type { AgentOverrideConfig } from '../types/agent-overrides'
import type { DynamicAgentTemplate } from '../types/dynamic-agent-template'

export interface SubagentValidationResult {
  valid: boolean
  invalidAgents: string[]
}

export interface AgentTemplateValidationResult {
  validConfigs: Array<{
    filePath: string
    config: AgentOverrideConfig | DynamicAgentTemplate
  }>
  validationErrors: Array<{ filePath: string; message: string }>
}

/**
 * Centralized validation for spawnable agents.
 * Validates that all spawnable agents reference valid agent types.
 */
export function validateSubagents(
  subagents: string[],
  dynamicAgentIds: string[],
): SubagentValidationResult & { availableAgents: string[] } {
  // Normalize dynamic agent IDs to allow users to reference them without org prefixes
  const normalizedDynamicAgentIds = normalizeAgentNames(dynamicAgentIds)

  // Build complete list of available agent types (normalized)
  const availableAgentTypes = [
    ...Object.values(AgentTemplateTypes),
    ...normalizedDynamicAgentIds,
  ]

  // Normalize subagents for comparison
  const normalizedSubagents = normalizeAgentNames(subagents)

  // Find invalid agents (those not in available types after normalization)
  const invalidAgents = subagents.filter(
    (agent, index) => !availableAgentTypes.includes(normalizedSubagents[index]),
  )

  return {
    valid: invalidAgents.length === 0,
    invalidAgents,
    availableAgents: availableAgentTypes,
  }
}

/**
 * Centralized validation for parent instructions.
 * Validates that all parent instruction keys reference valid agent types.
 */
export function validateParentInstructions(
  parentInstructions: Record<string, string>,
  dynamicAgentIds: string[],
): SubagentValidationResult & { availableAgents: string[] } {
  // Normalize dynamic agent IDs to allow users to reference them without org prefixes
  const normalizedDynamicAgentIds = normalizeAgentNames(dynamicAgentIds)

  // Build complete list of available agent types (normalized)
  const availableAgentTypes = [
    ...Object.values(AgentTemplateTypes),
    ...normalizedDynamicAgentIds,
  ]

  // Get the keys (agent IDs) from parentInstructions
  const parentInstructionKeys = Object.keys(parentInstructions)

  // Normalize parent instruction keys for comparison
  const normalizedParentInstructionKeys = normalizeAgentNames(
    parentInstructionKeys,
  )

  // Find invalid agents (those not in available types after normalization)
  const invalidAgents = parentInstructionKeys.filter(
    (agent, index) =>
      !availableAgentTypes.includes(normalizedParentInstructionKeys[index]),
  )

  return {
    valid: invalidAgents.length === 0,
    invalidAgents,
    availableAgents: availableAgentTypes,
  }
}

/**
 * Formats a validation error message for subagents
 */
export function formatSubagentError(
  invalidAgents: string[],
  availableAgents: string[],
): string {
  let message = `Invalid subagents: ${invalidAgents.join(', ')}. Double check the id, including the org prefix if applicable.`

  message += `\n\nAvailable agents: ${availableAgents.join(', ')}`

  return message
}

/**
 * Formats a validation error message for parent instructions
 */
export function formatParentInstructionsError(
  invalidAgents: string[],
  availableAgents: string[],
): string {
  let message = `Invalid parent instruction agent IDs: ${invalidAgents.join(', ')}. Double check the id, including the org prefix if applicable.`

  message += `\n\nAvailable agents: ${availableAgents.join(', ')}`

  return message
}

/**
 * Formats validation errors into a user-friendly error message
 * @param validationErrors - Array of validation errors
 * @returns Formatted error message string or undefined if no errors
 */
export function formatValidationErrorMessage(
  validationErrors: Array<{ filePath: string; message: string }>,
): string | undefined {
  if (validationErrors.length === 0) return undefined

  return validationErrors
    .map((error) => `❌ ${error.filePath}: ${error.message}`)
    .join('\n')
}

/**
 * Validates agent template files and returns both valid configs and validation errors
 * @param agentTemplates - Record of file paths to file contents
 * @param dynamicAgentIds - Array of dynamic agent IDs to include in validation
 * @returns Object containing valid configs and validation errors
 */
export function validateAgentTemplateConfigs(
  agentTemplates: Record<string, DynamicAgentTemplate>,
  dynamicAgentIds: string[] = [],
): AgentTemplateValidationResult {
  const validConfigs: Array<{
    filePath: string
    config: AgentOverrideConfig | DynamicAgentTemplate
  }> = []
  const validationErrors: Array<{ filePath: string; message: string }> = []

  for (const [agentId, content] of Object.entries(agentTemplates)) {
    try {
      const config = DynamicAgentTemplateSchema.parse(content)

      // Additional validation for subagents
      if (config.subagents && config.subagents.length > 0) {
        const validation = validateSubagents(config.subagents, dynamicAgentIds)
        if (!validation.valid) {
          validationErrors.push({
            filePath: agentId,
            message: formatSubagentError(
              validation.invalidAgents,
              validation.availableAgents,
            ),
          })
          continue
        }
      }

      validConfigs.push({ filePath: agentId, config })
    } catch (error) {
      validationErrors.push({
        filePath: agentId,
        message: `Invalid JSON or schema: ${error instanceof Error ? error.message : 'Unknown error'}`,
      })
    }
  }

  return { validConfigs, validationErrors }
}

/**
 * Validates agent template override files and returns only valid ones
 */
export function validateAgentTemplateFiles(
  agentTemplates: Record<string, DynamicAgentTemplate>,
  logger?: { warn: (obj: any, msg: string) => void },
): Record<string, DynamicAgentTemplate> {
  const validatedAgents: Record<string, DynamicAgentTemplate> = {}
  const { validConfigs, validationErrors } =
    validateAgentTemplateConfigs(agentTemplates)

  // Add valid configs to validated files
  for (const { filePath } of validConfigs) {
    validatedAgents[filePath] = agentTemplates[filePath]
  }

  // Log validation errors
  for (const { filePath, message } of validationErrors) {
    logger?.warn({ filePath }, message) ??
      console.warn(`${message}: ${filePath}`)
  }

  // Add non-JSON files without validation
  for (const [filePath, content] of Object.entries(agentTemplates)) {
    if (!filePath.endsWith('.json')) {
      validatedAgents[filePath] = content
    }
  }

  return validatedAgents
}

import type { AgentTemplate } from '@codebuff/common/types/agent-template'
import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { and, desc, eq } from 'drizzle-orm'

import { ProjectFileContext } from '@codebuff/common/util/file'
import { logger } from '../util/logger'
import { agentTemplates as staticTemplates } from './agent-list'
import {
  DynamicAgentValidationError,
  validateAgents,
  validateSingleAgent,
} from '@codebuff/common/templates/agent-validation'
import { DynamicAgentTemplate } from '@codebuff/common/types/dynamic-agent-template'

export type AgentRegistry = Record<string, AgentTemplate>

// Global database cache - only state in the system
const databaseAgentCache = new Map<string, AgentTemplate | null>()

/**
 * Parse agent ID to extract publisher, agent name, and version
 */
function parseAgentId(fullAgentId: string): {
  publisherId: string
  agentId: string
  version?: string
} | null {
  // Check if it's in the publisher/agent-id[@version] format
  const parts = fullAgentId.split('/')
  if (parts.length !== 2) {
    return null
  }

  const [publisherId, agentNameWithVersion] = parts

  // Check for version suffix
  const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
  if (versionMatch) {
    const [, agentId, version] = versionMatch
    return { publisherId, agentId, version }
  }

  return { publisherId, agentId: agentNameWithVersion }
}

/**
 * Fetch an agent from the database by publisher/agent-id[@version] format
 */
async function fetchAgentFromDatabase(parsedAgentId: {
  publisherId: string
  agentId: string
  version?: string
}): Promise<AgentTemplate | null> {
  const { publisherId, agentId, version } = parsedAgentId

  try {
    let agentConfig

    if (version && version !== 'latest') {
      // Query for specific version
      agentConfig = await db
        .select()
        .from(schema.agentConfig)
        .where(
          and(
            eq(schema.agentConfig.id, agentId),
            eq(schema.agentConfig.publisher_id, publisherId),
            eq(schema.agentConfig.version, version),
          ),
        )
        .then((rows) => rows[0])
    } else {
      // Query for latest version
      agentConfig = await db
        .select()
        .from(schema.agentConfig)
        .where(
          and(
            eq(schema.agentConfig.id, agentId),
            eq(schema.agentConfig.publisher_id, publisherId),
          ),
        )
        .orderBy(
          desc(schema.agentConfig.major),
          desc(schema.agentConfig.minor),
          desc(schema.agentConfig.patch),
        )
        .limit(1)
        .then((rows) => rows[0])
    }

    if (!agentConfig) {
      logger.debug(
        { publisherId, agentId, version },
        'fetchAgentFromDatabase: Agent not found in database',
      )
      return null
    }

    const rawAgentData = agentConfig.data as DynamicAgentTemplate

    // Ensure the agent has the full publisher/agent-id@version as its ID
    const agentDataWithId = {
      ...rawAgentData,
      id: `${publisherId}/${agentId}@${agentConfig.version}`,
    }

    // Use validateSingleAgent to convert to AgentTemplate type
    const validationResult = validateSingleAgent(agentDataWithId, {
      filePath: `${publisherId}/${agentId}@${agentConfig.version}`,
      skipSubagentValidation: true,
    })

    if (!validationResult.success) {
      logger.error(
        {
          publisherId,
          agentId,
          version: agentConfig.version,
          fullAgentId: agentDataWithId.id,
          error: validationResult.error,
        },
        'fetchAgentFromDatabase: Agent validation failed',
      )
      return null
    }

    logger.debug(
      {
        publisherId,
        agentId,
        version: agentConfig.version,
        fullAgentId: agentDataWithId.id,
        agentConfig,
      },
      'fetchAgentFromDatabase: Successfully loaded and validated agent from database',
    )

    return validationResult.agentTemplate!
  } catch (error) {
    logger.error(
      { publisherId, agentId, version, error },
      'fetchAgentFromDatabase: Error fetching agent from database',
    )
    return null
  }
}

/**
 * Single function to look up an agent template with clear priority order:
 * 1. localAgentTemplates (dynamic agents + static templates)
 * 2. Database cache
 * 3. Database query
 */
export async function getAgentTemplate(
  agentId: string,
  localAgentTemplates: Record<string, AgentTemplate>,
): Promise<AgentTemplate | null> {
  // 1. Check localAgentTemplates first (dynamic agents + static templates)
  if (localAgentTemplates[agentId]) {
    return localAgentTemplates[agentId]
  }
  // 2. Check database cache
  const cacheKey = agentId
  if (databaseAgentCache.has(cacheKey)) {
    return databaseAgentCache.get(cacheKey) || null
  }

  const parsed = parseAgentId(agentId)
  if (!parsed) {
    logger.debug({ agentId }, 'getAgentTemplate: Failed to parse agent ID')
    return null
  }

  // 3. Query database (only for publisher/agent-id format)
  const dbAgent = await fetchAgentFromDatabase(parsed)
  if (dbAgent && parsed.version && parsed.version !== 'latest') {
    // Cache only specific versions to avoid stale 'latest' results
    databaseAgentCache.set(cacheKey, dbAgent)
  }
  return dbAgent
}

/**
 * Assemble local agent templates from fileContext + static templates
 */
export function assembleLocalAgentTemplates(fileContext: ProjectFileContext): {
  agentTemplates: Record<string, AgentTemplate>
  validationErrors: DynamicAgentValidationError[]
} {
  // Load dynamic agents using the service
  const { templates: dynamicTemplates, validationErrors } = validateAgents(
    fileContext.agentTemplates || {},
  )

  // Combine static and dynamic templates
  const agentTemplates = { ...staticTemplates, ...dynamicTemplates }

  return { agentTemplates, validationErrors }
}

/**
 * Clear the database agent cache (useful for testing)
 */
export function clearDatabaseCache(): void {
  databaseAgentCache.clear()
}

import * as fs from 'fs'
import * as path from 'path'

import { DynamicAgentConfigSchema } from '@codebuff/common/types/dynamic-agent-template'
import { cyan, green } from 'picocolors'

import { getAllTsFiles, getAgentsDirectory } from './agent-utils'

import type { CodebuffConfig } from '@codebuff/common/json-config/constants'
import type {
  DynamicAgentConfigParsed,
  DynamicAgentTemplate,
} from '@codebuff/common/types/dynamic-agent-template'

export let loadedAgents: Record<string, DynamicAgentTemplate> = {}

export async function loadLocalAgents({
  verbose = false,
}: {
  verbose?: boolean
}): Promise<typeof loadedAgents> {
  loadedAgents = {}

  const agentsDir = getAgentsDirectory()

  if (!fs.existsSync(agentsDir)) {
    return loadedAgents
  }

  try {
    const tsFiles = getAllTsFiles(agentsDir)

    for (const fullPath of tsFiles) {
      const relativePath = path.relative(agentsDir, fullPath)
      const fileName = relativePath.replace(/\.ts$/, '').replace(/[/\\]/g, '-')

      let agentConfig: any
      let agentModule: any
      try {
        agentModule = await require(fullPath)
      } catch (error: any) {
        if (verbose) {
          console.error('Error importing agent:', error)
        }
        continue
      }
      delete require.cache[fullPath]

      try {
        agentConfig = agentModule.default
      } catch (error: any) {
        console.error('Error loading agent from file:', fullPath, error)
        continue
      }

      if (!agentConfig) continue

      let typedAgentConfig: DynamicAgentConfigParsed
      try {
        typedAgentConfig = DynamicAgentConfigSchema.parse(agentConfig)
      } catch (error: any) {
        console.error('Invalid agent format:', fullPath, error)
        continue
      }

      // Convert handleSteps function to string if present
      let handleStepsString: string | undefined
      if (agentConfig.handleSteps) {
        handleStepsString = agentConfig.handleSteps.toString()
      }

      loadedAgents[fileName] = {
        ...typedAgentConfig,
        systemPrompt: typedAgentConfig.systemPrompt || '',
        instructionsPrompt: typedAgentConfig.instructionsPrompt || '',
        stepPrompt: typedAgentConfig.stepPrompt || '',
        handleSteps: handleStepsString,
      }
    }
  } catch (error) {}

  return loadedAgents
}

export function getLoadedAgentNames(): Record<string, string> {
  return Object.fromEntries(
    Object.entries(loadedAgents).map(([agentType, agentConfig]) => {
      return [agentType, agentConfig.displayName]
    }),
  )
}

/**
 * Display loaded agents to the user
 */
export function displayLoadedAgents(codebuffConfig: CodebuffConfig) {
  const baseAgent = codebuffConfig.baseAgent
  if (baseAgent) {
    console.log(`\n${green('Configured base agent:')} ${cyan(baseAgent)}`)
  }

  const subagents = codebuffConfig.subagents
  if (subagents) {
    console.log(
      `${green('Configured subagents:')} ${subagents
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (Object.keys(loadedAgents).length > 0) {
    const loadedAgentNames = Object.values(getLoadedAgentNames())
    console.log(
      `\n${green('Found custom agents:')} ${loadedAgentNames
        .map((name) => cyan(name))
        .join(', ')}\n`,
    )
  } else if (baseAgent) {
    // One more new line.
    console.log()
  }
}

