export const DEFAULT_ORG_PREFIX = 'CodebuffAI/'

/**
 * Normalizes agent names by stripping only the default CodebuffAI organization prefix
 * Other organization prefixes are preserved to maintain their identity
 * @param agentName - The agent name that may include an org prefix
 * @returns The normalized agent name with only CodebuffAI prefix removed
 */
export function normalizeAgentName(agentName: string): string {
  if (agentName.startsWith(DEFAULT_ORG_PREFIX)) {
    return agentName.slice(DEFAULT_ORG_PREFIX.length)
  }
  return agentName
}

/**
 * Normalizes a list of agent names by stripping the default organization prefix
 * @param agentNames - Array of agent names or single agent name
 * @returns Array of normalized agent names
 */
export function normalizeAgentNames(agentNames: string | string[]): string[] {
  const agentList = Array.isArray(agentNames) ? agentNames : [agentNames]
  return agentList.map(normalizeAgentName)
}

/**
 * Resolves an agent ID by trying multiple strategies:
 * 1. Direct lookup in registry
 * 2. Try with DEFAULT_ORG_PREFIX for spawnable agents
 * 3. Return null if not found
 *
 * This provides a more robust alternative to string concatenation
 * and handles the common case where users reference spawnable agents
 * without the org prefix.
 */
export function resolveAgentId(
  agentId: string,
  agentRegistry: Record<string, any>,
): string | null {
  // Handle empty or invalid input
  if (!agentId || typeof agentId !== 'string') {
    return null
  }

  // Try direct lookup first
  if (agentId in agentRegistry) {
    return agentId
  }

  // Try with DEFAULT_ORG_PREFIX for spawnable agents
  // Only add prefix if the agent ID doesn't already contain a slash
  // (to avoid double-prefixing or interfering with other org prefixes)
  if (!agentId.includes('/')) {
    const prefixedAgentId = `${DEFAULT_ORG_PREFIX}${agentId}`
    if (prefixedAgentId in agentRegistry) {
      return prefixedAgentId
    }
  }

  return null
}

import { normalizeAgentNames } from './agent-name-normalization'
import { DynamicAgentTemplateSchema } from '../types/dynamic-agent-template'
import { AgentTemplateTypes } from '../types/session-state'

import type { DynamicAgentTemplate } from '../types/dynamic-agent-template'

export interface SubagentValidationResult {
  valid: boolean
  invalidAgents: string[]
}

export interface AgentTemplateValidationResult {
  validConfigs: Array<{
    filePath: string
    config: DynamicAgentTemplate
  }>
  validationErrors: Array<{ filePath: string; message: string }>
}

/**
 * Centralized validation for spawnable agents.
 * Validates that all spawnable agents reference valid agent types.
 */
export function validateSubagents(
  subagents: string[],
  dynamicAgentIds: string[],
): SubagentValidationResult & { availableAgents: string[] } {
  // Normalize dynamic agent IDs to allow users to reference them without org prefixes
  const normalizedDynamicAgentIds = normalizeAgentNames(dynamicAgentIds)

  // Build complete list of available agent types (normalized)
  const availableAgentTypes = [
    ...Object.values(AgentTemplateTypes),
    ...normalizedDynamicAgentIds,
  ]

  // Normalize subagents for comparison
  const normalizedSubagents = normalizeAgentNames(subagents)

  // Find invalid agents (those not in available types after normalization)
  const invalidAgents = subagents.filter(
    (agent, index) => !availableAgentTypes.includes(normalizedSubagents[index]),
  )

  return {
    valid: invalidAgents.length === 0,
    invalidAgents,
    availableAgents: availableAgentTypes,
  }
}

/**
 * Centralized validation for parent instructions.
 * Validates that all parent instruction keys reference valid agent types.
 */
export function validateParentInstructions(
  parentInstructions: Record<string, string>,
  dynamicAgentIds: string[],
): SubagentValidationResult & { availableAgents: string[] } {
  // Normalize dynamic agent IDs to allow users to reference them without org prefixes
  const normalizedDynamicAgentIds = normalizeAgentNames(dynamicAgentIds)

  // Build complete list of available agent types (normalized)
  const availableAgentTypes = [
    ...Object.values(AgentTemplateTypes),
    ...normalizedDynamicAgentIds,
  ]

  // Get the keys (agent IDs) from parentInstructions
  const parentInstructionKeys = Object.keys(parentInstructions)

  // Normalize parent instruction keys for comparison
  const normalizedParentInstructionKeys = normalizeAgentNames(
    parentInstructionKeys,
  )

  // Find invalid agents (those not in available types after normalization)
  const invalidAgents = parentInstructionKeys.filter(
    (agent, index) =>
      !availableAgentTypes.includes(normalizedParentInstructionKeys[index]),
  )

  return {
    valid: invalidAgents.length === 0,
    invalidAgents,
    availableAgents: availableAgentTypes,
  }
}

/**
 * Formats a validation error message for subagents
 */
export function formatSubagentError(
  invalidAgents: string[],
  availableAgents: string[],
): string {
  let message = `Invalid subagents: ${invalidAgents.join(', ')}. Double check the id, including the org prefix if applicable.`

  message += `\n\nAvailable agents: ${availableAgents.join(', ')}`

  return message
}

/**
 * Formats a validation error message for parent instructions
 */
export function formatParentInstructionsError(
  invalidAgents: string[],
  availableAgents: string[],
): string {
  let message = `Invalid parent instruction agent IDs: ${invalidAgents.join(', ')}. Double check the id, including the org prefix if applicable.`

  message += `\n\nAvailable agents: ${availableAgents.join(', ')}`

  return message
}

/**
 * Formats validation errors into a user-friendly error message
 * @param validationErrors - Array of validation errors
 * @returns Formatted error message string or undefined if no errors
 */
export function formatValidationErrorMessage(
  validationErrors: Array<{ filePath: string; message: string }>,
): string | undefined {
  if (validationErrors.length === 0) return undefined

  return validationErrors
    .map((error) => `❌ ${error.filePath}: ${error.message}`)
    .join('\n')
}

/**
 * Validates agent template files and returns both valid configs and validation errors
 * @param agentTemplates - Record of file paths to file contents
 * @param dynamicAgentIds - Array of dynamic agent IDs to include in validation
 * @returns Object containing valid configs and validation errors
 */
export function validateAgentTemplateConfigs(
  agentTemplates: Record<string, DynamicAgentTemplate>,
  dynamicAgentIds: string[] = [],
): AgentTemplateValidationResult {
  const validConfigs: Array<{
    filePath: string
    config: DynamicAgentTemplate
  }> = []
  const validationErrors: Array<{ filePath: string; message: string }> = []

  for (const [agentId, content] of Object.entries(agentTemplates)) {
    try {
      const config = DynamicAgentTemplateSchema.parse(content)

      // Additional validation for subagents
      if (config.subagents && config.subagents.length > 0) {
        const validation = validateSubagents(config.subagents, dynamicAgentIds)
        if (!validation.valid) {
          validationErrors.push({
            filePath: agentId,
            message: formatSubagentError(
              validation.invalidAgents,
              validation.availableAgents,
            ),
          })
          continue
        }
      }

      validConfigs.push({ filePath: agentId, config })
    } catch (error) {
      validationErrors.push({
        filePath: agentId,
        message: `Invalid JSON or schema: ${error instanceof Error ? error.message : 'Unknown error'}`,
      })
    }
  }

  return { validConfigs, validationErrors }
}

/**
 * Validates agent template override files and returns only valid ones
 */
export function validateAgentTemplateFiles(
  agentTemplates: Record<string, DynamicAgentTemplate>,
  logger?: { warn: (obj: any, msg: string) => void },
): Record<string, DynamicAgentTemplate> {
  const validatedAgents: Record<string, DynamicAgentTemplate> = {}
  const { validConfigs, validationErrors } =
    validateAgentTemplateConfigs(agentTemplates)

  // Add valid configs to validated files
  for (const { filePath } of validConfigs) {
    validatedAgents[filePath] = agentTemplates[filePath]
  }

  // Log validation errors
  for (const { filePath, message } of validationErrors) {
    logger?.warn({ filePath }, message) ??
      console.warn(`${message}: ${filePath}`)
  }

  // Add non-JSON files without validation
  for (const [filePath, content] of Object.entries(agentTemplates)) {
    if (!filePath.endsWith('.json')) {
      validatedAgents[filePath] = content
    }
  }

  return validatedAgents
}

import { convertJsonSchemaToZod } from 'zod-from-json-schema'

import { normalizeAgentNames } from '../util/agent-name-normalization'
import {
  formatSubagentError,
  validateSubagents,
} from '../util/agent-template-validation'
import { logger } from '../util/logger'

import type { ToolName } from '../tools/constants'
import type { AgentTemplate } from '../types/agent-template'
import type { DynamicAgentTemplate } from '../types/dynamic-agent-template'
import type { AgentTemplateType } from '../types/session-state'

export interface DynamicAgentValidationError {
  filePath: string
  message: string
}

/**
 * Collect all agent IDs from template files without full validation
 */
export function collectAgentIds(
  agentTemplates: Record<string, DynamicAgentTemplate> = {},
): string[] {
  const agentIds: string[] = []
  const jsonFiles = Object.keys(agentTemplates)

  for (const filePath of jsonFiles) {
    try {
      const content = agentTemplates[filePath]
      if (!content) {
        continue
      }

      // Extract the agent ID if it exists
      if (content.id && typeof content.id === 'string') {
        agentIds.push(content.id)
      }
    } catch (error) {
      // Log but don't fail the collection process for other errors
      logger.debug(
        { filePath, error },
        'Failed to extract agent ID during collection phase',
      )
    }
  }

  return agentIds
}

/**
 * Validate and load dynamic agent templates from user-provided agentTemplates
 */
export function validateAgents(
  agentTemplates: Record<string, DynamicAgentTemplate> = {},
): {
  templates: Record<string, AgentTemplate>
  validationErrors: DynamicAgentValidationError[]
} {
  const templates: Record<string, AgentTemplate> = {}
  const validationErrors: DynamicAgentValidationError[] = []

  const hasAgentTemplates = Object.keys(agentTemplates).length > 0

  if (!hasAgentTemplates) {
    return {
      templates,
      validationErrors,
    }
  }

  const agentKeys = Object.keys(agentTemplates)

  // Pass 1: Collect all agent IDs from template files
  const dynamicAgentIds = collectAgentIds(agentTemplates)

  // Pass 2: Load and validate each agent template
  for (const agentKey of agentKeys) {
    try {
      const content = agentTemplates[agentKey]
      if (!content) {
        continue
      }

      const validationResult = validateSingleAgent(content, {
        filePath: agentKey,
        dynamicAgentIds,
      })

      if (!validationResult.success) {
        validationErrors.push({
          filePath: agentKey,
          message: validationResult.error!,
        })
        continue
      }

      if (templates[content.id]) {
        validationErrors.push({
          filePath: agentKey,
          message: `Duplicate agent ID: ${content.id}`,
        })
        continue
      }
      templates[content.id] = validationResult.agentTemplate!
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'

      validationErrors.push({
        filePath: agentKey,
        message: `Error in agent template ${agentKey}: ${errorMessage}`,
      })

      logger.warn(
        { filePath: agentKey, error: errorMessage },
        'Failed to load dynamic agent template',
      )
    }
  }

  return {
    templates,
    validationErrors,
  }
}

/**
 * Validates a single dynamic agent template and converts it to an AgentTemplate.
 * This is a plain function equivalent to the core logic of loadSingleAgent.
 *
 * @param dynamicAgentIds - Array of all available dynamic agent IDs for validation
 * @param template - The dynamic agent template to validate
 * @param options - Optional configuration object
 * @param options.filePath - Optional file path for error context
 * @param options.skipSubagentValidation - Skip subagent validation when loading from database
 * @returns Validation result with either the converted AgentTemplate or an error
 */
export function validateSingleAgent(
  template: DynamicAgentTemplate,
  options?: {
    dynamicAgentIds?: string[]
    filePath?: string
    skipSubagentValidation?: boolean
  },
): {
  success: boolean
  agentTemplate?: AgentTemplate
  error?: string
} {
  const {
    filePath,
    skipSubagentValidation = true,
    dynamicAgentIds = [],
  } = options || {}

  try {
    // Validate subagents (skip if requested, e.g., for database agents)
    if (!skipSubagentValidation) {
      const subagentValidation = validateSubagents(
        template.subagents,
        dynamicAgentIds,
      )
      if (!subagentValidation.valid) {
        return {
          success: false,
          error: formatSubagentError(
            subagentValidation.invalidAgents,
            subagentValidation.availableAgents,
          ),
        }
      }
    }

    const validatedSubagents = normalizeAgentNames(
      template.subagents,
    ) as AgentTemplateType[]

    // Convert schemas and handle validation errors
    let inputSchema: AgentTemplate['inputSchema']
    try {
      inputSchema = convertInputSchema(
        template.inputSchema?.prompt,
        template.inputSchema?.params,
        filePath,
      )
    } catch (error) {
      return {
        success: false,
        error:
          error instanceof Error ? error.message : 'Schema conversion failed',
      }
    }

    // Convert outputSchema if present
    let outputSchema: AgentTemplate['outputSchema']
    if (template.outputSchema) {
      try {
        outputSchema = convertJsonSchemaToZod(template.outputSchema)
      } catch (error) {
        return {
          success: false,
          error: `Failed to convert outputSchema to Zod: ${error instanceof Error ? error.message : 'Unknown error'}`,
        }
      }
    }

    // Validate handleSteps if present
    if (template.handleSteps) {
      if (!isValidGeneratorFunction(template.handleSteps)) {
        return {
          success: false,
          error: `handleSteps must be a generator function: "function* (params) { ... }". Found: ${template.handleSteps.substring(0, 50)}...`,
        }
      }
    }

    // Convert to internal AgentTemplate format
    const agentTemplate: AgentTemplate = {
      ...template,
      outputSchema,
      inputSchema,
      toolNames: template.toolNames as ToolName[],
      subagents: validatedSubagents,
    }

    return {
      success: true,
      agentTemplate,
    }
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'

    return {
      success: false,
      error: `Error validating agent template: ${errorMessage}`,
    }
  }
}

/**
 * Validates if a string represents a valid generator function
 */
function isValidGeneratorFunction(code: string): boolean {
  const trimmed = code.trim()
  // Check if it's a generator function (must start with function*)
  return trimmed.startsWith('function*')
}

/**
 * Convert JSON schema to Zod schema format using json-schema-to-zod.
 * This is done once during loading to avoid repeated conversions.
 * Throws descriptive errors for validation failures.
 */
function convertInputSchema(
  inputPromptSchema?: Record<string, any>,
  paramsSchema?: Record<string, any>,
  filePath?: string,
): AgentTemplate['inputSchema'] {
  const result: any = {}
  const fileContext = filePath ? ` in ${filePath}` : ''

  // Handle prompt schema
  if (inputPromptSchema) {
    try {
      if (
        typeof inputPromptSchema !== 'object' ||
        Object.keys(inputPromptSchema).length === 0
      ) {
        throw new Error(
          `Invalid inputSchema.prompt${fileContext}: Schema must be a valid non-empty JSON schema object. Found: ${typeof inputPromptSchema}`,
        )
      }
      const promptZodSchema = convertJsonSchemaToZod(inputPromptSchema)
      // Validate that the schema results in string or undefined
      const testResult = promptZodSchema.safeParse('test')
      const testUndefined = promptZodSchema.safeParse(undefined)

      if (!testResult.success && !testUndefined.success) {
        const errorDetails =
          testResult.error?.issues?.[0]?.message || 'validation failed'
        throw new Error(
          `Invalid inputSchema.prompt${fileContext}: Schema must allow string or undefined values. ` +
            `Current schema validation error: ${errorDetails}. ` +
            `Please ensure your JSON schema accepts string types.`,
        )
      }

      result.prompt = promptZodSchema
    } catch (error) {
      if (error instanceof Error && error.message.includes('inputSchema')) {
        // Re-throw our custom validation errors
        throw error
      }

      // Handle json-schema-to-zod conversion errors
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'
      throw new Error(
        `Failed to convert inputSchema.prompt to Zod${fileContext}: ${errorMessage}. ` +
          `Please check that your inputSchema.prompt is a valid non-empty JSON schema object.`,
      )
    }
  }

  // Handle params schema
  if (paramsSchema) {
    try {
      if (
        typeof paramsSchema !== 'object' ||
        Object.keys(paramsSchema).length === 0
      ) {
        throw new Error(
          `Invalid inputSchema.params${fileContext}: Schema must be a valid non-empty JSON schema object. Found: ${typeof paramsSchema}`,
        )
      }
      const paramsZodSchema = convertJsonSchemaToZod(paramsSchema)
      result.params = paramsZodSchema
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unknown error'
      throw new Error(
        `Failed to convert inputSchema.params to Zod${fileContext}: ${errorMessage}. ` +
          `Please check that your inputSchema.params is a valid non-empty JSON schema object.`,
      )
    }
  }

  return result
}

import { normalizeAgentName } from './agent-name-normalization'
import { AGENT_PERSONAS } from '../constants/agents'

export interface AgentInfo {
  id: string
  displayName: string
  purpose?: string
  isBuiltIn: boolean
}

/**
 * Get all built-in agents (excluding hidden ones)
 */
export function getBuiltInAgents(): AgentInfo[] {
  return Object.entries(AGENT_PERSONAS)
    .filter(([, persona]) => !('hidden' in persona) || !persona.hidden)
    .map(([agentId, persona]) => ({
      id: agentId,
      displayName: persona.displayName,
      purpose: persona.purpose,
      isBuiltIn: true,
    }))
}

/**
 * Convert local agent configs to AgentInfo array
 */
export function getLocalAgents(
  localAgents: Record<string, { displayName: string; purpose?: string }>,
): AgentInfo[] {
  return Object.entries(localAgents).map(([agentId, config]) => ({
    id: normalizeAgentName(agentId),
    displayName: config.displayName,
    purpose: config.purpose,
    isBuiltIn: false,
  }))
}

/**
 * Get all agents (built-in + local)
 */
export function getAllAgents(
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): AgentInfo[] {
  return [...getBuiltInAgents(), ...getLocalAgents(localAgents)]
}

/**
 * Resolve display name to agent ID
 */
export function resolveNameToId(
  displayName: string,
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): string | null {
  const agents = getAllAgents(localAgents)
  const agent = agents.find(
    (a) => a.displayName.toLowerCase() === displayName.toLowerCase(),
  )
  return agent?.id || null
}

/**
 * Resolve agent ID to display name
 */
export function resolveIdToName(
  agentId: string,
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): string | null {
  const normalizedId = normalizeAgentName(agentId)
  const agents = getAllAgents(localAgents)
  const agent = agents.find((a) => a.id === normalizedId)
  return agent?.displayName || null
}

/**
 * Get agent display name from ID or name, with fallback
 */
export function getAgentDisplayName(
  agentIdOrName: string,
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): string {
  return (
    resolveIdToName(agentIdOrName, localAgents) ||
    (resolveNameToId(agentIdOrName, localAgents)
      ? agentIdOrName
      : agentIdOrName)
  )
}

/**
 * Get agent ID from display name or ID, with fallback
 */
export function getAgentId(
  agentIdOrName: string,
  localAgents: Record<string, { displayName: string; purpose?: string }> = {},
): string {
  return (
    resolveNameToId(agentIdOrName, localAgents) ||
    normalizeAgentName(agentIdOrName)
  )
}

