import { AgentTemplateTypes } from '@codebuff/common/types/session-state'
import { resolveAgentId } from '@codebuff/common/util/agent-name-normalization'
import { describe, expect, it, beforeEach } from 'bun:test'

import type { AgentTemplate } from '../templates/types'

describe('Agent ID Resolution', () => {
  let mockRegistry: Record<string, AgentTemplate>
  beforeEach(() => {
    mockRegistry = {
      // Built-in agents
      base: {
        id: 'base',
        displayName: 'Buffy',
        systemPrompt: 'Test',
        instructionsPrompt: 'Test',
        stepPrompt: 'Test',
        toolNames: ['end_turn'],
        subagents: [],
        outputMode: 'last_message',
        includeMessageHistory: true,
        model: 'anthropic/claude-4-sonnet-20250522',
        parentPrompt: 'Test',
        inputSchema: {},
      },
      [AgentTemplateTypes.file_picker]: {
        id: AgentTemplateTypes.file_picker,
        displayName: 'Fletcher',
        systemPrompt: 'Test',
        instructionsPrompt: 'Test',
        stepPrompt: 'Test',
        toolNames: ['find_files'],
        subagents: [],
        outputMode: 'last_message',
        includeMessageHistory: true,
        model: 'anthropic/claude-4-sonnet-20250522',
        parentPrompt: 'Test',
        inputSchema: {},
      },
      // Spawnable agents with org prefix
      'CodebuffAI/git-committer': {
        id: 'CodebuffAI/git-committer',
        displayName: 'Git Committer',
        systemPrompt: 'Test',
        instructionsPrompt: 'Test',
        stepPrompt: 'Test',
        toolNames: ['end_turn'],
        subagents: [],
        outputMode: 'last_message',
        includeMessageHistory: true,
        model: 'google/gemini-2.5-pro',
        parentPrompt: 'Test',
        inputSchema: {},
      },
      'CodebuffAI/example-agent': {
        id: 'CodebuffAI/example-agent',
        displayName: 'Example Agent',
        systemPrompt: 'Test',
        instructionsPrompt: 'Test',
        stepPrompt: 'Test',
        toolNames: ['end_turn'],
        subagents: [],
        outputMode: 'last_message',
        includeMessageHistory: true,
        model: 'anthropic/claude-4-sonnet-20250522',
        parentPrompt: 'Test',
        inputSchema: {},
      },
      // Custom user agent without prefix
      'my-custom-agent': {
        id: 'my-custom-agent',
        displayName: 'My Custom Agent',
        systemPrompt: 'Test',
        instructionsPrompt: 'Test',
        stepPrompt: 'Test',
        toolNames: ['end_turn'],
        subagents: [],
        outputMode: 'last_message',
        includeMessageHistory: true,
        model: 'anthropic/claude-4-sonnet-20250522',
        parentPrompt: 'Test',
        inputSchema: {},
      },
    }
  })

  describe('Direct ID Resolution', () => {
    it('should resolve built-in agent IDs directly', () => {
      expect(resolveAgentId('base', mockRegistry)).toBe('base')
      expect(resolveAgentId('file-picker', mockRegistry)).toBe('file-picker')
    })

    it('should resolve custom agent IDs directly', () => {
      expect(resolveAgentId('my-custom-agent', mockRegistry)).toBe(
        'my-custom-agent',
      )
    })

    it('should resolve prefixed agent IDs directly', () => {
      expect(resolveAgentId('CodebuffAI/git-committer', mockRegistry)).toBe(
        'CodebuffAI/git-committer',
      )
    })
  })

  describe('Prefixed ID Resolution', () => {
    it('should resolve unprefixed spawnable agent IDs by adding CodebuffAI prefix', () => {
      expect(resolveAgentId('git-committer', mockRegistry)).toBe(
        'CodebuffAI/git-committer',
      )
      expect(resolveAgentId('example-agent', mockRegistry)).toBe(
        'CodebuffAI/example-agent',
      )
    })

    it('should not add prefix to built-in agents', () => {
      // Built-in agents should be found directly, not with prefix
      expect(resolveAgentId('base', mockRegistry)).toBe('base')
      expect(resolveAgentId('file-picker', mockRegistry)).toBe('file-picker')
    })
  })

  describe('Error Cases', () => {
    it('should return null for non-existent agents', () => {
      expect(resolveAgentId('non-existent', mockRegistry)).toBeNull()
      expect(resolveAgentId('CodebuffAI/non-existent', mockRegistry)).toBeNull()
    })

    it('should return null for empty agent ID', () => {
      expect(resolveAgentId('', mockRegistry)).toBeNull()
    })
  })

  describe('Edge Cases', () => {
    it('should handle agent IDs that already have different org prefixes', () => {
      // Add an agent with a different org prefix
      mockRegistry['OtherOrg/special-agent'] = {
        id: 'OtherOrg/special-agent',
        displayName: 'Special Agent',
        systemPrompt: 'Test',
        instructionsPrompt: 'Test',
        stepPrompt: 'Test',
        toolNames: ['end_turn'],
        subagents: [],
        outputMode: 'last_message',
        includeMessageHistory: true,
        model: 'anthropic/claude-4-sonnet-20250522',
        parentPrompt: 'Test',
        inputSchema: {},
      }

      // Should find it directly
      expect(resolveAgentId('OtherOrg/special-agent', mockRegistry)).toBe(
        'OtherOrg/special-agent',
      )

      // Should not add CodebuffAI prefix to it
      expect(resolveAgentId('special-agent', mockRegistry)).toBeNull()
    })

    it('should handle agents with slashes in their names but no org prefix', () => {
      // This is an edge case - an agent ID that contains a slash but isn't an org prefix
      mockRegistry['weird/agent-name'] = {
        id: 'weird/agent-name',
        displayName: 'Weird Agent',
        systemPrompt: 'Test',
        instructionsPrompt: 'Test',
        stepPrompt: 'Test',
        toolNames: ['end_turn'],
        subagents: [],
        outputMode: 'last_message',
        includeMessageHistory: true,
        model: 'anthropic/claude-4-sonnet-20250522',
        parentPrompt: 'Test',
        inputSchema: {},
      }

      expect(resolveAgentId('weird/agent-name', mockRegistry)).toBe(
        'weird/agent-name',
      )
    })
  })
})

import { z } from 'zod'

import { CodebuffMessageSchema } from './message'
import { ProjectFileContextSchema } from '../util/file'

import type { CodebuffMessage } from './message'
import type { ProjectFileContext } from '../util/file'

export const toolCallSchema = z.object({
  toolName: z.string(),
  args: z.record(z.string(), z.any()),
  toolCallId: z.string(),
})
export type ToolCall = z.infer<typeof toolCallSchema>

export const toolResultSchema = z.object({
  toolName: z.string(),
  toolCallId: z.string(),
  result: z.string(),
})
export type ToolResult = z.infer<typeof toolResultSchema>

export const subgoalSchema = z.object({
  objective: z.string().optional(),
  status: z
    .enum(['NOT_STARTED', 'IN_PROGRESS', 'COMPLETE', 'ABORTED'])
    .optional(),
  plan: z.string().optional(),
  logs: z.string().array(),
})
export type Subgoal = z.infer<typeof subgoalSchema>

export const AgentStateSchema: z.ZodType<{
  agentId: string
  agentType: AgentTemplateType | null
  agentContext: Record<string, Subgoal>
  subagents: AgentState[]
  messageHistory: CodebuffMessage[]
  stepsRemaining: number
  output?: Record<string, any>
  parentId?: string
}> = z.lazy(() =>
  z.object({
    agentId: z.string(),
    agentType: z.string().nullable(),
    agentContext: z.record(z.string(), subgoalSchema),
    subagents: AgentStateSchema.array(),
    messageHistory: CodebuffMessageSchema.array(),
    stepsRemaining: z.number(),
    output: z.record(z.string(), z.any()).optional(),
    parentId: z.string().optional(),
  }),
)
export type AgentState = z.infer<typeof AgentStateSchema>

export const AgentTemplateTypeList = [
  // Base agents
  'base',
  'base_lite',
  'base_max',
  'base_experimental',
  'claude4_gemini_thinking',
  'superagent',
  'base_agent_builder',

  // Ask mode
  'ask',

  // Planning / Thinking
  'planner',
  'dry_run',
  'thinker',

  // Other agents
  'file_picker',
  'file_explorer',
  'researcher',
  'reviewer',
  'agent_builder',
  'example_programmatic',
] as const
type UnderscoreToDash<S extends string> = S extends `${infer L}_${infer R}`
  ? `${L}-${UnderscoreToDash<R>}` // recurse on the remainder
  : S
export const AgentTemplateTypes = Object.fromEntries(
  AgentTemplateTypeList.map((name) => [name, name.replaceAll('_', '-')]),
) as { [K in (typeof AgentTemplateTypeList)[number]]: UnderscoreToDash<K> }
const agentTemplateTypeSchema = z.enum(AgentTemplateTypeList)
// Allow dynamic agent types by extending the base enum with string
export type AgentTemplateType =
  | z.infer<typeof agentTemplateTypeSchema>
  | (string & {})

export const SessionStateSchema = z.object({
  fileContext: ProjectFileContextSchema,
  mainAgentState: AgentStateSchema,
})
export type SessionState = z.infer<typeof SessionStateSchema>

export function getInitialSessionState(
  fileContext: ProjectFileContext,
): SessionState {
  return {
    mainAgentState: {
      agentId: 'main-agent',
      agentType: null,
      agentContext: {},
      subagents: [],
      messageHistory: [],
      stepsRemaining: 12,
      output: undefined,
    },
    fileContext,
  }
}

