import { mainPrompt } from './main-prompt'

import type { MainPromptOptions } from './main-prompt'
import type { ClientToolCall } from './tools/constants'
import type { ClientAction } from '@codebuff/common/actions'
import type {
  SessionState,
  ToolResult,
} from '@codebuff/common/types/session-state'
import type { WebSocket } from 'ws'

const DEFAULT_MAX_ITERATIONS = 20

export async function loopMainPrompt(
  ws: WebSocket,
  action: Extract<ClientAction, { type: 'prompt' }>,
  options: MainPromptOptions & { maxIterations?: number },
): Promise<{
  sessionState: SessionState
  toolCalls: Array<ClientToolCall>
  toolResults: Array<ToolResult>
}> {
  const maxIterations = options.maxIterations ?? DEFAULT_MAX_ITERATIONS
  let { sessionState, toolResults, toolCalls } = await mainPrompt(
    ws,
    action,
    options,
  )
  let iterations = 0
  // Continue running as long as the agent is using tools and hasn't decided to end the turn.
  while (
    toolCalls.length > 0 &&
    !toolCalls.some((tc) => tc.toolName === 'end_turn')
  ) {
    const nextAction: Extract<ClientAction, { type: 'prompt' }> = {
      ...action,
      sessionState,
      toolResults,
      prompt: undefined,
    }
    const result = await mainPrompt(ws, nextAction, options)
    sessionState = result.sessionState
    toolResults = result.toolResults
    toolCalls = result.toolCalls
    iterations++
    if (iterations >= maxIterations) {
      break
    }
  }

  return { sessionState, toolCalls, toolResults }
}

import fs from 'fs'
import path from 'path'

import { withCacheControlCore } from '@codebuff/common/util/messages'

import { logger } from '../util/logger'

import type { CodebuffMessage } from '@codebuff/common/types/message'

export async function saveAgentRequest(
  messages: CodebuffMessage[],
  userInputId: string,
) {
  try {
    const promptsDir = path.join(process.cwd(), 'system-prompts')
    await fs.promises.mkdir(promptsDir, { recursive: true })

    const messageCount = messages.length
    const filename = `system-prompt-${messageCount}-${userInputId}.json`
    const filePath = path.join(promptsDir, filename)

    const transformedMessages = messages.map(withCacheControlCore)

    await fs.promises.writeFile(
      filePath,
      JSON.stringify(transformedMessages, null, 2),
    )

    logger.debug(
      { messageCount, userInputId },
      `Saved system prompt to ${filePath}`,
    )
  } catch (error) {
    logger.error({ error }, 'Failed to save system prompt')
  }
}

