import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { logger } from '@codebuff/common/util/logger'
import { eq } from 'drizzle-orm'
import { LoopsClient, APIError } from 'loops'

import type { LoopsEmailData, SendEmailResult } from './types'

const ORGANIZATION_INVITATION_TRANSACTIONAL_ID = 'cmbikixxm15xo4a0iiemzkzw1'
const BASIC_TRANSACTIONAL_ID = 'cmb8pafk92r820w0i7lkplkt2'

// Initialize Loops client
let loopsClient: LoopsClient | null = null
if (process.env.LOOPS_API_KEY) {
  loopsClient = new LoopsClient(process.env.LOOPS_API_KEY)
}

async function sendTransactionalEmail(
  transactionalId: string,
  email: string,
  dataVariables: Record<string, any> = {},
): Promise<SendEmailResult> {
  if (!loopsClient) {
    return {
      success: false,
      error:
        'Loops SDK not initialized (LOOPS_API_KEY missing or SDK init failed).',
    }
  }

  try {
    const response = await loopsClient.sendTransactionalEmail({
      transactionalId,
      email,
      dataVariables,
    })

    logger.info(
      { email, transactionalId, loopsId: (response as any)?.id },
      'Loops transactional email sent successfully via SDK',
    )
    return { success: true, loopsId: (response as any)?.id }
  } catch (error) {
    let errorMessage = 'Unknown SDK error during transactional email'
    if (error instanceof APIError) {
      logger.error(
        {
          ...error,
          email,
          transactionalId,
          errorType: 'APIError',
        },
        `Loops APIError sending transactional email: ${error.message}`,
      )
      errorMessage = `Loops APIError: ${error.message} (Status: ${error.statusCode})`
    } else {
      logger.error(
        { email, transactionalId, error },
        'An unexpected error occurred sending transactional email via Loops SDK',
      )
    }
    return { success: false, error: errorMessage }
  }
}

export async function sendSignupEventToLoops(
  userId: string,
  email: string | null,
  name: string | null,
): Promise<void> {
  if (!loopsClient) {
    logger.warn({ userId }, 'Loops SDK not initialized. Skipping signup event.')
    return
  }
  if (!email) {
    logger.warn(
      { userId },
      'User email missing, cannot send Loops signup event.',
    )
    return
  }

  try {
    const response = await loopsClient.sendEvent({
      eventName: 'signup',
      email,
      userId,
      contactProperties: {
        firstName: name?.split(' ')[0] ?? '',
      },
    })

    logger.info(
      { email, userId, eventName: 'signup', loopsId: (response as any)?.id },
      'Sent signup event to Loops via SDK',
    )
  } catch (error) {
    if (error instanceof APIError) {
      logger.error(
        {
          ...error,
          email,
          userId,
          eventName: 'signup',
          errorType: 'APIError',
        },
        `Loops APIError sending event: ${error.message}`,
      )
    } else {
      logger.error(
        { error, email, userId, eventName: 'signup' },
        'An unexpected error occurred sending signup event via Loops SDK',
      )
    }
    // Original function did not return error status, just logged.
  }
}

export async function sendOrganizationInvitationEmail(
  data: LoopsEmailData, // data no longer contains firstName
): Promise<SendEmailResult> {
  let lookedUpFirstName: string = 'there' // Default to 'there'
  try {
    const inviteeUserRecord = await db
      .select({ name: schema.user.name })
      .from(schema.user)
      .where(eq(schema.user.email, data.email.toLowerCase())) // Compare email case-insensitively
      .limit(1)

    if (inviteeUserRecord.length > 0 && inviteeUserRecord[0].name) {
      lookedUpFirstName = inviteeUserRecord[0].name.split(' ')[0] || 'there'
    }
  } catch (error) {
    logger.error(
      {
        email: data.email,
        error,
        source: 'sendOrganizationInvitationEmail-lookup',
      },
      'Error fetching user by email for invitation, using default name.',
    )
    // Continue with default name 'there'
  }

  return sendTransactionalEmail(
    ORGANIZATION_INVITATION_TRANSACTIONAL_ID,
    data.email,
    {
      firstName: lookedUpFirstName, // Use the looked-up or default name
      organizationName: data.organizationName || '', // data.organizationName is still expected
      inviterName: data.inviterName || '', // data.inviterName is still expected
      invitationUrl: data.invitationUrl || '', // data.invitationUrl is still expected
      role: data.role || 'member', // data.role is still expected
    },
  )
}

export async function sendBasicEmail(
  email: string,
  data: { subject: string; message: string },
): Promise<SendEmailResult> {
  return sendTransactionalEmail(BASIC_TRANSACTIONAL_ID, email, {
    subject: data.subject,
    message: data.message,
  })
}

import type { TableSchema } from '@google-cloud/bigquery'

interface BaseEvent {
  id: string // primary key, ID for this specific event
  agent_step_id: string // ID for a step of the agent loop, ie: a mainPrompt call
  user_id: string // user ID
}

interface BasePayload {
  user_input_id: string // ID of a given user input in a sesson
  client_session_id: string // ID for a given client session
  fingerprint_id: string // ID for a specific device
}

// Define possible trace types
export type TraceType =
  | 'get-relevant-files' // Get-relevant-files call in production
  | 'file-trees' // Uploads additional file trees of various sizes
  | 'agent-response' // Response from the agent at the end
  | 'get-expanded-file-context-for-training' // Additional capture of a stronger-model + higher-file limit call
  | 'get-expanded-file-context-for-training-blobs' // Capture of full file context from get-relevant-files-for-training call
  | 'grade-run' // Run grades (by a judge model)

// Base trace interface
export interface BaseTrace extends BaseEvent {
  created_at: Date
  type: TraceType
  payload: unknown
}

// Type-specific payload interfaces
export interface GetRelevantFilesPayload extends BasePayload {
  messages: unknown
  system: unknown
  output: string
  request_type: string
  model?: string
  repo_name?: string
}

export interface GetRelevantFilesTrace extends BaseTrace {
  type: 'get-relevant-files'
  payload: GetRelevantFilesPayload
}

export interface GetExpandedFileContextForTrainingTrace extends BaseTrace {
  type: 'get-expanded-file-context-for-training'
  payload: GetRelevantFilesPayload
}

export interface FilesBlobPayload extends BasePayload {
  files: Record<string, { content: string; tokens: number }>
}

export interface GetExpandedFileContextForTrainingBlobTrace extends BaseTrace {
  type: 'get-expanded-file-context-for-training-blobs'
  payload: FilesBlobPayload
}

interface FileTreePayload extends BasePayload {
  filetrees: Record<number, string>
}

export interface FileTreeTrace extends BaseTrace {
  type: 'file-trees'
  payload: FileTreePayload
}

interface AgentResponsePayload extends BasePayload {
  output: string
}

export interface AgentResponseTrace extends BaseTrace {
  type: 'agent-response'
  payload: AgentResponsePayload
}

interface GradeRunPayload extends BasePayload {
  type: 'grade-run'
  scores: string // Of format: [{model_name: "foo", score: 4}, {model_name: "bar", score: 3}, {model_name: "baz", score: 3}]
}

export interface GradeRunTrace extends BaseTrace {
  type: 'grade-run'
  payload: GradeRunPayload
}

// Union type for all trace records
export type Trace =
  | GetRelevantFilesTrace
  | FileTreeTrace
  | AgentResponseTrace
  | GetExpandedFileContextForTrainingBlobTrace
  | GetExpandedFileContextForTrainingTrace
  | GradeRunTrace

